      "path": "packages/dsh-remote-web/lib/index.js",
      "content": "// dsh-remote-web — node half (host plugin)（2026-09 由 dsh-remote-ui 更名 dsh-remote-web；卸载/清理兼容旧名）\n//\n// 提供 /dsh-remote/* 同源 HTTP 路由，供浏览器半的「远程访问」设置面板调用：\n//   - 读写配置目录下 .dsh-config.json（0600）\n//   - 查询/启停 bridge（launchctl，plist 缺失时自动生成，逻辑与 dsh-setup.mjs 一致）\n//   - 代理 relay API（captcha / register / login / public-config），直连、不走系统代理；\n//     另代理企业端一次性访问密钥 / 授权设备（/api/auth-key、/api/mobile-sessions、…/revoke、\n//     DELETE …/:id、POST …/purge，Bearer）供面板「📱 远程访问」卡使用\n//   - 自管理 self*（版本可见 / 新版检测 / 一键在线更新 / 彻底卸载）：插件市场没有更新卸载按钮，\n//     面板内即官方管理入口；更新=后台 npx 按 dist-tag(默认 latest,DSH_UPDATE_TAG 可切 beta/alpha)（幂等补齐运行环境并重启 bridge）；\n//     彻底卸载=profile 插件清理（uninstallSelf）+ 运行时清理（uninstallRuntime：停 bridge 自启动 /\n//     删 plist|unit / 杀残留进程 / 清空配置目录 ~/.dsh-remote），0.4.7 起回归真正「未安装」状态\n//   - 运行时自愈：缺运行环境自动后台安装、登录后自动拉起 bridge（0.4.2 起）\n//   - 登录后自动闭环（0.6.4）：GET /dsh-remote/bridge-status 下发连接阶段\n//     （no_account/no_runtime/installing/starting/connecting/online/error），并在返回前自动补装运行环境、\n//     拉起 bridge、清理卡死标记（带退避）；区分「bridge 进程在跑」与「设备已在中继注册成功（online）」。\n//     面板用 2~3s 短轮询自动推进到 online（无需点按钮/刷新页面），error 才给重试与诊断信息；\n//     另 POST /dsh-remote/connect/retry 手动重试、POST <api>/api/install-report 上报安装约定\n//     （install_source/version + host_os/arch，详见 installSourceOf）。\n//   - 0.1.2+ ?token 浏览器鉴权会话代持（0.4.1 起）\n//\n// 不依赖任何第三方包：只使用 node 内置模块与 cordis 注入的 webServer 服务。\nimport { readFileSync, writeFileSync, mkdirSync, existsSync, realpathSync, accessSync, chmodSync, openSync, closeSync, readSync, fstatSync, rmSync, renameSync, statSync, copyFileSync, cpSync, readdirSync, constants as fsConstants } from \"node:fs\";\nimport { join, dirname, sep, delimiter, isAbsolute, relative } from \"node:path\";\nimport { execSync, spawn, spawnSync } from \"node:child_process\";\nimport { randomUUID } from \"node:crypto\";\nimport { homedir, tmpdir } from \"node:os\";\nimport { fileURLToPath } from \"node:url\";\nimport { buildFixPrompt, REPORT_TITLE, REPORT_FORMAT, REPORT_KEYS } from \"./fix-prompt.js\";\n\n/** 本插件在 host 侧的服务依赖。 */\nexport const inject = [\"webServer\"];\n\n// ---------- 平台抽象层（0.6.7：Windows 支持） ----------\n//\n// 为什么单独抽一层：本插件整套「服务状态 / 启停」原本按 macOS/Linux 写死\n// （launchctl / systemctl / pgrep / ps / /bin/sh），在 Windows 上运行期直接炸：\n//   · process.getuid() 在 Windows 不存在（不是返回 undefined，是**没有这个函数**）\n//     → /dsh-remote/status 与 /bridge-status 双双 500，面板永久停在「查询中…」；\n//   · spawn(\"npx.cmd\") 不带 shell（Node ≥20.12 起）同步抛 EINVAL → 运行环境永远补不上；\n//   · spawn(\"/bin/sh\") 在 Windows 报 ENOENT，且当时没有 'error' 监听 → 未捕获异常打挂 dsh web。\n// 下面所有平台判断一律走 osPlatform()，绝不直接读 process.platform——这样测试可以用\n// DSH_RELAY_PLATFORM=win32 在 macOS/Linux 开发机上把 Windows 分支真正跑一遍（见 test/windows-compat.test.mjs）。\n\n/**\n * 当前运行平台（win32/darwin/linux/…）。\n * DSH_RELAY_PLATFORM 仅供测试/诊断模拟其它平台，生产环境不设置；调用时读取（非模块加载时固定）。\n */\nfunction osPlatform() {\n  return String(process.env.DSH_RELAY_PLATFORM || \"\").trim() || process.platform;\n}\n/** 是否 Windows：无 launchd/systemd、无 pgrep/ps、无 /bin/sh、npx 是 .cmd。 */\nfunction isWindows() {\n  return osPlatform() === \"win32\";\n}\nfunction isDarwin() {\n  return osPlatform() === \"darwin\";\n}\n/** 是否 Linux：Desktop 之外的自建/主机部署 + **飞牛 fnOS / 群晖这类 NAS**（0.6.15 的实测环境）。 */\nfunction isLinux() {\n  return osPlatform() === \"linux\";\n}\n\n/**\n * 当前进程 uid。**Windows 没有 process.getuid**（typeof !== \"function\"），\n * 旧实现无条件调用它，导致所有读状态的接口 500。取不到一律返回 null，\n * 调用方按「本平台无 launchd domain」处理。\n */\nfunction currentUid() {\n  return typeof process.getuid === \"function\" ? process.getuid() : null;\n}\n\n/** 同步睡眠（不引第三方依赖；Windows 没有 `sleep` 命令）。 */\nfunction sleepSync(ms) {\n  try {\n    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);\n  } catch {\n    const end = Date.now() + ms;\n    while (Date.now() < end) { /* 极端环境退化为忙等 */ }\n  }\n}\n\n/** quote 成 POSIX shell 单引号字面量（仅 darwin/linux 的 sh 调用用）。 */\nfunction shQuote(s) {\n  return \"'\" + String(s).replace(/'/g, `'\\\\''`) + \"'\";\n}\n\n/** 默认配置目录（可被 entry config 的 relayDir / DSH_RELAY_DIR 环境变量覆盖）。 */\nconst DEFAULT_RELAY_DIR = process.env.DSH_RELAY_DIR || join(homedir(), \".dsh-remote\");\n// 默认云端服务地址（SaaS 入口；自建用户在设置页/面板切换）。\n// DSH_RELAY_DEFAULT_API 只改「配置里根本没写 api_url」时的兜底：测试脚本把它指向本地死端口，\n// 这样任何**在临时目录被拆掉之后**才跑到的后台请求（如装机上报的重试）都不会打生产。\n// 真实故障形态见 test/wechat-bind-telemetry.test.mjs 的注释：用例拆目录 → 读到空配置 → 回落生产。\nconst DEFAULT_API = String(process.env.DSH_RELAY_DEFAULT_API || \"\").trim()\n  || \"https://n.risegao.cn:13443/relay-api\";\nconst DEFAULT_APP_URL = \"https://n.risegao.cn:13443/app/\";\n\n// ---------- 上游 dsh web 地址（bridge/watcher 都要连它，绝不写死 3080） ----------\n//\n// 【2026-09-23 用户实测故障】这里（以及运行时的 checkUpstream）原本把上游**写死**\n// `http://127.0.0.1:3080`：只要用户的 dsh web 不在默认端口（`dsh web --port 8090`、\n// profile 里配了 port、或 `--port 0` 让系统分配空闲端口），watcher 的「dsh web 在线吗」\n// 探测就永远失败 → **bridge 永远不启动**，而面板只会说「正在启动 Bridge…」（错误为空）\n// —— 用户反复修复也没有任何变化。\n// 这个插件就跑在 dsh web 进程里：`ctx.webServer` 是它自己的 HTTP 服务（`port` 是实际监听端口，\n// `config.port=0` 时也已被系统分配并回填），因此上游地址必须是**问出来**的，不是猜出来的。\nlet webServerCtx = null;\nconst FALLBACK_UPSTREAM = \"http://127.0.0.1:3080\";\n/** 从 dsh web 服务实例取实际端口（apply 时可能还没 listen 完，故调用时再读）。 */\nfunction boundWebPort() {\n  let ws = null;\n  try { ws = webServerCtx?.webServer || null; } catch { ws = null; } // 宿主 ctx 已销毁时静默回落\n  for (const v of [ws?.port, ws?.config?.port]) {\n    const n = Number(v);\n    if (Number.isInteger(n) && n > 0) return n;\n  }\n  const raw = String(process.env.DSH_WEB_URL || \"\").trim();\n  if (raw) {\n    try {\n      const n = Number(new URL(raw).port);\n      if (Number.isInteger(n) && n > 0) return n;\n    } catch { /* 非 URL：忽略 */ }\n  }\n  return 0;\n}\n/**\n * 本机 dsh web 的**回环**上游地址（bridge 的 loopback 围栏只认 127.0.0.1，\n * 所以即使 dsh web 绑的是 0.0.0.0，上游也照样写回环地址）。\n * 优先级：显式 DSH_BRIDGE_UPSTREAM（用户/部署覆盖）> 实际监听端口 > **主动发现** > DSH_WEB_URL > 3080。\n *\n * 【0.6.15 新增「主动发现」那一层】飞牛 fnOS 用户实测（2026-09-25）：\n *   `boundWebPort()` 在该环境下**取不到**自己的监听端口（诊断原文：未取到 dsh web 实际监听端口），\n *   于是上游回落 3080，而他的 dsh web 在 **2298** —— 面板永远「不可达」，用户反复改端口也没用。\n *   发现结果（`discoveredUpstream`）由 `discoverUpstreamSelf()` 异步填充（本机回环端口扫描 + 身份校验），\n *   填上之后这里就直接用它，watcher/bridge 拿到的 `DSH_BRIDGE_UPSTREAM` 也随之正确。\n */\nfunction upstreamUrl() {\n  const explicit = String(process.env.DSH_BRIDGE_UPSTREAM || \"\").trim();\n  if (explicit) return explicit.replace(/\\/+$/, \"\");\n  const port = boundWebPort();\n  if (port) return `http://127.0.0.1:${port}`;\n  if (discoveredUpstream.url && Date.now() - discoveredUpstream.at < UPSTREAM_DISCOVERY_TTL_MS) return discoveredUpstream.url;\n  return FALLBACK_UPSTREAM;\n}\n\n/** 主动发现的上游（插件半自己扫出来的；TTL 见 UPSTREAM_DISCOVERY_TTL_MS）。 */\nconst discoveredUpstream = { at: 0, url: \"\" };\nconst UPSTREAM_DISCOVERY_TTL_MS = 5 * 60 * 1000;\nlet upstreamDiscoveryInFlight = null;\n\n/**\n * 插件半主动发现上游地址（只在\"问不出自己端口\"时才真的去扫）。\n *\n * 复用 **运行环境里那一份**发现实现（`runtime/clients/dsh-remote/upstream-discovery.mjs`，与\n * watcher/bridge 是同一份代码），避免第三份实现漂移；运行环境缺失时（首次安装、纯插件半）\n * 静默回落，行为与旧版一致。\n * @param {string} relayDir\n * @param {{force?: boolean}} [opts]\n * @returns {Promise<string>} 发现到的地址（没发现返回上游回退值）\n */\nasync function discoverUpstreamSelf(relayDir, { force = false } = {}) {\n  if (String(process.env.DSH_BRIDGE_UPSTREAM || \"\").trim()) return upstreamUrl();\n  if (boundWebPort()) return upstreamUrl(); // 已经问出来了，不必扫\n  if (skipsSystemOps()) {\n    // 测试/诊断隔离：零系统副作用，也不做端口扫描。顺手清掉上一条真实分支留下的发现结果，\n    // 否则同一个测试进程里后面的用例会读到\"别人的\"上游（真实踩到过：本机 3080 上跑着 dsh web）。\n    discoveredUpstream.at = 0;\n    discoveredUpstream.url = \"\";\n    return upstreamUrl();\n  }\n  // 平台被 DSH_RELAY_PLATFORM 覆盖 = 测试/诊断在模拟别的系统（生产永不设置）：\n  // 这时**不做真实端口扫描** —— 扫描读到的是宿主这台机器的真端口，会让\"模拟 win32\"的用例\n  // 在本机恰好跑着 dsh web 时得到与 CI 不一样的结果（实测踩到）。\n  if (osPlatform() !== process.platform) {\n    discoveredUpstream.at = 0;\n    discoveredUpstream.url = \"\";\n    return upstreamUrl();\n  }\n  if (!force && discoveredUpstream.url && Date.now() - discoveredUpstream.at < UPSTREAM_DISCOVERY_TTL_MS) return discoveredUpstream.url;\n  if (upstreamDiscoveryInFlight) return upstreamDiscoveryInFlight;\n  upstreamDiscoveryInFlight = (async () => {\n    try {\n      const mod = await import(new URL(\"../runtime/clients/dsh-remote/upstream-discovery.mjs\", import.meta.url).href);\n      if (typeof mod?.discoverUpstream !== \"function\") return FALLBACK_UPSTREAM;\n      // ★ platform 必须跟着 osPlatform()：整个插件的平台判定都走它（DSH_RELAY_PLATFORM 可覆盖），\n      //   发现逻辑不一致的话，\"win32 模拟\"用例会去枚举宿主真实端口（本机 3080 上有 dsh web 就会被命中）。\n      const found = await mod.discoverUpstream({ relayDir, platform: osPlatform(), log: (m) => console.log(`[dsh-remote-web] ${m}`) });\n      const url = String(found?.url || \"\");\n      if (url) {\n        discoveredUpstream.at = Date.now();\n        discoveredUpstream.url = url;\n        // 固化到端口文件：watcher/bridge 是**别的进程**，只认这个文件\n        try {\n          const file = join(relayDir, UPSTREAM_FILE);\n          let cur = \"\";\n          try { cur = readFileSync(file, \"utf8\").trim(); } catch { /* 首次 */ }\n          if (cur !== url) {\n            mkdirSync(relayDir, { recursive: true });\n            writeFileSync(file, url + \"\\n\", { mode: 0o600 });\n          }\n        } catch { /* 非关键 */ }\n      }\n      return url || FALLBACK_UPSTREAM;\n    } catch {\n      return FALLBACK_UPSTREAM; // 运行环境还没装好 / 模块不在 → 保持旧行为\n    } finally {\n      upstreamDiscoveryInFlight = null;\n    }\n  })();\n  return upstreamDiscoveryInFlight;\n}\n\n/**\n * 把上游地址落盘（`<relayDir>/.dsh-upstream`），供**没有环境变量**的那些守护读取：\n * 开机自启的 watcher（Windows 登录任务 / launchd）由系统拉起，拿不到本进程的 env，\n * 只有插件半知道 dsh web 真实监听在哪个端口。运行时（0.6.12+）读这个文件当第二优先来源。\n * 内容没变就不写（面板每轮都会走到这里，别把磁盘写热）。\n *\n * @returns {{changed:boolean, url:string}} `changed=true` = **这一次真的改写了文件**。\n *   ★ 2026-10-13 为什么必须回报这个：修「12 秒重启风暴」时，唯一还站得住的\"需要重启一个\n *   **正在健康运行**的 bridge\"的理由就是\"它的上游地址变了（进程环境里是旧地址，不重启不生效）\"。\n *   而这个判据必须是**磁盘上的真实变化**，不能是\"我觉得它可能变了\" —— 后者又会变成\n *   每轮自愈都重启一次。调用方一律忽略返回值也没关系（旧行为不变）。\n */\nconst UPSTREAM_FILE = \".dsh-upstream\";\nfunction publishUpstream(relayDir) {\n  if (skipsSystemOps()) return { changed: false, url: \"\", skipped: true }; // 测试/诊断隔离：不得对磁盘产生任何副作用（含创建配置目录）\n  try {\n    const url = upstreamUrl();\n    const file = join(relayDir, UPSTREAM_FILE);\n    let cur = \"\";\n    try { cur = readFileSync(file, \"utf8\").trim(); } catch { /* 首次 */ }\n    if (cur === url) return { changed: false, url };\n    mkdirSync(relayDir, { recursive: true });\n    writeFileSync(file, url + \"\\n\", { mode: 0o600 });\n    return { changed: true, url };\n  } catch { /* 非关键：读不到就沿用运行时的回退链 */\n    return { changed: false, url: \"\" };\n  }\n}\n\n/**\n * 上游是否可达（面板诊断用，与 watcher 的判据同构：**只认网络失败**，\n * 4xx/5xx 也算「端口在听」——那样 bridge 连得上，问题在别处）。\n * 带 TTL 缓存：面板 2~3s 轮询一次，不能每次都发一个请求。\n */\nconst UPSTREAM_PROBE_TTL_MS = 5000;\nconst upstreamProbes = new Map();\nasync function probeUpstream(relayDir) {\n  const url = upstreamUrl();\n  const cached = upstreamProbes.get(relayDir);\n  if (cached && cached.url === url && Date.now() - cached.at < UPSTREAM_PROBE_TTL_MS) return cached.value;\n  let value;\n  try {\n    await fetch(url + \"/\", { signal: AbortSignal.timeout(1500) });\n    value = { ok: true, error: \"\" };\n  } catch (e) {\n    value = { ok: false, error: String(e?.message || e).slice(0, 200) };\n  }\n  upstreamProbes.set(relayDir, { at: Date.now(), url, value });\n  return value;\n}\n\n/**\n * 自启动服务（launchd plist / systemd unit）与子进程使用的 PATH。\n *\n * ⚠️ **必须含 `/usr/sbin` 与 `/sbin`**：它们是系统管理命令所在目录（`ioreg`、`sysctl`…），\n *    而 bridge 会用这些命令探测本机信息。\n *    真机实证（2026-09-22）：本文件此前**硬编码**了不含 `/usr/sbin` 的 PATH，而插件每次\n *    自愈/启动都会重写 plist —— 于是它覆盖掉了 dsh-setup.mjs 里那份**正确**的 SERVICE_PATH，\n *    结果 bridge 日志里刷 `/bin/sh: ioreg: command not found`，机器指纹静默退化成\n *    hostname 哈希（用户改一次主机名就被当成新设备）。\n * ⚠️ 与 `dsh-setup.mjs` 的 `SERVICE_PATH` **必须一致** —— 两处都会写同一个 plist，\n *    谁写谁说了算；有测试锁死这条一致性（跨文件不变量）。\n */\nconst SERVICE_PATH = \"/usr/local/bin:/opt/homebrew/bin:/usr/bin:/bin:/usr/sbin:/sbin\";\n\n/**\n * 把文件权限收紧到「只有本人可读写」。\n *\n * ⚠️ Windows 上 `{ mode: 0o600 }` 是**空操作**（Windows 用 ACL，不是 POSIX mode 位）：\n * 实测 .dsh-config.json 拿到的是用户目录的默认**继承 ACL**（AreAccessRulesProtected=False），\n * 也就是说代码里那句 0600 对 Windows 用户完全没效果 —— 而文件里是**明文账号密码**。\n * 风险不在\"同机他人可读\"（默认 ACL 下其实读不到），而在**任何按文件复制的场景**\n * （备份/同步盘/杀软上报/崩溃转储/用户发给作者的支持包）都会连钥匙一起被带走，\n * 而文档里的\"0600 请妥善保护\"会让用户误以为 Windows 上已有这层保护。\n * 这里显式断开继承、只授予当前用户；失败只警告一次，绝不影响主流程。\n */\nlet hardenWarned = false;\nfunction hardenFile(file) {\n  try { fs.chmodSync(file, 0o600); } catch { /* POSIX 上失败不致命 */ }\n  if (process.platform !== \"win32\") return;\n  const who = [process.env.USERDOMAIN, process.env.USERNAME].filter(Boolean).join(\"\\\\\");\n  // 两个环境变量都取不到时**绝不能静默返回**：那会让人以为文件已加固，实际仍是继承 ACL。\n  // 正常 Windows 会话不会走到这里（USERNAME 必然存在），但受限令牌/服务账户下有可能。\n  if (!who) {\n    if (!hardenWarned) {\n      hardenWarned = true;\n      console.warn(`⚠️ 无法收紧文件权限（USERDOMAIN/USERNAME 均未设置）：${file}`);\n    }\n    return;\n  }\n  let r;\n  try {\n    r = spawnSync(\"icacls\", [file, \"/inheritance:r\", \"/grant:r\", `${who}:F`],\n      { windowsHide: true, encoding: \"utf8\", timeout: 8000 });\n  } catch (e) { r = { status: -1, stderr: e.message }; }\n  if (r.status !== 0 && !hardenWarned) {\n    hardenWarned = true;\n    console.warn(`⚠️ 收紧文件权限失败（${who}）：${String(r.stderr || \"\").trim() || `icacls 退出码 ${r.status}`}`);\n    console.warn(\"   配置文件可能仍可被其它账户/备份工具读取，请自行确认其存放位置。\");\n  }\n}\n\n// ---------- 小工具 ----------\n\n/** 执行 shell 命令，不抛异常，返回 { ok, stdout, stderr, code }。 */\nfunction sh(cmd) {\n  try {\n    // windowsHide（C1 黑窗不变量）：Windows 上 execSync 经 cmd.exe 起控制台程序时，\n    // 若宿主（dsh web / 桌面端）没有控制台，系统会给子进程分配一个可见窗口。\n    // POSIX 上该选项被忽略。\n    const stdout = execSync(cmd, { encoding: \"utf8\", stdio: [\"ignore\", \"pipe\", \"pipe\"], timeout: 15000, windowsHide: true });\n    return { ok: true, stdout: String(stdout ?? \"\"), stderr: \"\", code: 0 };\n  } catch (e) {\n    return { ok: false, stdout: String(e.stdout ?? \"\"), stderr: String(e.stderr ?? \"\"), code: e.status ?? -1 };\n  }\n}\n\n/** 解析真实可执行路径（launchd 需要真实文件 + 可执行位）。 */\nfunction resolveExecutable(p) {\n  try {\n    const real = realpathSync(p);\n    accessSync(real, fsConstants.X_OK);\n    return real;\n  } catch {\n    return null;\n  }\n}\n\n/** 优先 node@20（node-datachannel 兼容性），回退当前 node。 */\n/**\n * 宿主是否跑在 **Electron 的 Node 模式**下（DeepSeek Harness 桌面端的 Host 就是）。\n *\n * 桌面端 `process.execPath` 是 **Electron 应用二进制**，不是 node：\n * 直接 `spawn(process.execPath, [script])` 得到的不是「跑脚本的 node」，\n * 而是**再启动一个 Electron 应用实例**（还会撞桌面端的单实例锁）。\n * 必须补 `ELECTRON_RUN_AS_NODE=1`（官方桌面端自己也正是这么做的：\n * 其内置 CLI 就是 `ELECTRON_RUN_AS_NODE=1 exec <Electron> --expose-internals <cli.js>`）。\n */\nconst IS_ELECTRON_HOST = Boolean(process.versions && process.versions.electron);\n\n/**\n * 本插件派生的**辅助脚本**（watcher 拉起、在线更新、doctor、运行环境清理、重启助手）\n * 一律用**当前进程自己的可执行文件**跑 —— 保持既有行为不变（宿主是哪个 node 就用哪个，\n * 不引入\"另找一个 node 可能版本不同\"的风险）。\n * 但桌面端宿主是 Electron：必须补 `ELECTRON_RUN_AS_NODE=1`，否则不是\"跑脚本\"而是**又开一个桌面端应用**。\n * 非 Electron 宿主下为空对象，行为与改动前完全一致。\n */\nconst SELF_NODE_ENV = IS_ELECTRON_HOST ? { ELECTRON_RUN_AS_NODE: \"1\" } : {};\n\n/**\n * 解析**自启动服务**里应当登记的解释器。\n *\n * 这里与 `SELF_NODE_ENV` 是两件事，不能混：服务由系统在**本应用退出之后**拉起，\n * 所以它登记的解释器必须活过桌面端的退出、甚至更新（.app 路径会变、可能被换掉）。\n * 因此**真实 node 优先**；只有找不到真实 node 时才回落宿主自身，\n * 此时若宿主是 Electron，服务定义里也必须带 `ELECTRON_RUN_AS_NODE=1`。\n *\n * @returns {{bin:string, electron:boolean}} bin 是可执行文件绝对路径；electron=true 表示\n *          该文件是 Electron 二进制，服务定义必须补 `ELECTRON_RUN_AS_NODE=1`。\n */\n/**\n * DeepSeek Harness **桌面端自带 Node** 的稳定落点候选。\n *\n * 为什么需要：桌面端主打的正是**机器上没有系统 node** 的用户；而自启动服务要活过\n * 桌面端的退出、甚至升级/重装（`.app` 路径会变、可能被换掉）。桌面端把自带运行时装在\n * **用户目录** `~/.dsh/dsh-runtimes/…`，它不随应用包更新而移动 —— 所以只要它存在，\n * 就该优先于任何指向 `.app` 内部的路径。\n *\n * 目录布局随桌面端版本演进（可能多套一层 runtime/node），故按多个候选探测；\n * `resolveExecutable()` 会过滤掉不存在的路径，多列无害。\n * @returns {string[]} 候选可执行文件绝对路径（可能都不存在）。\n */\nfunction desktopRuntimeNodeCandidates() {\n  const exe = isWindows() ? \"node.exe\" : \"node\";\n  const out = [];\n  // ① 稳定落点：装在**用户目录**，桌面端升级/重装都不动它。\n  //    ⚠️ 真实布局是 `dependencies/node/bin/<exe>`（2026-10-07 拆官方 0.2.0-rc.2 DMG 实测：\n  //    `…/Resources/runtime/primary-runtime/dependencies/node/bin/node` → Node v24.21.0）。\n  //    其余几个是兼容不同版本的兜底；resolveExecutable() 会过滤掉不存在的路径，多列无害。\n  const roots = [\n    process.env.DSH_DESKTOP_RUNTIME_DIR || \"\",\n    join(homedir(), \".dsh\", \"dsh-runtimes\", \"dsh-primary-runtime\"),\n    join(homedir(), \".dsh\", \"dsh-runtimes\", \"primary-runtime\"),\n  ].filter(Boolean);\n  for (const root of roots) {\n    out.push(\n      join(root, \"dependencies\", \"node\", \"bin\", exe),\n      join(root, \"bin\", exe),\n      join(root, \"node\", \"bin\", exe),\n      join(root, \"runtime\", \"bin\", exe),\n    );\n  }\n  // ② 应用自己把自带 node 的路径交给子进程（其 `runtime/bin/node` shim 就是靠这个变量）——\n  //    平台无关，且是\"应用自己说的\"，比我们猜路径可靠。\n  if (process.env.DSH_DESKTOP_NODE_EXECUTABLE) out.push(process.env.DSH_DESKTOP_NODE_EXECUTABLE);\n  // ③ 最后才是指向应用包内部的绝对路径：它是**真实存在的 node**，但会随桌面端更新换路径，\n  //    所以排在稳定落点之后（自启动服务登记它属于\"聊胜于无\"，好过登记 Electron 本体）。\n  if (isWindows()) {\n    const local = process.env.LOCALAPPDATA || \"\";\n    if (local) out.push(join(local, \"Programs\", \"DeepSeek Harness\", \"resources\", \"runtime\", \"primary-runtime\", \"dependencies\", \"node\", exe));\n  } else {\n    out.push(\n      \"/Applications/DeepSeek Harness.app/Contents/Resources/runtime/primary-runtime/dependencies/node/bin/node\",\n      \"/Applications/DSH Desktop.app/Contents/Resources/runtime/primary-runtime/dependencies/node/bin/node\",\n    );\n  }\n  return out;\n}\n\nfunction resolveServiceInterpreter() {\n  const candidates = [\n    \"/opt/homebrew/opt/node@20/bin/node\",\n    \"/usr/local/opt/node@20/bin/node\",\n    ...desktopRuntimeNodeCandidates(),\n    process.env.DSH_SETUP_NODE20 || \"\",\n  ].filter(Boolean);\n  for (const p of candidates) {\n    const real = resolveExecutable(p);\n    if (real) return { bin: real, electron: false };\n  }\n  return { bin: resolveExecutable(process.execPath) || process.execPath, electron: IS_ELECTRON_HOST };\n}\n\nconst SERVICE_INTERPRETER = resolveServiceInterpreter();\nconst NODE_BIN = SERVICE_INTERPRETER.bin;\n/**\n * 服务定义里（plist 的 EnvironmentVariables / systemd 的 Environment=）必须注入的变量。\n * 形如 `{ELECTRON_RUN_AS_NODE:\"1\"}` 或 `{}`。\n */\nconst SERVICE_NODE_ENV = SERVICE_INTERPRETER.electron ? { ELECTRON_RUN_AS_NODE: \"1\" } : {};\n/** plist `EnvironmentVariables` 里要追加的解释器变量（真实 node 时为空串 → 模板不变）。 */\nconst SERVICE_NODE_ENV_PLIST = Object.entries(SERVICE_NODE_ENV)\n  .map(([k, v]) => `<key>${k}</key><string>${v}</string>`).join(\"\");\n/** systemd unit 里要追加的 `Environment=` 行（真实 node 时为空串 → 模板不变）。 */\nconst SERVICE_NODE_ENV_UNIT = Object.entries(SERVICE_NODE_ENV)\n  .map(([k, v]) => `Environment=${k}=${v}\\n`).join(\"\");\n\n/**\n * 解析 npx 的调用方式。DeepSeek App 拉起 dsh web 时 PATH 只有 /usr/bin:/bin:/usr/sbin:/sbin\n * （没有 /opt/homebrew/bin 等），裸 `npx` 会 spawn ENOENT 而静默失败——必须按绝对路径找，\n * 且子进程 env 的 PATH 要把当前 node 所在目录补在最前（npx 的 #!/usr/bin/env node 依赖它）。\n *\n * 【0.6.7 Windows 修复】Windows 上 npx 是批处理 npx.cmd：\n *   · Node ≥20.12（CVE-2024-27980 的修复）起，`spawn(\"npx.cmd\")` 不带 shell 会**同步抛 EINVAL**，\n *     于是运行环境永远补不上（生产遥测里 install_failed/fail_code=npx_cmd_unavailable 全在 win32）；\n *   · 首选「用当前 node 直接跑 npm 自带的 npx-cli.js」——完全不经过 cmd.exe，没有空格/引号/\n *     中文路径陷阱，也不需要 shell:true；\n *   · 找不到 npx-cli.js 才退回 npx.cmd + shell:true（参数是常量，无注入面）。\n * @returns {{command:string, args:string[], shell:boolean, kind:string}}\n *          args 是前置参数（如 npx-cli.js 的路径），调用方接上自己的参数即可。\n */\nfunction npxInvocation() {\n  // 显式覆盖优先（测试注入假 npx；生产通常不设）\n  const overrideDir = process.env.DSH_SETUP_NPX_DIR || \"\";\n  const nodeDir = dirname(process.execPath);\n  if (isWindows()) {\n    // npm 自带 CLI 的位置：Node 官方 Windows 安装在 <node>\\node_modules\\npm\\bin\\npx-cli.js，\n    // 也有把 npm 放在同级 lib\\node_modules 下的布局，一并尝试。\n    const cliCandidates = [\n      ...(overrideDir ? [join(overrideDir, \"node_modules\", \"npm\", \"bin\", \"npx-cli.js\")] : []),\n      join(nodeDir, \"node_modules\", \"npm\", \"bin\", \"npx-cli.js\"),\n      join(nodeDir, \"lib\", \"node_modules\", \"npm\", \"bin\", \"npx-cli.js\"),\n    ];\n    for (const p of cliCandidates) {\n      if (existsSync(p)) return { command: process.execPath, args: [p], shell: false, kind: \"node-npx-cli\" };\n    }\n    // 退回 .cmd：Windows 上**必须** shell:true，否则 EINVAL（这是 0.6.6 及更早的死因）\n    const cmdDirs = [overrideDir, nodeDir, process.env.APPDATA ? join(process.env.APPDATA, \"npm\") : \"\"].filter(Boolean);\n    for (const d of cmdDirs) {\n      const real = resolveExecutable(join(d, \"npx.cmd\"));\n      if (real) return { command: real, args: [], shell: true, kind: \"npx-cmd\" };\n    }\n    return { command: \"npx.cmd\", args: [], shell: true, kind: \"npx-cmd-bare\" };\n  }\n  const dirs = [\n    overrideDir,\n    nodeDir,                             // 与当前 node 同目录（homebrew/usr/local 均可覆盖）\n    \"/opt/homebrew/bin\",\n    \"/usr/local/bin\",\n    \"/opt/homebrew/opt/node@20/bin\",\n    \"/usr/local/opt/node@20/bin\",\n    \"/usr/bin\",\n  ].filter(Boolean);\n  for (const d of dirs) {\n    const real = resolveExecutable(join(d, \"npx\"));\n    if (real) return { command: real, args: [], shell: false, kind: \"npx\" };\n  }\n  return { command: \"npx\", args: [], shell: false, kind: \"npx-bare\" }; // 全找不到 → 退回裸名（普通 shell 场景仍可用）\n}\n\n/** 子进程环境：把 node 目录补进 PATH（npx 及其 shebang 需要），可附加额外变量。 */\nfunction spawnEnv(extra) {\n  // ⚠️ 这里刻意用 **process.execPath**，不是 NODE_BIN：PATH 首位的用途是让 npx 的\n  // `#!/usr/bin/env node` 解析到**正在跑本插件的那个 node**（与 npxInvocation 同约定）。\n  // NODE_BIN 回答的是另一个问题——\"自启动服务里该登记哪个解释器\"（真实 node 优先）。\n  // 两者语义不同，混用会悄悄改掉 web 版上 npx 用哪个 node。\n  const nodeDir = dirname(process.execPath);\n  const base = process.env.PATH || \"\";\n  // PATH 分隔符必须按平台取（Windows 是 \";\"，POSIX 是 \":\"）：写死 \":\" 会把整条 PATH\n  // 在 Windows 上拼成一个不存在的路径，node/npx 全部找不到。\n  // 追加的 POSIX 目录只在类 Unix 上有意义，Windows 上不追加。\n  // 含 /usr/sbin 与 /sbin：插件用 spawnEnv 拉起的是 watcher，它会再拉起 bridge，\n  // 而 bridge 要用 ioreg 之类系统命令（缺了它 → 机器指纹静默退化，见 SERVICE_PATH 注释）。\n  const posixDirs = isWindows() ? [] : [\"/usr/local/bin\", \"/opt/homebrew/bin\", \"/usr/bin\", \"/bin\", \"/usr/sbin\", \"/sbin\"];\n  const PATH = [nodeDir, base, ...posixDirs].filter(Boolean).join(delimiter);\n  // ⚠️ SELF_NODE_ENV 展开在 extra **之前**（= 保持既有展开顺序，extra 依旧最后说了算）。\n  // 它只含 ELECTRON_RUN_AS_NODE 一个键，而没有任何调用方会去设置这个键，故不存在被误覆盖的场景。\n  // ⚠️ 也不要无条件设置（真实 node 下设了会污染子进程环境、并让 node 版本探测类工具困惑）。\n  return { ...process.env, ...SELF_NODE_ENV, PATH, ...(extra || {}) };\n}\n\n/**\n * 派生后台子进程并**始终挂 'error' 监听**。\n *\n * 背景（Windows 实测致命）：没有 'error' 监听器的 ChildProcess，一旦启动失败\n * （ENOENT/EINVAL/EPERM）就会把 error 事件抛成**未捕获异常**，直接打挂宿主 dsh web。\n * 面板的「重启 DeepSeek harness」按钮就是这么把 dsh web 打死的（spawn(\"/bin/sh\") 在 Windows ENOENT）。\n *\n * @returns {{child: import(\"node:child_process\").ChildProcess|null, error: Error|null}}\n *          error 非空 = 同步启动失败（参数非法/被策略拒绝）；异步失败由 onError 回调兜底。\n */\nfunction safeSpawn(command, args, opts = {}) {\n  const { onError, ...spawnOpts } = opts;\n  let child;\n  try {\n    // C1：默认 windowsHide（调用方显式传 false 才会覆盖）。插件派生的每一个子进程都是\n    // \"后台辅助进程\"，Windows 上绝不该出现可见控制台窗口（诊断报告 04 的 W1 黑窗）。\n    child = spawn(command, args, { windowsHide: true, ...spawnOpts });\n  } catch (e) {\n    return { child: null, error: e };\n  }\n  // 兜底监听：既用于上报，也用于「吞掉」本可打挂宿主的未捕获 error 事件。\n  child.on(\"error\", (e) => {\n    try { onError?.(e); } catch { /* 回调自身出错不得影响宿主 */ }\n  });\n  return { child, error: null };\n}\n\n/**\n * 派生后台子进程并等它「真的起来了」再返回。\n * 异步启动失败（ENOENT）不抛异常、只在下一个 tick 发 'error' 事件——不等就会误报成功\n * （旧实现的「已调度重启」就是在 spawn 失败的情况下照样返回成功）。\n * @returns {Promise<{child, error}>}\n */\nfunction spawnAndConfirm(command, args, opts = {}) {\n  return new Promise((resolve) => {\n    let child;\n    try {\n      // C1：同 safeSpawn，默认 windowsHide（Windows 上不弹控制台）。\n      child = spawn(command, args, { windowsHide: true, ...opts });\n    } catch (e) {\n      resolve({ child: null, error: e });\n      return;\n    }\n    let settled = false;\n    const settle = (error) => {\n      if (settled) return;\n      settled = true;\n      resolve({ child, error });\n    };\n    child.once(\"error\", (e) => settle(e));\n    child.once(\"spawn\", () => settle(null));\n    child.on(\"error\", () => { /* 已 settle 之后的 error 只吞掉，绝不外抛 */ });\n  });\n}\n\n// ---------- 后台子进程标记（防重入 + 宿主重启自愈） ----------\n// marker 内容 = JSON {pid, at}：pid 供“宿主重启后立即清理死进程残留”判断；\n// 兼容旧格式（纯时间戳数字 → 只按超时清理）。\n\nfunction readMarkerInfo(filePath) {\n  // ⚠️ `raw` 必须声明在 try **之外**：它下面还要用。此前写成 `const raw = …` 在 try 块内，\n  // 于是\"旧格式（纯时间戳数字）标记\"会在这里抛 ReferenceError ——\n  // 所有调用点都被 try/catch 吞掉，表现是**旧格式标记永远不会被清理**（潜伏缺陷，0.6.9 修）。\n  let raw = \"\";\n  try {\n    raw = readFileSync(filePath, \"utf8\").trim();\n    const j = JSON.parse(raw);\n    if (Number.isInteger(j?.pid) || Number.isInteger(j?.at)) return j;\n  } catch { /* 非 JSON → 数字时间戳或空 */ }\n  const t = Number(raw || \"0\");\n  return Number.isFinite(t) && t > 0 ? { pid: null, at: t } : null;\n}\n\nfunction writeMarker(filePath, pid) {\n  mkdirSync(dirname(filePath), { recursive: true });\n  writeFileSync(filePath, JSON.stringify({ pid: pid ?? null, at: Date.now() }), { mode: 0o600 });\n}\n\n/** pid 是否存活（ESRCH=已死）。 */\nfunction pidAlive(pid) {\n  if (!Number.isInteger(pid) || pid <= 0) return null; // 未知 → 由超时规则兜底\n  try {\n    process.kill(pid, 0);\n    return true;\n  } catch (e) {\n    return e.code === \"EPERM\" ? true : false; // EPERM=存在但无权限\n  }\n}\n\n/**\n * 清理残留标记：宿主 dsh web 在后台安装/更新期间被重启/强杀时，子进程清理回调随之丢失，\n * 若只按“30 分钟超时”清理，用户会在这半小时内反复遇到“已有更新进行中/正在安装”。\n * 现在：记录 pid → 重启后立刻清掉已死进程的标记；pid 不可读的旧标记仍按超时兜底。\n */\nfunction sweepStaleMarkers(relayDir) {\n  const now = Date.now();\n  for (const [name, logName, kind] of [\n    [PROVISION_MARKER, AUTO_INSTALL_LOG, \"install\"],\n    [UPDATE_MARKER, UPDATE_LOG, \"update\"],\n  ]) {\n    const p = join(relayDir, name);\n    let info;\n    try { info = readMarkerInfo(p); } catch { continue; }\n    if (!info) continue;\n    const dead = pidAlive(info.pid);\n    const expired = now - info.at > STALE_MARKER_MS;\n    // 【0.6.9 新增】进程**活着但长时间没有推进** → 先结束它再清标记。\n    // 诊断报告 P2：旧实现只看「进程还在不在」，挂死的进程因此永远不被结束，用户每次重试都堆一个。\n    if (dead !== false) {\n      const idle = progressIdleMs(relayDir, logName, info.at);\n      if (idle > stallIdleMs(kind)\n        && killStalledChild(relayDir, logName, info, kind, \"宿主启动清理\")) {\n        stopProgressWatch(kind === \"update\" ? UPDATE_WATCH_KEY : `install:${relayDir}`);\n        try { rmSync(p, { force: true }); } catch { /* ignore */ }\n        continue;\n      }\n    }\n    if (dead === false || (dead === null && expired)) {\n      try { rmSync(p, { force: true }); } catch { /* ignore */ }\n      appendLogLine(relayDir, AUTO_INSTALL_LOG,\n        `[dsh-remote-web] 清理残留标记 ${name}（pid=${info.pid ?? \"?\"}, at=${new Date(info.at).toISOString()}${dead === false ? \", 进程已死\" : \", 已超时\"}）`);\n    }\n  }\n}\n\n/**\n * 复用面板已有的 2~3s 轮询，顺手驱动「卡住的更新」自愈（诊断报告 F5）。\n *\n * 补装之所以能自愈，靠的是「每次轮询都再试一次」（ensureConnection → ensureRuntime）；\n * 而更新路径原先只有一次性 fire-and-forget（全文只有一个调用点），**一旦第一次卡住就再没有任何后续**。\n * 这里把同一套引擎平移到更新上：轮询时若发现「标记在、但日志很久没变」，\n * 就结束进程 + 清标记 + 如实记一条失败（面板据此给「重试」，而不是永久转圈）。\n */\nfunction healStalledJobs(relayDir) {\n  try {\n    const marker = join(relayDir, UPDATE_MARKER);\n    if (!existsSync(marker)) return false;\n    const info = readMarkerInfo(marker);\n    const idle = progressIdleMs(relayDir, UPDATE_LOG, info && info.at);\n    if (idle <= stallIdleMs(\"update\")) return false; // 还在推进：不打扰\n    const killed = killStalledChild(relayDir, UPDATE_LOG, info, \"update\", \"面板轮询发现长时间无输出\");\n    stopProgressWatch(UPDATE_WATCH_KEY);\n    try { rmSync(marker, { force: true }); } catch { /* ignore */ }\n    noteUpdateFailure(relayDir, `更新进程长时间没有响应（已 ${Math.round(idle / 1000)} 秒无输出），已结束并清理，可以重试`, \"update_stalled\");\n    telemetryRecord(relayDir, \"update_failed\", { fail_code: \"update_stalled\" });\n    appendLogLine(relayDir, UPDATE_LOG, `[update] 看门狗：已 ${Math.round(idle / 1000)}s 无输出 → 结束进程(${killed ? \"已结束\" : \"进程已不在\"})并清标记`);\n    return true;\n  } catch { return false; }\n}\n\n/** 读取 JSON body。 */\nasync function readJsonBody(req, maxBytes = 256 * 1024) {\n  let raw = \"\";\n  let n = 0;\n  let tooLarge = false;\n  for await (const chunk of req) {\n    n += chunk.length;\n    if (n > maxBytes) {\n      // 超限：**继续把请求读完**（丢弃内容）再返回，否则客户端可能在等一个没被读完的请求\n      tooLarge = true;\n      raw = \"\";\n      continue;\n    }\n    if (!tooLarge) raw += chunk;\n  }\n  if (tooLarge) return { __tooLarge: true }; // 上限保护：面板只发诊断/报告，256KB 足够\n  if (!raw) return {};\n  try {\n    return JSON.parse(raw);\n  } catch {\n    return { __parseError: true };\n  }\n}\n\n/** 统一 JSON 响应。 */\nfunction sendJson(res, code, body) {\n  const payload = JSON.stringify(body);\n  res.writeHead(code, {\n    \"content-type\": \"application/json; charset=utf-8\",\n    \"cache-control\": \"no-store\",\n  });\n  res.end(payload);\n}\n\n// ---------- 配置读写（与 dsh-setup.mjs 同一份 .dsh-config.json） ----------\n\nfunction configPathOf(relayDir) {\n  return join(relayDir, \".dsh-config.json\");\n}\n\nfunction loadConfig(relayDir) {\n  try {\n    return JSON.parse(readFileSync(configPathOf(relayDir), \"utf8\"));\n  } catch {\n    return {};\n  }\n}\n\nfunction saveConfig(relayDir, cfg) {\n  mkdirSync(dirname(configPathOf(relayDir)), { recursive: true });\n  // mode 0o600：与 dsh-setup.mjs 一致（文件已存在时 writeFileSync 不改权限，显式 chmod 兜底）\n  writeFileSync(configPathOf(relayDir), JSON.stringify(cfg, null, 2), { mode: 0o600 });\n  hardenFile(configPathOf(relayDir)); // Windows 上 mode 是空操作 → 显式收紧 ACL（内含明文账号密码）\n  try {\n    chmodSync(configPathOf(relayDir), 0o600);\n  } catch {\n    /* 非关键 */\n  }\n}\n\n/**\n * SaaS 模式权威归一化（与 dsh-setup.mjs 同规则）：\n * 清除自建残留(local_key/假 tunnel_url)，api_url 与 tunnel_url 一律按云端权威地址重算。\n * 解决“切过自建(填了假地址)后，再登/重装云端账号仍连错服务器、手机看不到设备”的残留配置问题。\n */\nfunction applySaaSMode(cfg) {\n  delete cfg.local_key;\n  delete cfg.server;\n  cfg.api_url = String(cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n  cfg.tunnel_url = cfg.api_url.replace(/\\/relay-api\\/?$/, \"\").replace(/^https/, \"wss\");\n  return cfg;\n}\n\n// ---------- 安装/配对自检 + 配对信息备份（2026-10-17 事故） ----------\n//\n// 事故：用户本机 `~/.dsh-remote`（bridge 运行时 + **账号配对信息/设备密钥**）被误删 →\n// bridge 无法启动、设备离线；手机端镜像页干等 47 秒；面板状态机只显示模糊的「未运行/准备中」，\n// 用户完全不知道该**重新安装**还是该**重新登录**。\n//\n// 这一段的职责（全部只读 + 明确的下一步动作，绝不偷偷替用户做决定）：\n//   ① setupStateOf：把「运行时在不在（clients/）」「配对信息在不在（.dsh-config.json）」分开如实报告，\n//      并给出面向非技术用户的一句话结论（缺什么、下一步做什么）；\n//   ② 运行时缺失 → 复用既有 ensureRuntime 从插件自带 runtime/ 自愈补装（配对缺失**必须用户登录**，\n//      绝不自动填入任何凭据）；\n//   ③ 配对备份（**双份**，2026-10-17 二次加固）：\n//        · 配置目录：<relayDir>/backup/dsh-config-<ISO>.json；\n//        · **插件 profile 下的独立数据目录**：<profile>/dsh-remote-web-data/config-backup/。\n//      真机事故里用户删的是**整个 ~/.dsh-remote 目录** —— 只备份在 relayDir 里等于没备份，\n//      所以必须再存一份在不随 relayDir 删除、也不随插件包升级（`<id>-plugin/` 会被整体替换）\n//      消失的位置。落点与插件 profile 同源（profile 目录推导规则见 pluginProfileDir，与\n//      registerRoutes 用的是同一份），目录 700 / 文件 600 / 每处保留最近 3 份。\n//      启动时发现主配置缺失但备份存在 → **不自动恢复**（防误用旧账号/别人的账号），\n//      只在状态里提示「检测到历史配对备份（时间），可一键恢复」并给恢复入口。\n//\n// 🔒 安全边界（备份文件里是明文密码/设备私钥）：\n//   · 日志只写**文件名与时间**，绝不写内容；状态对象里也不带任何凭据字段；\n//   · 备份失败一律静默（不影响安装/登录；两份里成功一份就算成功）；\n//   · 恢复前先把\"当前状态\"再备份一份（可回滚）；恢复必须由用户在面板里显式点击；\n//   · 彻底卸载时 profile 数据目录里的这份也一起删（否则\"已卸载\"还留着账号密钥，\n//     而且重装后会提示恢复一个用户已经不要了的旧账号）。\n\n/** 配对备份目录（相对 relayDir；第二份在 profile 数据目录，见 PROFILE_* 常量）。 */\nconst CONFIG_BACKUP_DIR = \"backup\";\nconst CONFIG_BACKUP_KEEP = 3;\nconst CONFIG_BACKUP_PREFIX = \"dsh-config-\";\n/** profile 下本插件自己的**独立数据目录**：不随 `<id>-plugin/`（升级时整体替换）消失。 */\nconst PROFILE_DATA_DIR = \"dsh-remote-web-data\";\nconst PROFILE_BACKUP_SUBDIR = \"config-backup\";\n/**\n * 备份来源与优先级：`profile` = 插件 profile 数据目录（抗整目录删除），`relay` = 配置目录。\n * 数组顺序 = 默认优先级（恢复默认选\"最新的一份\"，时间相同时 **profile 胜** ——\n * 它能在 relayDir 整个被删时活下来，是同一次写入里更耐久的那份副本）。\n */\nconst CONFIG_BACKUP_SOURCES = [\"profile\", \"relay\"];\n/** 来源 → 用户可见的中文标签（只说明位置，不含凭据信息）。 */\nconst CONFIG_BACKUP_SOURCE_TEXT = { profile: \"插件持久目录\", relay: \"配置目录\" };\n\n/**\n * 本插件所在的 profile 目录（与 registerRoutes 同一份推导规则：\n * 由插件自身文件位置推导，覆盖市场 git 安装 / 本地 include 两种形态；取不到用默认 web profile）。\n *\n * ⚠️ 为什么不直接用 plugin 包目录：升级/重装会整目录替换 `<profile>/<id>-plugin/`，\n *    放在它里面的备份会跟着没 —— 所以数据目录放在 profile 下的**同级独立目录**。\n */\nfunction pluginProfileDir() {\n  let dir = join(homedir(), \".dsh\", \"profiles\", \"web\");\n  try {\n    const here = fileURLToPath(import.meta.url);\n    // 依次尝试两种安装布局（当前名优先，历史名兜底）；split()[0] 未命中时返回原串，需显式判断后再试下一种\n    let m = here.split(\"/dsh-remote-web-plugin/\")[0];\n    if (m === here) m = here.split(\"/node_modules/dsh-remote-web/\")[0];\n    if (m === here) m = here.split(\"/dsh-remote-ui-plugin/\")[0];\n    if (m === here) m = here.split(\"/node_modules/dsh-remote-ui/\")[0];\n    if (m !== here) dir = m;\n  } catch { /* 保持默认 */ }\n  return dir;\n}\n\n/** 某个来源的备份目录绝对路径。 */\nfunction configBackupDirOf(relayDir, source = \"relay\") {\n  if (source === \"relay\") return join(relayDir, CONFIG_BACKUP_DIR);\n  return join(pluginProfileDir(), PROFILE_DATA_DIR, PROFILE_BACKUP_SUBDIR);\n}\n\n/** 人类可读时间（只用于状态/日志的\"时间\"提示，不含任何凭据）。 */\nfunction fmtLocalTime(ms) {\n  const n = Number(ms);\n  if (!Number.isFinite(n) || n <= 0) return \"\";\n  try {\n    const d = new Date(n);\n    const p = (v) => String(v).padStart(2, \"0\");\n    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;\n  } catch { return \"\"; }\n}\n\n/** 备份文件名的唯一合法形态（时间戳 + 可选序号；拒绝任何路径成分）。 */\nconst CONFIG_BACKUP_FILE_RE = /^dsh-config-[\\w.-]+\\.json$/;\n\n/**\n * 列出**某一个来源**的备份（新 → 旧）。只读目录；**绝不读取/返回备份文件内容**。\n * @returns {Array<{source:string, file:string, name:string, at:number, size:number}>}\n */\nfunction listConfigBackupsIn(relayDir, source) {\n  try {\n    const dir = configBackupDirOf(relayDir, source);\n    const files = readdirSync(dir).filter((n) => CONFIG_BACKUP_FILE_RE.test(String(n)));\n    return files.map((file) => {\n      let at = 0;\n      let size = 0;\n      try {\n        const st = statSync(join(dir, file));\n        at = Number(st.mtimeMs) || 0;\n        size = Number(st.size) || 0;\n      } catch { /* 文件刚被删/无权限：忽略该项时间 */ }\n      // name 里体现来源：profile:<file> / relay:<file>（状态/恢复接口都用它，绝不把绝对路径发散出去）\n      return { source, file, name: `${source}:${file}`, at, size };\n    });\n  } catch { return []; }\n}\n\n/**\n * 列出**两个来源合并**后的备份（新 → 旧）。\n * 时间相同时 **profile 排前面**（默认优先恢复它，见 CONFIG_BACKUP_SOURCES 注释）。\n * @returns {Array<{source:string, file:string, name:string, at:number, size:number}>}\n */\nfunction listConfigBackups(relayDir) {\n  const order = new Map(CONFIG_BACKUP_SOURCES.map((s, i) => [s, i]));\n  const all = [];\n  for (const source of CONFIG_BACKUP_SOURCES) all.push(...listConfigBackupsIn(relayDir, source));\n  return all.sort((a, b) => (b.at - a.at) || ((order.get(a.source) ?? 9) - (order.get(b.source) ?? 9))\n    || String(b.file).localeCompare(String(a.file)));\n}\n\n/**\n * 解析用户/状态给出的备份引用 → 列表里的真实条目（**只认列表内文件**，防路径穿越/任意文件读）。\n *   · 省略 / 空串 → 默认：最新一份（时间相同优先 profile）\n *   · `profile:<file>` / `relay:<file>` → 指定来源（状态里下发的就是这种 name）\n *   · 裸 `<file>` → 兼容旧状态（2026-10-17 之前只写 relay 一份）：两个来源里找，命中多个时优先 profile\n * @returns {{source:string,file:string,name:string,at:number,size:number}|null}\n */\nfunction findConfigBackup(relayDir, ref = \"\") {\n  const raw = String(ref || \"\").trim();\n  const all = listConfigBackups(relayDir);\n  if (!all.length) return null;\n  if (!raw) return all[0]; // listConfigBackups 已按\"新→旧、时间相同 profile 先\"排好\n  if (/[\\\\/]/.test(raw) || raw.includes(\"..\")) return null; // 明显是路径/穿越：直接拒绝\n  const m = /^(profile|relay):(.+)$/.exec(raw);\n  if (m) return all.find((b) => b.source === m[1] && b.file === m[2]) || null;\n  // 裸文件名（兼容旧状态）：同名的可能两份都在 → 优先 profile\n  const hits = all.filter((b) => b.file === raw);\n  return hits.find((b) => b.source === \"profile\") || hits[0] || null;\n}\n\n/** 只保留**每个来源**最近 CONFIG_BACKUP_KEEP 份（更老的删掉；失败静默）。 */\nfunction pruneConfigBackups(relayDir, keep = CONFIG_BACKUP_KEEP) {\n  for (const source of CONFIG_BACKUP_SOURCES) {\n    try {\n      const all = listConfigBackupsIn(relayDir, source);\n      for (const b of all.slice(Math.max(0, keep))) {\n        try { rmSync(join(configBackupDirOf(relayDir, source), b.file), { force: true }); } catch { /* 忽略 */ }\n      }\n    } catch { /* 单个来源失败不影响另一个 */ }\n  }\n}\n\n/**\n * 把当前 `.dsh-config.json` **同时**复制到两处（relayDir/backup 与 profile 数据目录），\n * 每处权限 600（目录 700）、各保留最近 3 份。\n *\n * 调用点：① 面板登录/配对成功（POST /dsh-remote/config）；② 运行环境安装完成（ensureRuntime 成功）；\n *         ③ 恢复前先备份当前状态。\n * 🔒 日志只写文件名+时间，**绝不写内容**；任何失败静默返回，绝不影响安装/登录主流程。\n *    单个落点失败（例如 relayDir 只读）不影响另一份成功 —— 至少有一份就返回 ok。\n * @returns {{ok:boolean, at?:number, name?:string, sources?:{profile?:string, relay?:string}, reason?:string}}\n *          name = 默认恢复会选中的那一份（profile 优先）；sources = 两个落点各自的文件名\n */\nfunction backupConfigFile(relayDir) {\n  try {\n    const src = configPathOf(relayDir);\n    if (!existsSync(src)) return { ok: false, reason: \"no-config\" }; // 还没配对：无可备份\n    const at = Date.now();\n    const stamp = new Date(at).toISOString().replace(/[:.]/g, \"-\");\n    const sources = {};\n    for (const source of CONFIG_BACKUP_SOURCES) {\n      try {\n        const dir = configBackupDirOf(relayDir, source);\n        mkdirSync(dir, { recursive: true, mode: 0o700 });\n        // 文件名只含时间戳（不含账号/手机号等任何内容）；同一毫秒重复备份时加序号，绝不覆盖已有备份\n        let file = `${CONFIG_BACKUP_PREFIX}${stamp}.json`;\n        for (let i = 2; existsSync(join(dir, file)) && i < 100; i += 1) {\n          file = `${CONFIG_BACKUP_PREFIX}${stamp}-${i}.json`;\n        }\n        copyFileSync(src, join(dir, file));\n        // 备份里是明文密码/设备私钥：POSIX 上 0600；Windows 显式收紧 ACL（mode 是空操作）\n        try { chmodSync(join(dir, file), 0o600); } catch { /* 非关键 */ }\n        try { hardenFile(join(dir, file)); } catch { /* 非关键 */ }\n        sources[source] = file;\n      } catch { /* 单个落点失败：另一份仍然有效（relayDir 只读/磁盘满等情况） */ }\n    }\n    if (!Object.keys(sources).length) return { ok: false, reason: \"failed\" }; // 两份都失败：静默返回\n    pruneConfigBackups(relayDir);\n    // 日志只写文件名与时间（两份各列出，便于排查到底哪一份没写成）\n    const names = CONFIG_BACKUP_SOURCES.filter((s) => sources[s]).map((s) => `${s}:${sources[s]}`).join(\"、\");\n    appendLogLine(relayDir, AUTO_INSTALL_LOG,\n      `[dsh-remote-web] 已备份配对配置 ${names}（${fmtLocalTime(at)}，权限 600；内容不写入日志）`);\n    const preferred = sources.profile ? `profile:${sources.profile}` : `relay:${sources.relay}`;\n    return { ok: true, at, name: preferred, sources };\n  } catch {\n    return { ok: false, reason: \"failed\" }; // 备份失败静默：绝不影响安装/登录\n  }\n}\n\n/**\n * 从备份恢复配对配置。**只能由用户在面板里显式触发**（绝不自动调用 —— 旧账号备份可能是\n * 别人的/已失效的，误用会把设备绑到错误账号）。\n * 恢复前先把当前配置再备份一份（同时写两份），失败静默。\n * @param {string} relayDir\n * @param {string} [name] `profile:<file>` / `relay:<file>` / 裸文件名（兼容旧状态）；省略 = 最新一份\n * @returns {{ok:boolean, restored?:string, source?:string, at?:number, reason?:string}}\n */\nfunction restoreConfigBackup(relayDir, name = \"\") {\n  try {\n    const list = listConfigBackups(relayDir);\n    if (!list.length) return { ok: false, reason: \"no-backup\" };\n    // ⚠️ 只接受**列表里真实存在**的文件名（防路径穿越/任意文件读）\n    const target = findConfigBackup(relayDir, name);\n    if (!target) return { ok: false, reason: \"no-such-backup\" };\n    const src = join(configBackupDirOf(relayDir, target.source), target.file);\n    if (existsSync(configPathOf(relayDir))) backupConfigFile(relayDir); // 恢复前先备份当前状态（可回滚）\n    mkdirSync(relayDir, { recursive: true });\n    copyFileSync(src, configPathOf(relayDir));\n    try { chmodSync(configPathOf(relayDir), 0o600); } catch { /* 非关键 */ }\n    try { hardenFile(configPathOf(relayDir)); } catch { /* 非关键 */ }\n    appendLogLine(relayDir, AUTO_INSTALL_LOG,\n      `[dsh-remote-web] 用户一键恢复配对配置：${target.name}`\n      + `（来自${CONFIG_BACKUP_SOURCE_TEXT[target.source] || target.source}，备份时间 ${fmtLocalTime(target.at)}；内容不写入日志）`);\n    return { ok: true, restored: target.name, source: target.source, at: target.at };\n  } catch {\n    return { ok: false, reason: \"failed\" };\n  }\n}\n\n/** 运行时本体是否在：`<relayDir>/clients`（插件自带 runtime/ 自愈补装的就是它）。 */\nfunction runtimeDirPresent(relayDir) {\n  try { return existsSync(join(relayDir, \"clients\")); } catch { return false; }\n}\n\n/** 配对信息是否在：`<relayDir>/.dsh-config.json`（账号密码 + 设备密钥）。 */\nfunction configPresent(relayDir) {\n  try { return existsSync(configPathOf(relayDir)); } catch { return false; }\n}\n\n/**\n * 安装/配对自检（对外状态的核心）：明确区分「运行时缺失」与「配对缺失」。\n *\n * kind：ok | runtime_missing | pairing_missing | all_missing | uninstalled\n * text：面向非技术用户的一句话结论（面板直接展示；旧客户端也可从 connect.detail 看到）\n * @returns {{kind:string, runtimePresent:boolean, configPresent:boolean, text:string, detail:string,\n *            relayDir:string, backup:null|{available:boolean,name:string,at:number,text:string,action:object}}}\n */\nfunction setupStateOf(relayDir) {\n  const rt = runtimeDirPresent(relayDir);\n  const cfg = configPresent(relayDir);\n  // 两份来源合并（新→旧；时间相同 profile 先）。只要任一份存在就能恢复 ——\n  // 这正是「整个 ~/.dsh-remote 被删、但 profile 持久目录那份还在」时的救命路径。\n  const backups = listConfigBackups(relayDir);\n  const latest = backups[0] || null;\n  const backup = (!cfg && latest)\n    ? {\n        available: true,\n        name: latest.name,      // profile:<file> / relay:<file>（来源可区分）\n        source: latest.source,  // profile | relay\n        at: latest.at,\n        // 两份都在时把清单也带上（面板/诊断可以显示\"还有哪一份\"）；仍不含任何凭据内容\n        sources: backups.map((b) => ({ name: b.name, at: b.at })),\n        text: `检测到历史配对备份（${fmtLocalTime(latest.at) || \"时间未知\"}，`\n          + `${CONFIG_BACKUP_SOURCE_TEXT[latest.source] || latest.source}），可一键恢复`,\n        action: {\n          kind: \"restore_config\",\n          method: \"POST\",\n          path: \"/dsh-remote/config/restore\",\n          body: { backup: latest.name },\n        },\n      }\n    : null;\n  const base = { runtimePresent: rt, configPresent: cfg, relayDir, backup };\n\n  // 已彻底卸载：不再提示\"重新安装\"（那是用户自己的选择；重启宿主后自然回到未安装状态）\n  if (UNINSTALLED_DIRS.has(relayDir)) {\n    return { ...base, kind: \"uninstalled\", text: \"\", detail: \"本插件已彻底卸载（配置与运行时已清理）\" };\n  }\n\n  const RUNTIME_TEXT = \"运行环境缺失：需要重新安装（应用内插件页重装或 npx @mrrisega/dsh-remote@latest）\";\n  const PAIRING_TEXT = \"未配对：需要在面板里登录一次（账号密码），登录后会自动重建运行环境并启动 bridge\";\n  const runtimeDetail = () => {\n    const inst = installStateOf(relayDir);\n    if (inst.installing) return \"插件正在后台用自带的运行环境自动补装（无需操作）；若 1~2 分钟后仍缺失，请按上面方式重新安装。\";\n    return \"插件会在下一轮状态查询时自动尝试用自带的运行环境补装；若补装失败，请按上面方式重新安装。\";\n  };\n  const pairingDetail = () => (backup\n    ? `登录会重新生成配对信息；也可以先点「恢复历史配对备份」（${fmtLocalTime(latest.at) || \"时间未知\"}）再用旧配对。`\n    : \"登录是唯一会写入配对信息的入口：插件绝不自动填入任何凭据。\");\n\n  if (!rt && !cfg) {\n    return { ...base, kind: \"all_missing\", text: RUNTIME_TEXT + \"\\n\" + PAIRING_TEXT,\n      detail: runtimeDetail() + \" \" + pairingDetail() };\n  }\n  if (!rt) {\n    return { ...base, kind: \"runtime_missing\", text: RUNTIME_TEXT, detail: runtimeDetail() };\n  }\n  if (!cfg) {\n    return { ...base, kind: \"pairing_missing\", text: PAIRING_TEXT, detail: pairingDetail() };\n  }\n  return { ...base, kind: \"ok\", text: \"\", detail: \"\" };\n}\n\n// ---------- Harness 浏览器会话代持(0.1.2-rc.1+ 的 ?token 鉴权) ----------\n\n/**\n * 新版 dsh web(0.1.2-rc.1+)启动会打印带 ?token= 的 URL,并只给\"换到了会话 Cookie\"的浏览器放行,\n * 其余请求一律 401(手机经隧道因此白页)。本插件与 Harness 同进程:\n *  - 通过 ctx.connection 服务拿到本进程 launch token(authenticatedUrl 自带 token);\n *  - 在本地向 /?token=… 发起 token 交换,捕获下发的 dsh-auth-* 会话 Cookie;\n *  - 写入 <relayDir>/.harness-cookie.json,bridge 上游转发时自动携带,让手机表现为已授权浏览器。\n * 老版本(无该鉴权)下 connection 服务没有 authenticatedUrl → 静默跳过,行为不变。\n */\nconst HARNESS_COOKIE_FILE = \".harness-cookie.json\";\n/**\n * fetch 失败时**把真实原因带出来**（2026-10-10）。\n * undici 只给一句 \"fetch failed\"，真因藏在 `e.cause`（ECONNREFUSED / ENOTFOUND /\n * CERT_HAS_EXPIRED / UND_ERR_CONNECT_TIMEOUT / 代理相关…）。以前这层被吞掉，\n * 于是面板上只有\"验证码服务不可达: fetch failed\"，排查只能猜。\n */\nfunction fetchFailReason(e) {\n  const parts = [String((e && e.message) || e)];\n  let c = e && e.cause;\n  for (let i = 0; c && i < 3; i += 1) {\n    const bit = c.code || c.message || c.name;\n    if (bit) parts.push(String(bit));\n    c = c.cause;\n  }\n  try { if (e && e.name && !parts.includes(e.name)) parts.push(String(e.name)); } catch { /* 忽略 */ }\n  return [...new Set(parts)].join(\" ← \");\n}\n\n/**\n * Cookie 按 **authority 分文件**(0.7.0-beta.2 起,2026-10-09 故障根治)。\n *\n * 【故障】`~/.dsh-remote/` 只有一份 `.harness-cookie.json`,而 Web 端(3080)与桌面端(每次启动\n *   随机端口)是**两个宿主进程**,各自的插件都往里写\"自己 authority 的 Cookie\" → 互相覆盖。\n *   桥撞 401 后重读磁盘,拿到的是另一个宿主刚写的 Cookie → 重试 → 还是 401 → 再读 → 又被\n *   覆盖回去……**乒乓,永不自愈**,手机端持续白页(现象与\"自愈坏了\"一模一样,极易误判)。\n * 【根治】每个宿主只写自己 authority 的文件:`.harness-cookie.<authority>.json`\n *   (`:` → `_`,如 `.harness-cookie.127.0.0.1_19387.json`),互不覆盖。旧版共享文件继续**写**\n *   一份镜像(旧桥还能用),但新桥只认当前上游 authority 的那一份,foreign 一律跳过。\n *   命名规则与桥半 `clients/dsh-remote/dsh-bridge.mjs` 同名,漂移由\n *   `clients/dsh-remote/test/harness-cookie-authority.test.mjs` 的跨文件不变量锁住。\n */\nfunction authoritySlug(authority) {\n  return String(authority).replace(/[^A-Za-z0-9._-]/g, \"_\");\n}\n/** 本宿主专属 Cookie 文件名(与桥半同规则)。 */\nfunction harnessCookieFileFor(authority) {\n  return `${HARNESS_COOKIE_FILE.slice(0, -\".json\".length)}.${authoritySlug(authority)}.json`;\n}\n/** 本宿主专属「作废」标记名(与桥半同规则)。 */\nfunction harnessCookieRevokedFileFor(authority) {\n  return `${HARNESS_COOKIE_REVOKED_FILE}.${authoritySlug(authority)}`;\n}\n/** 由本进程 webServer 端口推出 authority(与 bridge 的 Host 约定一致)。 */\nfunction harnessAuthorityOfPort(port) {\n  return port ? `127.0.0.1:${port}` : \"\";\n}\n/**\n * 手机端 401「dsh web authentication required; reopen the URL printed by dsh web」的根因就在这里：\n * 该 Cookie 由本插件在进程内经 ?token= 换取后交给 bridge 代持，**dsh web 每次重启都会换签名密钥**，\n * 旧 Cookie 立即失效。旧实现只在启动后重试 20 次(约 60s)就放弃、之后 6 小时才刷新一次 ——\n * 一旦启动那一刻 connection 服务还没就绪（或用户按引导重启 harness 后插件先于服务就绪），\n * Cookie 就会长时间不可用，手机端看到那段英文提示且**无法自行恢复**（他打不开电脑上打印的 URL）。\n * 现在改为：① 启动后持续重试 10 分钟；② 每 30 分钟主动刷新；③ 面板每次查状态时按需补齐；\n * ④ bridge 撞到 401 会写「作废」标记，插件下次查状态立即重取。四处叠加后用户无需任何操作。\n */\nconst HARNESS_AUTH_RETRY_MS = 3000;\nconst HARNESS_AUTH_RETRY_WINDOW_MS = 10 * 60 * 1000; // 持续尝试 10 分钟,不再 60s 后放弃\nconst HARNESS_AUTH_REFRESH_MS = 30 * 60 * 1000;      // 主动刷新周期(本地一次 fetch,成本可忽略)\nconst HARNESS_COOKIE_STALE_MS = 30 * 60 * 1000;      // 超过视为陈旧 → 按需重取\nconst HARNESS_COOKIE_REVOKED_FILE = \".harness-cookie-revoked\"; // bridge 撞 401 时写的标记\n\n/** 读取响应里的 set-cookie(兼容 getSetCookie / get 两种实现)。 */\nfunction setCookieOf(res) {\n  try {\n    if (typeof res.headers.getSetCookie === \"function\") return res.headers.getSetCookie().join(\"; \");\n  } catch { /* ignore */ }\n  return res.headers.get(\"set-cookie\") || \"\";\n}\n\nasync function mintHarnessCookie(ctx, relayDir) {\n  if (UNINSTALLED_DIRS.has(relayDir)) return false; // 已彻底卸载：不再代持会话、不再重建配置目录\n  try {\n    const port = ctx.webServer?.port;\n    if (!port) return false;\n    // 不能把 \"connection\" 写进 inject(0.1.1 无该服务会拖死激活),只能运行时 try 获取\n    let holder;\n    try { holder = ctx.get(\"connection\"); } catch { holder = void 0; }\n    if (!holder && ctx.connection !== void 0) { try { holder = ctx.connection; } catch { /* ignore */ } }\n    const svc = holder && typeof holder.authenticatedUrl === \"function\"\n      ? holder\n      : holder && holder.connection && typeof holder.connection.authenticatedUrl === \"function\"\n        ? holder.connection\n        : null;\n    if (!svc) return false; // 老版本无浏览器鉴权 → 无需 cookie\n    const tokenUrl = svc.authenticatedUrl(`http://127.0.0.1:${port}`);\n    const res = await fetch(tokenUrl, { redirect: \"manual\", signal: AbortSignal.timeout(6000) });\n    const cookie = setCookieOf(res).split(\";\")[0].trim();\n    if (!cookie || !cookie.startsWith(\"dsh-auth-\")) return false;\n    // 竞态兜底：fetch 期间用户点击了「彻底卸载」→ 不得重建已被清空的配置目录\n    if (UNINSTALLED_DIRS.has(relayDir)) return false;\n    const out = { authority: `127.0.0.1:${port}`, cookie, mintedAt: Date.now() };\n    mkdirSync(dirname(configPathOf(relayDir)), { recursive: true });\n    // ① 本宿主专属文件(权威,两个宿主互不覆盖 —— 故障根治点)\n    const ownPath = join(relayDir, harnessCookieFileFor(out.authority));\n    writeFileSync(ownPath, JSON.stringify(out, null, 2), { mode: 0o600 });\n    hardenFile(ownPath); // 会话 Cookie ≈ dsh web 的完整访问权，同样要收紧\n    // ② 旧版共享文件镜像:只为还跑着旧桥(<0.7.0-beta.2)的机器保留 —— 新桥优先读 ①,\n    //    且对 authority 不符的镜像**直接跳过**,所以这里写镜像不会再引发乒乓。\n    const legacyPath = join(relayDir, HARNESS_COOKIE_FILE);\n    writeFileSync(legacyPath, JSON.stringify(out, null, 2), { mode: 0o600 });\n    hardenFile(legacyPath);\n    return true;\n  } catch {\n    return false;\n  }\n}\n\n/**\n * 读取当前 authority 可用的 Cookie 文件状态:{cookie, authority, mintedAt} 或 null。\n *   ① 本宿主专属文件优先;\n *   ② 旧版共享文件仅在 authority 对得上、或旧插件没写 authority 字段(兼容)时采用;\n *   ③ 声明了别的 authority → 明确不用(那属于另一个宿主,用了必然 401)。\n * @param {string} relayDir 配置目录\n * @param {string} [authority] 本进程 authority(`127.0.0.1:<port>`);缺省只做兼容读取\n */\nfunction readHarnessCookie(relayDir, authority) {\n  const read = (file) => {\n    try {\n      const j = JSON.parse(readFileSync(join(relayDir, file), \"utf8\"));\n      return j && typeof j.cookie === \"string\" && j.cookie ? j : null;\n    } catch {\n      return null;\n    }\n  };\n  if (authority) {\n    const own = read(harnessCookieFileFor(authority));\n    if (own) return own;\n  }\n  const legacy = read(HARNESS_COOKIE_FILE);\n  if (!legacy) return null;\n  const claimed = typeof legacy.authority === \"string\" ? legacy.authority : \"\";\n  if (claimed === \"\" || !authority || claimed === authority) return legacy;\n  return null; // foreign authority:另一个宿主的 Cookie,本宿主用不了\n}\n\nlet harnessMintInflight = false;\nlet harnessMintLastAt = 0;\n\n/**\n * 按需确保 Cookie 可用(去重 + 限频):\n *   缺失 / 超过 HARNESS_COOKIE_STALE_MS / bridge 写了作废标记 → 重取一次。\n * 被 /dsh-remote/status 与 /dsh-remote/bridge-status 调用(面板轮询 2.5~30s),\n * 因此只要面板开着,手机端 401 会在秒级内自愈;不需要用户做任何事。\n * @param {object} ctx cordis 上下文\n * @param {string} relayDir 配置目录\n * @param {{force?: boolean}} [opts]\n * @returns {Promise<boolean>} 本次是否确认 Cookie 可用\n */\nasync function ensureHarnessCookie(ctx, relayDir, opts) {\n  const force = !!(opts && opts.force);\n  const authority = harnessAuthorityOfPort(ctx.webServer?.port);\n  const ownRevokedPath = authority ? join(relayDir, harnessCookieRevokedFileFor(authority)) : \"\";\n  const legacyRevokedPath = join(relayDir, HARNESS_COOKIE_REVOKED_FILE);\n  const cur = readHarnessCookie(relayDir, authority);\n  // 作废标记两个来源:\n  //   ① 本宿主专属标记(新桥 0.7.0-beta.2+ 写)—— 精确,不会被人家的 401 催着重换;\n  //   ② 旧版共享标记(旧桥写)—— 仅当它**晚于**我们手上这份 Cookie 时才认:说明是它被拒了。\n  //      否则(比如另一个宿主刚被拒、标记比我们的 Cookie 还旧)不理会,避免两个宿主互相催。\n  let revoked = ownRevokedPath !== \"\" && existsSync(ownRevokedPath);\n  if (!revoked && existsSync(legacyRevokedPath)) {\n    try {\n      const revokedAt = Number(readFileSync(legacyRevokedPath, \"utf8\").trim()) || 0;\n      revoked = !cur || revokedAt > Number(cur.mintedAt || 0);\n    } catch { /* 标记读不到就当没有 */ }\n  }\n  if (!force && !revoked) {\n    if (cur && Date.now() - Number(cur.mintedAt || 0) < HARNESS_COOKIE_STALE_MS) return true;\n  }\n  if (harnessMintInflight) return false;              // 去重:同一时刻只换一次\n  if (Date.now() - harnessMintLastAt < 5000) return false; // 限频:5s 内不重复换\n  harnessMintInflight = true;\n  harnessMintLastAt = Date.now();\n  try {\n    const ok = await mintHarnessCookie(ctx, relayDir);\n    if (ok || revoked) {\n      // 清标记:① 本宿主专属标记(精确);② 旧版共享标记(旧桥写的,清了不影响新桥)。\n      // 代价:多宿主机器上可能清掉\"另一个宿主\"的旧标记 —— 那只让对方的**快速**自愈退化成\n      // 30 分钟周期刷新,不会造成错误状态,故不做更细的归属判定(复杂度不值)。\n      if (ownRevokedPath) { try { rmSync(ownRevokedPath, { force: true }); } catch { /* ignore */ } }\n      try { rmSync(legacyRevokedPath, { force: true }); } catch { /* ignore */ }\n    }\n    if (!ok && revoked) console.warn(\"[dsh-remote-web] 浏览器会话 Cookie 已被 dsh web 作废,重取失败,下次查状态再试\");\n    return ok;\n  } finally {\n    harnessMintInflight = false;\n  }\n}\n\n/** 后台调度:启动后持续重试(10 分钟窗口) + 每 30 分钟主动刷新(与插件生命周期同进退)。 */\nfunction scheduleHarnessMint(ctx, relayDir) {\n  const startedAt = Date.now();\n  const bootIv = setInterval(() => {\n    if (Date.now() - startedAt > HARNESS_AUTH_RETRY_WINDOW_MS) { clearInterval(bootIv); return; }\n    void ensureHarnessCookie(ctx, relayDir, { force: true }).catch(() => {});\n  }, HARNESS_AUTH_RETRY_MS);\n  bootIv.unref?.();\n  void ensureHarnessCookie(ctx, relayDir, { force: true }).catch(() => {}); // 立刻来一次\n  const refreshIv = setInterval(() => {\n    void ensureHarnessCookie(ctx, relayDir).catch(() => {});\n  }, HARNESS_AUTH_REFRESH_MS);\n  refreshIv.unref?.();\n  return () => {\n    clearInterval(bootIv);\n    clearInterval(refreshIv);\n  };\n}\n\n// ---------- 桌面运行环境就绪判定 / 系统级操作开关 ----------\n\n/**\n * 入口脚本（`<relayDir>/dsh-setup.mjs`）**声明要用到的**运行时文件清单。\n *\n * 为什么要解析入口脚本、而不是写死一张文件表：\n *   · 写死会与运行时版本漂移（0.6.x 期间 clients/ 下文件增删过多次），漏一个就把好机器误判成坏机器；\n *   · 入口脚本自己「点名」的文件就是它启动/拉起 bridge 时**必然**要读到的文件，是唯一稳定的真相源。\n * 解析规则：只认**带引号的相对路径字面量**（注释里用反引号提到的名字不算），避免被说明文字误伤。\n * 再对每个点名的脚本做一次有界闭包展开（它的 `./x.mjs` 相对导入同样必须存在）。\n *\n * 结果按「入口文件的 mtime+size」缓存：面板 2~3s 轮询一次，不能每次都读 200KB 源码；\n * 而入口一变（补装/更新）键就变，立刻重算——依赖文件后来补齐时靠 existsSync 当场看到。\n */\nconst RUNTIME_MANIFEST_CACHE = new Map();\nconst RUNTIME_REF_RE = /[\"'](?:\\.\\/)?(clients[\\\\/]dsh-remote[\\\\/][^\"'\\n]+?\\.mjs)[\"']/g;\nconst RUNTIME_IMPORT_RE = /from\\s+[\"']\\.\\/([^\"'\\n]+\\.mjs)[\"']/g;\n/** 闭包展开深度上限：入口 → dsh-bridge.mjs → 其直接依赖（实测正好 2 层）。 */\nconst RUNTIME_CLOSURE_DEPTH = 4;\n\nfunction runtimeManifest(relayDir) {\n  const entry = join(relayDir, \"dsh-setup.mjs\");\n  let key = \"\";\n  try {\n    const st = statSync(entry);\n    key = `${st.mtimeMs}:${st.size}`;\n  } catch {\n    return []; // 入口不存在 → 由 missingRuntimeFiles 单独报告\n  }\n  const cached = RUNTIME_MANIFEST_CACHE.get(relayDir);\n  if (cached && cached.key === key) return cached.files;\n  let src = \"\";\n  try { src = readFileSync(entry, \"utf8\"); } catch { return []; }\n  const files = new Set();\n  const queue = [...src.matchAll(RUNTIME_REF_RE)].map((m) => m[1].replace(/\\\\/g, \"/\"));\n  for (let i = 0; i < queue.length && i < 64; i += 1) {\n    const rel = queue[i];\n    if (files.has(rel)) continue;\n    files.add(rel);\n    if (queue.length > RUNTIME_CLOSURE_DEPTH * 16) break; // 上限兜底：异常源码不至于把这里拖死\n    let body = \"\";\n    try { body = readFileSync(join(relayDir, rel), \"utf8\"); } catch { continue; } // 缺文件由调用方报告\n    const dir = dirname(rel);\n    for (const m of body.matchAll(RUNTIME_IMPORT_RE)) {\n      const next = join(dir, m[1]).replace(/\\\\/g, \"/\");\n      if (!files.has(next) && !queue.includes(next)) queue.push(next);\n    }\n  }\n  const list = [...files];\n  RUNTIME_MANIFEST_CACHE.set(relayDir, { key, files: list });\n  return list;\n}\n\n/**\n * 桌面运行环境缺失/不完整的文件清单（空 = 就绪）。\n *\n * 【2026-09-23 用户实测故障】判据原本是「`dsh-setup.mjs` 存在即就绪」——**存在 ≠ 能加载**。\n * npx 补装是「先拷入口脚本、再递归拷 clients/」，中途被打断（用户关窗口 / 杀软锁文件 /\n * 机器休眠 / 看门狗判超时结束进程）就会留下一个**只有入口脚本的半装运行时**。此后：\n *   · runtimeReady() 恒为 true → 插件再也不补装（自愈彻底停摆）；\n *   · 面板如实显示「运行环境: 已就绪」，而插起来的 watcher **秒退**（Cannot find module …）；\n *   · 用户看到的是「连接阶段: starting」+「最近错误: 无」永远不动 —— 正是那份用户反馈。\n * 现在改成「入口脚本点名的文件真的都在」，半装运行时会被判为缺失 → 走既有的自动补装链路自愈。\n */\nfunction missingRuntimeFiles(relayDir) {\n  if (!existsSync(join(relayDir, \"dsh-setup.mjs\"))) return [\"dsh-setup.mjs\"];\n  /* ⚠️ 已知盲区（2026-10-10 发现，**暂不做 gating**）：bridge 顶层 `import WebSocket from \"ws\"` 是裸依赖，\n     而 runtimeManifest 只跟**相对路径 import**，所以\"运行环境里有没有 ws\"从未进过这份自检。\n     试过把 `node_modules/ws` 加进必需清单，但真实语义是 **Node 会向上找 node_modules**\n     （~/.dsh-remote/node_modules/ws 与宿主/父级 node_modules 都可能提供它），\n     按\"某个固定路径必须存在\"判会误伤 —— 实测直接打挂 17 个连接流程用例，且真实机器上\n     ws 本来就解析得到（已验证）。所以这里保持\"只判入口点名的相对文件\"，\n     根治放在**源头**：安装器拷贝插件时必须保留 `runtime/node_modules`（已修 + 有用例），\n     以及 `npm run sync:local` 会把 ws 一并同步到 relayDir。 */\n  return runtimeManifest(relayDir).filter((rel) => !existsSync(join(relayDir, rel)));\n}\n\n/**\n * 桌面运行环境是否就绪：入口脚本存在 **且** 它声明要用到的文件都在\n * （只装「插件半」时入口本身不存在，必须先补装；半装运行时同样判为缺失以便自愈）。\n */\nfunction runtimeReady(relayDir) {\n  return missingRuntimeFiles(relayDir).length === 0;\n}\n\n/**\n * 系统级操作总开关（测试隔离）：置位后不做 launchctl / npx 安装 / 杀进程等一切真实系统操作。\n * 生产环境绝不设置；测试与 CI 必须设置，否则用例会去碰本机真实的 bridge 自启动服务。\n */\nfunction skipsSystemOps() {\n  return process.env.DSH_RELAY_SKIP_SERVICE === \"1\";\n}\n\n// ---------- bridge 服务状态 / 启停（launchctl，macOS） ----------\n\nfunction launchAgentPath() {\n  if (isDarwin()) return join(homedir(), \"Library/LaunchAgents/com.dshremote.bridge.plist\");\n  return null;\n}\n/**\n * ★ 这份自启动 plist 是否**确实是为本 relayDir 装的**（内容里写着 `<relayDir>/dsh-setup.mjs`）。\n *\n * 🔴 2026-10-10 故障（两次，同一根因）：`reapBrokenAutostart()` 用**当前 relayDir** 判断\n *   \"入口脚本缺失\"（测试的临时 relayDir 当然没有 dsh-setup.mjs → 判 true），\n *   但删除的却是 `launchAgentPath()` = **真实 HOME 下那份 plist** → 把开发者本机的自启动\n *   连 bootout 带删文件一起干掉了（远程访问中断，且日志里看不出异常）。\n *   判据与删除目标必须是**同一个东西**：先确认这份 plist 属于本 relayDir，再动手。\n */\nfunction plistOwnedByRelayDir(relayDir) {\n  try {\n    const p = launchAgentPath();\n    if (!p || !existsSync(p)) return false;\n    return readFileSync(p, \"utf8\").includes(join(relayDir, \"dsh-setup.mjs\"));\n  } catch { return false; }\n}\n\n\n/**\n * Linux 的 systemd user unit 路径（与 dsh-setup.mjs 的 `autostartFilePath()` **同一路径**）。\n * 为什么插件半也要写这个文件：插件自愈（scheduleRuntime）是\"用户在面板里点什么就修什么\"的那条路，\n * 它以前在 Linux 上只会调 `systemctl --user restart`，而 unit 可能压根不存在。\n */\nfunction linuxUnitPath() {\n  if (!isLinux()) return null;\n  return join(homedir(), \".config/systemd/user/dsh-bridge.service\");\n}\n\n/**\n * 本机到底有没有**可用的 user systemd 会话**。\n *\n * 为什么必须先问：飞牛 fnOS / 群晖这类 NAS 上，插件跑在**系统服务**里（不是登录会话），\n * 没有 `XDG_RUNTIME_DIR`、也没有 `systemd --user` 的 user manager —— 这时 `systemctl --user`\n * 会直接报 \"Failed to connect to bus\"，unit 写多少份都没用。以前插件在这条路上只会返回\n * \"不支持自启动\"，bridge 于是**从来没被拉起来过**（用户诊断里 `bridge 进程: 未运行`）。\n */\nfunction systemdUserAvailable() {\n  if (!isLinux()) return false;\n  if (!process.env.XDG_RUNTIME_DIR) return false; // 没有 runtime dir 就不可能有 user manager\n  return sh(\"systemctl --user show-environment\").ok;\n}\n\n/**\n * 上面那个判断的**带缓存**版本（面板 2~3 秒轮询一次 /status，不能每次都起一个 systemctl）。\n * 60 秒 TTL：用户装了 systemd 会话/登出登录之后一分钟内就会跟上。\n * 缓存键带上平台与 XDG_RUNTIME_DIR：测试/诊断会把它们换掉，换了就必须重新探（否则读到上一轮结论）。\n */\nlet systemdProbeCache = { at: 0, ok: false, key: \"\" };\nfunction systemdUserAvailableCached(ttlMs = 60_000) {\n  const key = `${osPlatform()}|${process.env.XDG_RUNTIME_DIR || \"\"}|${process.env.PATH || \"\"}`;\n  if (systemdProbeCache.key === key && Date.now() - systemdProbeCache.at < ttlMs) return systemdProbeCache.ok;\n  const ok = systemdUserAvailable();\n  systemdProbeCache = { at: Date.now(), ok, key };\n  return ok;\n}\n\n/**\n * ★★ 2026-10-13 修复（线上反馈 fb_3c4c5a13bc47 / 用户 842）：Linux 上「bridge 到底在不在跑」的\n * **权威**判据 —— 问服务管理器本人，而不是猜进程名。\n *\n * 为什么 `pgrep` 不能当就绪判据：自愈 watcher 每 `selfhealIntervalMs()`（默认 12s）拍一次，\n * 旧就绪判据是 `manualStatus(relayDir).watcher.length > 0`，它靠\n * `pgrep -fl 'dsh-setup.mjs|dsh-bridge.mjs'` 的名称匹配。这个探测**极易拿到空结果**\n * （PATH 里没有 /usr/bin、pgrep 不存在、进程名与模式不匹配、进程属于别的会话……），\n * 而拿到空结果后的动作是 `systemctl --user restart dsh-bridge` —— **restart 会杀掉正在\n * 健康运行的 bridge**。实测后果：该设备 `audit_log` 的 `device.claim`（= bridge 进程启动的\n * 必然产物）一天 **3567** 次、相邻间隔 p50 **12001ms**、连续 10 小时整点 300 次/小时；\n * 全站上百台设备每天 1.1~1.5 万次重登记。每次重启都以新连接顶掉旧隧道，中继随即把该设备\n * **所有手机镜像 WS 关掉（close 1012 \"bridge offline\"）**，镜像页每 ~12.3 秒断线重连并全量重放\n * 界面状态 —— 用户看到的就是\"选项窗口一会儿显示、一会儿消失\"。\n * 而中继侧对这类 churn 只做了日志抑制，所以运维侧长期看不见。\n *\n * 🔴 结论：**探测失败 ≠ 进程死了**，绝不允许把前者翻译成\"每 12 秒杀一次隧道\"。\n *\n * 为什么必须是三态而不是布尔：`known:false`（问不到 systemd —— NAS/容器里没有 user manager、\n * 甚至没有 systemctl 命令）与「问了，明确不是 active」在语义上完全不同：\n *   · known=false → 回退到进程探测（与旧行为一致，不能因为问不到就认为它死了）；\n *   · known=true & active=false → 才可以动手拉起。\n * 把这两种混成一个 `false`，等于又制造了一次\"判据失败就重启\"的事故。\n */\nfunction linuxSystemdUnitState() {\n  if (!isLinux()) return { known: false, active: false, raw: \"\" };\n  const r = sh(\"systemctl --user is-active dsh-bridge\");\n  const raw = String(r.stdout || \"\").trim();\n  if (raw === \"active\") return { known: true, active: true, raw };\n  // is-active 对 inactive/failed/activating… 会以非 0 退出，但**会打印状态字** —— 那是有效回答。\n  // 一个字都没打印 = systemctl 根本没回答（没有 user manager / 没有这个命令）→ 未知，不是\"死\"。\n  if (!raw) return { known: false, active: false, raw };\n  return { known: true, active: false, raw };\n}\n\n/** 写 Linux systemd user unit（与 dsh-setup.mjs 同内容）。写不了返回 null（不致命，还有脱离进程兜底）。 */\nfunction writeLinuxUnit(relayDir) {\n  const unitPath = linuxUnitPath();\n  if (!unitPath) return null;\n  const setup = join(relayDir, \"dsh-setup.mjs\");\n  const unit = `[Unit]\nDescription=dsh-remote bridge (auto-starts with dsh web)\n\n[Service]\nExecStart=${NODE_BIN} ${setup} run\nRestart=on-failure\nRestartSec=5\nEnvironment=PATH=${SERVICE_PATH}\n${SERVICE_NODE_ENV_UNIT}Environment=DSH_BRIDGE_UPSTREAM=${upstreamUrl()}\nEnvironment=DSH_BRIDGE_INSTALL_SOURCE=${installSourceOf(relayDir)}\nEnvironment=DSH_BRIDGE_INSTALL_VERSION=${PLUGIN_VERSION}\nEnvironment=DSH_BRIDGE_HARNESS_VERSION=${harnessVersion()}\n\n[Install]\nWantedBy=default.target\n`;\n  try {\n    mkdirSync(dirname(unitPath), { recursive: true });\n    writeFileSync(unitPath, unit, { mode: 0o644 });\n    return unitPath;\n  } catch (e) {\n    appendLogLine(relayDir, AUTO_INSTALL_LOG, `[dsh-remote-web] 写入 systemd unit 失败: ${e.message}`);\n    return null;\n  }\n}\n\n/**\n * Linux：拉起 bridge 的阶梯（**与 macOS 同构：可自愈优先，可用兜底**）。\n *\n * 【0.6.15 故障根因】0.6.14 及更早，`startBridge` 只认 macOS 的 launchd，Linux 直接返回\n * `unsupported: 当前平台（linux）暂不支持自启动服务`。于是：\n *   · 自愈轮次每轮都调用它、每轮都拿到 unsupported、**bridge 永远起不来**；\n *   · 用户面板上的表现是永远停在「正在启动 Bridge…」+「bridge 进程: 未运行」；\n *   · 用户以为是\"端口不对\"，于是反复改端口号（改到 3080 也没用）——\n *     因为**根本没人在听那个端口**，跟端口一点关系都没有。\n *   实测环境：飞牛 fnOS（Debian 系 NAS），插件跑在系统服务里，没有 user systemd 会话。\n *\n * 阶梯：\n *   ①（有 user systemd 会话时）systemd --user enable --now dsh-bridge —— 开机自启 + 崩溃自愈；\n *   ②（没有会话 / ① 失败）脱离进程拉起 `node <relayDir>/dsh-setup.mjs run` —— 与 Windows 同一条路径，\n *      \"现在一定能用\"，代价是只有\"重开 dsh web 时插件会自动拉起\"这一层保障（如实告知用户）。\n */\nfunction startBridgeLinux(relayDir) {\n  if (skipsSystemOps()) return { ok: false, status: \"skipped\", detail: \"测试隔离（DSH_RELAY_SKIP_SERVICE=1）：跳过真实服务操作\" };\n  if (!runtimeReady(relayDir)) {\n    ensureRuntime(relayDir);\n    return {\n      ok: false,\n      status: \"provisioning\",\n      runtimeMissing: true,\n      detail: \"桌面运行环境（bridge）尚未安装，已在后台自动安装，完成后会自动启动 bridge——请稍候刷新面板（也可点下方「一键更新」查看进度）\",\n    };\n  }\n  const up = publishUpstream(relayDir); // 脱离进程拉起的 watcher 没有本进程 env，只认这个文件\n  const unit = writeLinuxUnit(relayDir);\n  if (unit && systemdUserAvailable()) {\n    // ★★ 2026-10-13 幂等闸门（修「12 秒重启风暴」的核心）：\n    //   先问**服务管理器本人**这个 unit 是不是 active，而不是拿 pgrep 猜进程名。\n    //   active = systemd 把它拉起来了、正在跑 —— 此时绝不能 restart（restart 会杀掉旧进程、\n    //   新建隧道，中继随即 close(1012) 掉该设备所有手机镜像 WS，镜像页全量重放）。\n    //   旧代码在这里**无条件 restart**：只要上游判据（pgrep）拿不到，它就每 12 秒把一台\n    //   健康运行的 bridge 杀掉重建一次，一天 3567 次（见 linuxSystemdUnitState 的长注释）。\n    const state = linuxSystemdUnitState();\n    if (state.active && !up.changed) {\n      // 唯一还站得住的\"需要重启\"的理由不存在 → 什么都不做，如实回报\"在跑、没重启\"。\n      return {\n        ok: true, status: \"running\", pid: null, reused: true,\n        detail: \"已由 systemd --user 托管 bridge（运行中，未重启）\",\n      };\n    }\n    const why = state.active\n      // 上游地址**确实变了**（运行中的进程环境里是旧地址，不重启就会对着旧端口转发）——\n      // 这是唯一允许动一个健康服务的理由，所以必须过护栏：万一上游地址在抖，\n      // 也不能退化成\"每 12 秒重启一次\"（那正是本次故障的形态）。\n      ? `上游地址变更为 ${up.url}`\n      // 没在跑（含 is-active=activating/failed 这类瞬时态）：本该起它，但**反复 restart 一个\n      // 起不来的 unit** 每次都会派生一个新 bridge 进程（= 一次 device.claim = 顶掉一次隧道），\n      // 所以这里的 restart 同样要过护栏 —— 护栏就该放在\"破坏性动作\"的调用点上，\n      // 而不是指望每个调用者自己记得限流。\n      : `systemd --user 说它没在跑（is-active=${state.raw || \"无回答\"}）`;\n    const g = guardedSystemdRestart(relayDir, why);\n    if (!g.allowed) {\n      // ⚠️ 被护栏拦下时**绝不能**再落到下面的\"脱离进程\"兜底：那条路会直接派生一个新 watcher，\n      //    每拍一个 —— 护栏就形同虚设（这正是我们要止住的东西）。\n      // 而回报要分两种：unit 本来就 active 时它**仍在运行**，不能因为\"我们没重启\"就报失败\n      // （否则面板会把一台好机器显示成故障）。\n      if (state.active) {\n        return {\n          ok: true, status: \"running\", pid: null, reused: true, staleUpstream: true,\n          detail: `bridge 正在运行；上游地址已变更为 ${up.url}，但为避免重启风暴暂不重启它（重开 dsh web 后自然生效）`,\n        };\n      }\n      return {\n        ok: false, status: \"selfheal-throttled\",\n        detail: `自愈护栏拦下了对 systemd unit 的重启（${g.gate.reason === \"exhausted\" ? \"已达本进程重启上限\" : \"距上次重启过近\"}），本轮不重启 bridge`,\n      };\n    }\n    if (g.ok) {\n      // accounted: true = 这次破坏性重启已经在 guardedSystemdRestart 里记过账（护栏额度 + 可见日志）。\n      // 调用方（自愈 watcher）据此**不得再记一次**，否则一次尝试吃掉两格额度，5 分钟退避缩水成 2.5 分钟。\n      return { ok: true, status: \"running\", pid: null, accounted: true, detail: \"已由 systemd --user 托管 bridge（开机自启 + 崩溃自愈）\" };\n    }\n    if (state.active) {\n      // 因上游变更而重启、但重启后仍不是 active：如实回报（已在 guardedSystemdRestart 里记账）\n      return {\n        ok: true, status: \"running\", pid: null, reused: true, staleUpstream: true,\n        detail: `bridge 仍在运行，但上游地址已变更为 ${up.url} 且本次重启未确认生效（详见安装日志）`,\n      };\n    }\n    appendLogLine(relayDir, AUTO_INSTALL_LOG,\n      `[dsh-remote-web] systemd --user 拉起 bridge 失败（restart=${g.rs.ok ? \"ok\" : \"fail\"}），改用后台进程`);\n  }\n  const d = startBridgeDetached(relayDir, unit\n    ? \"本机没有可用的 user systemd 会话（NAS / 容器 / 精简系统常见），已改为后台进程\"\n    : \"systemd unit 写入失败，已改为后台进程\");\n  return d;\n}\n\n/**\n * 执行一次「systemd 破坏性重启 bridge」：**先过护栏，过了才真的 restart**，并记账 + 写可见日志。\n *\n * 为什么要把 `systemctl --user restart` 收敛到这一个函数里：这条命令是本次故障里唯一真正\n * 造成伤害的动作（杀旧 bridge → 新进程 → 新隧道 → 中继 close(1012) 掉手机镜像）。\n * 它散落在多处调用点时，任何一处忘了限流就又是一次\"十二秒杀一次隧道\"；\n * 收到一处之后，\"什么情况下允许执行它\"就有了唯一答案，也能被单测直接钉住。\n * @returns {{allowed:boolean, gate:object, ok:boolean, en:object, rs:object, act:object}}\n */\nfunction guardedSystemdRestart(relayDir, why) {\n  const gate = selfhealRestartGate(relayDir);\n  if (!gate.allowed) {\n    noteSelfhealBlocked(relayDir, gate);\n    return { allowed: false, gate, ok: false, en: null, rs: null, act: null };\n  }\n  sh(\"systemctl --user daemon-reload\");\n  const en = sh(\"systemctl --user enable dsh-bridge\");\n  const rs = sh(\"systemctl --user restart dsh-bridge\");\n  const act = rs.ok ? sh(\"systemctl --user is-active dsh-bridge\") : { ok: false, stdout: \"\", stderr: \"\" };\n  const active = Boolean(rs.ok && act.ok && String(act.stdout).trim() === \"active\");\n  noteSelfhealRestart(relayDir, why, active ? \"running\" : `restart=${rs.ok ? \"ok\" : \"fail\"}/is-active=${String(act.stdout).trim() || \"?\"}`);\n  return { allowed: true, gate, ok: active, en, rs, act };\n}\n\n/**\n * launchd 作业 target（`gui/<uid>/<label>`）。\n * **Windows/Linux 上没有 launchctl、也没有 process.getuid**——旧实现无条件调\n * `process.getuid()`，在 Windows 上直接 TypeError（这正是面板两个读状态接口 500 的根因）。\n * 现在：非 macOS 或取不到 uid 一律返回 null，调用方必须先判空。\n */\n/**\n * launchd 域名阶梯（**必须与 dsh-setup.mjs 一致**）。\n *\n * 故障（2026-09-19 实测）：安装器按 macOS 26 的修复把作业装在 **`user/<uid>`** 域\n * （gui 域会被系统置为 on-demand-only，RunAtLoad/KeepAlive 失效），\n * 但插件这边只认 `gui/<uid>` → 切换账号时那次\"重启 bridge\"实际执行的是\n *   launchctl bootout gui/501/com.dshremote.bridge   → 找不到\n *   launchctl bootstrap gui/501 <plist>              → 失败\n * 结果：旧 bridge 继续用**旧账号**跑，新账号的设备列表里永远看不到这台机器。\n * 现在两边用同一条阶梯：user/<uid> 优先，gui/<uid> 兜底。\n */\nfunction launchDomains() {\n  if (!isDarwin()) return [];\n  const uid = currentUid();\n  return uid === null ? [] : [`user/${uid}`, `gui/${uid}`];\n}\n/** 所有可能承载本服务的 launchd target（按优先级）。 */\nfunction launchTargets() {\n  return launchDomains().map((d) => `${d}/com.dshremote.bridge`);\n}\nfunction launchTarget() {\n  return launchTargets()[0] || null; // 首选域（user/<uid>）\n}\n\n/**\n * 检查 launchd 服务状态。\n *\n * 【0.6.2 关键修复】`launchctl print` 只要成功，它的 `state` 就是权威，**不得**再回退\n * `launchctl list`。原因：plist 指向不存在的入口脚本时，KeepAlive 会让作业陷入\n * 「秒退→立刻重拉」的崩溃循环，而在重拉的瞬间 `launchctl list` 的 PID 列会闪现一个\n * **已经死掉**的 pid（实测 `launchctl list` = `40213 1 com.dshremote.bridge`，\n * 同时 `ps -p 40213` 为空、`launchctl print` = `state = spawn scheduled`）。\n * 旧实现据此谎报 running=true，后果有二：\n *   1) 面板显示「运行中」，用户以为 bridge 在跑（实际从未注册成功）；\n *   2) scheduleRuntime 判定「已在运行」→ 自愈 watcher 永久停摆，再也不补运行环境。\n * 现在：print 的 state 为准 + 附带 runs/lastExitCode/crashing 供面板与自愈解释原因；\n * 仅在 print 本身不可用时才回退 list，且回退路径要求 pid 真实存活。\n */\nconst NO_LAUNCHD = { running: false, pid: null, state: \"\", runs: null, lastExitCode: null, crashing: false };\n\nfunction launchdStatus() {\n  // 非 macOS 没有 launchctl（Windows 上连 process.getuid 都没有）：直接返回「无此服务」，\n  // 不再去 shell 里调一个不存在的命令——这既避免 500，也避免每次轮询白起一个 cmd.exe。\n  if (!isDarwin()) return { ...NO_LAUNCHD };\n  // 逐域查询：安装器可能把作业装在 user/<uid>，插件以前只看 gui/<uid> → 会把\"正在运行\"看成\"未运行\"。\n  for (const target of launchTargets()) {\n    const st = launchdStatusIn(target);\n    if (st.running || st.crashing || st.state) return st;\n  }\n  return { ...NO_LAUNCHD };\n}\n\nfunction launchdStatusIn(target) {\n  const pr = sh(`launchctl print ${target}`);\n  if (pr.ok) {\n    const stateMatch = pr.stdout.match(/state\\s*=\\s*([^\\n]+)/);\n    const state = stateMatch ? stateMatch[1].trim() : \"\";\n    const pidMatch = pr.stdout.match(/(?:^|\\n)\\s*pid\\s*=\\s*(\\d+)/);\n    const runsMatch = pr.stdout.match(/runs\\s*=\\s*(\\d+)/);\n    const exitMatch = pr.stdout.match(/last exit code\\s*=\\s*(-?\\d+)/);\n    const runs = runsMatch ? Number(runsMatch[1]) : null;\n    const lastExitCode = exitMatch ? Number(exitMatch[1]) : null;\n    const running = state === \"running\";\n    // 崩溃循环：作业在 launchd 里可见但没在跑，且上次退出码非 0（KeepAlive 会无限重拉）\n    const crashing = !running && runs !== null && runs > 0 && lastExitCode !== null && lastExitCode !== 0;\n    return { running, pid: running && pidMatch ? Number(pidMatch[1]) : null, state, runs, lastExitCode, crashing };\n  }\n  const ls = sh(\"launchctl list | grep com.dshremote.bridge\");\n  if (ls.ok) {\n    const pidStr = ls.stdout.trim().split(/\\s+/)[0];\n    if (pidStr && pidStr !== \"-\" && /^\\d+$/.test(pidStr)) {\n      const pid = Number(pidStr);\n      // list 的 PID 列在崩溃循环中会出现已死进程 → 必须校验存活才敢报运行\n      if (pidAlive(pid) !== false) return { running: true, pid, state: \"running\", runs: null, lastExitCode: null, crashing: false };\n    }\n  }\n  return { running: false, pid: null, state: \"\", runs: null, lastExitCode: null, crashing: false };\n}\n\n// ---------- Windows：bridge 进程发现（0.6.7 立；2026-10-29 反馈后重写） ----------\n//\n// Windows 没有 pgrep/ps/launchctl，而 bridge 在 Windows 上也不由服务管理器托管\n// （dsh-setup.mjs 明确不生成 Windows 自启动）。所以进程发现按「pid 文件 → bridge 自写证据 → PowerShell 扫描」三级：\n//   ① pid 文件：插件自己 spawn 的 watcher、以及 `dsh-remote run` 跑起来的 watcher/bridge\n//      都会把 pid 落到配置目录（见 dsh-setup.mjs 的 writePidFile）。读文件 + process.kill(pid,0)\n//      判活，零 shell 开销——面板 2~3s 轮询一次也扛得住。\n//   ② bridge **自己**写的单实例锁 `.dsh-bridge-instance.lock`（{pid,at,script}，见 dsh-bridge.mjs 的\n//      acquireInstanceLock）与状态文件 `.dsh-bridge-state.json` 里的 pid：进程自证身份。父进程\n//      watcher 会把 `.dsh-bridge.pid` 删掉（子进程一退出就删），而孤儿 bridge 仍活着的场景里，\n//      这条「自写证据」是唯一还成立的判据（2026-10-29 事故正是这个形态）。\n//   ③ PowerShell 全量枚举 + 命令行匹配：兼容「用户跑的是没写 pid 文件的旧版运行时」。\n//      这条路径要起一个 powershell.exe（数百毫秒），故结果带 TTL 缓存，绝不被轮询打爆。\n//\n// 【2026-10-29 修复的三处结构性缺陷】（取证：dsh-relay-internal/2026-10-29-反馈bridge_wedged-取证/）\n//   F1 旧条件 `if (!watcher.length && !bridge.length)`：**watcher pid 文件有效时永不扫**。于是\n//      「watcher 在跑 + bridge pid 文件刚被删（新 bridge 撞本地实例锁秒退时 watcher 会删它）」\n//      ⇒ bridge 恒为空 ⇒ 面板「bridge 未运行 / 中继未注册」⇒ 90s 后判「守护卡死」⇒ 误重启 3 次\n//      ⇒ bridge_wedged，而中继数据面全程在线。现在改成「**只要 bridge 为空就扫**」，扫描结果只补充不覆盖。\n//   F2 旧扫描写死 `Name='node.exe'`：桌面端（Electron）宿主用 process.execPath 拉起 watcher，\n//      镜像名是桌面端 exe；bridge 的解释器是 NODE_BIN（可能也是同一个 exe）⇒ 两类进程都可能全漏。\n//      现在无 Name 过滤、按命令行匹配，并把 Name 一起带回（故障时一眼看出解释器是谁）。\n//   F3 扫描失败与「扫到 0 个」不再混为一谈：失败时置 degraded，随 /bridge-status 下发（scanDegraded）。\n\nconst WATCHER_PID_FILE = \".dsh-watcher.pid\";\nconst BRIDGE_PID_FILE = \".dsh-bridge.pid\";\n/** bridge 自己写的单实例锁（必须与 dsh-bridge.mjs 的 INSTANCE_LOCK_FILE 同名）。 */\nconst BRIDGE_LOCK_FILE = \".dsh-bridge-instance.lock\";\n/** Windows 自启动任务名（与 dsh-setup.mjs 的 WIN_TASK_NAME 必须一致）。 */\nconst WIN_TASK_NAME = \"dsh-remote-bridge\";\nconst WIN_SCAN_TTL_MS = 5000;\n/**\n * pid 文件的「信任窗口」：**取不到进程命令行**时（Windows 上 PowerShell 不可用/进程不在扫描结果里；\n * POSIX 上 ps 失败），只有 pid 文件足够新才敢按「大概是我们的进程」处理。超过窗口一律当无法确认 ——\n * 宁可漏杀/漏报，也绝不对一个可能已被系统回收给无关进程的 pid 发 taskkill /T /F。\n */\nconst PID_FILE_TRUST_MS = 10 * 60 * 1000;\n/**\n * 状态文件心跳的信任窗口：新版 bridge 在心跳拍里节流刷新 `.dsh-bridge-state.json` 的\n * `{pid, heartbeat_at}`（≥10s 一次，隧道心跳默认 20s；见 dsh-bridge.mjs 的 stampBridgeHeartbeat）。\n * 120s ≈ 容忍 6 拍丢失（机器休眠/事件循环卡顿）。超过窗口就认为「这份 pid 可能已被系统回收\n * 给无关进程」，此时必须靠命令行确认，绝不能只看 pid 活着就报「bridge 在跑」。\n */\nconst STATE_HEARTBEAT_TRUST_MS = 120_000;\n\n/**\n * 扫描结果缓存 TTL。生产恒为 WIN_SCAN_TTL_MS；`DSH_RELAY_WIN_SCAN_TTL_MS` 只给用例用\n * （0 = 不缓存），避免同一进程内多条用例被 5s 缓存互相串味 —— 与 DSH_RELAY_WEDGE_MS 同一约定。\n */\nfunction winScanTtlMs() {\n  const v = Number(process.env.DSH_RELAY_WIN_SCAN_TTL_MS);\n  return Number.isFinite(v) && v >= 0 ? v : WIN_SCAN_TTL_MS;\n}\n\n/** 读 pid 文件（内容为纯数字 pid；缺失/损坏返回 null）。 */\nfunction readPidFile(relayDir, name) {\n  try {\n    const n = Number(String(readFileSync(join(relayDir, name), \"utf8\")).trim());\n    return Number.isInteger(n) && n > 0 ? n : null;\n  } catch {\n    return null;\n  }\n}\n\n/** pid 文件有多旧（毫秒）；读不到 = Infinity（= 完全不可信）。 */\nfunction pidFileAgeMs(relayDir, name) {\n  try { return Date.now() - (statSync(join(relayDir, name)).mtimeMs || 0); } catch { return Infinity; }\n}\n\n/** 安静读一个 JSON 证据文件（bridge 自写的锁/状态）；缺失/损坏 → null。 */\nfunction readJsonFileQuiet(p) {\n  try {\n    const j = JSON.parse(readFileSync(p, \"utf8\"));\n    return j && typeof j === \"object\" ? j : null;\n  } catch { return null; }\n}\n\n/**\n * 用 PowerShell 列出所有**命令行里带 dsh-setup.mjs / dsh-bridge.mjs** 的进程（不再按镜像名过滤）。\n * 走 -EncodedCommand（UTF-16LE base64）：命令行里带引号/中文/空格时不会被 PowerShell 自己的\n * 引号解析吃掉，也不需要经过 shell。Get-CimInstance 不可用时回退 Get-WmiObject（Win7/精简系统）。\n *\n * @returns {{procs: Array<{pid:number, ppid:number|null, name:string, commandLine:string}>, degraded:boolean}}\n *          degraded=true 表示「没扫成」（无 PowerShell / 调用超时 / JSON 解析失败）——\n *          必须与「扫到 0 个」区分开，否则诊断里会谎报「本机一个进程都没有」。\n */\nlet winProcScanCache = { at: 0, procs: [], degraded: false };\nfunction windowsProcessScan() {\n  const ttl = winScanTtlMs();\n  if (ttl > 0 && Date.now() - winProcScanCache.at < ttl) return winProcScanCache;\n  const script = [\n    \"try { $p = Get-CimInstance Win32_Process } catch { $p = Get-WmiObject Win32_Process }\",\n    \"$p | Where-Object { $_.CommandLine -and ($_.CommandLine -match 'dsh-setup\\\\.mjs' -or $_.CommandLine -match 'dsh-bridge\\\\.mjs') } | Select-Object ProcessId,ParentProcessId,Name,CommandLine | ConvertTo-Json -Compress\",\n  ].join(\"; \");\n  const encoded = Buffer.from(script, \"utf16le\").toString(\"base64\");\n  let procs = [];\n  let degraded = false;\n  try {\n    const r = spawnSync(\"powershell.exe\", [\"-NoProfile\", \"-NonInteractive\", \"-EncodedCommand\", encoded], {\n      encoding: \"utf8\", timeout: 8000, windowsHide: true, maxBuffer: 8 * 1024 * 1024,\n    });\n    const raw = String(r.stdout || \"\").trim();\n    // 非 0 退出且没有输出 = 没扫成（无 PowerShell / 被策略拒 / WMI 不可用）\n    if (!raw) {\n      if (r.error || (Number.isFinite(r.status) && r.status !== 0)) degraded = true;\n    } else {\n      try {\n        const parsed = JSON.parse(raw);\n        for (const p of (Array.isArray(parsed) ? parsed : [parsed])) {\n          const pid = Number(p && p.ProcessId);\n          if (!Number.isInteger(pid) || pid <= 0) continue;\n          procs.push({\n            pid,\n            ppid: Number(p.ParentProcessId) || null,\n            name: String((p && p.Name) || \"\"),\n            commandLine: String((p && p.CommandLine) || \"\"),\n          });\n        }\n      } catch { procs = []; degraded = true; } // 有输出但不是 JSON → 当作没扫成\n    }\n  } catch { procs = []; degraded = true; } // spawnSync 抛错（ENOENT 等）→ 没扫成\n  if (ttl > 0) winProcScanCache = { at: Date.now(), procs, degraded };\n  return { procs, degraded };\n}\n\n/**\n * Windows 登录任务（任务计划程序）是否已注册——由 dsh-setup.mjs 安装/一键更新时注册，\n * 插件只读不写。带 60s 缓存：面板 2~3s 轮询一次状态，不能每轮都起一个 schtasks。\n */\nlet winTaskCache = { at: 0, ok: false };\nfunction windowsTaskRegistered() {\n  if (Date.now() - winTaskCache.at < 60_000) return winTaskCache.ok;\n  let ok = false;\n  try {\n    const r = spawnSync(\"schtasks\", [\"/Query\", \"/TN\", WIN_TASK_NAME], { windowsHide: true, encoding: \"utf8\", timeout: 8000 });\n    ok = r.status === 0;\n  } catch { ok = false; }\n  winTaskCache = { at: Date.now(), ok };\n  return ok;\n}\n\n/* ── 进程身份校验（防 PID 复用：既防误判「在跑」，也防误杀）─────────────────────────\n *\n * pid 文件只证明「某个时刻有人写了这个 pid」，**不证明**「现在这个 pid 还是我们的进程」。\n * Windows 的 PID 会被快速回收，于是「watcher 死了 → pid 文件还在 → 该 pid 已被无关进程占用」\n * 是常态而不是异常。旧实现只做 pidAlive() 判活，后果有两个方向：\n *   · 误判「守护在运行」⇒ 自愈永久 no-op（「多次修复都没解决」那一类）；\n *   · 更严重：stopBridgeDetached 会 taskkill /T /F 杀掉它 ⇒ **杀掉一棵与产品无关的进程树**。\n * 纪律（与 dsh-setup.mjs 的 looksLikeWatcher/looksLikeBridge 同一方向：宁可漏杀）：\n *   · 命令行**确认**是本 relayDir 的 dsh-setup.mjs / dsh-bridge.mjs → ident 非空（是我们的）；\n *   · 命令行**取到了但不是**（不指向这两个脚本 / 不指向本 relayDir）→ cmdKnown=true、ident=\"\"；\n *   · 取不到命令行（Windows：不在扫描结果里或扫描 degraded；POSIX：ps 失败）→ cmdKnown=false，\n *     这一档只能用 pid 文件新鲜度兜底（PID_FILE_TRUST_MS）。\n */\nfunction processCommandLine(pid, procs) {\n  if (!Number.isInteger(pid) || pid <= 0) return \"\";\n  if (procs) {\n    const hit = procs.find((p) => p && p.pid === pid);\n    return hit ? String(hit.commandLine || \"\") : \"\";\n  }\n  return commandLineOfPid(pid);\n}\n\n/** @returns {{ident:\"watcher\"|\"bridge\"|\"\", cmdKnown:boolean}} */\nfunction pidIdentityOf(pid, relayDir, procs) {\n  const cmd = processCommandLine(pid, procs);\n  if (!cmd) return { ident: \"\", cmdKnown: false };\n  const norm = (v) => String(v).replace(/\\\\/g, \"/\").toLowerCase();\n  const isBridge = /dsh-bridge\\.mjs/.test(cmd);\n  const isWatcher = /dsh-setup\\.mjs/.test(cmd);\n  if (!isBridge && !isWatcher) return { ident: \"\", cmdKnown: true };      // 取到了命令行：明确不是我们的脚本\n  if (!norm(cmd).includes(norm(relayDir || \"\"))) return { ident: \"\", cmdKnown: true }; // 同类脚本，但不是本配置目录\n  return { ident: isBridge ? \"bridge\" : \"watcher\", cmdKnown: true };\n}\n\n/**\n * Windows 版 manualStatus：pid 文件 → bridge 自写证据 → PowerShell 扫描（扫描结果只补充、不覆盖）。\n *\n * 返回值里的 scanDegraded / bridgeEvidence 是 2026-10-29 事故的产物：面板/诊断必须能区分\n * 「bridge 真没有（pid 文件、锁、状态文件、扫描四路都说没有）」与「我们根本没能扫」（degraded），\n * 否则又会像那次一样把「工具看不见」当成「进程不存在」。\n */\nfunction windowsManualStatus(relayDir) {\n  const selfPid = process.pid;\n  const watcher = [];\n  const bridge = [];\n  const allBridge = [];\n  const evidence = [];\n  const push = (arr, pid) => { if (pid && !arr.includes(pid)) arr.push(pid); };\n  const addBridge = (pid, why) => {\n    if (!pid || pid === selfPid || allBridge.includes(pid)) return;\n    push(bridge, pid); push(allBridge, pid); evidence.push(why);\n  };\n  const wPid = readPidFile(relayDir, WATCHER_PID_FILE);\n  const bPid = readPidFile(relayDir, BRIDGE_PID_FILE);\n  const wAlive = Boolean(wPid && pidAlive(wPid) !== false);\n  const bAlive = Boolean(bPid && pidAlive(bPid) !== false);\n\n  // ① bridge pid 文件（父进程 watcher 写的那份；子进程一退出它就会被删 —— 这正是事故现场的形态）\n  if (bAlive && bPid !== selfPid) addBridge(bPid, \"pid-file\");\n\n  // ② bridge 自写证据（F3）：进程自己写的「我在跑」比任何外部扫描都可靠，而且不需要起 PowerShell。\n  //    · `.dsh-bridge-instance.lock`：{pid,at,script}，bridge 启动时自己写（script 即身份自证）；\n  //    · `.dsh-bridge-state.json`：新版 bridge 写 {pid, heartbeat_at}（心跳拍 ≥10s 刷新一次）。\n  //    这两条正是「父进程把 .dsh-bridge.pid 删了、孤儿 bridge 还活着」时唯一还成立的判据。\n  const state = bridgeStateFile(relayDir);\n  const stPid = Number(state && state.pid);\n  const hbAt = Number(state && state.heartbeat_at) || 0;\n  const hbFresh = hbAt > 0 && Date.now() - hbAt < STATE_HEARTBEAT_TRUST_MS;\n  const stPidAlive = Number.isInteger(stPid) && stPid > 0 && stPid !== selfPid && pidAlive(stPid) !== false;\n  const lock = readJsonFileQuiet(join(relayDir, BRIDGE_LOCK_FILE));\n  const lockPid = Number(lock && lock.pid);\n  const lockAlive = Number.isInteger(lockPid) && lockPid > 0 && lockPid !== selfPid && pidAlive(lockPid) !== false;\n  const lockScriptOk = String((lock && lock.script) || \"\") === \"dsh-bridge.mjs\";\n  // 心跳「已经停了」= 状态文件里有过心跳但已超信任窗口。此时锁文件里的 pid 很可能已被系统回收给\n  // 无关进程（bridge 死了、锁没删），必须先拿到命令行确认 —— 否则会永久谎报「bridge 在跑」。\n  const heartbeatStopped = hbAt > 0 && !hbFresh;\n  let lockNeedsProof = false;      // 需要命令行确认的锁候选\n\n  let procs = null;                // null = 本次没扫描（省掉一次 PowerShell）\n  let scanDegraded = false;\n  if (!bridge.length) {\n    if (lockAlive && lockScriptOk) {\n      if (heartbeatStopped) lockNeedsProof = true;   // 心跳停了 → 等扫描用命令行确认\n      else addBridge(lockPid, \"instance-lock\");      // script 自证 + pid 活着（心跳新鲜或旧版无心跳）\n    }\n    if (!bridge.length && stPidAlive && hbFresh) addBridge(stPid, \"state-file\");\n  }\n\n  if (!bridge.length) {\n    // ③ F1：**只要 bridge 为空就扫**（不再要求 watcher 也为空）。\n    //    旧条件 `if (!watcher.length && !bridge.length)` 让「watcher 在跑、bridge pid 文件刚被删」\n    //    时一次都不扫 ⇒ bridge 恒为空 ⇒ 误判卡死 → 误重启 → bridge_wedged（2026-10-29 事故）。\n    //    F2：扫描不按镜像名过滤（Electron 宿主的 watcher/bridge 不叫 node.exe），按命令行匹配。\n    const sc = windowsProcessScan();\n    procs = sc.procs;\n    scanDegraded = Boolean(sc.degraded);\n    for (const p of procs) {\n      if (!p || p.pid === selfPid) continue;\n      const cmd = String(p.commandLine || \"\");\n      if (/dsh-setup\\.mjs/.test(cmd)) { push(watcher, p.pid); continue; }\n      if (/dsh-bridge\\.mjs/.test(cmd)) addBridge(p.pid, \"scan\");\n    }\n    // 扫描也没找到时，才允许「自写证据 + 命令行确认」这一档（宁可漏报，也不假阳性）\n    if (!bridge.length && lockNeedsProof && pidIdentityOf(lockPid, relayDir, procs).ident === \"bridge\") {\n      addBridge(lockPid, \"instance-lock\");\n    }\n    if (!bridge.length && stPidAlive && pidIdentityOf(stPid, relayDir, procs).ident === \"bridge\") {\n      addBridge(stPid, \"state-file\");\n    }\n  }\n\n  // ⑤ watcher（守护）pid 文件：必须通过身份/新鲜度校验，否则**不得**报「守护在运行」——\n  //    否则 PID 复用会让 watcherWedgeOf 判「守护活了 N 秒仍无 bridge」→ 误重启（甚至误杀）。\n  if (wAlive && wPid !== selfPid) {\n    let trusted;\n    if (procs) {\n      const id = pidIdentityOf(wPid, relayDir, procs);\n      if (id.ident === \"watcher\") trusted = true;\n      else if (id.ident === \"bridge\") { addBridge(wPid, \"scan\"); trusted = false; } // pid 文件被覆盖成 bridge：算 bridge 更准\n      else trusted = !id.cmdKnown && pidFileAgeMs(relayDir, WATCHER_PID_FILE) < PID_FILE_TRUST_MS;\n    } else {\n      // bridge 已从 pid 文件/自写证据确认 ⇒ 本次没扫描。watcher 列表此时不参与任何风险决策\n      // （wedge 只在「bridge 为空」时才计算），保持旧行为即可，不必为此白起一次 PowerShell。\n      trusted = true;\n    }\n    if (trusted) push(watcher, wPid);\n  }\n\n  return { watcher, bridge, allBridge, scanDegraded, bridgeEvidence: evidence };\n}\n\n/** 检查手动运行的 watcher（dsh-setup.mjs run）与 bridge 子进程（排除 launchd 托管链）。 */\nfunction manualStatus(relayDir) {\n  if (isWindows()) return windowsManualStatus(relayDir || DEFAULT_RELAY_DIR);\n  const launchdPid = launchdStatus().pid;\n  const pg = (() => {\n    const r = sh(\"pgrep -fl 'dsh-setup.mjs|dsh-bridge.mjs'\");\n    return { out: r.ok ? r.stdout : \"\", stderr: String(r.stderr || \"\") };\n  })();\n  const out = pg.out;\n  const watcher = [];\n  const bridge = [];\n  // 全部 bridge 子进程（含 launchd 托管链里的）：连接阶段判定「bridge 进程真的在跑」用它。\n  // launchd 作业本身跑的是 watcher（dsh-setup.mjs run），它再拉起 dsh-bridge.mjs 子进程——\n  // 只看 launchd.running 会把「watcher 在、bridge 子进程没起来」误判成「进程在跑」。\n  const allBridge = [];\n  // 取候选进程的父 pid，判断是否属于 launchd 托管链\n  const parentOf = (pid) => {\n    const r = sh(`ps -o ppid= -p ${pid}`);\n    const m = r.ok && r.stdout.trim().match(/^(\\d+)/);\n    return m ? Number(m[1]) : null;\n  };\n  for (const line of out.split(\"\\n\")) {\n    if (/pgrep/.test(line)) continue; // 排除 execSync 的 sh -c 包装进程\n    const m = line.match(/^(\\d+)\\s+(.+)$/);\n    if (!m) continue;\n    const pid = Number(m[1]);\n    if (pid === process.pid || pid === launchdPid) continue;\n    const launchdManaged = launchdPid !== null && parentOf(pid) === launchdPid;\n    if (/dsh-setup\\.mjs/.test(m[2])) {\n      if (!launchdManaged) watcher.push(pid);\n      continue;\n    }\n    if (/dsh-bridge\\.mjs/.test(m[2])) {\n      allBridge.push(pid);\n      if (!launchdManaged) bridge.push(pid); // launchd 托管的 bridge 子进程（原语义：不计入 manual.bridge）\n    }\n  }\n  // scanDegraded/bridgeEvidence 与 Windows 版对齐（见 windowsManualStatus 的注释）：\n  // POSIX 上 pgrep 匹配的就是命令行本身，不存在「镜像名不对」的盲区。\n  // 注意 pgrep「没匹配到」= 退出码 1 + 无输出 + 无错误输出 ⇒ 这是**有效结论（0 个）**，不是 degraded；\n  // 只有 pgrep 本身不存在/执行失败（stderr 非空）才算扫描不可用。\n  return {\n    watcher, bridge, allBridge,\n    scanDegraded: Boolean(pg.stderr && pg.stderr.trim()),\n    bridgeEvidence: allBridge.length ? [\"pgrep\"] : [],\n  };\n}\n\n// ---------- 插件市场一键全功能：缺桌面运行环境时自动后台安装 dsh-remote ----------\n\n/** 「上一次自动启动失败的原话 + 连续次数」——同一条结论不重复刷日志（见 ensureConnection 的注释）。 */\nconst lastAutostartFailure = new Map();\n\nconst PROVISION_MARKER = \".dsh-setup-installing\";\nconst AUTO_INSTALL_LOG = \".dsh-setup-install.log\";\nconst STALE_MARKER_MS = 30 * 60 * 1000; // 超过该时长视为上次进程残留，插件启动时清理\n/**\n * 「本次运行环境是插件自愈补装的」记录文件（install_source 判据）：\n * 插件市场只装面板插件时，桌面运行环境由插件后台 `npx @mrrisega/dsh-remote` 补上，\n * 这条路径归为 install_source=plugin_market；由用户自己跑安装器的（plist 里带\n * DSH_BRIDGE_INSTALL_SOURCE=npx）归为 npx。见 installSourceOf()。\n */\nconst PROVISIONED_MARKER = \".dsh-provisioned-by-plugin\";\n/**\n * 自愈 watcher 轮询间隔（默认 12s）。DSH_RELAY_SELFHEAL_MS 可覆盖——仅供测试把\n * 崩溃循环自愈链路压到亚秒级验证，生产不必设置。调用时读取（而非模块加载时固定），\n * 测试才能在 import 之后再改。\n */\nfunction selfhealIntervalMs() {\n  return Math.max(200, Number(process.env.DSH_RELAY_SELFHEAL_MS) || 12_000);\n}\n\n/**\n * ★★ 2026-10-13 自愈重启护栏（熔断 + 退避）—— 修「12 秒重启风暴」的第二道闸。\n *\n * 为什么在\"权威存活判据\"之外还必须再有一道：\n *   权威判据解决的是\"**活着却被判成死**\"（见 `linuxSystemdUnitState()`）。\n *   但如果 bridge **真的**起不来（上游端口不对、运行环境半装、unit 写不进去、unit 一直 failed），\n *   旧的 12s 循环同样会每拍重启一次 —— 那是同一个病的另一种形态：\n *   **一次真实故障被翻译成\"每天 7200 次重启\"**（历史上 Windows 补装失败就出过 12 秒一次、\n *   累计 606 次的失败风暴，见 `provisionRetryGate` 的注释）。所以：\n *     · 同一 relayDir、**本进程生命周期内**的破坏性重启最多 `SELFHEAL_MAX_RESTARTS` 次；\n *     · 两次之间至少隔 `selfhealMinRestartMs()`（默认 5 分钟）；\n *     · 超限就**停手**，并把原因明确写进安装日志（面板「复制诊断信息」与用户主动上报的\n *       诊断包里都会带上它）——而不是静默地每 12 秒再来一次。\n *\n * 为什么上限按\"本进程生命周期\"而不是\"每天\"：合法的上游变更（dsh web 换端口）几乎总伴随着\n * dsh web 重启，而重启就会重置这份记录 —— 所以 3 次对正常用户绰绰有余，对故障循环刚好够呛。\n * `DSH_RELAY_SELFHEAL_MIN_RESTART_MS` 仅供本仓库测试把节奏压到亚秒级\n * （与 `DSH_RELAY_SELFHEAL_MS` / `DSH_RELAY_WEDGE_MS` 同一约定）：生产不设置。\n */\nconst SELFHEAL_MAX_RESTARTS = 3;\nconst SELFHEAL_MIN_RESTART_MS = 5 * 60 * 1000;\nfunction selfhealMinRestartMs() {\n  const v = Number(process.env.DSH_RELAY_SELFHEAL_MIN_RESTART_MS);\n  return Number.isFinite(v) && v >= 0 ? v : SELFHEAL_MIN_RESTART_MS;\n}\n/** relayDir → { count, lastAt, blockedLine }；blockedLine = 已经告知过的\"被拦下\"结论（防刷屏）。 */\nconst selfhealRestarts = new Map();\nfunction selfhealGuardOf(relayDir) {\n  return selfhealRestarts.get(relayDir) || { count: 0, lastAt: 0, blockedLine: \"\" };\n}\n\n/**\n * 现在允许对这个 relayDir 做**破坏性重启**吗？（纯查询，不改状态 —— 调用方在真的重启之后\n * 用 `noteSelfhealRestart` 记账，这样\"只查不记\"的路径不会凭空消耗额度。）\n * @returns {{allowed:boolean, reason:\"ok\"|\"too-soon\"|\"exhausted\", count:number, waitMs:number}}\n */\nfunction selfhealRestartGate(relayDir, now = Date.now()) {\n  const rec = selfhealGuardOf(relayDir);\n  if (rec.count >= SELFHEAL_MAX_RESTARTS) return { allowed: false, reason: \"exhausted\", count: rec.count, waitMs: 0 };\n  const min = selfhealMinRestartMs();\n  const since = now - (rec.lastAt || 0);\n  if (rec.lastAt && since < min) return { allowed: false, reason: \"too-soon\", count: rec.count, waitMs: min - since };\n  return { allowed: true, reason: \"ok\", count: rec.count, waitMs: 0 };\n}\n\n/**\n * 记一次**真的做了**破坏性重启，并留下一行可见日志。\n *\n * ★ 可观测性是这次修复的一半：这个故障拖了 3 个月才被定位，直接原因就是\"重连风暴在中继侧\n *   只被日志抑制、在客户端侧又什么都没记\"——运维侧全程看不见。所以重启事件必须留痕：\n *   写既有的安装日志（`.dsh-setup-install.log`，面板诊断与用户上报都会带它的尾部），不新造通道。\n * @param {string} why 人类可读的原因（\"权威判据说没在跑\" / \"上游地址变更\"）\n * @param {string} outcome 重启后的结果（\"running\" / \"failed: …\"）\n */\nfunction noteSelfhealRestart(relayDir, why, outcome = \"\") {\n  const rec = selfhealGuardOf(relayDir);\n  rec.count += 1;\n  rec.lastAt = Date.now();\n  rec.blockedLine = \"\"; // 结论变了：下一次\"被拦下\"要重新说一遍\n  selfhealRestarts.set(relayDir, rec);\n  appendLogLine(relayDir, AUTO_INSTALL_LOG,\n    `[dsh-remote-web] 自愈重启 bridge（第 ${rec.count}/${SELFHEAL_MAX_RESTARTS} 次·本进程生命周期内，`\n    + `之后 ${Math.round(selfhealMinRestartMs() / 1000)} 秒内不再重启）：${why}${outcome ? ` → ${outcome}` : \"\"}`);\n  return rec;\n}\n\n/**\n * 「这一拍本来想重启，但被护栏拦下了」——**同一条结论只说一次**（理由同 `noteAutostartFailure`：\n * 每 12 秒写一行的日志等于没有日志，用户复制过来的诊断里会全是重复行，第一现场反而被淹没）。\n * 注意：文案里**不得带倒计时秒数**，否则每一拍的文本都不同，去重就失效了。\n */\nfunction noteSelfhealBlocked(relayDir, gate) {\n  const rec = selfhealGuardOf(relayDir);\n  const line = gate.reason === \"exhausted\"\n    ? `已停止自愈重启 bridge：本进程生命周期内已重启 ${SELFHEAL_MAX_RESTARTS} 次仍未就绪，`\n      + `为避免\"每 ${Math.round(selfhealIntervalMs() / 1000)} 秒杀掉一次正在跑的隧道\"已熔断；`\n      + `请点面板「一键更新」，或查看 bridge 日志确认真正的失败原因`\n    : `已暂缓自愈重启 bridge：距上次重启不足 ${Math.round(selfhealMinRestartMs() / 1000)} 秒`\n      + `（不会每 ${Math.round(selfhealIntervalMs() / 1000)} 秒重启一次，那样会反复切断手机镜像连接）`;\n  if (rec.blockedLine === line) return false;\n  rec.blockedLine = line;\n  selfhealRestarts.set(relayDir, rec);\n  appendLogLine(relayDir, AUTO_INSTALL_LOG, `[dsh-remote-web] ${line}`);\n  return true;\n}\n\n/** 桥已确认就绪：清掉护栏状态，让\"后来真的再挂一次\"能重新自愈（否则额度会被历史故障吃光）。 */\nfunction resetSelfhealGuard(relayDir) {\n  selfhealRestarts.delete(relayDir);\n}\n\n/** 向日志追加一行（多个子进程写同一日志用 append 模式，互不覆盖）。 */\nfunction appendLogLine(relayDir, name, line) {\n  try {\n    const fd = openSync(join(relayDir, name), \"a\");\n    try {\n      writeFileSync(fd, `\\n${line}\\n`);\n    } finally {\n      closeSync(fd);\n    }\n  } catch { /* 非关键 */ }\n}\n\n/**\n * 清理“进程残留”标记的实现见上方小工具区 sweepStaleMarkers（pid 存活 + 超时双保险）。\n */\n\n/** 插件市场只装了 UI 插件;若桌面缺 dsh-remote 运行环境(dsh-setup.mjs=bridge/自启动),\n * 由插件在后台自动执行一次 `npx @mrrisega/dsh-remote` 补齐,用户无需手动跑命令。\n * 已有环境(包括手动 npx 装过)直接跳过。返回 true=已就绪。\n * 注意：默认优先官方源——镜像(npmmirror)可能滞后于刚发布的版本，装到旧版会把\n * 已被 0.4.5 移除的“用户 include”重新写回 profile（历史上造成 dsh web 重复 ID 崩溃）。 */\n/**\n * 补装失败退避（2026-09-15 生产故障）。\n *\n * 背景：Windows 用户补装 `npx @mrrisega/dsh-remote` 持续失败时，自愈调度每轮都重试，\n * 生产遥测里看到单机 12 秒一次、累计 606 次的失败风暴（1659 次 install_failed 全在 Windows）。\n * 这既刷屏日志、也让真实失败原因淹没在噪声里。\n *\n * 策略：连续失败后按 30s → 2m → 10m 退避（封顶 10 分钟）；用户点「一键修复 / 一键更新」时\n * 显式放行（resetProvisionRetry），保证人工操作永远能立即重试。\n */\nconst PROVISION_RETRY_BACKOFF_MS = [30_000, 120_000, 600_000];\n\nfunction provisionRetryGate(relayDir) {\n  const key = String(relayDir);\n  let st = provisionRetry.get(key);\n  if (!st) { st = { fails: 0, nextAt: 0 }; provisionRetry.set(key, st); }\n  if (Date.now() < st.nextAt) {\n    return { ok: false, waitMs: st.nextAt - Date.now(), fails: st.fails };\n  }\n  return { ok: true, st };\n}\n\nfunction noteProvisionFailure(relayDir) {\n  const key = String(relayDir);\n  const st = provisionRetry.get(key) || { fails: 0, nextAt: 0 };\n  st.fails += 1;\n  const wait = PROVISION_RETRY_BACKOFF_MS[Math.min(st.fails, PROVISION_RETRY_BACKOFF_MS.length) - 1];\n  st.nextAt = Date.now() + wait;\n  provisionRetry.set(key, st);\n  return { fails: st.fails, waitMs: wait };\n}\n\nfunction noteProvisionSuccess(relayDir) {\n  provisionRetry.delete(String(relayDir));\n}\n\n/** 用户显式要求重试（一键修复/一键更新）→ 清掉退避，让这次一定真的执行。 */\nfunction resetProvisionRetry(relayDir) {\n  provisionRetry.delete(String(relayDir));\n}\n\n// ---------- 运行环境随插件分发（0.6.12）：本地拷贝优先，npx 只作兜底 ----------\n//\n// 【2026-09-23 生产取证】Windows 上「装插件 → 后台 npx 补装运行环境」这条链是最大的流失源：\n// 近 14 天 427 台 win32 里 138 台 install_failed（32%）；v0.6.6 的 95 台里 73 台装机失败，\n// 其中 48 台点过「一键更新」却一台都没救回来。npx 在 Windows 上可失败的环节太多：\n// spawn npx.cmd 的 EINVAL、控制台代码页（GBK）导致连归因都读不出来、npm 缓存目录不可写、\n// 拷贝到一半被打断 → 半装运行时（入口在、依赖不在，插件却报「已就绪」）。\n// 现在插件包自带 runtime/（scripts/bundle-runtime.mjs 打进 npm 包），补装退化为**本地文件拷贝**：\n// 零网络、零 npx、零代码页，而且运行环境版本永远等于插件版本（不再出现插件 0.6.10 配运行时 0.6.9）。\n// 拷贝完必须自检（missingRuntimeFiles）——「半装」绝不当作成功，那正是上一版用户卡死的直接原因。\n\n/**\n * 本插件自带的运行环境目录（lib/ → ../runtime）；仓库开发形态/未打包时返回 null。\n * DSH_RELAY_BUNDLED_RUNTIME 可显式指定（测试/诊断用；指向不存在的目录 = 强制走 npx 兜底分支）。\n */\nfunction readBundledRuntime() {\n  const override = String(process.env.DSH_RELAY_BUNDLED_RUNTIME || \"\").trim();\n  if (override) return existsSync(join(override, \"dsh-setup.mjs\")) ? override : null;\n  try {\n    const here = dirname(fileURLToPath(import.meta.url));\n    const cand = join(here, \"..\", \"runtime\");\n    return existsSync(join(cand, \"dsh-setup.mjs\")) ? cand : null;\n  } catch { return null; }\n}\n\n/** 自带运行环境拷贝失败的退避（避免每次面板轮询都重试同一件不可能的事）。 */\nconst bundledCopyFails = new Map(); // relayDir → nextAt\n\n/**\n * 用插件自带的运行环境就地补装（纯本地拷贝）。\n * @returns {{ok:boolean, reason?:string, detail?:string, missing?:string[]}}\n */\nfunction provisionFromBundledRuntime(relayDir) {\n  const src = readBundledRuntime();\n  if (!src) return { ok: false, reason: \"no-bundled-runtime\" };\n  if (skipsSystemOps()) return { ok: false, reason: \"skipped\" };\n  if (Date.now() < (bundledCopyFails.get(relayDir) || 0)) return { ok: false, reason: \"backoff\" };\n  try {\n    mkdirSync(relayDir, { recursive: true });\n    copyFileSync(join(src, \"dsh-setup.mjs\"), join(relayDir, \"dsh-setup.mjs\"));\n    for (const dir of [\"clients\", \"node_modules\"]) {\n      const from = join(src, dir);\n      if (!existsSync(from)) continue;\n      cpSync(from, join(relayDir, dir), { recursive: true, force: true });\n    }\n    // 版本标记：与插件同版（诊断据此显示「运行时 x.y.z」）\n    try { writeFileSync(join(relayDir, \".dsh-setup-version\"), `${PLUGIN_VERSION}\\n`); } catch { /* 非关键 */ }\n    const missing = missingRuntimeFiles(relayDir);\n    if (missing.length) {\n      bundledCopyFails.set(relayDir, Date.now() + 60_000);\n      return { ok: false, reason: \"incomplete\", missing };\n    }\n    bundledCopyFails.delete(relayDir);\n    return { ok: true };\n  } catch (e) {\n    bundledCopyFails.set(relayDir, Date.now() + 60_000);\n    return { ok: false, reason: \"copy-failed\", detail: e.message };\n  }\n}\n\nfunction ensureRuntime(relayDir) {\n  if (UNINSTALLED_DIRS.has(relayDir)) return false; // 已彻底卸载：不再自动安装运行环境\n  if (runtimeReady(relayDir)) return true;\n  if (skipsSystemOps()) return false; // 测试隔离：绝不在用例里 spawn 真实 npx 安装\n  // ① 插件自带的运行环境优先：本地拷贝即可，**不经过 npx、不联网**。\n  //    这一条同时治好「半装运行环境」（runtimeReady 为假 → 整份重拷 → 自检通过才算成功）。\n  const local = provisionFromBundledRuntime(relayDir);\n  if (local.ok) {\n    appendLogLine(relayDir, AUTO_INSTALL_LOG,\n      `[dsh-remote-web] 已用插件自带的运行环境就地补齐（v${PLUGIN_VERSION}，本地拷贝，未使用 npx）`);\n    backupConfigFile(relayDir); // 安装完成后备份配对信息（文件不存在则静默跳过；内容绝不写日志）\n    telemetryRuntimeReady(relayDir);\n    return true;\n  }\n  if (local.reason === \"incomplete\") {\n    appendLogLine(relayDir, AUTO_INSTALL_LOG,\n      `[dsh-remote-web] 自带运行环境拷贝后仍不完整（缺 ${local.missing.slice(0, 3).join(\", \")}）→ 转 npx 补装`);\n    telemetryRecord(relayDir, \"install_failed\", { fail_code: \"install_script_missing\" });\n  }\n  // ② 兜底：npx 补装（老路径保持不变；仓库开发形态、或没打包 runtime/ 的安装形态走这里）\n  const gate = provisionRetryGate(relayDir);\n  if (!gate.ok) {\n    // 退避中：不重复 spawn（避免失败风暴）。面板会据 provisionRetryInfo() 显示\"上次失败、X 后可重试\"。\n    return false;\n  }\n  const marker = join(relayDir, PROVISION_MARKER);\n  if (existsSync(marker)) return false; // 正在安装中\n  try {\n    mkdirSync(relayDir, { recursive: true });\n    const log = join(relayDir, AUTO_INSTALL_LOG);\n    const watchKey = `install:${relayDir}`;\n    const clear = () => {\n      stopProgressWatch(watchKey);\n      try { rmSync(marker, { force: true }); } catch { /* ignore */ }\n    };\n    // 补装失败（spawn 都起不来）时统一收尾：清安装标记 + 记日志 + 进退避 + 匿名遥测。\n    // 没有这条兜底，spawn 的异步 'error' 会变成未捕获异常打挂宿主（旧实现在 Windows 上正是如此）。\n    const failSpawn = (e, kind) => {\n      clear();\n      appendLogLine(relayDir, AUTO_INSTALL_LOG, `[auto-install] 启动 npx 失败(${kind}): ${e.message}`);\n      noteProvisionFailure(relayDir);\n      telemetryRecord(relayDir, \"install_failed\", { fail_code: telemetryFailCodeFromError(e) });\n    };\n    let stalledInstall = false; // 本轮是否因\"长时间无输出\"被判卡住（归因用）\n    const npx = npxInvocation();\n    const { child, error } = safeSpawn(npx.command, [...npx.args, \"--yes\", UPDATE_SPEC], {\n      detached: true,\n      // Windows 上跑 npx.cmd 必须经 shell（Node ≥20.12 起否则 EINVAL）；走 node+npx-cli.js 时不需要。\n      shell: npx.shell,\n      // Windows：别让 Node 给子进程开一个控制台窗口（POSIX 上该选项被忽略）\n      windowsHide: true,\n      // DSH_BRIDGE_INSTALL_SOURCE：本机运行环境是插件自愈补的 → 安装器原样透传到 plist/bridge env，\n      // 于是设备行上的 install_source 如实记成 plugin_market（而不是安装器默认的 npx）。\n      // DSH_BRIDGE_HARNESS_VERSION 同理：安装器会把它写进 plist；不给的话，桥重启后就丢了宿主版本。\n      env: spawnEnv({ npm_config_registry: \"https://registry.npmjs.org\", DSH_BRIDGE_INSTALL_SOURCE: \"plugin_market\", DSH_BRIDGE_HARNESS_VERSION: harnessVersion() }),\n      stdio: [\"ignore\", openSync(log, \"a\"), openSync(log, \"a\")],\n      onError: (e) => failSpawn(e, npx.kind),\n    });\n    if (error || !child) {\n      failSpawn(error || new Error(\"spawn 未返回子进程\"), npx.kind);\n      return false;\n    }\n    writeMarker(marker, child.pid); // 记 pid：宿主重启后可立即清理死进程残留\n    // 【0.6.9 关键修复】补装同样要有无输出看门狗。\n    // 这一条直接对应\"面板注册完成、设备却没有上报\"的装机流失：npx 拉取在\"连得上但传不动\"的\n    // 链路上会**挂起**（进程活着、永远不产出 exit），旧实现只在\"pid 死 或 标记超 10 分钟\"时才清理，\n    // 于是卡住的安装能吃满 10 分钟退避窗口、反复失败；用户看到的是\"正在安装…\"永远不动。\n    startProgressWatch(watchKey, {\n      relayDir, logName: AUTO_INSTALL_LOG, kind: \"install\",\n      getChild: () => child,\n      onStall: (idle) => {\n        stalledInstall = true;\n        appendLogLine(relayDir, AUTO_INSTALL_LOG,\n          `[auto-install] 已 ${Math.round(idle / 1000)}s 无输出 → 判定卡住，结束该进程并按失败处理（下一轮会重试）`);\n      },\n    });\n    // 记下「本机运行环境是插件自愈补的」：登录后的 /api/install-report 与 bridge 设备登记\n    // 都据此上报 install_source=plugin_market（区分用户自己跑 npx 安装器的那条路径）。\n    try {\n      writeFileSync(join(relayDir, PROVISIONED_MARKER),\n        JSON.stringify({ at: Date.now(), version: PLUGIN_VERSION, source: \"plugin_market\" }));\n    } catch { /* 非关键：上报时按缺省判据降级 */ }\n    // 匿名遥测：补装生命周期（install_started → runtime_ready / install_failed(fail_code)）。\n    // 失败原因只归类到白名单 fail_code，绝不外发原始错误文本（可能含路径/主机名/用户名）。\n    const tb = telemetryBook(relayDir);\n    tb.installStartedAt = Date.now();\n    telemetryRecord(relayDir, \"install_started\");\n    child.on(\"exit\", (code) => {\n      clear();\n      appendLogLine(relayDir, AUTO_INSTALL_LOG, `[auto-install] npx 退出 code=${code ?? \"?\"}`);\n      if (code === 0 && runtimeReady(relayDir)) {\n        noteProvisionSuccess(relayDir);\n        backupConfigFile(relayDir); // 安装完成后备份配对信息（无配置/失败都静默）\n        telemetryRuntimeReady(relayDir); // 退出码 0 ≠ 装好了\n      } else {\n        // 退出码非 0、卡住超时、或退出码 0 但安装脚本没落盘（装到一半/装错包）→ 都算失败并进入退避\n        const code2 = stalledInstall ? \"runtime_install_timeout\"\n          : (code === 0 ? \"install_script_missing\" : telemetryFailCodeFromText(readTail(log)));\n        const back = noteProvisionFailure(relayDir);\n        appendLogLine(relayDir, AUTO_INSTALL_LOG,\n          `[auto-install] 第 ${back.fails} 次失败（归因 ${code2}），${Math.round(back.waitMs / 1000)}s 后才会重试`);\n        telemetryRecord(relayDir, \"install_failed\", { fail_code: code2 });\n      }\n    });\n    child.on(\"error\", (e) => {\n      clear();\n      appendLogLine(relayDir, AUTO_INSTALL_LOG, `[auto-install] 启动失败: ${e.message}`);\n      console.warn(`[dsh-remote-web] 自动安装子进程启动失败: ${e.message}`);\n      noteProvisionFailure(relayDir);\n      telemetryRecord(relayDir, \"install_failed\", { fail_code: telemetryFailCodeFromError(e) });\n    });\n    child.unref();\n    console.log(`[dsh-remote-web] 检测到缺少桌面运行环境,已在后台自动安装(日志: ${log}),完成后将自动启动 bridge`);\n    return false;\n  } catch (e) {\n    console.warn(`[dsh-remote-web] 自动安装启动失败: ${e.message}`);\n    try { rmSync(marker, { force: true }); } catch { /* ignore */ }\n    noteProvisionFailure(relayDir);\n    telemetryRecord(relayDir, \"install_failed\", { fail_code: telemetryFailCodeFromError(e) });\n    return false;\n  }\n}\n\n/**\n * 生成 plist（与 dsh-setup.mjs 的 writeAutostartFile **必须同构**），返回路径。\n *\n * ⚠️ 两份模板历史上漂移过、并因此各造成一个真机故障（插件每次自愈/启动都会重写 plist，\n *    所以**插件这份谁写谁说了算**，漂移等于把安装器那份正确的覆盖掉）：\n *   · 漏 `/usr/sbin`、`/sbin`（SERVICE_PATH）→ bridge 找不到 `ioreg` → 机器指纹静默退化成\n *     hostname 哈希（改一次主机名就被当成新设备）；\n *   · 漏 `LimitLoadToSessionType` → `bootstrap user/<uid>` 失败（rc=5）→ 域阶梯回退到\n *     gui/<uid>，而 macOS 26 上 gui 域是 on-demand-only、`RunAtLoad`/`KeepAlive` 失效 →\n *     **服务被系统（BTM）回收后再也回不来**，只能手动点面板「启动」。\n *   两者都由 launchd-domain.test.mjs 的跨文件不变量锁死。\n */\nfunction writeAutostartFile(relayDir) {\n  const plistPath = launchAgentPath();\n  if (!plistPath) return null;\n  const setupUrl = join(relayDir, \"dsh-setup.mjs\");\n  const plist = `<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n<plist version=\"1.0\"><dict>\n  <key>Label</key><string>com.dshremote.bridge</string>\n  <key>ProgramArguments</key>\n  <array><string>${NODE_BIN}</string><string>${setupUrl}</string><string>run</string></array>\n  <key>RunAtLoad</key><true/>\n  <key>KeepAlive</key><true/>\n  <key>ThrottleInterval</key><integer>10</integer>\n  <key>LimitLoadToSessionType</key><array><string>Aqua</string><string>Background</string></array>\n  <key>StandardOutPath</key><string>${join(relayDir, \".dsh-bridge.log\")}</string>\n  <key>StandardErrorPath</key><string>${join(relayDir, \".dsh-bridge.log\")}</string>\n  <key>EnvironmentVariables</key><dict><key>PATH</key><string>${SERVICE_PATH}</string>${SERVICE_NODE_ENV_PLIST}<key>DSH_BRIDGE_INSTALL_SOURCE</key><string>${installSourceOf(relayDir)}</string><key>DSH_BRIDGE_INSTALL_VERSION</key><string>${PLUGIN_VERSION}</string><key>DSH_BRIDGE_HARNESS_VERSION</key><string>${harnessVersion()}</string></dict>\n</dict></plist>`;\n  mkdirSync(dirname(plistPath), { recursive: true });\n  writeFileSync(plistPath, plist, { mode: 0o644 });\n  return plistPath;\n}\n\n/**\n * 自启动 plist 里的入口脚本是否已不存在（不存在 = launchd 必然陷入崩溃循环）。\n * 只解析 ProgramArguments 里的第一个 .mjs 参数，不引入 plist 解析依赖。\n */\nfunction plistEntryMissing() {\n  const plistPath = launchAgentPath();\n  if (!plistPath || !existsSync(plistPath)) return false;\n  let raw = \"\";\n  try { raw = readFileSync(plistPath, \"utf8\"); } catch { return false; }\n  const m = raw.match(/<string>([^<]*\\.mjs)<\\/string>/);\n  if (!m) return false;\n  return !existsSync(m[1]);\n}\n\n/**\n * 摘掉「指向不存在入口脚本」的自启动项，止住 launchd 崩溃循环。\n *\n * 现场（0.6.1 及更早）：只装插件半的用户在面板点「启动 bridge」或首次登录时，\n * startBridge 会无条件生成指向 `<relayDir>/dsh-setup.mjs` 的 plist 并 bootstrap，\n * 而该文件并不存在 → launchd KeepAlive 无限重拉（日志 20+ 次 MODULE_NOT_FOUND、\n * `runs = 23 / last exit code = 1`）。此时仅删 plist 文件没用：作业已加载在 launchd 里，\n * 必须 bootout 才会停。判据严格限定为「入口脚本确实缺失」，绝不碰正常停止的服务。\n * @returns {boolean} 是否执行了清理\n */\nfunction reapBrokenAutostart(relayDir) {\n  if (skipsSystemOps()) return false;\n  // 只有 macOS 有 launchd 自启动项可摘；Windows/Linux 走的是 systemd/无自启动，判据不适用。\n  if (!isDarwin()) return false;\n  if (!plistEntryMissing()) return false;\n  // 归属校验：这份 plist 不是给本 relayDir 装的 → 一个字节都不动（见 plistOwnedByRelayDir）\n  if (!plistOwnedByRelayDir(relayDir)) return false;\n  const st = launchdStatus();\n  if (!st.running && !st.crashing && !st.state) return false; // 作业未被 launchd 加载、无可摘的东西\n  for (const target of launchTargets()) sh(`launchctl bootout ${target}`);\n  try { rmSync(launchAgentPath(), { force: true }); } catch { /* 非关键 */ }\n  appendLogLine(relayDir, AUTO_INSTALL_LOG,\n    `[dsh-remote-web] 已摘除失效自启动：plist 入口 ${join(relayDir, \"dsh-setup.mjs\")} 不存在`\n    + `（launchd state=${st.state || \"?\"}, runs=${st.runs ?? \"?\"}, lastExit=${st.lastExitCode ?? \"?\"}）→ 转入后台补装运行环境`);\n  return true;\n}\n\n/** 写 pid 文件（Windows 进程发现用；写不了不致命，还有 PowerShell 兜底扫描）。 */\nfunction writePidFile(relayDir, name, pid) {\n  if (!Number.isInteger(pid) || pid <= 0) return false;\n  try {\n    mkdirSync(relayDir, { recursive: true });\n    writeFileSync(join(relayDir, name), String(pid), { mode: 0o600 });\n    return true;\n  } catch {\n    return false;\n  }\n}\n\n/** 结束一个进程（Windows 用 taskkill 连子进程一起收；POSIX 用给定信号）。 */\nfunction killPid(pid, signal = \"SIGTERM\") {\n  if (!Number.isInteger(pid) || pid <= 0) return false;\n  if (isWindows()) {\n    const r = spawnSync(\"taskkill\", [\"/PID\", String(pid), \"/T\", \"/F\"], { windowsHide: true, encoding: \"utf8\", timeout: 8000 });\n    return r.status === 0 || pidAlive(pid) === false;\n  }\n  try {\n    process.kill(pid, signal);\n    return true;\n  } catch {\n    return pidAlive(pid) !== true; // ESRCH = 本来就不在了，也算成功\n  }\n}\n\n/**\n * 「脱离进程」方式启动 bridge（Windows 必用；macOS/Linux 在 launchd/systemd 托管不了时兜底）。\n *\n * Windows 上没有服务管理器自启动；macOS 上 launchd 被系统置为 on-demand-only（gui 域）时也托管不住。\n * 此时插件直接把 watcher（`node <relayDir>/dsh-setup.mjs run`）作为脱离进程拉起：\n * 这与用户手动跑 `dsh-remote run` 是**同一条代码路径**，watcher 自己盯着 127.0.0.1:3080，\n * dsh web 活着就拉起 dsh-bridge.mjs、dsh web 退出就把 bridge 停掉。\n * 代价（如实告知用户）：不随开机自启；但 dsh web 每次启动后插件都会在自愈轮次里重新拉起它。\n */\nfunction startBridgeDetached(relayDir, fallbackReason = \"\") {\n  if (skipsSystemOps()) return { ok: false, status: \"skipped\", detail: \"测试隔离（DSH_RELAY_SKIP_SERVICE=1）：跳过真实服务操作\" };\n  if (!runtimeReady(relayDir)) {\n    ensureRuntime(relayDir);\n    return {\n      ok: false,\n      status: \"provisioning\",\n      runtimeMissing: true,\n      detail: \"桌面运行环境（bridge）尚未安装，已在后台自动安装，完成后会自动启动 bridge——请稍候刷新面板（也可点下方「一键更新」查看进度）\",\n    };\n  }\n  // 幂等：watcher 已在跑就别再拉第二个（否则会有两个 bridge 抢同一个设备登记）。\n  // ⚠️ 2026-10-29（PID 复用）：pid **活着**不等于它是我们的 watcher —— pid 文件可能是上一任守护\n  //    留下的，而那个 pid 早已被系统回收给无关进程。不校验就会**永久**返回「已在运行」⇒\n  //    面板「启动 / 立即修复」与每轮自愈全部空转（这与「多次修复都没解决」是同一类故障）。\n  const forced = takeForcedDetachedSpawn();\n  if (forced) {\n    // 旧守护杀不掉/被跳过结束，但本轮确实要「换掉它」：跳过幂等判断，直接拉起新实例。\n    // 新实例会用自己的 pid 覆盖 pid 文件；旧实例若真活着，dsh-setup.mjs 自己的 pid 去重会拦住它自己。\n    appendLogLine(relayDir, AUTO_INSTALL_LOG,\n      `[dsh-remote-web] ${forced} → 强制拉起新守护（跳过「已在运行」幂等判断）`);\n  }\n  const existing = forced ? null : readPidFile(relayDir, WATCHER_PID_FILE);\n  if (existing && existing !== process.pid && pidAlive(existing) !== false) {\n    const id = pidIdentityOf(existing, relayDir);\n    const fresh = pidFileAgeMs(relayDir, WATCHER_PID_FILE) < PID_FILE_TRUST_MS;\n    if (id.ident || (!id.cmdKnown && fresh)) return { ok: true, status: \"running\", pid: existing };\n    appendLogLine(relayDir, AUTO_INSTALL_LOG,\n      `[dsh-remote-web] watcher pid 文件里的 pid=${existing} `\n      + `${id.cmdKnown ? \"不是本运行环境的进程（PID 可能已被系统回收）\" : \"无法确认归属且 pid 文件已超 10 分钟未更新\"}`\n      + \" → 按过期处理，重新拉起守护\");\n    removePidFileQuiet(relayDir, WATCHER_PID_FILE);\n  }\n  const setup = join(relayDir, \"dsh-setup.mjs\");\n  if (!existsSync(setup)) return { ok: false, status: \"not-installed\", detail: `运行环境入口脚本不存在（${setup}）` };\n  publishUpstream(relayDir); // 落盘上游地址：开机自启拉起的守护（没有 env）据此找到 dsh web\n  const log = join(relayDir, \".dsh-bridge.log\");\n  let out = \"ignore\";\n  try { out = openSync(log, \"a\"); } catch { /* 打不开日志：退化到丢弃输出，不阻断启动 */ }\n  const { child, error } = safeSpawn(process.execPath, [setup, \"run\"], {\n    detached: true,\n    cwd: homedir(),\n    env: spawnEnv({\n      DSH_BRIDGE_INSTALL_SOURCE: installSourceOf(relayDir),\n      DSH_BRIDGE_INSTALL_VERSION: PLUGIN_VERSION,\n      // 宿主版本：bridge 自己推不出来（它是另一个进程），只能由插件在宿主进程内问出来再注入。\n      DSH_BRIDGE_HARNESS_VERSION: harnessVersion(),\n      // 上游端口**必须**透传：watcher 用它判断「dsh web 在线吗」，bridge 用它做转发目标。\n      // 不传的话两边都回落到写死的 3080 —— dsh web 不在默认端口时 bridge 永远不启动（0.6.12 修）。\n      DSH_BRIDGE_UPSTREAM: upstreamUrl(),\n      // C7：**必须显式**把 relayDir 传给 watcher。\n      // 旧实现只靠 spawnEnv 继承宿主的 DSH_RELAY_DIR（第 7800+ 行：relayDir 也可能来自\n      // config.relayDir），于是\"relayDir 来自配置、宿主环境没有该变量\"时，watcher/bridge 会\n      // 回落到 ~/.dsh-remote —— 面板看到的现象是「守护在跑、bridge 永远不出现」（1415 那类故障），\n      // 而且 pid 文件/日志也都写去了另一个目录。\n      DSH_RELAY_DIR: relayDir,\n    }),\n    stdio: [\"ignore\", out, out],\n    windowsHide: true,\n    onError: (e) => appendLogLine(relayDir, AUTO_INSTALL_LOG, `[dsh-remote-web] 脱离进程启动 bridge 失败(${osPlatform()}): ${e.message}`),\n  });\n  if (typeof out === \"number\") { try { closeSync(out); } catch { /* 已随子进程继承，父进程这份可以关 */ } }\n  if (error || !child) {\n    const msg = (error || new Error(\"spawn 未返回子进程\")).message;\n    return { ok: false, status: \"failed\", detail: `启动 bridge 失败: ${msg}` };\n  }\n  writePidFile(relayDir, WATCHER_PID_FILE, child.pid);\n  child.unref();\n  return {\n    ok: true,\n    status: \"running\",\n    pid: child.pid,\n    // 如实区分两条路径：装过（且平台支持）就有自启动；否则只有\"重开 dsh web 自动拉起\"这一层保障\n    detail: isWindows() && windowsTaskRegistered()\n      ? \"已在后台启动 bridge 守护（已注册登录任务，下次登录会自动运行）\"\n      : `已在后台启动 bridge 守护${fallbackReason ? `（${fallbackReason}；不随开机自启，重开 dsh web 时插件会自动拉起）` : \"（不随开机自启，重开 dsh web 时插件会自动拉起）\"}`,\n  };\n}\n\n/* ── F4：动进程之前先验身份（2026-10-29 修复 PID 复用误杀）────────────────────────\n *\n * 旧实现 `stopBridgeDetached` 对 pid 文件里的 pid 只做 pidAlive() 判活，然后直接\n * `killPid()`（Windows = `taskkill /PID <pid> /T /F`）。pid 一旦被系统回收给无关进程，\n * 这条路径会**杀掉一棵与产品无关的进程树**。现在按「身份 / 新鲜度」两级决定：\n *   · ident 非空（命令行确认是本 relayDir 的 dsh-setup.mjs / dsh-bridge.mjs）→ 结束它；\n *   · cmdKnown=true 但 ident=\"\"（取到了命令行、明确不是我们的）→ **不结束**，只清残留 pid 文件；\n *   · 取不到命令行 → 只有 pid 文件在 PID_FILE_TRUST_MS 内才敢结束，否则跳过并写一行安装日志。\n * pid 文件的删除同样收紧：**只有「进程已确认结束」或「已确认不是我们的进程」才删**，\n * 不再无条件先删（那会让「进程还在、现场没了」成为常态，正是这次事故取证困难的原因之一）。\n */\nfunction pidFileVerdict(relayDir, name) {\n  const pid = readPidFile(relayDir, name);\n  if (!pid) return { name, pid: null, alive: false, ident: \"\", cmdKnown: false, ageMs: Infinity, fresh: false };\n  const alive = pidAlive(pid) !== false;\n  const ageMs = pidFileAgeMs(relayDir, name);\n  const id = alive ? pidIdentityOf(pid, relayDir) : { ident: \"\", cmdKnown: false };\n  return { name, pid, alive, ident: id.ident, cmdKnown: id.cmdKnown, ageMs, fresh: ageMs < PID_FILE_TRUST_MS };\n}\n\nfunction removePidFileQuiet(relayDir, name) {\n  try { rmSync(join(relayDir, name), { force: true }); } catch { /* 非关键 */ }\n}\n\n/* 「重启卡死守护」专用的一次性强制拉起标记。\n *\n * 场景：pid 文件里的守护**杀不掉**（pid 已被系统回收给无关进程 / kill 工具不可用 / 按安全纪律\n * 主动跳过）。这时 `startBridge` 的幂等判断会因「pid 文件还在且新鲜」再次返回「已在运行」→\n * 重启自愈变成永久 no-op（本次要根治的死循环换个形态回来）。所以由调用方显式下一个一次性标记，\n * 让紧接着的那次 `startBridgeDetached` 跳过幂等判断、直接拉起新实例。\n * 用模块级标记而不是改 `startBridge(relayDir)` 签名：那两处签名被源码契约用例按字面锁定。\n */\nlet forcedDetachedSpawn = \"\";\nfunction forceNextDetachedSpawn(reason) { forcedDetachedSpawn = String(reason || \"restart\"); }\nfunction takeForcedDetachedSpawn() { const r = forcedDetachedSpawn; forcedDetachedSpawn = \"\"; return r; }\n\n/** 停止「脱离进程」方式运行的 bridge（结束 watcher 与其 bridge 子进程，并清掉 pid 文件）。 */\nfunction stopBridgeDetached(relayDir, opts = {}) {\n  // 账号切换时用 force：即使处于测试隔离模式也要把进程停掉（否则\"换个账号\"在测试里走不通），\n  // 但隔离模式下仍只用信号结束**本插件记录的** pid，不碰任何系统服务。\n  if (skipsSystemOps() && !opts.force) return { ok: false, status: \"skipped\", detail: \"测试隔离（DSH_RELAY_SKIP_SERVICE=1）：跳过真实服务操作\" };\n  const decisions = [WATCHER_PID_FILE, BRIDGE_PID_FILE].map((name) => pidFileVerdict(relayDir, name));\n  const killed = [];\n  const skipped = [];\n  for (const d of decisions) {\n    if (!d.pid) { removePidFileQuiet(relayDir, d.name); continue; }      // 文件里没有有效 pid：无主残留\n    if (!d.alive) { removePidFileQuiet(relayDir, d.name); continue; }    // 已确认结束 → 删（安全）\n    if (d.ident) {\n      killPid(d.pid, \"SIGKILL\");                                        // Windows 上是 taskkill /T /F：连带子进程\n      killed.push(d.pid);\n      if (pidAlive(d.pid) === false) removePidFileQuiet(relayDir, d.name); // 只有确认结束才删\n      continue;\n    }\n    if (d.cmdKnown) {\n      // 取到了命令行、明确不是我们的进程（别的配置目录/别的脚本）：不结束，只清残留文件\n      appendLogLine(relayDir, AUTO_INSTALL_LOG,\n        `[dsh-remote-web] ${d.name} 里的 pid=${d.pid} 不是本运行环境的进程（PID 可能已被系统回收），`\n        + \"不结束它，按残留清理 pid 文件\");\n      removePidFileQuiet(relayDir, d.name);\n      continue;\n    }\n    // 取不到命令行：只有 pid 文件足够新才敢认为它是我们的进程；否则宁可漏杀\n    if (d.fresh) {\n      killPid(d.pid, \"SIGKILL\");\n      killed.push(d.pid);\n      if (pidAlive(d.pid) === false) removePidFileQuiet(relayDir, d.name); // 只有确认结束才删\n      continue;\n    }\n    skipped.push(d);\n  }\n  for (const d of skipped) {\n    appendLogLine(relayDir, AUTO_INSTALL_LOG,\n      `[dsh-remote-web] 无法确认 pid 归属，跳过结束（避免误杀）：${d.name} pid=${d.pid}`\n      + `（pid 文件已 ${Math.max(1, Math.round((d.ageMs || 0) / 60000))} 分钟未更新，且取不到该进程的命令行）`);\n  }\n  // 本轮「没能结束掉」的 pid（尝试过但杀不掉，或按安全纪律主动跳过）：\n  // 调用方（尤其是「重启卡死守护」那条自愈）用它决定要不要强制拉起新实例 ——\n  // 否则「pid 文件里那个 pid 杀不掉且仍然新鲜」会让重启变成永久 no-op。\n  const unresolvedPids = [...killed, ...skipped.map((d) => d.pid)].filter((pid) => pidAlive(pid) !== false);\n  // 复核：pid 文件之外可能还有用户手动跑起来、或用旧版运行时起的进程\n  const manual = manualStatus(relayDir);\n  const still = [...new Set([...manual.watcher, ...manual.bridge])];\n  return {\n    ok: still.length === 0,\n    status: still.length ? \"failed\" : \"stopped\",\n    pid: null,\n    killed,\n    skippedPids: skipped.map((d) => d.pid),\n    unresolvedPids,\n    detail: still.length\n      ? `仍有 ${still.length} 个 bridge 相关进程未结束（pid ${still.join(\", \")}）`\n      : (skipped.length ? \"已结束可确认归属的进程；无法确认归属的 pid 已跳过（避免误杀）\" : void 0),\n  };\n}\n\n/** 启动 bridge：确保运行环境就绪 + plist 存在 → launchctl bootstrap（回退 load -w）。 */\nfunction startBridge(relayDir) {\n  if (UNINSTALLED_DIRS.has(relayDir)) {\n    // 已彻底卸载：面板/自愈在重启前可能仍在内存中，禁止再把自启动与 plist 拉回来\n    return { ok: false, status: \"uninstalled\", detail: \"插件已彻底卸载，重启 dsh web 后生效\" };\n  }\n  if (isWindows()) return startBridgeDetached(relayDir);\n  // Linux（含飞牛/群晖这类 NAS）：阶梯见 startBridgeLinux —— 0.6.14 及更早这里只有\n  // `unsupported` 一条死路，bridge 在 Linux 上**从来没被拉起来过**。\n  if (isLinux()) return startBridgeLinux(relayDir);\n  const plistPath = launchAgentPath();\n  if (!plistPath) {\n    return {\n      ok: false,\n      status: \"unsupported\",\n      detail: `当前平台（${osPlatform()}）暂不支持自启动服务，请手动运行 \\`dsh-remote run\\``,\n    };\n  }\n  if (skipsSystemOps()) return { ok: false, status: \"skipped\", detail: \"测试隔离（DSH_RELAY_SKIP_SERVICE=1）：跳过真实服务操作\" };\n  // 【0.6.2 关键修复】运行环境缺失时绝不 bootstrap：写一个指向不存在脚本的 plist\n  // 只会让 launchd 进入 KeepAlive 崩溃循环——面板还可能因瞬时 pid 谎报「已启动」。\n  // 正确做法：先把运行环境补起来（后台 npx），就绪后由 scheduleRuntime / 面板再次启动。\n  if (!runtimeReady(relayDir)) {\n    ensureRuntime(relayDir);\n    return {\n      ok: false,\n      status: \"provisioning\",\n      runtimeMissing: true,\n      detail: \"桌面运行环境（bridge）尚未安装，已在后台自动安装，完成后会自动启动 bridge——请稍候刷新面板（也可点下方「一键更新」查看进度）\",\n    };\n  }\n  // plist 存在但入口不是当前运行环境（relayDir 变更/旧安装）→ 重写，避免又指到失效路径\n  if (existsSync(plistPath) && !readFileSync(plistPath, \"utf8\").includes(join(relayDir, \"dsh-setup.mjs\"))) {\n    writeAutostartFile(relayDir);\n  }\n  if (!existsSync(plistPath)) writeAutostartFile(relayDir);\n  if (!existsSync(plistPath)) return { ok: false, status: \"not-installed\", detail: \"plist 生成失败\" };\n  // 与 dsh-setup.mjs 同一条域阶梯：user/<uid> 优先（macOS 26 上唯一支持 RunAtLoad/KeepAlive 的域），\n  // gui/<uid> 兜底（只能靠 kickstart 拉这一次，不保证崩溃自愈）。\n  let lastDetail = \"\";\n  for (const domain of launchDomains()) {\n    const target = `${domain}/com.dshremote.bridge`;\n    // 清掉**另一个**域的历史注册，避免两处并存导致重复实例（与安装器同构）\n    for (const other of launchDomains()) {\n      if (other !== domain) sh(`launchctl bootout ${other}/com.dshremote.bridge`);\n    }\n    sh(`launchctl bootout ${target}`);\n    let boot = sh(`launchctl bootstrap ${domain} ${shQuote(plistPath)}`);\n    if (!boot.ok) {\n      sh(`launchctl unload ${shQuote(plistPath)}`);\n      boot = sh(`launchctl load -w ${shQuote(plistPath)}`);\n    }\n    if (!boot.ok) { lastDetail = (boot.stderr || boot.stdout).trim() || `launchctl bootstrap ${domain} 失败`; continue; }\n    // bootstrap 只是登记：立刻 kickstart 一次，确保\"这一次\"一定起来\n    sh(`launchctl kickstart -k ${target}`);\n    const st = launchdStatusIn(target);\n    if (st.running) return { ok: true, status: \"running\", pid: st.pid, domain };\n    lastDetail = st.state ? `已登记但未运行（state=${st.state}, runs=${st.runs ?? \"?\"}）` : \"已登记但查不到状态\";\n  }\n  // launchd 都托管不了（macOS 26 的 on-demand-only / 权限异常等）→ 退化为脱离进程，\n  // 与 Windows 走同一条路径：绝不出现\"重启失败但用户无感、旧账号继续跑\"这种静默失败。\n  const d = startBridgeDetached(relayDir, `launchd 无法托管（${lastDetail || \"未知原因\"}）`);\n  return d.ok ? d : { ok: false, status: \"failed\", detail: `${lastDetail}；脱离进程兜底也失败：${d.detail}` };\n}\n\n/**\n * 运行时自愈 watcher：补齐桌面运行环境 + 环境就绪后自动拉起 bridge。\n *\n * 【0.6.2 顺序修复】运行环境检查提到最前，且必须先于「账号就绪」与「服务是否在跑」：\n *   - 旧版先判 `st.running` 才判运行环境，而崩溃循环中的作业会被误判为 running\n *     → watcher `done = true` 永久停摆，自动补装（ensureRuntime）再也不会执行，\n *     这正是「市场装完插件、bridge 却起不来」且永不恢复的直接原因；\n *   - 补装运行环境不该等用户先登录：市场安装只给到插件半，登录那一刻就会 startBridge。\n *\n * ★★ 2026-10-13 重写就绪判据与\"动手\"策略（修线上反馈 fb_3c4c5a13bc47 的 12 秒重启风暴）：\n *   【症状】Linux 用户（npx 安装，0.6.18）的 bridge 被本函数**每 12.001 秒重启一次**，\n *     一天 3567 次；每次重启换一条新隧道 → 中继 close(1012) 掉该设备所有手机镜像 WS →\n *     镜像页每 ~12.3 秒断线重连并全量重放 → 用户看到的交互选择窗口\"一会显示、一会儿消失\"。\n *     全站上百台设备每天 1.1~1.5 万次重登记，多台设备间隔 p50 精确 ≈12.0s。\n *   【成因】就绪判据只有 `launchdStatus().running`（macOS）与\n *     `manualStatus().watcher.length > 0`（靠 pgrep 名称匹配，Linux/Windows 共用）。\n *     这两个判据都**可能在服务其实健康时返回\"没在跑\"**，而拿到\"没在跑\"之后直接\n *     `startBridge()` → `systemctl --user restart`（**破坏性**：杀旧进程、建新隧道）。\n *     于是\"判据失败\"被逐字翻译成\"每 12 秒杀一次隧道\"，而且 `done` 永远不置位。\n *   【现在】三层，缺一不可：\n *     ① **权威判据优先**：Linux 问 `systemctl --user is-active dsh-bridge`（见\n *        `linuxSystemdUnitState()`），pgrep 只作为\"问不到 systemd 时\"的兜底；\n *     ② **成功即止**：任一判据确认就绪 → 立刻 `done = true; clearInterval`，\n *        不再依赖下一拍去重新猜（旧代码即使这次 startBridge 成功，也要等下一拍 pgrep 认得出来\n *        才算成功，而它恰恰认不出来 → 永远重启）；\n *     ③ **护栏**：确需动手时先过 `selfhealRestartGate()`（≥5 分钟最小间隔 + 本进程内最多 3 次），\n *        被拦下或触顶都写入**可见**的安装日志（这个故障之所以拖了三个月，正是因为客户端侧\n *        什么都没记、中继侧又把 churn 日志抑制了，运维全程看不见）。\n */\nfunction scheduleRuntime(relayDir) {\n  let done = false;\n  // 本进程启动时是否缺运行环境：缺 → 补齐完成后需要重启 DeepSeek harness 才算「安装完成」。\n  let awaitingRestartHint = !runtimeReady(relayDir);\n  const iv = setInterval(() => {\n    if (done) { clearInterval(iv); return; }\n    if (UNINSTALLED_DIRS.has(relayDir)) { done = true; clearInterval(iv); return; } // 已彻底卸载：自愈 watcher 停摆\n    try {\n      if (!runtimeReady(relayDir)) {\n        reapBrokenAutostart(relayDir); // 先摘掉指向不存在脚本的自启动，止住崩溃循环\n        ensureRuntime(relayDir);       // 后台 npx 补齐（marker 防重入）；就绪后下一轮自动拉起\n        telemetryRuntimeProbe(relayDir); // 匿名遥测：补装超时归类（runtime_install_timeout）\n        return;\n      }\n      telemetryRuntimeProbe(relayDir); // 匿名遥测：环境刚补齐 → runtime_ready（每进程一次）\n      if (awaitingRestartHint) {\n        awaitingRestartHint = false;\n        // 运行环境刚在本进程内补齐 —— **不需要重启 harness**：\n        //   · bridge 是独立 launchd 进程，补齐后自愈调度会直接把它拉起；\n        //   · 插件本体走 patch 热加载，装完即生效。\n        // 以前这里会 markRestartPending(\"first-install\") 弹出\"需要重启 DeepSeek harness\"横幅，\n        // 在热加载落地后已经变成纯粹的误导（用户实测反馈），故移除。\n      }\n      const cfg = loadConfig(relayDir);\n      const hasAcct = Boolean((cfg.phone || cfg.email) && cfg.password) || Boolean(cfg.local_key);\n      if (!hasAcct) return;\n      // ── ① 权威判据（按平台各问各的服务管理器）──\n      // 运行环境已在，看服务是否已在运行（runtime 可能位于 npx 缓存/固化目录，不必重复安装）\n      const st = launchdStatus();\n      if (st.running) {\n        done = true; clearInterval(iv); resetSelfhealGuard(relayDir);\n        logSelfhealReady(relayDir, cfg, `launchd state=${st.state || \"running\"}`);\n        return;\n      }\n      // Linux：**systemd 才是权威**。它说 active 就是 bridge 真的在跑（隧道是它的职责），\n      // 此时哪怕 pgrep 一个进程都没匹配上，也必须认为\"就绪\"并停摆 —— 这正是本次故障的正解。\n      if (isLinux()) {\n        const sys = linuxSystemdUnitState();\n        if (sys.active) {\n          done = true; clearInterval(iv); resetSelfhealGuard(relayDir);\n          logSelfhealReady(relayDir, cfg, \"systemd --user is-active=active\");\n          return;\n        }\n      }\n      // ── ② 兜底判据（问不到服务管理器时，还是得靠进程探测；Windows 只有这一条）──\n      // 非 macOS（Windows **与 Linux**）没有 launchd：以「watcher 进程在跑」为就绪判据。\n      // 否则 launchdStatus 永远是 false，done 永远不置位，watcher 会一直空转。\n      // ★ Linux 也必须走这一支：`startBridge` 现在能在 Linux 上真正拉起 bridge（0.6.15），\n      //   但就绪判据漏了 Linux 的话，每轮自愈都会重复走一遍\"写 unit + 起进程\"。\n      if (!isDarwin() && manualStatus(relayDir).watcher.length > 0) {\n        done = true; clearInterval(iv); resetSelfhealGuard(relayDir);\n        logSelfhealReady(relayDir, cfg, \"进程探测（pgrep/pid 文件）\");\n        return;\n      }\n      // ── ②.5 设备绑定硬上限（bridge 退出码 5）：永久性失败时**不要**每 12 秒重启一次 ──\n      // 本自愈循环与 ensureConnection 是两条独立的拉起路径。watcher（dsh-setup.mjs）已在按\n      // 10s→1min→5min→15min（封顶 30min）退避等待时，这里再 startBridge（systemctl restart /\n      // launchctl kickstart）会把 watcher 整个换掉、把它的内存退避清零 —— 又回到 10s 空撞一次。\n      // 所以退避窗口内直接放弃本拍（人工操作走面板按钮 = force 路径，不受这条约束）。\n      const bindErrNow = readBindError(relayDir);\n      const bindGateNow = bindFailGate(relayDir, bindErrNow);\n      if (bindGateNow.permanent && bindGateNow.blocked) {\n        const book = connectBook(relayDir);\n        if (book.bindFailLogged !== bindGateNow.until) {\n          book.bindFailLogged = bindGateNow.until;\n          appendLogLine(relayDir, AUTO_INSTALL_LOG,\n            `[dsh-remote-web] 自愈暂停拉起 bridge：设备绑定已达上限（退出码 ${DEVICE_BIND_CAP_EXIT_CODE}），`\n            + `约 ${Math.ceil(bindGateNow.remainingMs / 1000)} 秒后再试（指数退避，最长 30 分钟）；`\n            + \"请在手机端「管理电脑」解绑不再使用的设备，解绑后自动恢复\");\n        }\n        return;\n      }\n      // ── ③ 确实没在跑 → 过护栏后才动手（绝不允许\"判据失败\"直接变成\"每 12 秒杀一次隧道\"）──\n      const gate = selfhealRestartGate(relayDir);\n      if (!gate.allowed) { noteSelfhealBlocked(relayDir, gate); return; }\n      const r = startBridge(relayDir); // 环境在但服务没起 → 拉起\n      if (r && r.ok) {\n        // 起来了：立刻置位 + 记账 + 清掉失败去重状态。**不再等下一拍重新判据** ——\n        // 旧代码把\"是否成功\"交给下一拍的 pgrep 去回答，而它答不出来，于是永远重启。\n        // `accounted` = 这次重启已经在 startBridgeLinux/guardedSystemdRestart 里记过账，别再记一次。\n        if (!r.reused && !r.accounted) noteSelfhealRestart(relayDir, \"权威判据说没在跑\", r.status || \"running\");\n        clearAutostartFailure(relayDir);\n        done = true; clearInterval(iv); resetSelfhealGuard(relayDir);\n        logSelfhealReady(relayDir, cfg, `startBridge=${r.status || \"running\"}${r.reused ? \"（幂等：本来就在跑）\" : \"\"}`);\n        return;\n      }\n      // 测试隔离（DSH_RELAY_SKIP_SERVICE=1）：startBridge 只会返回 `skipped` —— 它**什么都没做**，\n      // 既不该吃掉护栏额度，也不该往安装日志里写\"自愈重启\"（生产不会出现这个状态）。\n      if (r && r.status === \"skipped\") return;\n      // Linux 的 systemd 重启已经在 `guardedSystemdRestart` 里记过账、也写过日志（含\"被拦下\"），\n      // 这里不能再记一次 —— 否则一次尝试吃掉两格额度，5 分钟的退避会缩水成 2.5 分钟。\n      if (r && r.status === \"selfheal-throttled\") return;\n      // 其它路径（macOS launchd 失败 / Windows / 脱离进程）没有自带护栏：在此记账 + 写可见日志，\n      // 否则\"拉起失败 → 下一拍再试 → 每 12 秒一次\"就是同一个病换个平台复发。\n      noteSelfhealRestart(relayDir, \"权威判据说没在跑\", (r && r.detail) || (r && r.status) || \"未知原因\");\n      // 触顶：护栏会在下一拍开始拦住我们并写一行\"已停止自愈重启\"，这里不再做任何动作。\n    } catch { /* 下一轮再试 */ }\n  }, selfhealIntervalMs());\n  iv.unref?.();\n  return () => clearInterval(iv);\n}\n\n/**\n * 自愈判定「已就绪、循环停摆」时留一行可见日志（同一条结论只写一次）。\n *\n * 为什么值得单独记一行：用户反馈里\"连接是不是自己在修、修好了没有\"无从判断 ——\n * 旧代码在就绪时**什么都不写**，于是\"自愈watcher 判据失败→每 12 秒重启\"这种故障\n * 在日志里只留下 bridge 反复重启的痕迹，看不出是插件在动手。这一行把\"是我判定的、依据是什么\"钉住。\n * ⚠️ 带上**隧道注册**证据（bridge 状态文件里的 device_id / 日志尾部），但不拿它当就绪判据：\n *   它比进程存活更容易闪断，若用它当 done 的条件，等于又造一个会抖的判据（正是本次故障的病因）。\n */\nfunction logSelfhealReady(relayDir, cfg, basis) {\n  if (lastSelfhealReadyLine.get(relayDir) === basis) return;\n  lastSelfhealReadyLine.set(relayDir, basis);\n  const state = bridgeStateFile(relayDir);\n  const registered = Boolean(state && state.device_id) && (!cfg || !cfg.device_id || String(state.device_id) === String(cfg.device_id));\n  appendLogLine(relayDir, AUTO_INSTALL_LOG,\n    `[dsh-remote-web] 自愈判定 bridge 已就绪，已停止自愈循环（依据：${basis}；`\n    + `隧道注册：${registered ? `已登记（device_id=${state.device_id}）` : \"尚无登记证据（不影响就绪判定，注册由 bridge/watcher 自己负责）\"}）`);\n}\n/** `logSelfhealReady` 的去重状态：同一个 relayDir 只有判据变了才再写一行。 */\nconst lastSelfhealReadyLine = new Map();\n\n/** 停止 bridge：macOS 走 launchctl bootout；Linux 走 systemd/脱离进程；Windows 结束 watcher/bridge 进程。 */\nfunction stopBridge(relayDir) {\n  if (isWindows()) return stopBridgeDetached(relayDir);\n  // 测试隔离：置位时绝不对真实 launchd/systemd 下手（切换账号也会走到这里，\n  // 少了这一条，用例就会去 bootout 开发者本机上真实运行的 bridge —— 实测过的污染风险）。\n  if (skipsSystemOps()) return { ok: false, status: \"skipped\", detail: \"测试隔离（DSH_RELAY_SKIP_SERVICE=1）：跳过真实服务操作\" };\n  // ★ Linux（0.6.15）：以前这里直接落到「没有 launchd 服务可停」的死路 —— Linux 用户的\n  //   面板「停止」、以及**切换账号时的重置**都会失败（旧 bridge 继续用旧凭据跑）。\n  //   现在：有 user systemd 就先停 unit，再统一用脱离进程那条路把 pid 文件/残留进程收干净。\n  if (isLinux()) {\n    let systemdStopped = false;\n    if (systemdUserAvailableCached()) {\n      sh(\"systemctl --user stop dsh-bridge\");\n      const a = sh(\"systemctl --user is-active dsh-bridge\");\n      systemdStopped = !(a.ok && a.stdout.trim() === \"active\");\n    }\n    const d = stopBridgeDetached(relayDir);\n    if (d.ok) {\n      return {\n        ok: true,\n        status: \"stopped\",\n        pid: null,\n        detail: systemdStopped ? \"已停止 bridge（systemd --user 与后台进程均已结束）\" : void 0,\n      };\n    }\n    return { ...d, detail: [d.detail, systemdStopped ? \"systemd unit 已停\" : \"\"].filter(Boolean).join(\"；\") };\n  }\n  const targets = launchTargets();\n  if (!targets.length) return { ok: false, status: \"unsupported\", detail: `当前平台（${osPlatform()}）没有 launchd 服务可停，请手动结束 \\`dsh-remote run\\` 进程` };\n  // 两个域都要停：作业可能由安装器装在 user/<uid>，而旧版插件只会去 gui/<uid> 找不到（实测故障）\n  let lastErr = \"\";\n  for (const target of targets) {\n    const r = sh(`launchctl bootout ${target}`);\n    if (!r.ok) lastErr = (r.stderr || r.stdout).trim();\n  }\n  const st = launchdStatus();\n  return { ok: !st.running, status: st.running ? \"failed\" : \"stopped\", pid: null, detail: st.running ? (lastErr || \"停止失败\").trim() : void 0 };\n}\n\n// ---------- 彻底卸载：bridge 自启动 / 残留进程 / 配置目录 ----------\n\n/**\n * 已执行「彻底卸载」的 relayDir 集合。卸载动作本身不改代码，但 dsh web 重启前本插件仍在内存中：\n * 自愈调度（scheduleRuntime/ensureRuntime/startBridge）与浏览器会话代持（mintHarnessCookie）\n * 若继续执行，会把刚清空的配置目录 / 自启动服务重新拉起来——故卸载后本进程内一律停摆，\n * 直到 dsh web 重启（profile 引用已移除，插件整体不再加载）或重新激活（apply 时清除）。\n */\nconst UNINSTALLED_DIRS = new Set();\n/** 补装失败退避状态（relayDir → {fails, nextAt}）；见 provisionRetryGate。 */\nconst provisionRetry = new Map();\n\n/** 标记某 relayDir 已完成彻底卸载（其后续自愈/代持调度全部停摆）。 */\nfunction markUninstalled(relayDir) {\n  if (relayDir) UNINSTALLED_DIRS.add(relayDir);\n}\n\n/**\n * 彻底卸载 —— 「运行时/bridge」部分：把本机 dsh-remote 运行时回归到未安装状态。\n * 执行顺序（每步独立 try/catch，单项失败不致命，不影响后续步骤；结果以标志位返回）：\n *   1) 停掉自启动服务并移除自启动文件：macOS launchctl bootout com.dshremote.bridge +\n *      删 ~/Library/LaunchAgents/com.dshremote.bridge.plist；Linux systemctl --user\n *      stop/disable dsh-bridge（+ 删 ~/.config/systemd/user/dsh-bridge.service）。\n *      ⚠ 必须先停服务再删配置目录：否则 launchd KeepAlive / systemd Restart 会立刻\n *      重启一个「指向已被删除文件」的进程；\n *   2) 杀掉仍存活的手动 watcher/bridge 进程（launchd/systemd 托管的进程已随 bootout 结束，\n *      manualStatus() 本身也排除了本进程与 launchd 托管链）；\n *   3) rm -rf 配置目录 relayDir（账号/设备密钥/.dsh-config.json/.harness-cookie.json/\n *      固化运行时 dsh-setup.mjs + clients 等全部残留）。\n * 安全护栏：\n *   - DSH_RELAY_SKIP_SERVICE=1（测试隔离开关，生产勿设）：跳过 1/2 的一切系统级操作，\n *     只清理配置目录——避免测试真的去 launchctl / systemctl / kill 真实服务；\n *   - 自启动文件只处理「属于当前 HOME 的 plist/unit」，误配/测试环境不碰同名真实服务；\n *   - 配置目录删除前校验：不是 \"/\"、不是家目录、不是 dsh web profile 目录或其父级（防误删用户数据）。\n */\nfunction uninstallRuntime(relayDir, protectedPath) {\n  const out = {\n    stoppedService: false, // 自启动服务原本在运行且已停止\n    removedPlist: false,   // 自启动文件（plist / systemd unit）已删除\n    killedPids: [],        // 额外结束的残留进程 pid 列表\n    removedDir: false,     // 配置目录 relayDir 已整目录清空\n    servicePlatform: isDarwin() ? \"launchd\" : isWindows() ? \"windows-detached\" : osPlatform() === \"linux\" ? \"systemd\" : \"none\",\n  };\n  const skipService = process.env.DSH_RELAY_SKIP_SERVICE === \"1\";\n  if (!skipService) {\n    // a) 停服务 + 移除自启动文件\n    try {\n      if (isDarwin()) {\n        /* 🔴 2026-10-10 故障护栏：**relayDir 不在当前 HOME 之下时，绝不碰真实自启动**。\n           当天某个用例用「真 HOME + 临时 relayDir」调到了这里：plist 路径解析到真实的\n           ~/Library/LaunchAgents/com.dshremote.bridge.plist → 先 bootout 真桥、再把 plist 删了\n           → **开发者本机的远程访问被测试整个卸掉**（job 消失、桥停摆）。\n           判据：生产部署里 relayDir 一定在 HOME 之下（~/.dsh-remote）；\n           测试夹具的 relayDir 在 /var/folders/... 而 HOME 是真实的 —— 这个不一致必须拒绝。\n           显式要跨目录操作时设 DSH_RELAY_ALLOW_FOREIGN_SERVICE=1。 */\n        const underHome = (() => {\n          try {\n            const rel = relative(homedir(), relayDir);\n            return rel === \"\" || (!rel.startsWith(\"..\") && !isAbsolute(rel));\n          } catch { return false; }\n        })();\n        if (!underHome && process.env.DSH_RELAY_ALLOW_FOREIGN_SERVICE !== \"1\") {\n          out.serviceSkipped = `relayDir 不在 HOME 之下（${relayDir}），拒绝改动真实自启动服务`;\n          return out;\n        }\n        // 只处理「plist 位于当前 HOME」的服务：本插件/dsh-setup.mjs 安装的服务一定在此\n        const plistPath = launchAgentPath();\n        if (plistPath && existsSync(plistPath)) {\n          /* ★★ 归属校验（2026-10-10 故障的最终护栏）：\n             这份 plist 必须**确实是为本 relayDir 装的**（内容里写着 <relayDir>/dsh-setup.mjs）。\n             不校验的话，只要有用例拿「真 HOME + 临时 relayDir」走到这里，就会把开发者本机\n             真实的服务**先 bootout 再删文件**（当天实测发生：桥停摆、远程访问中断）。\n             归属不符 → 整个服务分支跳过（并如实说明），绝不越界。 */\n          const ownedByThisDir = plistOwnedByRelayDir(relayDir);\n          if (!ownedByThisDir) {\n            out.serviceSkipped = `plist 不属于本 relayDir，拒绝改动：${plistPath}`;\n            return out;\n          }\n          // crashing 也要 bootout：崩溃循环中的作业在 launchd 里仍是「已加载」，\n          // 只删 plist 文件它照样被 KeepAlive 反复重拉（见 launchdStatus 注释）。\n          const st = launchdStatus();\n          if (st.running || st.crashing) {\n            const r = stopBridge(relayDir); // launchctl bootout → KeepAlive 一并失效\n            out.stoppedService = r.ok;\n          }\n          rmSync(plistPath, { force: true });\n          out.removedPlist = !existsSync(plistPath);\n        }\n      } else if (isWindows()) {\n        // Windows：自启动 = 任务计划程序里的登录任务（dsh-setup.mjs 注册）。\n        // 卸载必须把任务一起删掉，否则下次登录又会被拉起来 —— 用户会以为\"卸载没生效\"。\n        const before = manualStatus(relayDir);\n        if (before.watcher.length || before.bridge.length) {\n          const r = stopBridgeWindows(relayDir);\n          out.stoppedService = r.ok;\n        }\n        try {\n          const r = spawnSync(\"schtasks\", [\"/Delete\", \"/TN\", WIN_TASK_NAME, \"/F\"], { windowsHide: true, encoding: \"utf8\", timeout: 15000 });\n          out.removedPlist = r.status === 0 || /cannot find|找不到|不存在/i.test(String(r.stdout || \"\") + String(r.stderr || \"\"));\n        } catch { /* 任务不存在/无权限：不致命，残留可由用户手动清理 */ }\n      } else if (osPlatform() === \"linux\") {\n        // systemd --user 用户态服务，与 dsh-setup.mjs 安装的 dsh-bridge 同名\n        const isActive = sh(\"systemctl --user is-active dsh-bridge\");\n        if (isActive.ok && String(isActive.stdout).trim() === \"active\") {\n          sh(\"systemctl --user stop dsh-bridge\");\n          const after = sh(\"systemctl --user is-active dsh-bridge\");\n          out.stoppedService = !(after.ok && String(after.stdout).trim() === \"active\");\n        }\n        sh(\"systemctl --user disable dsh-bridge\"); // 幂等；失败不致命\n        const unitPath = join(homedir(), \".config\", \"systemd\", \"user\", \"dsh-bridge.service\");\n        if (existsSync(unitPath)) {\n          try { rmSync(unitPath, { force: true }); } catch { /* 非关键 */ }\n          sh(\"systemctl --user daemon-reload\");\n          out.removedPlist = !existsSync(unitPath);\n        }\n      }\n    } catch { /* 服务清理失败不致命：目录照常清理，剩余残留可由用户手动处理 */ }\n    // b) 杀残留手动进程（launchd 托管的已随 bootout 结束；manualStatus 排除本进程）\n    try {\n      const manual = manualStatus(relayDir);\n      const targets = [...manual.watcher, ...manual.bridge];\n      for (const pid of targets) {\n        try { process.kill(pid, \"SIGTERM\"); out.killedPids.push(pid); } catch { /* EPERM/ESRCH 忽略 */ }\n      }\n      if (targets.length) {\n        sleepSync(1000); // 同步等待进程退出（Windows 没有 sleep 命令，改用 Atomics.wait）\n        for (const pid of targets) {\n          if (pidAlive(pid)) {\n            try { process.kill(pid, \"SIGKILL\"); } catch { /* 已退出 */ }\n          }\n        }\n      }\n    } catch { /* ignore */ }\n  }\n  // c) 清空配置目录（账号/密钥/会话 cookie/固化运行时等全部残留）\n  try {\n    const isRoot = dirname(relayDir) === relayDir;                     // \"/\" 或盘符根\n    const isHome = relayDir === homedir();\n    const hitsProfile = Boolean(protectedPath) && (\n      relayDir === protectedPath || relayDir.startsWith(protectedPath + sep)\n      || protectedPath.startsWith(relayDir + sep)\n    ); // 配置目录误指向 dsh web profile → 绝不整目录删除\n    if (relayDir && !isRoot && !isHome && !hitsProfile && existsSync(relayDir)) {\n      rmSync(relayDir, { recursive: true, force: true });\n      out.removedDir = !existsSync(relayDir);\n    }\n  } catch { /* 目录正被占用等：删除失败不致命（残留可由用户手动删除） */ }\n  return out;\n}\n\n// ---------- DeepSeek harness 重启（0.6.2：首次安装/更新后必须重启才能加载插件本体） ----------\n//\n// 为什么需要：dsh web 的插件（宿主半 + 浏览器半）都是在**进程启动时**装载的。\n// 市场点击安装只把文件写进 profile，当前进程里既没有 /dsh-remote/* 路由、也没有面板入口，\n// 必须重启 DeepSeek harness 才生效（面板与 bridge 才能真正可用）。\n// 本段提供：① 持久化「待重启」状态（跨进程判定重启是否真的发生过）；\n//           ② 一条可靠的重启实现（优先交回监管者，其次自拉起）；③ 面板按钮用的路由。\n\nconst RESTART_STATE_FILE = \".dsh-restart-state.json\";\nconst RESTART_SCRIPT_FILE = \".dsh-restart-harness.sh\";   // macOS/Linux：/bin/sh 脚本\nconst RESTART_HELPER_FILE = \".dsh-restart-harness.mjs\"; // Windows：node 助手（无 /bin/sh）\nconst RESTART_LOG_FILE = \".dsh-restart.log\";\n\n/**\n * 当前 dsh web 进程身份（pid + 启动时刻）。模块加载时算一次并固定：\n * 若每次调用重算，`Date.now() - uptime*1000` 的毫秒漂移会让同一个进程算出不同的 id，\n * 结清逻辑就会误判「已经重启过」而错误撤下提示。\n */\nconst BOOT_ID = `${process.pid}-${Math.round(Date.now() - process.uptime() * 1000)}`;\n\nfunction bootId() {\n  return BOOT_ID;\n}\n\n/** 读取「待重启」状态；文件缺失/损坏一律视为无需重启。 */\nfunction readRestartState(relayDir) {\n  try {\n    const raw = JSON.parse(readFileSync(join(relayDir, RESTART_STATE_FILE), \"utf8\"));\n    if (raw && typeof raw === \"object\") return raw;\n  } catch { /* 无文件 / 损坏 */ }\n  return { pending: false };\n}\n\nfunction writeRestartState(relayDir, state) {\n  try {\n    mkdirSync(relayDir, { recursive: true });\n    writeFileSync(join(relayDir, RESTART_STATE_FILE), JSON.stringify({ ...state, updatedAt: Date.now() }, null, 2), { mode: 0o600 });\n  } catch { /* 写盘失败不致命：面板退化为不提示 */ }\n}\n\n/**\n * 标记「需要用户动一下」的状态。kind = refresh(插件被运行时改写,刷新页面即可)。\n * 历史 kind(first-install / update)已废弃:热加载落地后,装插件与在线更新都不再需要重启 harness。\n */\n/** 桌面端「暫存插件更新」marker（dsh-setup 在应用运行时暂存；bridge 在应用退出后自动安装）。 */\nfunction readDesktopUpdatePending(relayDir) {\n  try {\n    const m = JSON.parse(readFileSync(join(relayDir, \".plugin-update-pending.json\"), \"utf8\"));\n    return { version: String(m.version || \"\"), stagedAt: Number(m.stagedAt) || 0 };\n  } catch {\n    return null;\n  }\n}\n\n/** 更新进程成功收尾后写「待生效」提示：桌面端暂存更新 → 退出应用后自动安装；其它 → 重启 dsh web。 */\nfunction markUpdateRestartPending(relayDir) {\n  const staged = readDesktopUpdatePending(relayDir);\n  if (staged) {\n    return markRestartPending(\n      relayDir,\n      \"restart-app\",\n      `新版本${staged.version ? ` ${staged.version}` : \"\"} 已下载：退出并重新打开 DeepSeek Harness 后自动生效（无需终端）`\n    );\n  }\n  return markRestartPending(relayDir, \"restart\", \"插件已更新，重启 dsh web 后生效\");\n}\n\nfunction markRestartPending(relayDir, kind, reason) {\n  const cur = readRestartState(relayDir);\n  if (cur.pending && cur.kind === kind) return cur; // 幂等：同一原因不反复重写\n  const next = { pending: true, kind, reason, at: Date.now(), bootId: bootId(), installedBy: cur.installedBy || \"\" };\n  writeRestartState(relayDir, next);\n  return next;\n}\n\n/**\n * 插件装载时调用：bootId 与记录中的不同 = 中间确实重启过一次 → 结清「待重启」状态。\n * @returns {{cleared:boolean, state:object}}\n */\nfunction settleRestartState(relayDir) {\n  const cur = readRestartState(relayDir);\n  if (!cur.pending) return { cleared: false, state: cur };\n  if (cur.bootId && cur.bootId === bootId()) return { cleared: false, state: cur }; // 同一进程：仍待重启\n  const state = { pending: false, kind: \"\", reason: \"\", at: cur.at || 0, bootId: bootId(), lastRestartedAt: Date.now() };\n  writeRestartState(relayDir, state);\n  return { cleared: true, state };\n}\n\n/**\n * 插件文件是否**晚于本进程启动**才落盘（= 运行中被市场安装/在线更新改写过）。\n * 依据：本插件自身 package.json 的 mtime 对比 dsh web 进程启动时刻（2s 容差）。\n */\nfunction pluginInstalledAfterBoot() {\n  try {\n    const here = fileURLToPath(import.meta.url);            // <profile>/node_modules/<pkg>/lib/index.js\n    const pkgFile = join(dirname(dirname(here)), \"package.json\");\n    const mtimeMs = statSync(pkgFile).mtimeMs;\n    const bootMs = Date.now() - process.uptime() * 1000;\n    if (!(mtimeMs > bootMs + 2000)) return false;\n    // ⚠️ 只看时间戳会**误报**:安装器补装/在线更新会把同样的文件重写一遍(哪怕是同一个版本),\n    // 时间戳变新 → 被当成\"有新插件要装载\" → 弹出\"需要重启/刷新\"横幅(用户实测踩到:\n    // 自愈补装把 profile 副本重写了一次,运行中的旧代码就写下了\"需要重启\")。\n    // 真正该提示用户的只有一件事:**磁盘上的插件版本与本进程装载的版本不同**。\n    // 版本相同 → 运行中的代码就是目标版本,什么都不用做。\n    const diskVersion = String(JSON.parse(readFileSync(pkgFile, \"utf8\")).version || \"\");\n    const runningVersion = String(PLUGIN_VERSION || \"\");\n    return Boolean(diskVersion && runningVersion && diskVersion !== runningVersion);\n  } catch { return false; }\n}\n\n/** 本进程的启动命令（重启时原样复用：node 路径 + dsh 参数 + 工作目录）。 */\nfunction selfCommand() {\n  return { node: process.execPath, args: process.argv.slice(1), cwd: process.cwd() };\n}\n\n/** macOS：从 `launchctl list` 里找出托管本进程（pid 精确匹配）的作业标签。 */\nfunction launchdLabelForPid(pid) {\n  const r = sh(\"launchctl list\");\n  if (!r.ok) return \"\";\n  for (const line of r.stdout.split(\"\\n\")) {\n    const m = line.trim().match(/^(\\d+)\\s+(-?\\d+)\\s+(\\S+)$/);\n    if (m && Number(m[1]) === pid) return m[3];\n  }\n  return \"\";\n}\n\n/** Linux：从 /proc/self/cgroup 里找出托管本进程的 systemd 单元。 */\nfunction systemdUnitForSelf() {\n  try {\n    const cg = readFileSync(\"/proc/self/cgroup\", \"utf8\");\n    const m = cg.match(/\\/([A-Za-z0-9_.@-]+\\.service)/);\n    return m ? m[1] : \"\";\n  } catch { return \"\"; }\n}\n\n/**\n * 生成重启脚本（延迟执行，先把 HTTP 响应让浏览器收完）。\n * mode=launchd/systemd：交给监管者重启最干净（KeepAlive/Restart 会拉起新进程）；\n * mode=relaunch：没有监管者时自行拉起同一条命令行（detached 新会话，脱离将被 kill 的旧进程）。\n */\nfunction buildRestartScript(mode, target, cmd, relayDir) {\n  const log = join(relayDir, RESTART_LOG_FILE);\n  const head = `#!/bin/sh\\n# dsh-remote 自动生成：重启 DeepSeek harness（mode=${mode}）\\necho \"[$(date '+%F %T')] restart mode=${mode} target=${target || \"-\"} pid=${process.pid}\" >> '${log}'\\nsleep 1\\n`;\n  if (mode === \"launchd\") {\n    return `${head}exec launchctl kickstart -k '${target}' >> '${log}' 2>&1\\n`;\n  }\n  if (mode === \"systemd\") {\n    return `${head}exec systemctl --user restart '${target}' >> '${log}' 2>&1\\n`;\n  }\n  const quote = (s) => \"'\" + String(s).replace(/'/g, `'\\\\''`) + \"'\";\n  const argv = [cmd.node, ...cmd.args].map(quote).join(\" \");\n  // 先优雅退出旧进程，超时再强杀；随后在新会话里拉起同一条命令\n  return `${head}kill -TERM ${process.pid} 2>/dev/null\\n`\n    + `i=0\\nwhile [ $i -lt 60 ]; do kill -0 ${process.pid} 2>/dev/null || break; i=$((i+1)); sleep 0.5; done\\n`\n    + `kill -KILL ${process.pid} 2>/dev/null\\n`\n    + `cd ${quote(cmd.cwd)} || exit 1\\n`\n    + `exec ${argv} >> '${log}' 2>&1\\n`;\n}\n\n/**\n * Windows 重启助手（0.6.7 新增）——**必须**是 .mjs 而不是 /bin/sh 脚本。\n *\n * 现场（0.6.6 及更早，用户实测）：restartHarness 生成 `#!/bin/sh` 脚本再 `spawn(\"/bin/sh\")`，\n * Windows 没有 /bin/sh → ENOENT；而那个 ChildProcess 又没挂 'error' 监听\n * → 未捕获异常直接终止 dsh web。更糟的是代码先把「已调度重启」写进日志并返回成功，\n * 用户看到\"成功\"、进程却已经没了（残留物 `.dsh-restart.log` 里正是 `mode=relaunch helper=undefined`）。\n *\n * 现在：用当前 node 跑本文件（不走任何 shell，参数原样传递，路径含空格/中文都不出问题），\n * 且**先校验新进程能拉起来再动旧进程**——宁可重启失败，也不能把自己杀掉却起不来。\n */\nfunction buildRestartHelperSource(cmd, relayDir) {\n  const plan = JSON.stringify({\n    pid: process.pid, node: cmd.node, args: cmd.args, cwd: cmd.cwd,\n    log: join(relayDir, RESTART_LOG_FILE),\n  });\n  return `// dsh-remote 自动生成：重启 DeepSeek harness（Windows 助手；由插件写入并 detached 执行）\nimport { spawn, spawnSync } from \"node:child_process\";\nimport { appendFileSync, existsSync, openSync, closeSync } from \"node:fs\";\nimport { setTimeout as delay } from \"node:timers/promises\";\n\nconst PLAN = ${plan};\nfunction logLine(msg) {\n  try { appendFileSync(PLAN.log, \"\\\\n[\" + new Date().toISOString() + \"] \" + msg + \"\\\\n\"); } catch (e) { /* 日志写不了不阻断重启 */ }\n}\n\n// ① 先确认新进程真的拉得起来，再动旧进程（旧实现最大的风险是\"杀掉却起不来\"）\nif (PLAN.cwd && !existsSync(PLAN.cwd)) { logLine(\"重启中止：工作目录不存在 \" + PLAN.cwd); process.exit(1); }\nif (PLAN.cwd) process.chdir(PLAN.cwd); // 先切回原工作目录：入口若是相对路径也能被正确解析\nif (!existsSync(PLAN.node)) { logLine(\"重启中止：node 不存在 \" + PLAN.node); process.exit(1); }\nconst entry = PLAN.args[0];\nif (!entry || !existsSync(entry)) { logLine(\"重启中止：dsh 入口不存在 \" + entry); process.exit(1); }\n\nfunction alive(pid) {\n  try { process.kill(pid, 0); return true; } catch (e) { return e.code === \"EPERM\"; }\n}\n\nlogLine(\"restart helper 启动：mode=relaunch(win32) 旧 pid=\" + PLAN.pid);\nawait delay(1000); // 先把 HTTP 响应让浏览器收完\n\n// ② 结束旧进程（Windows 上 process.kill 即 TerminateProcess）\ntry { process.kill(PLAN.pid); } catch (e) { /* 可能已自行退出 */ }\nconst deadline = Date.now() + 30000;\nwhile (Date.now() < deadline && alive(PLAN.pid)) await delay(200);\nif (alive(PLAN.pid)) {\n  logLine(\"旧进程 30s 未退出，改用 taskkill /T /F\");\n  spawnSync(\"taskkill\", [\"/PID\", String(PLAN.pid), \"/T\", \"/F\"], { windowsHide: true, timeout: 8000 });\n  await delay(500);\n}\n\n// ③ 用同一条命令行自拉起（脱离本助手，助手退出后它继续跑）\nlet out = \"ignore\";\ntry { out = openSync(PLAN.log, \"a\"); } catch (e) { /* 退化到丢弃输出 */ }\nconst child = spawn(PLAN.node, PLAN.args, {\n  cwd: PLAN.cwd, detached: true, stdio: [\"ignore\", out, out], windowsHide: true,\n});\nchild.on(\"error\", (e) => logLine(\"重新拉起失败：\" + e.message));\nchild.unref();\nif (typeof out === \"number\") { try { closeSync(out); } catch (e) {} }\nlogLine(\"已重新拉起 dsh web：pid=\" + String(child.pid));\n`;\n}\n\n/**\n * 重启 DeepSeek harness（dsh web）。\n * 只重启「承载本插件的那个进程」（pid 匹配到的监管者或自身），绝不触碰 bridge。\n * @returns {Promise<{ok:boolean, status:string, mode?:string, detail?:string, script?:string, log?:string}>}\n */\nasync function restartHarness(relayDir, opts = {}) {\n  if (skipsSystemOps()) return { ok: false, status: \"skipped\", detail: \"测试隔离（DSH_RELAY_SKIP_SERVICE=1）：跳过真实重启\" };\n  // 桌面端（Electron 宿主）：**绝不重启 Host**。\n  //   · Host 是桌面应用（Electron）的子进程，把它杀掉会触发桌面端的**原生致命恢复弹窗**，\n  //     用户的观感是\"应用崩了\"，远差于\"没重启\"；\n  //   · 而且桌面端重启用处很小：插件由共享插件管理器安装、激活走 profile 的 patch HMR\n  //     （存盘后约 1 秒重新 compose），日常更新刷新页面即可生效；\n  //   · 真要重启，正确动作是**退出并重开桌面应用**，那由用户/操作系统负责，不该由插件代劳。\n  // 因此这里如实返回\"做不到 + 该怎么做\"，而不是假装成功或把宿主打死。\n  if (IS_ELECTRON_HOST) {\n    return {\n      ok: false,\n      status: \"desktop-managed\",\n      mode: \"desktop\",\n      detail: \"当前运行在 DeepSeek Harness 桌面端：Host 由桌面应用托管，插件不能单独重启它（强行退出会让应用弹致命错误）。\"\n        + \"插件更新一般刷新页面即可生效；确实需要重启时，请退出并重新打开 DeepSeek Harness —— 后台服务与手机端连接不受影响。\",\n    };\n  }\n  const cmd = selfCommand();\n  let mode = \"relaunch\";\n  let target = \"\";\n  if (isDarwin()) {\n    const label = launchdLabelForPid(process.pid);\n    const uid = currentUid();\n    if (label && uid !== null) { mode = \"launchd\"; target = `gui/${uid}/${label}`; }\n  } else if (osPlatform() === \"linux\") {\n    const unit = systemdUnitForSelf();\n    if (unit) { mode = \"systemd\"; target = unit; }\n  }\n  // Windows 一律走 .mjs 助手（无监管者，也不存在 /bin/sh）\n  const script = isWindows() ? buildRestartHelperSource(cmd, relayDir) : buildRestartScript(mode, target, cmd, relayDir);\n  // 匿名遥测：重启 DeepSeek harness（自动倒计时或手动按钮都经这里）——触发一次记一条。\n  // 放在 dry-run 之前：测试/诊断用的 dry-run 也走同一条入口，便于用例锁死这条埋点。\n  telemetryRecord(relayDir, \"harness_restart\");\n  telemetryFlushSoon(relayDir); // 本进程约 1~2 秒后就会被替换：尽量当下把这条发出去（发不出去留盘上，下次装载补发）\n  if (opts.dryRun || process.env.DSH_RELAY_RESTART_DRYRUN === \"1\") {\n    // 测试/诊断用：只返回将要执行的脚本，不做任何真实动作\n    return { ok: true, status: \"dry-run\", mode, target, script, log: join(relayDir, RESTART_LOG_FILE) };\n  }\n  const scriptPath = join(relayDir, isWindows() ? RESTART_HELPER_FILE : RESTART_SCRIPT_FILE);\n  try {\n    mkdirSync(relayDir, { recursive: true });\n    writeFileSync(scriptPath, script, { mode: 0o700 });\n    const log = join(relayDir, RESTART_LOG_FILE);\n    // 非 macOS 平台没有 /bin/sh；Windows 用 node 直接跑 .mjs 助手。\n    const runner = isWindows() ? process.execPath : \"/bin/sh\";\n    const out = openSync(log, \"a\");\n    // 【0.6.7 关键修复】必须等「真的派生成功」再报成功：spawn 失败是**异步** 'error' 事件，\n    // 旧实现不等就返回 ok:true（Windows 上 /bin/sh ENOENT 时正是如此）→ 用户看到\"成功\"、\n    // 进程其实已经没了。spawnAndConfirm 同时保证永远有 'error' 监听，绝不打挂宿主。\n    const { child, error } = await spawnAndConfirm(runner, [scriptPath], {\n      detached: true,\n      cwd: homedir(),\n      env: spawnEnv(),\n      stdio: [\"ignore\", out, out],\n      windowsHide: true,\n    });\n    try { closeSync(out); } catch { /* 已随子进程继承，父进程这份可以关 */ }\n    if (error || !child) {\n      const msg = (error || new Error(\"spawn 未返回子进程\")).message;\n      appendLogLine(relayDir, RESTART_LOG_FILE, `[restart] 调度失败：${msg}（未执行任何重启动作，dsh web 仍在运行）`);\n      return { ok: false, status: \"failed\", mode, target, log, detail: `调度重启失败: ${msg}` };\n    }\n    child.unref();\n    appendLogLine(relayDir, RESTART_LOG_FILE, `[restart] 已调度重启：mode=${mode}${target ? \" target=\" + target : \"\"} helper=${child.pid}`);\n    return {\n      ok: true,\n      status: \"restarting\",\n      mode,\n      target,\n      pid: child.pid,\n      log,\n      detail: mode === \"launchd\" ? \"已交由 launchd 重启（约 2~5 秒）\"\n        : mode === \"systemd\" ? \"已交由 systemd 重启（约 2~5 秒）\"\n        : \"无监管者，已用同一条命令行自拉起（约 2~5 秒）\",\n    };\n  } catch (e) {\n    return { ok: false, status: \"failed\", detail: `调度重启失败: ${e.message}` };\n  }\n}\n\n// ---------- relay API 代理（直连，不走系统代理；undici 默认忽略代理环境变量） ----------\n\nasync function relayFetch(relayDir, pathname, init) {\n  const cfg = loadConfig(relayDir);\n  const api = (cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n  const url = `${api}${pathname}`;\n  try {\n    // 6s 超时：relay 不可达时快速降级，不拖慢面板\n    const res = await fetch(url, { ...init, signal: AbortSignal.timeout(6000) });\n    // 企业端拒绝当前 JWT（过期/轮换）→ 立刻让 token 缓存失效，下一次请求重新认证\n    if (res.status === 401 || res.status === 403) invalidateRelayToken(relayDir);\n    const text = await res.text();\n    let body = null;\n    try {\n      body = JSON.parse(text);\n    } catch {\n      body = text;\n    }\n    return { status: res.status, ok: res.ok, body };\n  } catch (e) {\n    return { status: 0, ok: false, body: { error: { message: `relay 不可达: ${e.message}` } } };\n  }\n}\n\n// ---------- bridge_secret 自愈（device-login 共享密钥） ----------\n\n/**\n * 企业端 POST /api/device-login 强制校验 `x-dsh-bridge-secret`（缺失/失效 → 401 \"需要有效设备密钥\"），\n * 密钥由服务端公开配置 /api/public-config 下发、与 dsh-setup.mjs 的 `bridge_secret` 同源。\n *\n * 一键安装器（npx @mrrisega/dsh-remote → dsh-setup.mjs）会在安装时取一次并写入 .dsh-config.json；\n * 但**只装插件**的路径（dsh plugin add / 插件市场安装）没有这一步，于是：\n *   首次安装 → 打开设置面板立即登录 → 面板请求 /dsh-remote/access-key & mobile-sessions\n *   → relayToken 拿不到 token（401 需要设备密钥）→ 面板显示「尚未登录」（其实是密钥缺失）\n * 直到后台自愈（scheduleRuntime → ensureRuntime 跑一次 npx 安装器）把 bridge_secret 写回配置，\n * 或用户手动刷新页面才恢复——这正是「首次安装后立即登录，二维码/设备列表报红字」的根因。\n *\n * 这里在插件侧补上同一份自愈：缺密钥就取一次、落盘并缓存；失败短退避后可再试，不阻塞面板。\n */\nlet bridgeSecretCache = { dir: \"\", secret: \"\", failedAt: 0 };\nconst BRIDGE_SECRET_RETRY_MS = 15_000;\n\n/** 读取配置里已保存的 bridge_secret（无则空串）。 */\nfunction readBridgeSecret(relayDir) {\n  try {\n    return String(loadConfig(relayDir).bridge_secret || \"\").trim();\n  } catch {\n    return \"\";\n  }\n}\n\n/**\n * 取 device-login 共享密钥：配置已有 → 直接用；否则向企业端公开配置取一次并写回配置（内存缓存兜底）。\n * @param {string} relayDir 配置目录\n * @param {object} [cfgOverride] 尚未落盘的配置（登录请求刚写入 phone/password 时用），仅用于判断模式\n * @param {{force?: boolean, timeoutMs?: number}} [opts] force=true 跳过本地文件/缓存强制重取；\n *        timeoutMs 限制单次公开配置请求耗时（登录路径用更短的上限，避免拖慢登录响应）\n * @returns {Promise<string>} 密钥（取不到为空串，调用方按“中继未就绪”降级，不抛错）\n */\nasync function bridgeSecretOf(relayDir, cfgOverride, opts) {\n  const force = !!(opts && opts.force);\n  if (!force) {\n    const local = readBridgeSecret(relayDir);\n    if (local) {\n      bridgeSecretCache = { dir: relayDir, secret: local, failedAt: 0 };\n      return local;\n    }\n    if (bridgeSecretCache.dir === relayDir && bridgeSecretCache.secret) return bridgeSecretCache.secret;\n    if (bridgeSecretCache.dir === relayDir && Date.now() - bridgeSecretCache.failedAt < BRIDGE_SECRET_RETRY_MS) return \"\"; // 负缓存：别把公开配置打爆\n  }\n  const cfg = cfgOverride && typeof cfgOverride === \"object\" ? { ...loadConfig(relayDir), ...cfgOverride } : loadConfig(relayDir);\n  if (cfg.local_key) return \"\"; // 自建模式走 /_login，不用设备密钥\n  const api = (cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n  const timeoutMs = Number((opts && opts.timeoutMs) || 0) > 0 ? Number(opts.timeoutMs) : 6000;\n  let secret = \"\";\n  try {\n    const r = await fetch(`${api}/api/public-config`, { signal: AbortSignal.timeout(timeoutMs) });\n    if (r.ok) {\n      const d = await r.json();\n      secret = String((d && d.bridge_secret) || \"\").trim();\n    }\n  } catch { /* 网络抖动：负缓存短退避后再试 */ }\n  if (!secret) {\n    bridgeSecretCache = { dir: relayDir, secret: \"\", failedAt: Date.now() };\n    return \"\";\n  }\n  bridgeSecretCache = { dir: relayDir, secret, failedAt: 0 };\n  // 落盘（与 dsh-setup.mjs 同一份配置）：即使本进程退出，下次启动也不再缺密钥/不再是旧密钥\n  let healed = false;\n  try {\n    const cur = loadConfig(relayDir);\n    if (!cur.bridge_secret || (force && cur.bridge_secret !== secret)) {\n      cur.bridge_secret = secret;\n      saveConfig(relayDir, cur);\n      healed = true;\n    }\n  } catch { /* 写盘失败不致命：内存缓存本次进程内仍生效 */ }\n  // 密钥是「从无到有」补上的：已经在跑的 bridge 是用空密钥起的，隧道认证同样会失败——\n  // 后台重启一次让它带上密钥（一次性事件，失败只记日志不打断面板请求）。\n  if (healed && !UNINSTALLED_DIRS.has(relayDir)) {\n    setTimeout(() => {\n      try {\n        const st = launchdStatus();\n        if (!st.running) return;\n        const r = startBridge(relayDir);\n        console.log(`[dsh-remote-web] 已补记 bridge_secret，后台重启 bridge 使其生效: ${r.status}`);\n      } catch (e) {\n        console.warn(`[dsh-remote-web] 补记 bridge_secret 后重启 bridge 失败: ${e.message}`);\n      }\n    }, 50).unref?.();\n  }\n  return secret;\n}\n\n// ---------- 账号 / 用量 / 邀请代理（我的信息、额度提示、邀请记录） ----------\n\n/** token 获取失败的原因（供 UI 区分“未登录”与“中继未就绪”，不再一律谎报“尚未登录”）。 */\nconst AUTH_NO_CREDENTIALS = \"no_credentials\";       // 本机没存账号/自建密钥 → 该去登录\nconst AUTH_BAD_CREDENTIALS = \"bad_credentials\";     // 账号密码被企业端拒绝 → 该重新登录\nconst AUTH_RELAY_UNREACHABLE = \"relay_unreachable\"; // 网络/5xx/超时 → 稍后重试\nconst AUTH_RELAY_NOT_READY = \"relay_not_ready\";     // 凭证齐全但企业端未接受（缺失/轮换中的设备密钥等）→ 稍后重试\n\nconst sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\n\n/**\n * relay token 短期缓存（60s）：连接阶段的 2~3s 短轮询会反复取 token，若每次都走 device-login\n * （即账号密码认证），就会**每几秒打一次企业端认证接口**——审计日志刷屏、可能触发限流，且纯属浪费。\n *   - TTL 60s：远短于 JWT 自身有效期；账号密码/共享密钥变更最多 60s 生效；\n *   - 键含 api_url + 账号 + 模式：换账号、切自建/云端、换服务端会自动 miss；\n *   - 并发合并（relayTokenInflight）：同一时刻多个请求共用一次认证；\n *   - 只缓存成功结果；企业端回 401/403（JWT 过期/轮换）时 relayFetch 立即 invalidateRelayToken。\n */\nconst RELAY_TOKEN_TTL_MS = 60_000;\nconst relayTokenCache = new Map();    // relayDir → { key, token, exp, status }\nconst relayTokenInflight = new Map(); // relayDir → { key, promise }\n/** 缓存键：同一台机器换了账号/服务端/模式时自动失效，避免把别人的 token 用错地方。 */\nfunction relayTokenKeyOf(cfg) {\n  return [\n    (cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\"),\n    cfg.local_key ? \"local\" : \"saas\",\n    cfg.local_key ? String(cfg.local_key).slice(0, 8) : (cfg.phone || cfg.email || \"\"),\n  ].join(\"|\");\n}\n/** 丢弃某 relayDir 的 token 缓存（账号变更、退出登录、企业端拒绝 JWT 时调用）。 */\nfunction invalidateRelayToken(relayDir) {\n  if (!relayDir) return;\n  relayTokenCache.delete(relayDir);\n  deviceProbeCache.delete(relayDir); // 认证失效时「设备探活」结论同样过期（否则 15s 内不会重试）\n}\n/**\n * 账号设备表探活缓存（见 accountDeviceBound）：企业端每次 GET /api/devices 都会写一行活跃明细\n * （user_activity），因此绝不跟着 2.5s 的 UI 轮询打——15s 一次，且只在与中继注册证据缺失时才探。\n */\nconst DEVICE_PROBE_TTL_MS = 15_000;\nconst deviceProbeCache = new Map(); // relayDir → { at, value }\n\n/** 单次 device-login：返回 { ok, status, token, code, detail }（不抛错，便于按原因降级/重试）。 */\nasync function deviceLoginOnce(api, cfg, secret) {\n  try {\n    const r = await fetch(`${api}/api/device-login`, {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\", ...(secret ? { \"x-dsh-bridge-secret\": secret } : {}) },\n      body: JSON.stringify({ phone: cfg.phone, email: cfg.phone, password: cfg.password }),\n      signal: AbortSignal.timeout(6000)\n    });\n    const text = await r.text();\n    let d = null;\n    try { d = JSON.parse(text); } catch { d = null; }\n    return {\n      ok: r.ok,\n      status: r.status,\n      token: (d && d.token) || \"\",\n      code: (d && d.error && d.error.code) || \"\",\n      detail: (d && d.error && (d.error.message || d.error.code)) || \"\",\n    };\n  } catch (e) {\n    return { ok: false, status: 0, token: \"\", code: \"\", detail: e.message };\n  }\n}\n\n/** 单次本地认证（自建模式）：POST {隧道同源}/_login。 */\nasync function localLoginOnce(cfg, api) {\n  const fallbackApi = (api || cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n  try {\n    const u = new URL(cfg.tunnel_url || fallbackApi.replace(/^https?/, \"wss\"));\n    u.protocol = u.protocol === \"wss:\" ? \"https:\" : \"http:\";\n    u.pathname = \"/_login\";\n    const r = await fetch(u.toString(), {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify({ key: cfg.local_key }),\n      signal: AbortSignal.timeout(6000)\n    });\n    if (!r.ok) return { ok: false, status: r.status, token: \"\", code: \"\", detail: \"\" };\n    const d = await r.json();\n    return { ok: true, status: 200, token: (d && d.token) || \"\", code: \"\", detail: \"\" };\n  } catch (e) {\n    return { ok: false, status: 0, token: \"\", code: \"\", detail: e.message };\n  }\n}\n\n/**\n * 获取短期 relay token:SaaS → device-login;本地模式 → /_login(从隧道地址推导同源)。\n * 与旧版差异：① 缺 device-login 共享密钥时自愈补齐；② 服务端轮换密钥(401/403)自动重取重试；\n * ③ 网络抖动/5xx 退避重试一次；④ 失败时给出**可判定原因**而非空串（消除“尚未登录”误报）。\n * @returns {Promise<{token:string, reason:string, status:number, detail:string}>}\n */\nasync function relayTokenWithReason(relayDir, cfgOverride, opts = {}) {\n  const cfg = cfgOverride && typeof cfgOverride === \"object\" ? { ...loadConfig(relayDir), ...cfgOverride } : loadConfig(relayDir);\n  const key = relayTokenKeyOf(cfg);\n  const now = Date.now();\n  const hit = relayTokenCache.get(relayDir);\n  if (!opts.force && hit && hit.key === key && hit.token && now < hit.exp) {\n    return { token: hit.token, reason: \"\", status: hit.status || 200, detail: \"\", cached: true };\n  }\n  // 并发合并：同一时刻的多个请求（状态轮询 / 二维码 / 设备列表 / 上报）共用一次认证\n  const flying = relayTokenInflight.get(relayDir);\n  if (!opts.force && flying && flying.key === key) return flying.promise;\n  const promise = relayTokenUncached(relayDir, cfg, cfgOverride).then((res) => {\n    if (res && res.token) {\n      relayTokenCache.set(relayDir, { key, token: res.token, exp: Date.now() + RELAY_TOKEN_TTL_MS, status: res.status || 200 });\n    } else {\n      relayTokenCache.delete(relayDir); // 失败不缓存：下一轮立刻重试\n    }\n    relayTokenInflight.delete(relayDir);\n    return res;\n  }, (e) => {\n    relayTokenInflight.delete(relayDir);\n    throw e;\n  });\n  relayTokenInflight.set(relayDir, { key, promise });\n  return promise;\n}\n\n/** 未缓存的真实取 token 逻辑（relayTokenWithReason 的缓存/合并外壳在这里之上一层）。 */\nasync function relayTokenUncached(relayDir, cfg, cfgOverride) {\n  const api = (cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n  if (cfg.local_key) {\n    let r = await localLoginOnce(cfg, api);\n    if (!r.token && (r.status === 0 || r.status >= 500)) { await sleep(350); r = await localLoginOnce(cfg, api); }\n    if (r.token) return { token: r.token, reason: \"\", status: r.status, detail: \"\" };\n    return {\n      token: \"\",\n      reason: r.status === 401 || r.status === 403 ? AUTH_BAD_CREDENTIALS : AUTH_RELAY_UNREACHABLE,\n      status: r.status,\n      detail: r.detail,\n    };\n  }\n  if (!cfg.phone || !cfg.password) return { token: \"\", reason: AUTH_NO_CREDENTIALS, status: 0, detail: \"\" };\n\n  let secret = await bridgeSecretOf(relayDir, cfgOverride);\n  let r = await deviceLoginOnce(api, cfg, secret);\n  // 带了密钥仍被拒 → 可能是服务端轮换了共享密钥：丢弃缓存强制重取一次再试\n  if (!r.token && (r.status === 401 || r.status === 403) && secret) {\n    const fresh = await bridgeSecretOf(relayDir, cfgOverride, { force: true });\n    if (fresh && fresh !== secret) r = await deviceLoginOnce(api, cfg, fresh);\n  }\n  // 网络抖动/超时/5xx：短退避重试一次（首次安装后中继握手偶发失败很常见）\n  if (!r.token && (r.status === 0 || r.status >= 500)) {\n    await sleep(350);\n    r = await deviceLoginOnce(api, cfg, await bridgeSecretOf(relayDir, cfgOverride));\n  }\n  if (r.token) return { token: r.token, reason: \"\", status: r.status, detail: \"\" };\n  if (r.code === \"bad_credentials\") return { token: \"\", reason: AUTH_BAD_CREDENTIALS, status: r.status, detail: r.detail };\n  // 凭证齐全但企业端没给 token（设备密钥缺失/轮换中、限流、其它 4xx）→ 可重试，不谎报“未登录”\n  if (r.status === 0 || r.status >= 500) return { token: \"\", reason: AUTH_RELAY_UNREACHABLE, status: r.status, detail: r.detail };\n  return { token: \"\", reason: AUTH_RELAY_NOT_READY, status: r.status, detail: r.detail };\n}\n\n/** 兼容旧调用方（反馈/账号/配额等只需 token 字符串）。 */\nasync function relayToken(relayDir) {\n  const r = await relayTokenWithReason(relayDir).catch(() => ({ token: \"\" }));\n  return r.token || \"\";\n}\n\n/** 我的信息:SaaS 账号的生效套餐/到期日/邀请码(经 /api/me)。 */\nasync function relayAccount(relayDir) {\n  const token = await relayToken(relayDir);\n  if (!token) return null;\n  const r = await relayFetch(relayDir, \"/api/me\", { headers: { authorization: `Bearer ${token}` } });\n  if (!r.ok || !r.body || !r.body.user) return null;\n  const u = r.body.user;\n  return {\n    phone: maskPhone(u.phone || \"\"),\n    plan: u.plan || \"free\",\n    plan_source: u.plan_source || \"plan\",\n    plan_ends_at: u.plan_ends_at ?? null,\n    trial_expires_at: u.trial_expires_at ?? null,\n    invite_code: u.invite_code || \"\",\n    invited_by: u.invited_by ?? null\n  };\n}\n\n/** 流量用量:router /_quota(免费用户百分比提示)。 */\nasync function relayQuota(relayDir) {\n  const token = await relayToken(relayDir);\n  if (!token) return null;\n  const cfg = loadConfig(relayDir);\n  // router 同源:apiUrl(https://host/relay-api) → https://host;本地模式从 tunnel_url 推导\n  let origin = \"\";\n  if (cfg.tunnel_url) {\n    const u = new URL(cfg.tunnel_url);\n    u.protocol = u.protocol === \"wss:\" ? \"https:\" : \"http:\";\n    origin = u.origin;\n  } else {\n    const u = new URL((cfg.api_url || DEFAULT_API));\n    origin = u.origin;\n  }\n  try {\n    const r = await fetch(`${origin}/_quota`, {\n      headers: { cookie: `dsh_token=${encodeURIComponent(token)}` },\n      signal: AbortSignal.timeout(6000)\n    });\n    if (!r.ok) return null;\n    const d = await r.json();\n    return d.quota || null;\n  } catch {\n    return null;\n  }\n}\n\n/** 我的邀请记录(登录态):有效邀请 + 奖励。 */\nasync function relayInviteRecords(relayDir) {\n  const token = await relayToken(relayDir);\n  if (!token) return null;\n  const r = await relayFetch(relayDir, \"/api/invite-records\", { headers: { authorization: `Bearer ${token}` } });\n  if (!r.ok || !r.body) return null;\n  return { records: r.body.records || [], rewards: r.body.rewards || [] };\n}\n\n// ---------- 交流群二维码（后台配置，公开读取） ----------\n\n/**\n * 交流群二维码/客服微信：企业端配置经公开配置 /api/public-config 的 community 字段下发\n * （community.qrcode 形如 \"/qr/group-qr.png\"）。面板与反馈页展示「加入交流群」用。\n *\n * 面板跑在电脑本机 dsh web（http://127.0.0.1:3080），相对路径无法直接当 <img src>，\n * 故这里按企业端公开约定拼成绝对地址：<api_url><qrcode>（与手机端 PWA 的 API_BASE + qr 一致）。\n * 30s 内存缓存：面板与反馈卡都会取，避免重复打公开配置。\n */\nconst COMMUNITY_TTL_MS = 30_000;\nlet communityCache = { dir: \"\", at: 0, data: null };\n\nasync function communityInfo(relayDir) {\n  if (communityCache.data && communityCache.dir === relayDir && Date.now() - communityCache.at < COMMUNITY_TTL_MS) {\n    return communityCache.data;\n  }\n  const cfg = loadConfig(relayDir);\n  const api = (cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n  const r = await relayFetch(relayDir, \"/api/public-config\");\n  const b = r.ok && r.body && typeof r.body === \"object\" ? r.body : {};\n  const c = b.community && typeof b.community === \"object\" ? b.community : {};\n  const raw = String(c.qrcode || \"\").trim();\n  const qrcode = raw && !/^https?:/i.test(raw) ? api + (raw.startsWith(\"/\") ? raw : `/${raw}`) : raw;\n  const data = { qrcode, wechat: String(c.wechat || \"\") };\n  communityCache = { dir: relayDir, at: Date.now(), data };\n  return data;\n}\n\n// ---------- 📄 会员服务购买协议 URL（购买入口的《会员服务购买协议》链接） ----------\n\n/**\n * 购买入口必须带《会员服务购买协议》链接（业主要求，2026-10-23 客户端 0.7.5-beta.1）。\n *\n * URL 来源优先级：\n *   1) 企业端 `public-config` 的 `agreement_url`（**新字段**；企业端还没上线时没有 → 忽略）；\n *   2) 固定兜底 `DEFAULT_PURCHASE_AGREEMENT_URL`（正式协议由企业端提供，未就绪也能点开）。\n *\n * 安全：只允许 **http(s) 绝对地址**；`javascript:` / `data:` / 协议相对（`//host`）/ 相对路径\n * 一律回兜底 —— 这个值最终会进 `<a href>`，绝不能吃进可执行协议（与 qr_url 同一套纪律）。\n *\n * 软着陆：public-config 不可达 / 非对象 / 字段缺失全部回兜底并 `ok:true`。\n * 协议链接**永远不该**成为购买流程的故障点（打不开也不影响旁边的「升级 / 续费」按钮）。\n */\nexport const DEFAULT_PURCHASE_AGREEMENT_URL = \"https://n.risegao.cn:13443/relay-api/api/purchase-agreement\";\n\n/** 从 public-config 解析协议 URL（纯函数，便于单测：优先级 + 安全过滤 + 降级一次看完）。 */\nexport function purchaseAgreementUrlFrom(publicConfig) {\n  const raw = publicConfig && typeof publicConfig === \"object\"\n    ? String(publicConfig.agreement_url == null ? \"\" : publicConfig.agreement_url).trim()\n    : \"\";\n  if (/^https?:\\/\\/[^\\s]+$/i.test(raw)) return raw;\n  return DEFAULT_PURCHASE_AGREEMENT_URL;\n}\n\n/** GET /dsh-remote/purchase-agreement 的实现：读公开配置 → 安全过滤 → 兜底。 */\nasync function purchaseAgreementInfo(relayDir) {\n  let body = null;\n  try {\n    const r = await relayFetch(relayDir, \"/api/public-config\");\n    body = r && r.ok && r.body && typeof r.body === \"object\" ? r.body : null;\n  } catch {\n    body = null; // relayFetch 本身不抛；这里只是防御（协议链接不能把面板打挂）\n  }\n  const raw = body && typeof body === \"object\" ? String(body.agreement_url == null ? \"\" : body.agreement_url).trim() : \"\";\n  const url = purchaseAgreementUrlFrom(body);\n  return {\n    ok: true,\n    url,\n    // 便于排障：这个 URL 是服务端配的，还是走兜底（面板不展示，只出现在响应里）\n    source: url !== DEFAULT_PURCHASE_AGREEMENT_URL ? \"public_config\" : (raw ? \"public_config_invalid\" : \"fallback\"),\n  };\n}\n\n// ---------- 一次性访问密钥 / 已授权设备代理（E1 企业端新增 auth-key / mobile-sessions） ----------\n\n/** 从 relay 响应里尽量提取人类可读错误信息（兼容 {error:{message}} / {error:\"..\"} / {message} / 纯文本）。 */\nfunction relayErrorMessage(r) {\n  const b = r && typeof r === \"object\" ? r.body : null;\n  if (b && typeof b === \"object\") {\n    if (typeof b.error === \"string\" && b.error) return b.error;\n    if (b.error && typeof b.error === \"object\") {\n      if (typeof b.error.message === \"string\" && b.error.message) return b.error.message;\n    }\n    if (typeof b.message === \"string\" && b.message) return b.message;\n  }\n  if (typeof b === \"string\" && b.trim()) return b.trim();\n  const st = r && r.status;\n  return st ? `企业端请求失败（HTTP ${st}）` : \"企业端不可达，请稍后重试\";\n}\n\n/** 未登录（无账号/自建密钥）时的统一返回文案。 */\nfunction notLoggedInJson() {\n  return { ok: false, error: \"尚未登录：请先在「账号」卡片登录手机号账号（或切换到自建服务）后重试\", hint: \"login_required\" };\n}\n\n/**\n * 凭证齐全但拿不到 relay token 时的统一返回：区分「密码失效需重新登录」与「中继暂未就绪可重试」。\n * 关键：不再把中继未就绪/设备密钥缺失谎报成“尚未登录”（旧版 UI 因此显示误导性红字）。\n */\nfunction relayAuthFailureJson(reason, detail) {\n  if (reason === AUTH_NO_CREDENTIALS) return { status: 401, body: notLoggedInJson() };\n  if (reason === AUTH_BAD_CREDENTIALS) {\n    return {\n      status: 401,\n      body: {\n        ok: false,\n        error: \"本机保存的账号密码已被中继拒绝（可能已在别处修改过密码）：请用新密码重新登录「账号」卡片后重试\",\n        hint: \"relogin_required\",\n        retryable: false,\n        detail: String(detail || \"\"),\n      },\n    };\n  }\n  const unreachable = reason === AUTH_RELAY_UNREACHABLE;\n  return {\n    status: 503,\n    body: {\n      ok: false,\n      error: unreachable\n        ? \"中继服务暂时不可达（网络波动或中继正在重启），请稍后重试\"\n        : \"账号已登录，但中继连接尚未就绪（正在建立安全通道），请稍后重试\",\n      hint: unreachable ? \"relay_unreachable\" : \"relay_not_ready\",\n      retryable: true,\n      detail: String(detail || \"\"),\n    },\n  };\n}\n\n/**\n * 取 relay token 或直接回错误响应（面板代理统一入口）。\n * @returns {Promise<string>} token；为空串表示已写出错误响应（调用方直接 return）\n */\nasync function relayTokenOrReject(relayDir, res, cfgOverride) {\n  const a = await relayTokenWithReason(relayDir, cfgOverride).catch((e) => ({\n    token: \"\",\n    reason: AUTH_RELAY_UNREACHABLE,\n    status: 0,\n    detail: e && e.message,\n  }));\n  if (a.token) return a.token;\n  const { status, body } = relayAuthFailureJson(a.reason, a.detail);\n  console.warn(`[dsh-remote-web] 取 relay token 失败(${a.reason}/${a.status}): ${a.detail || \"无详情\"}`);\n  sendJson(res, status, body);\n  return \"\";\n}\n\n/**\n * 透传企业端响应体：契约字段可能在顶层或 data 子对象里（容错）。\n * 返回扁平对象；数组字段只取首层数组。\n */\nfunction flattenRelayBody(r) {\n  const b = r && typeof r === \"object\" && r.body && typeof r.body === \"object\" ? r.body : {};\n  const d = b.data && typeof b.data === \"object\" ? { ...b.data, ...b } : b;\n  return d;\n}\n\n/**\n * GET /dsh-remote/access-key → 创建一次性访问密钥（企业端 POST /api/auth-key，Bearer device-login token）。\n * 契约容错：url 必须可用；qr_data_url 取不到时返回 null（UI 只展示链接并说明“二维码暂不可用”，不报错）。\n */\nasync function proxyCreateAccessKey(relayDir, res) {\n  const token = await relayTokenOrReject(relayDir, res);\n  if (!token) return;\n  const r = await relayFetch(relayDir, \"/api/auth-key\", {\n    method: \"POST\",\n    headers: { authorization: `Bearer ${token}`, \"content-type\": \"application/json\" },\n    body: JSON.stringify({}),\n  });\n  const d = flattenRelayBody(r);\n  const url = typeof d.url === \"string\" ? d.url.trim() : \"\";\n  if (!r.ok || !url) {\n    // url 不可用是硬失败（企业端契约缺陷）；错误码/状态透传给 UI 展示\n    const err = r.ok && !url ? \"企业端未返回可用的访问地址（缺 url）\" : relayErrorMessage(r);\n    return sendJson(res, (r && r.status) || 502, { ok: false, error: err, relayStatus: (r && r.status) || 0 });\n  }\n  return sendJson(res, 200, {\n    ok: true,\n    url,\n    key: d.key ?? null,\n    expires_at: d.expires_at ?? null,\n    ttl_ms: d.ttl_ms ?? null,\n    qr_data_url: d.qr_data_url ?? null,\n    relayStatus: (r && r.status) || 200,\n  });\n}\n\n/**\n * GET /dsh-remote/mobile-sessions → 已授权设备列表（企业端 GET /api/mobile-sessions，Bearer）。\n */\nasync function proxyMobileSessions(relayDir, res) {\n  const token = await relayTokenOrReject(relayDir, res);\n  if (!token) return;\n  const r = await relayFetch(relayDir, \"/api/mobile-sessions\", {\n    method: \"GET\",\n    headers: { authorization: `Bearer ${token}` },\n  });\n  const d = flattenRelayBody(r);\n  const sessions = Array.isArray(d.sessions) ? d.sessions : [];\n  if (!r.ok) {\n    return sendJson(res, (r && r.status) || 502, { ok: false, error: relayErrorMessage(r), relayStatus: (r && r.status) || 0, sessions });\n  }\n  return sendJson(res, 200, { ok: true, sessions, relayStatus: (r && r.status) || 200 });\n}\n\n/**\n * POST /dsh-remote/mobile-sessions/revoke（body {id}）→ 取消配对（企业端 POST /api/mobile-sessions/:id/revoke，Bearer）。\n */\nasync function proxyRevokeMobileSession(relayDir, req, res) {\n  const body = await readJsonBody(req);\n  if (body.__parseError) return sendJson(res, 400, { ok: false, error: \"JSON 解析失败\" });\n  const id = String(body.id ?? \"\").trim();\n  if (!id) return sendJson(res, 400, { ok: false, error: \"缺少参数 id（会话 ID）\" });\n  const token = await relayTokenOrReject(relayDir, res);\n  if (!token) return;\n  const r = await relayFetch(relayDir, `/api/mobile-sessions/${encodeURIComponent(id)}/revoke`, {\n    method: \"POST\",\n    headers: { authorization: `Bearer ${token}` },\n  });\n  const d = flattenRelayBody(r);\n  // 兼容两种成功形态：HTTP ok，或 body.ok === true（允许企业端 200 + ok:false 表示业务失败）\n  const ok = !!(r.ok && d.ok !== false);\n  if (!ok) {\n    return sendJson(res, (r && r.status) || 502, { ok: false, error: relayErrorMessage(r), relayStatus: (r && r.status) || 0 });\n  }\n  return sendJson(res, 200, { ok: true, relayStatus: (r && r.status) || 200 });\n}\n\n/**\n * DELETE /dsh-remote/mobile-sessions/delete（body {id}）→ 删除本机该设备的授权记录\n * （企业端 DELETE /api/mobile-sessions/:id，Bearer：本人整行删除并拉黑 jti）。\n */\nasync function proxyDeleteMobileSession(relayDir, req, res) {\n  const body = await readJsonBody(req);\n  if (body.__parseError) return sendJson(res, 400, { ok: false, error: \"JSON 解析失败\" });\n  const id = String(body.id ?? \"\").trim();\n  if (!id) return sendJson(res, 400, { ok: false, error: \"缺少参数 id（会话 ID）\" });\n  const token = await relayTokenOrReject(relayDir, res);\n  if (!token) return;\n  const r = await relayFetch(relayDir, `/api/mobile-sessions/${encodeURIComponent(id)}`, {\n    method: \"DELETE\",\n    headers: { authorization: `Bearer ${token}` },\n  });\n  const d = flattenRelayBody(r);\n  const ok = !!(r.ok && d.ok !== false);\n  if (!ok) {\n    return sendJson(res, (r && r.status) || 502, { ok: false, error: relayErrorMessage(r), relayStatus: (r && r.status) || 0 });\n  }\n  return sendJson(res, 200, { ok: true, relayStatus: (r && r.status) || 200 });\n}\n\n/**\n * POST /dsh-remote/mobile-sessions/purge → 清理本人所有已解绑（revoked）记录\n * （企业端 POST /api/mobile-sessions/purge，Bearer）。\n */\nasync function proxyPurgeMobileSessions(relayDir, res) {\n  const token = await relayTokenOrReject(relayDir, res);\n  if (!token) return;\n  const r = await relayFetch(relayDir, \"/api/mobile-sessions/purge\", {\n    method: \"POST\",\n    headers: { authorization: `Bearer ${token}` },\n  });\n  const d = flattenRelayBody(r);\n  const ok = !!(r.ok && d.ok !== false);\n  if (!ok) {\n    return sendJson(res, (r && r.status) || 502, { ok: false, error: relayErrorMessage(r), relayStatus: (r && r.status) || 0 });\n  }\n  const removed = Number.isInteger(d.removed) ? d.removed : null;\n  const payload = { ok: true, relayStatus: (r && r.status) || 200 };\n  if (removed !== null) payload.removed = removed;\n  return sendJson(res, 200, payload);\n}\n\n// ---------- 综合状态 ----------\n\n/**\n * 读取 bridge 写入的 E2EE 开关状态（<relayDir>/.e2ee-state.json，写入方见\n * clients/dsh-remote/e2ee-client.mjs 的 writeE2eeStateFile：{enabled, reason, profile, epoch, caps, at}）。\n * 归一化后只透出固定展示字段（enabled/reason/profile/epoch/caps），at 等调试字段不外泄；\n * 文件缺失/损坏一律视为「未启用（明文回退）」——面板据此显示普通安全连接。\n */\nexport function readE2eeStateFile(relayDir) {\n  const none = () => ({ enabled: false, reason: \"no_state_file\", profile: \"\", epoch: 0, caps: [] });\n  try {\n    const f = join(relayDir, \".e2ee-state.json\");\n    if (!existsSync(f)) return none();\n    const s = JSON.parse(readFileSync(f, \"utf8\"));\n    if (!s || typeof s !== \"object\") return none();\n    return {\n      enabled: s.enabled === true,\n      reason: typeof s.reason === \"string\" && s.reason ? s.reason : \"\",\n      profile: typeof s.profile === \"string\" ? s.profile : \"\",\n      epoch: Number.isInteger(s.epoch) && s.epoch >= 0 ? s.epoch : 0,\n      caps: Array.isArray(s.caps) ? s.caps.filter((c) => typeof c === \"string\") : [],\n    };\n  } catch {\n    return none();\n  }\n}\n\n/**\n * 手机号脱敏(隐私审计 2026-09):面板/镜像 UI 一律不下发明文手机号。\n * 明文只在 bridge 本机 config / 服务端账号体系内流转,浏览器侧仅见掩码。\n */\nfunction maskPhone(p) {\n  const s = String(p || \"\");\n  return s.length >= 7 ? s.slice(0, 3) + \"****\" + s.slice(-4) : (s ? s.slice(0, 1) + \"****\" : \"\");\n}\n\nasync function composeStatus(relayDir) {\n  const cfg = loadConfig(relayDir);\n  const launchd = launchdStatus();\n  const manual = manualStatus(relayDir);\n  // 注册/绑定失败提示(bridge 写 .bind-error.json;面板据此展示“已达上限/需解绑”引导)\n  let bindError = null;\n  try {\n    const f = join(relayDir, \".bind-error.json\");\n    if (existsSync(f)) bindError = JSON.parse(readFileSync(f, \"utf8\"));\n  } catch { /* 无/损坏忽略 */ }\n  // 远程地址（public-config 的 app_url，取不到用默认）\n  const pub = await relayFetch(relayDir, \"/api/public-config\");\n  const pubBody = pub.ok && pub.body && typeof pub.body === \"object\" ? pub.body : {};\n  const remoteUrl = pubBody.app_url || DEFAULT_APP_URL;\n  const apiUrl = pubBody.api_url || cfg.api_url || DEFAULT_API;\n  return {\n    ok: true,\n    config: {\n      phone: maskPhone(cfg.phone || \"\"),\n      hasPhone: Boolean(cfg.phone),\n      hasPassword: Boolean(cfg.password),\n      deviceId: cfg.device_id || \"\",\n      apiUrl,\n      mode: cfg.local_key ? \"local\" : \"saas\",   // 连接模式:saas(公网) | local(自建)\n      selfHostUrl: cfg.tunnel_url ? cfg.tunnel_url.replace(/^wss?:\\/\\//, \"\").replace(/\\/+$/, \"\") : \"\",\n      hasLocalKey: Boolean(cfg.local_key),\n    },\n    remoteUrl,\n    relayReachable: pub.ok,\n    service: {\n      plistExists: Boolean(launchAgentPath() && existsSync(launchAgentPath())),\n      // 平台与服务管理器：面板据此给出平台正确的文案（Windows 没有\"自启动服务\"这回事，\n      // 也不该把 bridge 说成 launchd/systemd 服务）\n      platform: osPlatform(),\n      serviceManager: isDarwin() ? \"launchd\" : isWindows() ? \"detached\" : osPlatform() === \"linux\" ? (systemdUserAvailableCached() ? \"systemd\" : \"detached\") : \"none\",\n      // Windows：登录任务（任务计划程序）是否已注册——面板据此给\"能不能开机自启\"的准确说法\n      autostartTask: isWindows() ? windowsTaskRegistered() : null,\n      launchd,\n      manual,\n      running: launchd.running || manual.bridge.length > 0,\n      // 桌面运行环境（固化运行时 dsh-setup.mjs）是否就绪：面板据此区分\n      // 「运行环境没装（正在自动补装）」与「装了但没跑」，不再把崩溃循环显示成「运行中」。\n      runtimeReady: runtimeReady(relayDir),\n      bindError,\n      // E2EE 开关状态（bridge 写 .e2ee-state.json；文件缺失 = 未启用明文）：\n      // {enabled, reason, profile, epoch, caps}，供面板「📱 远程访问」卡展示加密状态。\n      e2ee: readE2eeStateFile(relayDir),\n    },\n    // 是否需要重启 DeepSeek harness（首次安装 / 在线更新后必须重启才加载插件本体）：\n    // {pending, kind: first-install|update, reason, at}，供面板顶部醒目提示 + 重启按钮。\n    restart: readRestartState(relayDir),\n    // 桌面端暂存的插件更新（存在 = 新版本已下载，退出应用后由 bridge 自动安装并生效）\n    desktopUpdatePending: readDesktopUpdatePending(relayDir),\n    // 安装/配对自检（2026-10-17 事故）：运行时（clients/）与配对（.dsh-config.json）是否齐全、\n    // 缺什么、下一步该做什么；配对主配置缺失但备份存在时给出可一键恢复的 backup.action。\n    // 字段契约见 setupStateOf；connect.setup 是同一份对象（bridge-status 短轮询也能拿到）。\n    setup: setupStateOf(relayDir),\n    // 连接阶段（登录后自动闭环：环境 → bridge 进程 → 设备已在中继注册）：\n    // 面板用它显示「正在准备运行环境…/正在启动 Bridge…/正在连接中继…/已连接 ✅」，\n    // 并用 /dsh-remote/bridge-status 以 2~3s 短轮询自动推进（无需用户点按钮或刷新页面）。\n    connect: await composeConnect(relayDir, { cfg, launchd, manual }),\n    // 隐私审计(2026-09):不再下发真实 hostname(移除 host 字段)——设备标识统一走 deviceId/服务端登记名\n  };\n}\n\n// ---------- 用户反馈代理（反馈 API 与账号服务同源，走 /relay-api/） ----------\n\n/**\n * 反馈 API 基址：feedback_url（自建/兼容实现）> 账号 API 基址（默认生产 relay-api）。\n * 反馈端点路径与账号 API 同构：{base}/api/feedback*。\n */\nfunction feedbackApiOf(cfg) {\n  return (cfg.feedback_url || cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n}\n\n/** 读取请求体（上限 64KB，与反馈服务一致）。 */\nasync function readBodyBuffer(req, limit = 64 * 1024) {\n  const chunks = [];\n  let total = 0;\n  for await (const c of req) {\n    total += c.length;\n    if (total > limit) {\n      const e = new Error(\"body too large\");\n      e.status = 413;\n      throw e;\n    }\n    chunks.push(c);\n  }\n  return Buffer.concat(chunks);\n}\n\n/**\n * 把 /dsh-remote/feedback/* 代理到反馈 API（同源 /relay-api/）：\n *   - 自动附加本机稳定身份 X-Dsh-Device（device_id）与 X-Dsh-Phone（已登录手机号）\n *   - 透传浏览器带的 Authorization（thread_token，存于浏览器 localStorage）\n *   - 不转发 cookie/浏览器标记；反馈服务不可达时降级 502 JSON\n */\n// 账号 JWT 缓存（反馈请求高频，避免每次 device-login 刷审计日志）；过期前复用\nlet fbTokenCache = { token: \"\", exp: 0 };\nasync function feedbackAuthToken(relayDir) {\n  if (fbTokenCache.token && Date.now() < fbTokenCache.exp) return fbTokenCache.token;\n  const t = await relayToken(relayDir).catch(() => \"\");\n  if (t) fbTokenCache = { token: t, exp: Date.now() + 100 * 60 * 1000 };\n  else fbTokenCache = { token: \"\", exp: 0 };\n  return t;\n}\n/**\n * 把「请求路径后缀」安全地拼到上游基址上（2026-09-27 安全审计 S4-C0）。\n *\n * ⚠️ 为什么不能只 `new URL(suffix, base)`：`suffix` 来自**请求路径**，而\n *    `new URL(\"//evil.com/x\", base)` 是**协议相对 URL** —— origin 直接跳到 evil.com。\n *    实测逃逸形态是**三斜杠**：请求 `/dsh-remote/feedback///evil.com/collect`，\n *    路由前缀匹配通过（pathname 原样保留三斜杠），旧代码只 `replace(/^\\//,\"\")` 剥掉一个，\n *    于是剩下 `//evil.com/collect` → 解析成 `https://evil.com/collect`，\n *    而 proxyFeedback 会**自动带上本机账号 JWT + 真实手机号 + device_id** ——\n *    攻击者凭这个 JWT 就能签发设备访问密钥、配对到自己手机上 = 用户电脑被完整接管。\n *    两斜杠/`%2f`/`..` 都被限制在中继域内，**唯独三斜杠会逃逸**。\n *\n * 两道断言（不是二选一，缺一不可）：\n *   ① origin 必须与基址一致 → 挡住协议相对/绝对 URL 逃逸；\n *   ② pathname 必须以基址路径为前缀 → 挡住 `..` 逃出基址路径（如 /relay-api/ → /api/）。\n * 任何一条不过就抛，调用方按 4xx/5xx 处理，**绝不在这种情况下把凭据发出去**。\n */\nexport function safeUpstreamUrl(base, suffix) {\n  const b = new URL(base);\n  const u = new URL(String(suffix == null ? \"\" : suffix).replace(/^\\/+/, \"\"), b);\n  if (u.origin !== b.origin) throw new Error(`上游地址逃逸(origin): ${u.origin} ≠ ${b.origin}`);\n  const prefix = b.pathname.endsWith(\"/\") ? b.pathname : `${b.pathname}/`;\n  if (!u.pathname.startsWith(prefix)) throw new Error(`上游路径逃逸(path): ${u.pathname} 不在 ${prefix} 之下`);\n  return u;\n}\n\nasync function proxyFeedback(relayDir, req, res, pathname) {\n  const cfg = loadConfig(relayDir);\n  const api = feedbackApiOf(cfg);\n  const suffix = pathname.replace(/^\\/dsh-remote\\/feedback/, \"\") || \"/\";\n  // 相对路径解析：保留基址的路径前缀（如 /relay-api），避免 new URL 绝对路径吞掉 base path。\n  // 必须走 safeUpstreamUrl：拼错的/恶意的后缀会带着账号 JWT 跑到别的域去（S4-C0）。\n  const base = api.endsWith(\"/\") ? api : `${api}/`;\n  let url;\n  try {\n    url = safeUpstreamUrl(base, suffix);\n  } catch (e) {\n    return sendJson(res, 400, { ok: false, error: `非法的反馈接口路径: ${e.message}` });\n  }\n  const headers = {\n    \"x-dsh-device\": cfg.device_id || \"\",\n    \"x-dsh-client\": `dsh-remote-web/${PLUGIN_VERSION}`,\n    // 真实 UA 必须**转发**：以前不转发，上游 fetch 就用 undici 默认 UA（`node`），\n    // 后台「机型」列对每条真实反馈都显示同一个没用值（生产实测 fb_* 全是 user_agent=node），\n    // 于是「Windows 还是 Linux 出的问题」只能靠翻安装日志考古。同时补一个结构化平台字段\n    // （x-dsh-platform），比让后台解析 UA 可靠得多。\n    \"user-agent\": String(req.headers[\"user-agent\"] || `dsh-remote-web/${PLUGIN_VERSION}`),\n    \"x-dsh-platform\": process.platform,\n  };\n  if (cfg.phone) headers[\"x-dsh-phone\"] = String(cfg.phone);\n  const auth = req.headers.authorization;\n  if (auth && /^Bearer\\s+/i.test(auth)) {\n    headers.authorization = auth;\n  } else if (cfg.local_key || (cfg.phone && cfg.password)) {\n    // 登录态统一免验证码：节点半自动附加账号 JWT（服务端对有效 JWT 免验证码）\n    const t = await feedbackAuthToken(relayDir);\n    if (t) headers.authorization = `Bearer ${t}`;\n  }\n  const method = req.method || \"GET\";\n  const init = { method, headers };\n  if (method !== \"GET\" && method !== \"HEAD\") {\n    let buf;\n    try {\n      buf = await readBodyBuffer(req);\n    } catch (e) {\n      return sendJson(res, e.status || 413, { ok: false, error: \"请求体过大\" });\n    }\n    if (buf.length) {\n      const ct = req.headers[\"content-type\"] || \"application/json\";\n      init.body = buf;\n      headers[\"content-type\"] = ct;\n    }\n  }\n  try {\n    const r = await fetch(url, { ...init, signal: AbortSignal.timeout(8000) });\n    // 401（token 失效）→ 清缓存，下次请求自动刷新\n    if (r.status === 401) fbTokenCache = { token: \"\", exp: 0 };\n    const text = await r.text();\n    let body = null;\n    try {\n      body = JSON.parse(text);\n    } catch {\n      body = text;\n    }\n    res.writeHead(r.status, { \"content-type\": r.headers.get(\"content-type\") || \"application/json; charset=utf-8\", \"cache-control\": \"no-store\" });\n    res.end(text);\n    return body;\n  } catch (e) {\n    return sendJson(res, 502, { ok: false, error: `反馈服务不可达: ${e.message}`, hint: \"请确认反馈服务已启动，或检查 .dsh-config.json 的 feedback_url\" });\n  }\n}\n\n/**\n * 把 `/dsh-remote/announcements*` 代理到云端公告 API（契约冻结见\n * 服务端公告契约文档（冻结 v1） §3）：\n *   · GET  /dsh-remote/announcements       → 上游 GET  {api}/api/announcements?client=desktop[&install_id=…]\n *   · POST /dsh-remote/announcements/click → 上游 POST {api}/api/announcements/click  {id[, install_id]}\n *\n * 三条刻意的设计（都是\"服务端契约之外\"的客户端纪律，写在这里免得后人\"顺手优化\"掉）：\n *\n * ① **身份维度二选一，绝不混用**：能拿到账号 JWT 就只带 `Authorization: Bearer`（服务端按 user 维度去重，\n *    同一个人手机看过电脑就不再弹）；拿不到才退回 `install_id`（装机维度）。\n *    两者**同时**带上会让唯一索引 (announcement_id, user_id, install_id) 把\"同一人两台机器\"\n *    算成两行 —— UV 直接翻倍。所以下面是有 Bearer 就不带 install_id，反之亦然。\n * ② **install_id 复用本机既有的 device_id，绝不新造 ID**：服务端那个维度就是\"这台电脑\"，\n *    再生成一个 ID 只会让同一台机器在统计里变成两台（且新 ID 与反馈/设备列表的约定对不上）。\n *    注意 `cfg.device_id` 是**本机设备标识**，与遥测的 `.telemetry-install-id` 不是一回事：\n *    后者在 DSH_REMOTE_TELEMETRY=0 时根本不生成，公告不该被遥测开关牵连。\n * ③ **失败一律软着陆**：上游 404（老服务端）/ 不可达 / 超时都只回一个 JSON，**绝不抛**。\n *    浏览器半对这一切的既定反应是 fail closed（不显示入口、不弹窗），所以这里透传状态码即可，\n *    既不用把它改写成 200（那会让\"接口通不通\"这件事查不出来），也不会把面板打挂。\n */\nasync function proxyAnnouncements(relayDir, req, res, pathname) {\n  const method = String(req.method || \"GET\").toUpperCase();\n  try {\n    const cfg = loadConfig(relayDir);\n    const api = String(cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n    const suffix = pathname.replace(/^\\/dsh-remote\\/announcements/, \"\") || \"/\";\n    const isClick = method === \"POST\" && suffix === \"/click\";\n    // 未知子路径：老/新浏览器半都可能拼错，直接 404（不抛、不代理到奇怪的上游路径）\n    if (!(isClick || (method === \"GET\" && (suffix === \"/\" || suffix === \"\")))) {\n      return sendJson(res, 404, { ok: false, error: \"unknown announcements route\" });\n    }\n\n    const headers = { \"x-dsh-client\": `dsh-remote-web/${PLUGIN_VERSION}` };\n    // 浏览器已带的 Bearer 优先透传（与 proxyFeedback 同约定：那是请求方自己的身份）；\n    // 否则由 node 半附当前账号 JWT —— 只有\"确实配了账号\"才值得为此跑一次 device-login。\n    const auth = req.headers.authorization;\n    let bearer = \"\";\n    if (auth && /^Bearer\\s+/i.test(auth)) bearer = String(auth);\n    else if (cfg.local_key || (cfg.phone && cfg.password)) {\n      const t = await feedbackAuthToken(relayDir).catch(() => \"\");\n      if (t) bearer = `Bearer ${t}`;\n    }\n    if (bearer) headers.authorization = bearer;\n\n    let url;\n    let init = { method, headers };\n    if (isClick) {\n      url = `${api}/api/announcements/click`;\n      let payload = {};\n      try {\n        const buf = await readBodyBuffer(req);\n        const parsed = JSON.parse(buf.toString(\"utf8\") || \"{}\");\n        if (parsed && typeof parsed === \"object\") payload = parsed;\n      } catch { payload = {}; }   // 请求体读不到/不是 JSON → 上游按无 id 处理（404），不在这里抛\n      // 无账号维度时补 install_id，保证点击也能记到\"这台电脑\"名下（有 Bearer 时**不补**，见上面 ① ）\n      if (!bearer) {\n        const installId = String(cfg.device_id || \"\").trim();\n        if (installId && !payload.install_id) payload.install_id = installId;\n      }\n      init = { ...init, headers: { ...headers, \"content-type\": \"application/json\" }, body: JSON.stringify(payload) };\n    } else {\n      url = `${api}/api/announcements?client=desktop`;\n      if (!bearer) {\n        const installId = String(cfg.device_id || \"\").trim();\n        if (installId) url += `&install_id=${encodeURIComponent(installId)}`;\n      }\n    }\n\n    const r = await fetch(url, { ...init, signal: AbortSignal.timeout(8000) });\n    if (r.status === 401) fbTokenCache = { token: \"\", exp: 0 };   // token 失效 → 下次请求重取\n    const text = await r.text();\n    res.writeHead(r.status, {\n      \"content-type\": r.headers.get(\"content-type\") || \"application/json; charset=utf-8\",\n      \"cache-control\": \"no-store\",\n    });\n    res.end(text);\n  } catch (e) {\n    // 网络不可达 / 超时 / JSON 异常：一律 502 + 人话，绝不把异常抛回 webServer（那会变成 500 堆栈）\n    return sendJson(res, 502, { ok: false, error: `公告服务不可达: ${fetchFailReason(e)}` });\n  }\n}\n\n// ---------- 🎉 企微交流群引导代理（实际使用满 2 小时弹一次；2026-10-23 业主需求） ----------\n/**\n * 桌面端插件面板的「加入企业微信群」引导数据来自企业端**用户级**接口：\n *   GET  /api/community-invite/status → { ok, show, reason, used_seconds, required_seconds, qr_url }\n *   POST /api/community-invite/shown  → { ok:true }（幂等）\n * 浏览器半没有企业端用户 token（它跑在 dsh web 同源页里，只认本机 node 半的路由），\n * 所以由 node 半用 **device-login token** 代调（企业端 device token 的 sub 就是 user，\n * 与 /api/me、/api/mobile-sessions 走的是同一条身份链）。\n *\n * 三条纪律：\n * ① **不透传浏览器带来的 Authorization**：这是纯用户级接口，身份只应该是\"本机登录账号\"。\n *    面板浏览器手里没有任何企业端用户 token，透传只会让\"谁的身份\"变得含混\n *    （与 announcements 的 user/install 二选一不同，那个接口两种维度都合法）。\n * ② **判定与记账全在服务端**：show=false（未满 2h / 已弹过 / 后台没配二维码）原样透传，\n *    前端绝不自己算时长；`shown` 幂等，展示时与关闭时各调一次是安全超集。\n * ③ **失败一律软着陆**：未登录/自建（没有企业端账号体系）→ 200 + ok:false + reason\n *    （面板静默、不弹不报错）；上游 4xx/5xx → 透传状态码 + 可读 error（排障能看见，\n *    面板依旧静默）；网络不可达 → 502 JSON，绝不抛回 webServer。\n */\nasync function proxyCommunityInvite(relayDir, req, res, pathname) {\n  const method = String(req.method || \"GET\").toUpperCase();\n  const suffix = pathname.replace(/^\\/dsh-remote\\/community-invite/, \"\") || \"/\";\n  const isStatus = method === \"GET\" && suffix === \"/status\";\n  const isShown = method === \"POST\" && suffix === \"/shown\";\n  if (!isStatus && !isShown) {\n    return sendJson(res, 404, { ok: false, show: false, reason: \"unknown_route\", error: \"unknown community-invite route\" });\n  }\n  const cfg = loadConfig(relayDir);\n  // 自建部署：没有企业端账号体系，交流群引导不适用 —— 不发请求、也不让面板弹\n  if (cfg.local_key) return sendJson(res, 200, { ok: false, show: false, reason: \"local_mode\" });\n  // 没配账号：面板登录前也可能误调 —— 静默拒绝（前端本来就只在 loggedIn 后调）\n  if (!(cfg.phone && cfg.password)) return sendJson(res, 200, { ok: false, show: false, reason: \"not_logged_in\" });\n  const token = await relayToken(relayDir).catch(() => \"\");\n  if (!token) return sendJson(res, 200, { ok: false, show: false, reason: \"not_logged_in\" });\n\n  const upstreamPath = isShown ? \"/api/community-invite/shown\" : \"/api/community-invite/status\";\n  const init = { method: isShown ? \"POST\" : \"GET\", headers: { authorization: `Bearer ${token}` } };\n  if (isShown) {\n    init.headers[\"content-type\"] = \"application/json\";\n    init.body = \"{}\";\n  }\n  const r = await relayFetch(relayDir, upstreamPath, init);\n  const d = flattenRelayBody(r);\n  if (!r.ok) {\n    // 透传状态码 + 可读错误：面板仍然静默（它只看 ok/show），但排障时能直接看到 401/404/500\n    return sendJson(res, (r && r.status) || 502, {\n      ok: false,\n      show: false,\n      reason: isShown ? \"report_failed\" : \"status_failed\",\n      error: relayErrorMessage(r),\n      relayStatus: (r && r.status) || 0\n    });\n  }\n  if (isShown) {\n    // 幂等上报：不关心上游回什么（只认 ok:false 才报失败），面板两个按钮都会调\n    return sendJson(res, 200, { ok: d.ok !== false, relayStatus: r.status || 200 });\n  }\n  // status：只挑面板需要的字段（不整包透传，避免把内部字段带进浏览器；字段容错见契约）\n  // qr_url 归一化：企业端后台配的可能是站内相对路径（如 /qr/group-qr.png），\n  // 与 /dsh-remote/community 同一约定拼成**企业端绝对地址**再下发 —— 面板跑在 dsh web 源上，\n  // 相对路径会被浏览器解析到 127.0.0.1，图片必然挂。其它协议（data:/javascript:/协议相对）一律丢弃，\n  // 前端按\"二维码不可用\"降级（保留文案与按钮）。\n  const apiBase = String(cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n  const rawQr = typeof d.qr_url === \"string\" ? d.qr_url.trim() : \"\";\n  let qrUrl = \"\";\n  if (/^https?:\\/\\//i.test(rawQr)) qrUrl = rawQr;\n  else if (rawQr.charAt(0) === \"/\" && rawQr.charAt(1) !== \"/\") qrUrl = apiBase + rawQr;\n  return sendJson(res, 200, {\n    ok: d.ok !== false,\n    show: d.show === true, // fail closed：非严格 true 一律不弹\n    reason: typeof d.reason === \"string\" ? d.reason : \"\",\n    used_seconds: Number(d.used_seconds) || 0,\n    required_seconds: Number(d.required_seconds) || 0,\n    qr_url: qrUrl,\n    relayStatus: r.status || 200\n  });\n}\n\n// ---------- 自管理：版本 / 在线更新 / 彻底卸载（面板内“版本与更新”卡片） ----------\n\n/** 插件 id / 包名（2026-09 由 dsh-remote-ui 更名）。 */\nconst PLUGIN_ID = \"dsh-remote-web\";\n/** 更名前 id（≤0.4.9）：彻底卸载/清理时一并移除，防旧拷贝残留。 */\nconst PLUGIN_LEGACY_IDS = [\"dsh-remote-ui\"];\nconst PLUGIN_ALL_IDS = [PLUGIN_ID, ...PLUGIN_LEGACY_IDS];\n/**\n * 插件自身发布版本 —— **从 package.json 派生,不再手写**(与 dsh-remote 根包同步递增)。\n *\n * 为什么改成派生(2026-09-23):原先这里是硬编码字符串,每次发版要**手改两处**\n * (package.json + 这里),beta.8 就漏改了 —— 装到用户机器上的插件在**装机上报**里\n * 仍然自称 beta.7。而 `x-dsh-client` 头、更新通道判定(含 `-` 即 beta)、面板「插件版本」、\n * 更新检测拿的都是这个值:一处漏改会同时污染装机来源统计与更新判断,\n * 而且**发出去之后改不回来**(npm 同一版本不可覆盖)。\n *\n * 测试本来就会红(它拿 package.json 与上报值对账 —— 这次正是它抓住的),\n * 但让两份数据**只有一个来源**才是根治。\n * 读不到时退回 `0.0.0-unknown`:让异常**显式可见**,绝不悄悄冒充某个真实版本。\n */\nconst PLUGIN_VERSION = (() => {\n  try {\n    const pkg = JSON.parse(readFileSync(new URL(\"../package.json\", import.meta.url), \"utf8\"));\n    return String(pkg && pkg.version ? pkg.version : \"\") || \"0.0.0-unknown\";\n  } catch {\n    return \"0.0.0-unknown\";\n  }\n})();\nconst UPDATE_LOG = \".dsh-update.log\";\nconst UPDATE_MARKER = \".dsh-update-running\";\n\n/**\n * 更新通道（发布策略）：普通用户只拉稳定 dist-tag `latest`；预发(alpha/beta)由作者/内测\n * 通过 `DSH_UPDATE_TAG=beta`（或显式版本号）拉取。迭代一律先发 beta/alpha，稳定后才升 latest。\n */\n/**\n * 「无输出看门狗」——更新与补装共用（0.6.9）。\n *\n * 0.6.8 诊断报告的核心结论：旧的三套卡死治理（sweepStaleMarkers / runOnlineUpdate 的陈旧判定 /\n * 镜像回退）**判据全选错了** —— 它们问的是\"标记还在不在 / 进程还活不活\"，没有一套在问\n * \"它还在不在往前推进\"。而中国网络访问 registry.npmjs.org 的**典型**失败形态恰恰是**挂起**\n * （TCP 连得上、传输不动）：进程活着、标记是新的、却永远不产出任何事件（没有 exit、没有新日志）。\n * 于是镜像回退只在\"快速失败\"这一种形态下生效，最常见的那种零覆盖 ——\n * 用户看到的是永久「更新中 / 正在安装」，而装机数就是不涨。\n *\n * 判据换成**日志文件多久没有新增字节**：进度信号是现成的（两条路径本来就把子进程输出写进日志），\n * 而且用 mtime 判定在**宿主重启后依然有效**（内存里的看门狗做不到这点）。\n * 超时 → 判定卡住 → 结束该子进程 → 走与 exit≠0 **完全相同**的回退路径。\n * 阈值可用 DSH_UPDATE_IDLE_MS / DSH_INSTALL_IDLE_MS 覆盖（仅供测试把链路压到亚秒级）。\n */\nfunction stallPollMs() {\n  const n = Number(process.env.DSH_STALL_POLL_MS);\n  return Number.isFinite(n) && n > 0 ? n : 2000;\n}\n/** 无输出多久判定卡住；默认 120s（给慢链路留余量，又不让用户干等到天荒地老）。 */\nfunction stallIdleMs(kind) {\n  const env = kind === \"update\" ? process.env.DSH_UPDATE_IDLE_MS : process.env.DSH_INSTALL_IDLE_MS;\n  const n = Number(env);\n  return Number.isFinite(n) && n > 0 ? n : 120_000;\n}\n\n/** 日志文件自 `since` 以来多久没变化（毫秒）。取不到文件时退化为\"距 since 的时长\"。 */\nfunction progressIdleMs(relayDir, logName, since) {\n  try {\n    return Date.now() - statSync(join(relayDir, logName)).mtimeMs;\n  } catch {\n    return Date.now() - (Number(since) || Date.now());\n  }\n}\n\n/** 进度看板：key → { startedAt, lastProgressAt, lastSize, stalled, kind, timer }（供面板读\"已用时/是否卡住\"）。 */\nconst progressWatch = new Map();\n\n/**\n * 给一个后台子进程装上无输出看门狗。\n * @param {string} key 唯一键（'update' / 'install:<relayDir>'）\n * @param {{relayDir:string, logName:string, getChild:()=>any, onStall?:(idleMs:number)=>void, kind:\"update\"|\"install\"}} opts\n */\nfunction startProgressWatch(key, opts) {\n  stopProgressWatch(key);\n  const { relayDir, logName, getChild, onStall, kind } = opts;\n  const logFile = join(relayDir, logName);\n  const st = { startedAt: Date.now(), lastProgressAt: Date.now(), lastSize: -1, stalled: false, kind, timer: null };\n  progressWatch.set(key, st);\n  const timer = setInterval(() => {\n    let size = -1;\n    try { size = statSync(logFile).size; } catch { size = -1; } // 文件还没有 = 也没有任何输出\n    if (size !== st.lastSize) { st.lastSize = size; st.lastProgressAt = Date.now(); return; } // 有新增输出 = 在推进\n    const idle = Date.now() - st.lastProgressAt;\n    if (idle < stallIdleMs(kind)) return;\n    st.stalled = true;\n    clearInterval(timer);\n    timer.unref?.();\n    // ① 先结束子进程：它会触发 'exit'，从而走与\"退出码非 0\"完全相同的回退/报错路径\n    try { getChild()?.kill(); } catch { /* 已退出 */ }\n    // ② 再通知调用方记日志（顺序固定：kill 是必须发生的动作，日志是告知）\n    try { onStall?.(idle); } catch { /* 回调出错不得影响关闭 */ }\n  }, stallPollMs());\n  timer.unref?.();\n  st.timer = timer;\n  return st;\n}\n\nfunction stopProgressWatch(key) {\n  const st = progressWatch.get(key);\n  if (st?.timer) clearInterval(st.timer);\n  progressWatch.delete(key);\n}\n\n/** 供面板/诊断读取的进度信息（没有进行中的任务时返回 null）。 */\nfunction progressInfoOf(key) {\n  const st = progressWatch.get(key);\n  if (!st) return null;\n  const now = Date.now();\n  return {\n    elapsedMs: now - st.startedAt,\n    idleMs: now - st.lastProgressAt,\n    stalled: Boolean(st.stalled),\n    idleThresholdMs: stallIdleMs(st.kind),\n  };\n}\n\n/**\n * 结束\"标记里记着、但已经不推进\"的子进程。\n * 诊断报告 P2：挂死的子进程**从不被结束**（`child.kill()` 在插件半全文无匹配，标记里的 pid\n * 只被用来\"判活\"、从未被用来\"结束\"）→ 用户重试几次就在机器上堆几个挂死的 node 进程，无人回收。\n * 判据同样不能用 pidAlive（挂起的进程是\"活\"的），要结合\"日志多久没变化\"。\n */\nfunction killStalledChild(relayDir, logName, info, kind, why) {\n  const pid = Number(info && info.pid);\n  if (!Number.isInteger(pid) || pid <= 0) return false;\n  if (pidAlive(pid) !== true) return false;                     // 已经死了：交给标记清理逻辑\n  const idle = progressIdleMs(relayDir, logName, info && info.at);\n  if (idle < stallIdleMs(kind)) return false;                   // 还在推进：不碰它\n  const ok = killPid(pid, \"SIGKILL\");                            // Windows 上走 taskkill /T /F\n  appendLogLine(relayDir, AUTO_INSTALL_LOG,\n    `[dsh-remote-web] 结束卡住的${kind === \"update\" ? \"更新\" : \"运行环境安装\"}进程 pid=${pid}（${why}；已 ${Math.round(idle / 1000)}s 无输出）`);\n  return ok;\n}\n\n/**\n * 更新通道（0.6.9 修：诊断报告 P3「通道默认值不自洽」）。\n * 原实现无条件拉 `latest`：**预发版装机的用户在面板点「一键更新」= 降级或什么都不做**，\n * 而面板既不显示当前通道、也不沿用当前通道 —— 作者/内测用户点出一个方向相反的操作且无从判断。\n * 现在：显式设置优先（DSH_UPDATE_TAG，用于主动切通道），否则**沿用装机通道**\n * （当前是预发版 → beta；正式版 → latest）。\n */\nfunction updateChannel() {\n  const explicit = String(process.env.DSH_UPDATE_TAG || \"\").trim().replace(/^@/, \"\");\n  if (explicit) return explicit;\n  return /-/.test(String(PLUGIN_VERSION || \"\")) ? \"beta\" : \"latest\";\n}\nconst UPDATE_TAG = updateChannel();\nconst UPDATE_SPEC = `@mrrisega/dsh-remote@${UPDATE_TAG}`;\n/** 看门狗在 progressWatch 里的键（更新只有一个，用常量；补装按 relayDir 区分）。 */\nconst UPDATE_WATCH_KEY = \"update\";\n/**\n * 被用户取消的更新（按 relayDir）。\n * 为什么需要：取消会 kill 子进程 → 触发 'exit' → 那里的\"换源重试\"逻辑会**立刻重新 spawn**，\n * 把标记写回来，用户看到的是\"点了取消还在更新\"。这个集合就是给重试链装的总闸。\n */\nconst updateCancelledDirs = new Set();\n\n/** 抓一次 npm dist-tags（官方源优先，失败回退 npmmirror；纯服务端无 CORS 限制）。 */\nasync function fetchDistTags() {\n  for (const reg of [\"https://registry.npmjs.org/@mrrisega/dsh-remote\", \"https://registry.npmmirror.com/@mrrisega/dsh-remote\"]) {\n    try {\n      const res = await fetch(reg, { signal: AbortSignal.timeout(8000) });\n      if (!res.ok) continue;\n      const j = await res.json();\n      const tags = j && j[\"dist-tags\"] ? j[\"dist-tags\"] : {};\n      if (Object.keys(tags).length) return tags;\n    } catch { /* 试下一个源 */ }\n  }\n  return {};\n}\n\n/** 在「当前通道」与 latest 之间取更高者（**更新与\"检查更新\"必须用同一约定**，否则面板会说\"已是最新\"而更新却装新版）。 */\nfunction pickBestTag(tags) {\n  const t = tags || {};\n  const channelVer = typeof t[UPDATE_TAG] === \"string\" ? t[UPDATE_TAG] : \"\";\n  const latestVer = typeof t.latest === \"string\" ? t.latest : \"\";\n  if (!latestVer) return { tag: UPDATE_TAG, version: channelVer, why: \"线上没有 latest 通道信息\" };\n  if (!channelVer) return { tag: \"latest\", version: latestVer, why: \"当前通道无对应版本，改用 latest\" };\n  const cmp = compareVersions(latestVer, channelVer);\n  if (cmp !== null && cmp > 0) {\n    return { tag: \"latest\", version: latestVer, why: `latest(${latestVer}) 高于当前通道 ${UPDATE_TAG}(${channelVer})` };\n  }\n  return { tag: UPDATE_TAG, version: channelVer, why: `当前通道 ${UPDATE_TAG}(${channelVer}) 不低于 latest(${latestVer})` };\n}\n\n/** 查询\"对我而言\"的最新版本号（约定同 pickBestTag）。 */\nasync function npmLatestVersion() {\n  return pickBestTag(await fetchDistTags()).version;\n}\n\n/**\n * 决定本次更新**真正该装的 tag**：在「当前通道」与 `latest` 之间**取更高者**。\n *\n * 为什么不无条件跟随通道（诊断报告 P3 的另一半）：开发期内 beta 领先（跟随 beta 是对的），\n * 但**正式版一旦发布，latest 就反超**；此时死跟 beta 会让内测用户卡在一个旧 beta 上，\n * 点「一键更新」什么都不发生 —— 那正是报告里说的\"方向相反的操作\"。\n * 取更高者同时满足两种情况：既不会把 beta 装机降级到稳定版，也不会让它错过已发布的稳定版。\n * 取不到 tag（断网/超时）时保守回退到当前通道，绝不因此阻断更新。\n * @returns {{tag:string, version:string, why:string}}\n */\nasync function resolveUpdateTarget() {\n  try {\n    return pickBestTag(await fetchDistTags());\n  } catch {\n    return { tag: UPDATE_TAG, version: \"\", why: \"无法读取 npm 通道信息，按当前通道执行\" };\n  }\n}\n\n/**\n * 语义化版本比较（只处理本仓库用到的形态：`X.Y.Z` 与 `X.Y.Z-<pre>.<n>`）。\n * 为什么需要它：面板判断\"有没有新版本\"不能只用 `latest !== current` ——\n * 预设版之间（beta.10 → beta.11）无法比较大小，而且预设版在 semver 里**低于**同号正式版\n * （0.6.4 < 0.6.4），朴素不等判断会把\"已经装了预设版\"误判成落后。\n * @returns {number} a>b → 1；a<b → -1；相等 → 0\n */\nfunction compareVersions(a, b) {\n  const parse = (v) => {\n    const m = /^(\\d+)\\.(\\d+)\\.(\\d+)(?:-([0-9A-Za-z.-]+))?/.exec(String(v || \"\").trim());\n    if (!m) return null;\n    return { nums: [Number(m[1]), Number(m[2]), Number(m[3])], pre: m[4] ? m[4].split(\".\") : null };\n  };\n  const x = parse(a);\n  const y = parse(b);\n  if (!x || !y) return null; // 无法解析 → 交给调用方保守处理\n  for (let i = 0; i < 3; i += 1) {\n    if (x.nums[i] !== y.nums[i]) return x.nums[i] > y.nums[i] ? 1 : -1;\n  }\n  if (!x.pre && !y.pre) return 0;\n  if (!x.pre) return 1;   // 有预设版 < 无预设版（semver §11）\n  if (!y.pre) return -1;\n  const len = Math.max(x.pre.length, y.pre.length);\n  for (let i = 0; i < len; i += 1) {\n    const p1 = x.pre[i];\n    const p2 = y.pre[i];\n    if (p1 === undefined) return -1;\n    if (p2 === undefined) return 1;\n    const n1 = /^\\d+$/.test(p1) ? Number(p1) : null;\n    const n2 = /^\\d+$/.test(p2) ? Number(p2) : null;\n    if (n1 !== null && n2 !== null) { if (n1 !== n2) return n1 > n2 ? 1 : -1; continue; }\n    if (n1 !== null) return -1; // 数字标识符 < 字母标识符\n    if (n2 !== null) return 1;\n    if (p1 !== p2) return p1 > p2 ? 1 : -1;\n  }\n  return 0;\n}\n\n/**\n * 最近一次在线更新的失败信息（内存态，TTL 10 分钟）。\n *\n * 为什么需要它：此前\"一键更新/一键修复\"点了没反应 —— spawn 是异步的，npx 解析失败时\n * 同步分支仍然返回 `{ok:true}`，而错误只写进 `.dsh-update.log`；前端看到 ok:true 就显示\n * 「更新已开始」，2 秒后轮询到 marker 被清（running:false）便显示「已更新完成」——\n * 版本没变、运行环境仍缺失，界面上没有任何失败提示（用户实测：点了没反应）。\n * 现在失败原因进内存态并可查询，前端在\"没成功\"时能如实报错。\n */\nconst updateFailures = new Map(); // relayDir → { at, detail, failCode }\nconst UPDATE_FAILURE_TTL_MS = 10 * 60 * 1000;\n\nfunction noteUpdateFailure(relayDir, detail, failCode) {\n  updateFailures.set(String(relayDir), { at: Date.now(), detail: String(detail || \"未知原因\"), failCode: failCode || \"unknown\" });\n}\n\nfunction recentUpdateFailure(relayDir) {\n  const rec = updateFailures.get(String(relayDir));\n  if (!rec) return null;\n  if (Date.now() - rec.at > UPDATE_FAILURE_TTL_MS) { updateFailures.delete(String(relayDir)); return null; }\n  return rec;\n}\n\n/** 以 detached 子进程执行 `npx --yes <UPDATE_SPEC>`（env 可覆盖 npm 源/更新通道）。\n * @returns {{child, error}} 由 safeSpawn 返回——永远挂了 'error' 监听，启动失败不会打挂宿主。\n */\nfunction spawnUpdater(relayDir, extraEnv, onError, spec = UPDATE_SPEC) {\n  const log = join(relayDir, UPDATE_LOG);\n  const npx = npxInvocation();\n  return safeSpawn(npx.command, [...npx.args, \"--yes\", spec], {\n    detached: true,\n    cwd: homedir(),\n    // Windows 上跑 npx.cmd 必须经 shell（Node ≥20.12 起否则 EINVAL）；走 node+npx-cli.js 时不需要。\n    shell: npx.shell,\n    windowsHide: true, // Windows：不弹控制台窗口（POSIX 上该选项被忽略）\n    // PATH 补 node 目录：App 最小 PATH 下也能跑 npx；同时保持本机既有的安装来源约定\n    // （在线更新会重跑安装器并重写 plist，若不带来源就会把 plugin_market 误记成 npx）。\n    env: spawnEnv({\n      DSH_BRIDGE_INSTALL_SOURCE: installSourceOf(relayDir),\n      // 安装器会把这些环境变量原样写进 plist/systemd 单元，所以宿主版本也要一起给它 ——\n      // 否则安装器重启桥之后，新写的自启动项里就没有 harness 版本了。\n      DSH_BRIDGE_INSTALL_VERSION: PLUGIN_VERSION,\n      DSH_BRIDGE_HARNESS_VERSION: harnessVersion(),\n      ...(extraEnv || {}),\n    }),\n    stdio: [\"ignore\", openSync(log, \"a\"), openSync(log, \"a\")],\n    onError,\n  });\n}\n\n/* ── C8：升级/更新「覆盖运行时之前停旧进程 + 装完按命令行清残留」───────────────────\n *\n * 为什么必须停（诊断报告 04 §五 R1）：安装器的 ensureRuntimeCopy() 会把 clients/ 与\n * node_modules/ws **覆盖式**拷进运行时目录，而旧 watcher/bridge 正在用这些文件跑。\n * Windows 上杀软持有句柄 → 覆盖写失败 → 半装 → bridge `ERR_MODULE_NOT_FOUND: Cannot find\n * package 'ws'`；同时旧 bridge 成孤儿、与新起的一份同 deviceId 互踢。\n *\n * 安全纪律（这套代码在**开发者的真机上**被测试执行，误杀/误停是不可接受的）：\n *   · 只停「命令行里带**本 relayDir** 路径」的进程 —— 别的配置目录、别的用户的 bridge 一律不碰；\n *   · 取不到命令行（ps/PowerShell 不可用）→ 不停（漏停由安装器自己接管处理，方向选安全侧）；\n *   · 走 stopBridgeDetached/manualStatus 那条路（pid 文件 + 命令行扫描），**不碰 launchd/systemd**\n *     —— 服务本身由安装器收尾时重写并重启，插件这一侧只负责\"别让旧代码继续跑\"。\n */\n\n/** 该 pid 的完整命令行（Windows 复用带 TTL 缓存的 PowerShell 扫描；取不到返回空串）。 */\nfunction commandLineOfPid(pid) {\n  if (!Number.isInteger(pid) || pid <= 0) return \"\";\n  if (isWindows()) {\n    // 2026-10-29：改走「无镜像名过滤」的全量扫描（旧的 Name='node.exe' 过滤看不到 Electron 宿主的进程）。\n    const hit = windowsProcessScan().procs.find((p) => p.pid === pid);\n    return hit ? String(hit.commandLine || \"\") : \"\";\n  }\n  const r = sh(`ps -p ${pid} -o command=`);\n  return r.ok ? String(r.stdout || \"\").trim() : \"\";\n}\n\n/** 这个 pid 是否真的在跑**本 relayDir** 里的脚本（命令行校验；取不到 → false）。 */\nfunction pidRunsFrom(pid, relayDir) {\n  const cmd = commandLineOfPid(pid);\n  if (!cmd) return false; // 看不清就不动：误杀无关进程的代价远高于漏停\n  const norm = (v) => String(v).replace(/\\\\/g, \"/\").toLowerCase();\n  return norm(cmd).includes(norm(relayDir));\n}\n\n/** 收集本 relayDir 这套运行时的 watcher/bridge pid（pid 文件 + 命令行扫描）。 */\nfunction collectRuntimePids(relayDir) {\n  const pids = new Set();\n  for (const name of [WATCHER_PID_FILE, BRIDGE_PID_FILE]) {\n    const pid = readPidFile(relayDir, name);\n    if (Number.isInteger(pid) && pid > 0 && pid !== process.pid) pids.add(pid);\n  }\n  const ms = manualStatus(relayDir) || {};\n  for (const pid of [...(ms.watcher || []), ...(ms.bridge || []), ...(ms.allBridge || [])]) {\n    if (Number.isInteger(pid) && pid > 0 && pid !== process.pid) pids.add(pid);\n  }\n  return [...pids];\n}\n\n/**\n * 覆盖运行时之前停掉本 relayDir 的旧 watcher/bridge（幂等）。\n * @returns {{skipped: boolean, pids: number[]}}\n */\nfunction stopBridgeForRuntimeReplace(relayDir) {\n  if (skipsSystemOps()) return { skipped: true, pids: [] };\n  const pids = collectRuntimePids(relayDir).filter((pid) => pidAlive(pid) !== false && pidRunsFrom(pid, relayDir));\n  for (const pid of pids) killPid(pid, \"SIGKILL\"); // Windows 上是 taskkill /T /F：连带子进程\n  // 2026-10-29：pid 文件只在「已确认结束」或「已确认不是我们的进程」时才删；\n  // 取不到命令行且进程仍活着的条目保持现场（宁可留残留文件，也不制造「进程在、文件没了」的假象）。\n  for (const name of [WATCHER_PID_FILE, BRIDGE_PID_FILE]) {\n    const v = pidFileVerdict(relayDir, name);\n    if (!v.pid || !v.alive || v.cmdKnown) removePidFileQuiet(relayDir, name);\n  }\n  return { skipped: false, pids };\n}\n\n/**\n * 装完清残留：只处理**本轮更新前就在跑**的那批 pid，且仍满足命令行校验。\n * 为什么不用\"扫所有本 relayDir 的 bridge\"：npx 安装器的收尾会重启服务并拉起**新的** bridge，\n * 那一个是新代码、必须留下；按\"更新前的 pid 集合\"点名清理才不会误杀新实例。\n * @returns {number[]} 被结束的 pid\n */\nfunction sweepBridgeAfterRuntimeReplace(relayDir, beforePids = []) {\n  if (skipsSystemOps() || !Array.isArray(beforePids) || !beforePids.length) return [];\n  const killed = [];\n  for (const pid of beforePids) {\n    if (pidAlive(pid) === false) continue;\n    if (!pidRunsFrom(pid, relayDir)) continue; // pid 可能已被系统回收 → 必须重新校验命令行\n    if (killPid(pid, \"SIGKILL\")) killed.push(pid);\n  }\n  return killed;\n}\n\n/** 更新失败/取消时把 bridge 恢复起来（否则用户会莫名失去远程访问）。只在本轮真停过进程时执行。 */\nfunction restoreBridgeAfterUpdate(relayDir, stoppedPids = []) {\n  if (skipsSystemOps() || !stoppedPids.length) return null;\n  try {\n    const r = startBridgeDetached(relayDir);\n    return r;\n  } catch { return null; }\n}\n\n/**\n * 后台执行在线一键更新：npx 按 dist-tag(默认 latest)（幂等自愈：补运行环境/更新 bridge/收敛 include）。\n * 稳健性：\n *   - npx 用绝对路径 + PATH 补全解析（App 拉起的 dsh web PATH 最小化时不再 ENOENT 静默失败）；\n *   - 【官方源优先】镜像(npmmirror)滞后时会把旧版(如 0.4.4)当成最新安装，旧 pluginCmd 会把\n *     已被移除的“用户 include”重新写回 profile → dsh web 重启重复 ID 崩溃。故先试官方源，\n *     失败(国内网络)才回退用户默认镜像源；\n *   - marker 记录 pid，子进程退出/出错即清理；宿主重启后由 sweepStaleMarkers 立即清掉死进程残留。\n */\nasync function runOnlineUpdate(relayDir) {\n  /** C8：本轮更新前停掉的旧进程 pid（失败时要恢复；成功时要清残留）。 */\n  let stopInfo = { skipped: true, pids: [] };\n  try {\n    mkdirSync(relayDir, { recursive: true });\n    const marker = join(relayDir, UPDATE_MARKER);\n    if (existsSync(marker)) {\n      // 残留 marker（进程被强杀/上次异常退出）会让点击**永久**被拒，前端还会把它当成\n      // \"正在跟踪进度\"而只转圈不报错。超过 10 分钟一律视为陈旧并清理。\n      let stale = false;\n      try { stale = Date.now() - statSync(marker).mtimeMs > 10 * 60 * 1000; } catch { /* ignore */ }\n      if (stale) {\n        try { rmSync(marker, { force: true }); } catch { /* ignore */ }\n        appendLogLine(relayDir, UPDATE_LOG, \"[update] 清理超过 10 分钟的陈旧 in-progress 标记\");\n      } else {\n        return { ok: false, detail: \"已有更新在进行中，请稍候（若长时间无进展，最多 10 分钟后可重试）\" };\n      }\n    }\n    updateCancelledDirs.delete(relayDir); // 新一轮开始：清掉上次的取消闸\n    // 【0.6.9】目标 tag 在「当前通道」与 latest 之间取更高者（见 resolveUpdateTarget 注释）：\n    // 既不把内测装机降级到稳定版，也不让它错过已发布的正式版。\n    const target = await resolveUpdateTarget();\n    const spec = `@mrrisega/dsh-remote@${target.tag}`;\n    // 新一轮开始 → 先把上一轮的日志归档（见 rotateUpdateLog 注释：无界增长 + 面板黑框拉回旧尾巴）\n    rotateUpdateLog(relayDir);\n    appendLogLine(relayDir, UPDATE_LOG,\n      `[update] 开始在线更新 ${spec}（通道 ${UPDATE_TAG}；${target.why}）(${new Date().toISOString()})`);\n    telemetryRecord(relayDir, \"update_started\"); // 匿名遥测：在线更新开始\n\n    // C8：**覆盖运行时之前**先停掉本 relayDir 的旧 watcher/bridge（幂等）。\n    // 安装器随后会覆盖写 clients/ 与 node_modules/ws —— 旧进程一边跑一边被覆盖，\n    // Windows 上极易半装（`Cannot find package 'ws'`）并留下孤儿进程新老互踢。\n    stopInfo = stopBridgeForRuntimeReplace(relayDir);\n    appendLogLine(relayDir, UPDATE_LOG, stopInfo.skipped\n      ? \"[update] 测试隔离：跳过「停旧 bridge」（DSH_RELAY_SKIP_SERVICE=1）\"\n      : (stopInfo.pids.length\n        ? `[update] 覆盖运行时前已停旧 bridge/watcher（pid ${stopInfo.pids.join(\", \")}）`\n        : \"[update] 覆盖运行时前检查：本 relayDir 没有旧 bridge/watcher 在跑\"));\n    /** 失败/取消：把刚停掉的 bridge 拉回来（只在本轮真停过进程时执行，避免测试里碰真实服务）。 */\n    const restoreIfStopped = () => {\n      if (!stopInfo.pids.length) return;\n      const r = restoreBridgeAfterUpdate(relayDir, stopInfo.pids);\n      appendLogLine(relayDir, UPDATE_LOG,\n        `[update] 已重新拉起 bridge（${(r && r.status) || \"unknown\"}），远程访问不受影响`);\n    };\n    /** 成功：按\"更新前那批 pid\"点名清残留（保持命令行校验，绝不误杀安装器刚拉起的新实例）。 */\n    const sweepIfSucceeded = () => {\n      const killed = sweepBridgeAfterRuntimeReplace(relayDir, stopInfo.pids);\n      if (killed.length) {\n        appendLogLine(relayDir, UPDATE_LOG, `[update] 装完清残留：已结束旧 bridge 进程（pid ${killed.join(\", \")}）`);\n      }\n    };\n\n    let retried = false;\n    let stalled = false; // 本轮是否因\"长时间无输出\"被判定卡住（决定失败归因与是否回退）\n    const clear = () => {\n      stopProgressWatch(UPDATE_WATCH_KEY);\n      try { rmSync(marker, { force: true }); } catch { /* ignore */ }\n    };\n    // 启动失败（ENOENT/EINVAL…）的收尾：清 marker + 记日志 + 记失败原因（面板可查询）+ 匿名遥测。\n    // 抽出来给「同步失败」与「异步 'error' 事件」共用，保证任何一种失败都不会变成未捕获异常。\n    const failUpdaterSpawn = (e) => {\n      appendLogLine(relayDir, UPDATE_LOG, `[update] 子进程启动失败: ${e.message}`);\n      clear();\n      const fc = telemetryFailCodeFromError(e);\n      noteUpdateFailure(relayDir, e.message, fc); // ← 面板可查询，不再只躺在日志里\n      telemetryRecord(relayDir, \"update_failed\", { fail_code: fc });\n      restoreIfStopped(); // C8：更新没起来 → 把刚停掉的 bridge 拉回来，别让用户失去远程访问\n    };\n    /**\n     * 第三跳：离线通道（0.6.12）。\n     * 为什么必须有：Windows 上 Node ≥20.12 起 `spawn(\"npx.cmd\")` 不带 shell 会抛 EINVAL，\n     * 于是「更新」这条路对老版本机器**彻底失效**（生产遥测：79 台点过更新、79 台全失败）。\n     * 离线通道用 HTTPS 取 tarball + 纯 Node 解包 + 跑包内安装器，不经 npx/npm/shell。\n     */\n    const runOffline = () => {\n      if (updateCancelledDirs.has(relayDir)) { updateCancelledDirs.delete(relayDir); return null; }\n      const helper = join(dirname(fileURLToPath(import.meta.url)), \"offline-update.mjs\");\n      if (!existsSync(helper)) {\n        appendLogLine(relayDir, UPDATE_LOG, \"[update] 离线更新助手缺失（插件包不完整），放弃离线通道\");\n        return null;\n      }\n      appendLogLine(relayDir, UPDATE_LOG,\n        `[update] npx 两次都未成功 → 改用离线通道（tarball + 纯 Node 解包，不经 npx/npm）…`);\n      let out = \"ignore\";\n      try { out = openSync(join(relayDir, UPDATE_LOG), \"a\"); } catch { /* 打不开日志：退化丢弃输出 */ }\n      const holder = { child: null };\n      const { child, error } = safeSpawn(process.execPath, [helper, relayDir, target.tag], {\n        detached: true,\n        env: spawnEnv({\n          DSH_BRIDGE_INSTALL_SOURCE: installSourceOf(relayDir),\n          DSH_BRIDGE_INSTALL_VERSION: PLUGIN_VERSION,\n          DSH_BRIDGE_HARNESS_VERSION: harnessVersion(),\n          npm_config_registry: \"https://registry.npmjs.org\",\n        }),\n        stdio: [\"ignore\", out, out],\n        windowsHide: true,\n        onError: (e) => failUpdaterSpawn(e),\n      });\n      if (typeof out === \"number\") { try { closeSync(out); } catch { /* 子进程已继承 */ } }\n      if (error || !child) return null;\n      holder.child = child;\n      writeMarker(marker, child.pid);\n      startProgressWatch(UPDATE_WATCH_KEY, {\n        relayDir, logName: UPDATE_LOG, kind: \"update\",\n        getChild: () => holder.child,\n        onStall: (idle) => {\n          stalled = true;\n          appendLogLine(relayDir, UPDATE_LOG,\n            `[update] 离线通道也已 ${Math.round(idle / 1000)}s 无输出 → 判定卡住，结束该进程`);\n        },\n      });\n      child.on(\"exit\", (code) => {\n        stopProgressWatch(UPDATE_WATCH_KEY);\n        if (updateCancelledDirs.has(relayDir)) {\n          updateCancelledDirs.delete(relayDir);\n          appendLogLine(relayDir, UPDATE_LOG, \"[update] 已取消：不再重试\");\n          restoreIfStopped(); // C8：取消也要把 bridge 拉回来\n          return;\n        }\n        appendLogLine(relayDir, UPDATE_LOG, `[update] 离线通道退出 code=${code ?? \"?\"}`);\n        clear();\n        if (code !== 0 || stalled) {\n          const tail = readTail(join(relayDir, UPDATE_LOG));\n          const fc = stalled ? \"update_stalled\" : telemetryFailCodeFromText(tail);\n          const lastLine = String(tail || \"\").split(\"\\n\").map((l) => l.trim()).filter(Boolean).slice(-1)[0] || \"\";\n          noteUpdateFailure(relayDir, stalled\n            ? \"离线通道也长时间没有输出（已判定卡住并结束）：请检查本机能否访问 registry.npmjs.org\"\n            : (lastLine || `离线通道退出码 ${code}`), fc);\n          telemetryRecord(relayDir, \"update_failed\", { fail_code: fc });\n          restoreIfStopped(); // C8\n        } else {\n          updateFailures.delete(String(relayDir));\n          sweepIfSucceeded(); // C8：装完清残留（按更新前的 pid 点名 + 命令行复核）\n          // 更新成功 → 落一条「必须重启 dsh web」的强提醒（见 run() 成功分支的同款注释）\n          markUpdateRestartPending(relayDir);\n        }\n      });\n      child.unref();\n      return child;\n    };\n    let offlineTried = false;\n    const run = () => {\n      if (updateCancelledDirs.has(relayDir)) { updateCancelledDirs.delete(relayDir); return null; } // 已取消：不再重试\n      // 第一次：官方 npm 源；失败(exit≠0 **或长时间无输出**)才回退用户默认源（通常为国内镜像）\n      stalled = false;\n      const holder = { child: null };\n      const { child, error } = spawnUpdater(\n        relayDir, retried ? {} : { npm_config_registry: \"https://registry.npmjs.org\" }, failUpdaterSpawn, spec);\n      if (error || !child) {\n        if (error) failUpdaterSpawn(error);\n        return null;\n      }\n      holder.child = child;\n      writeMarker(marker, child.pid);\n      // 【0.6.9 关键修复】无输出看门狗：中国网络访问 npm 官方源的典型失败形态是**挂起**\n      // （进程活着、永远不产出 exit），旧实现只看\"退出码非 0\"，于是回退永不触发、标记永不清除、\n      // 用户永久停在「更新中」。这里以\"日志多久没新增字节\"为判据，卡住即结束进程 →\n      // 自然而然地走下面 exit≠0 的同一条回退路径。\n      startProgressWatch(UPDATE_WATCH_KEY, {\n        relayDir, logName: UPDATE_LOG, kind: \"update\",\n        getChild: () => holder.child,\n        onStall: (idle) => {\n          stalled = true;\n          appendLogLine(relayDir, UPDATE_LOG,\n            `[update] 已 ${Math.round(idle / 1000)}s 无输出 → 判定卡住，结束该进程${retried ? \"（已重试过，不再回退）\" : \"，回退默认源(npmmirror 等)重试\"}…`);\n        },\n      });\n      child.on(\"exit\", (code) => {\n        stopProgressWatch(UPDATE_WATCH_KEY);\n        // 用户取消导致的退出：既不重试、也不记失败（取消不是失败）\n        if (updateCancelledDirs.has(relayDir)) {\n          updateCancelledDirs.delete(relayDir);\n          appendLogLine(relayDir, UPDATE_LOG, \"[update] 已取消：不再换源重试\");\n          restoreIfStopped(); // C8：取消也要把 bridge 拉回来\n          return;\n        }\n        if (!retried && (code !== 0 || stalled)) {\n          retried = true;\n          appendLogLine(relayDir, UPDATE_LOG,\n            `[update] ${stalled ? \"官方源长时间无输出\" : `官方源安装失败(exit=${code})`}，回退默认源(npmmirror 等)重试…`);\n          run();\n          return;\n        }\n        // 两次 npx 都没成功 → 第三跳：离线通道（不经 npx/npm）。这是给\"npx 坏掉的机器\"留的出路，\n        // 也是 2026-09 那批「点了一键更新却永远失败」的 Windows 用户唯一可能自救的路径。\n        if (!offlineTried && (code !== 0 || stalled)) {\n          offlineTried = true;\n          if (runOffline()) return;\n          appendLogLine(relayDir, UPDATE_LOG, \"[update] 离线通道也未能启动，按失败收尾\");\n        }\n        appendLogLine(relayDir, UPDATE_LOG, `[update] npx 退出 code=${code ?? \"?\"}（${retried ? \"默认源\" : \"官方源\"}）`);\n        clear();\n        // 在线更新改写了插件/运行环境文件 → 版本对不上时由 pluginInstalledAfterBoot() 自动识别，\n        // 面板会提示\"刷新页面\"。这里**不再**写\"需要重启 DeepSeek harness\"的待重启标记：\n        // 插件走 patch 热加载、bridge 是独立进程，重启 harness 已无必要（用户实测反馈）。\n        // 成功不发事件（update_started 已发过，失败才发 update_failed；白名单里没有 update_done，\n        // 硬发只会被服务端静默丢弃）。\n        if (code !== 0 || stalled) {\n          const tail = readTail(join(relayDir, UPDATE_LOG));\n          // 卡住是一种**独立的失败形态**，必须有自己的归因码 —— 旧实现只在 exit≠0 时记失败，\n          // 所以遥测里永远看不到\"卡死\"这一类，规模被持续低估（诊断报告 F2）。\n          const fc = stalled ? \"update_stalled\" : telemetryFailCodeFromText(tail);\n          // 只把最后的可读片段给用户看（不含完整路径/用户名）；分类码仍按白名单上报\n          const lastLine = String(tail || \"\").split(\"\\n\").map((l) => l.trim()).filter(Boolean).slice(-1)[0] || \"\";\n          noteUpdateFailure(relayDir, stalled\n            ? \"更新进程长时间没有任何输出（已判定卡住并结束），通常是本机到 npm 官方源的链路不通\"\n            : (lastLine || `安装进程退出码 ${code}`), fc);\n          telemetryRecord(relayDir, \"update_failed\", { fail_code: fc });\n          restoreIfStopped(); // C8：三次尝试都已失败 → 先把 bridge 拉回来（用户可以先继续用，再手动重试）\n        } else {\n          updateFailures.delete(String(relayDir)); // 成功即清掉旧失败\n          sweepIfSucceeded(); // C8：装完清残留（安装器可能又拉起一个新 bridge，只清更新前那批）\n          // 【2026-09-26】更新成功 → 写一条 kind=\"restart\" 的待重启标记。\n          //\n          // 修的是\"文案与状态机不一致\"：版本卡一直写「请重启 dsh web 后生效」（client.js 的\n          // `updated` 分支），但**没有任何一处**在成功路径上写过待重启状态 —— 于是那句文案是个\n          // 无人兑现的承诺，用户在页面上也看不到任何\"要动一下\"的强提示。\n          //\n          // kind 用 \"restart\" 而**不是**既有的 \"refresh\"：两者是**不同的动作**\n          //   · refresh  = 插件文件在运行中被改写，刷新浏览器即可（客户端半新的，node 半也是新的）\n          //   · restart  = 在线更新刚换了插件包，需要重启 dsh web 才载入新的 node 半\n          // 客户端按 kind 一一对应地换文案与主按钮（见 client.js 的 restartAlert），\n          // 混用一个 kind 就会再次出现\"文案说刷新、状态其实是重启\"。\n          // settleRestartState() 靠 bootId 自动结清 —— 用户真的重启后这条提示自己消失，不需要额外清理。\n          markUpdateRestartPending(relayDir);\n        }\n      });\n      child.unref();\n      return child;\n    };\n    const child = run();\n    // spawn 是异步的：解析失败时 pid 可能是 undefined。此时**不能**同步返回 ok:true，\n    // 否则前端会显示\"更新已开始\"、随后看到 running:false 便报\"已完成\"（实测的静默失败）。\n    if (!child || !child.pid) {\n      const rec = recentUpdateFailure(relayDir);\n      return { ok: false, detail: (rec && rec.detail) || \"无法启动更新进程（npx 不可用？）\", failCode: rec ? rec.failCode : \"unknown\" };\n    }\n    return { ok: true, pid: child.pid, log: join(relayDir, UPDATE_LOG), channel: UPDATE_TAG, targetTag: target.tag, targetVersion: target.version };\n  } catch (e) {\n    try { rmSync(join(relayDir, UPDATE_MARKER), { force: true }); } catch { /* ignore */ }\n    telemetryRecord(relayDir, \"update_failed\", { fail_code: telemetryFailCodeFromError(e) });\n    // C8：异常也要把停掉的 bridge 拉回来（否则\"更新失败\"= 远程访问直接没了）\n    if (stopInfo.pids.length && !skipsSystemOps()) {\n      const r = restoreBridgeAfterUpdate(relayDir, stopInfo.pids);\n      appendLogLine(relayDir, UPDATE_LOG, `[update] 响应异常，已重新拉起 bridge（${(r && r.status) || \"unknown\"}）`);\n    }\n    return { ok: false, detail: String(e.message || e) };\n  }\n}\n\n/** 读日志尾部(更新进度展示)。 */\nfunction tailOf(filePath, lines = 24) {\n  try {\n    const all = readFileSync(filePath, \"utf8\").split(\"\\n\");\n    return all.slice(-lines).join(\"\\n\");\n  } catch { return \"\"; }\n}\n\n/**\n * 新一轮在线更新**开始前**轮转 `.dsh-update.log`：旧内容归档成 `.dsh-update.log.1`（只留一份）。\n *\n * 为什么必须在\"开始\"时做，而不是\"成功\"时清空：\n *   ① 这份日志是 `openSync(..., \"a\")` **只 append 从不截断**的 —— 一轮轮更新下来会无界增长，\n *      违反工作区 AGENTS.md「日志必须有轮转」；而失败现场恰恰是最需要保留的那一份，\n *      所以在成功时删反而会把证据毁掉。归档旧的一轮、新的一轮另起一页才是对的分界。\n *   ② 面板的「更新日志」黑框读的就是这个文件的尾部（tailOf）：不轮转的话，**刷新页面还会把\n *      上一次的尾巴拉回来**，用户看到的\"更新黑框永不消失\"有一半责任在这里。\n *      客户端那半已经按 running 状态 gate 住了（见 client.js 的 updShowLog），这一条是宿主侧的根治。\n * 轮转失败（权限/占用）不致命：退化成继续 append 的旧行为，绝不影响更新本身。\n */\nfunction rotateUpdateLog(relayDir) {\n  try {\n    const file = join(relayDir, UPDATE_LOG);\n    if (!existsSync(file)) return;\n    const prev = `${file}.1`;\n    try { rmSync(prev, { force: true }); } catch { /* 上一份归档删不掉就覆盖写，继续 */ }\n    renameSync(file, prev);\n  } catch { /* 轮转失败：静默，退化为 append */ }\n}\n\n/**\n * 判断 patch 文本是否是「合法的顶层 YAML 数组文档」。\n *\n * 为什么必须判（2026-09-18 Windows 用户实测的致命故障）：dsh 解析 cordis.patch.yml 时\n * **要求顶层是数组**，而**纯注释文档的 YAML 解析结果是 `null` 而不是空数组**，于是 dsh 直接：\n *   `Error: dsh: overlay …/cordis.patch.yml must be a top-level YAML array of loader patch entries`\n * 官方空 profile 模板是「注释 + `[]`」——`[]` 这个占位符不能省。\n * 卸载把插件条目摘掉后若只剩注释，用户就再也起不来 dsh web（面板也进不去，只能靠 CLI 自救）。\n */\n/** 顶层（无缩进）非注释行 = YAML 的结构行；缩进行属于上一条目。 */\nfunction patchStructuralLines(text) {\n  return String(text ?? \"\")\n    .split(/\\r?\\n/)\n    .map((l) => l.replace(/\\s+$/, \"\"))\n    .filter((l) => l.trim() !== \"\" && !/^\\s*#/.test(l) && !/^[ \\t]/.test(l));\n}\n\n/** 是否是合法的顶层数组文档（`[]` 占位，或若干 `-` 开头的顶层条目）。 */\nfunction isPatchArrayDocument(text) {\n  const roots = patchStructuralLines(text);\n  return roots.length > 0 && roots.every((l) => l === \"[]\" || l.startsWith(\"-\"));\n}\n\n/** 只有注释/空行 → YAML 解析成 null（不是空数组），必须补 `[]` 占位，否则 dsh 起不来。 */\nfunction needsArrayPlaceholder(text) {\n  return patchStructuralLines(text).length === 0;\n}\n\n/** 摘掉本插件的 patch 条目：管理标记块 + 无标记的 `- insert:` 块（当前名与历史名都清）。 */\nfunction stripOwnEntriesFromPatch(patch) {\n  // ① 管理标记块（dsh-setup 写入的形式）\n  // 结尾标记后面可能还有残留文字（历史变体），用 [^\\n]* 吃掉整行，避免留下半截内容\n  const out = String(patch ?? \"\").replace(/\\n?# >>> dsh-remote-(?:web|ui)[^\\n]*\\n[\\s\\S]*?# <<< dsh-remote-(?:web|ui)[^\\n]*\\n?/g, \"\\n\");\n  // ② 无标记的 insert 块（旧版 / 其它工具写入的形式，历史故障里出现过）。\n  //    只摘标记块是不够的：目录已删而 patch 仍引用 → dsh 插件树加载失败 → 整个 dsh web 起不来。\n  const lines = out.split(\"\\n\");\n  const kept = [];\n  let i = 0;\n  while (i < lines.length) {\n    if (/^- insert:\\s*$/.test(lines[i])) {\n      const block = [lines[i]];\n      let j = i + 1;\n      while (j < lines.length && (lines[j].startsWith(\" \") || lines[j].startsWith(\"\\t\"))) { block.push(lines[j]); j += 1; }\n      if (PLUGIN_ALL_IDS.some((id) => new RegExp(`\\\\b${id}\\\\b`).test(block.join(\"\\n\")))) {\n        while (kept.length && /^\\s*#/.test(kept[kept.length - 1])) kept.pop(); // 连带条目上方的说明注释\n        i = j;\n        continue;\n      }\n      kept.push(...block);\n      i = j;\n      continue;\n    }\n    kept.push(lines[i]);\n    i += 1;\n  }\n  return kept.join(\"\\n\").replace(/\\n{3,}/g, \"\\n\\n\").trimEnd() + \"\\n\";\n}\n\n/**\n * 原子写回 patch，并保证结果仍是合法顶层数组：条目被删光时补回 `[]` 占位。\n * ⚠️ 只在「一个结构行都不剩」时补 —— 不能因为\"看起来不像数组\"就乱补，\n *    那会把本来好的文件写坏（例如把 `[]` 追加到已有 insert 块后面 → YAML 直接报错）。\n */\nfunction writePatchDocument(patchFile, text) {\n  const body = String(text ?? \"\").replace(/\\s+$/, \"\") + \"\\n\";\n  const fixed = needsArrayPlaceholder(body) ? `${body}[]\\n` : body;\n  const tmp = `${patchFile}.dsh-remote.tmp`;\n  writeFileSync(tmp, fixed);\n  renameSync(tmp, patchFile);\n  return fixed;\n}\n\n/**\n * 「运行时清理助手」源码（卸载用；由插件生成、detached 执行）。\n *\n * 为什么必须是独立进程（2026-09-18 用户实测的僵死故障）：\n *   uninstallRuntime() 里有 spawnSync(\"schtasks\"/\"powershell\"/\"taskkill\")，同步子进程调用会把\n *   **dsh web 的事件循环整个钉死** —— 不只是这一个请求不返回，手机端隧道、其它页面、所有 API\n *   一起停摆，表现为「端口在听、连接建立、但永不响应」。而 spawnSync 的 timeout 在 Windows 上\n *   **并不可靠**（实测被策略拦截的进程 18s+ 仍未返回），所以不能把 timeout 当设计依据：\n *   真正的解法是不要把同步子进程调用留在宿主进程里。\n *\n * 助手做的是「宁可少做也不卡住」的有界清理：杀残留进程 → 删自启动 → 清配置目录，每步独立 try/catch。\n */\nfunction buildRuntimeCleanupHelper(relayDir, protectedPath) {\n  /* ★ 归属校验（2026-10-10 故障第三条路径）：计划里的 plistPath 用的是**当前 homedir**，\n     而 relayDir 来自调用方 —— 两者不必是同一个目录。曾有测试用「真 HOME + 临时 relayDir」\n     走到这里，于是这个 detached 助手把**开发者本机真实的自启动 plist 删了**（异步删，\n     所以在进程内插桩根本抓不到）。现在：plist 里没写着本 relayDir 的入口脚本 → **不给路径**，\n     助手自然一个字节都不动。 */\n  const homePlist = join(homedir(), \"Library\", \"LaunchAgents\", \"com.dshremote.bridge.plist\");\n  const ownsHomePlist = (() => {\n    try { return existsSync(homePlist) && readFileSync(homePlist, \"utf8\").includes(join(relayDir, \"dsh-setup.mjs\")); } catch { return false; }\n  })();\n  const plan = JSON.stringify({\n    relayDir,\n    protectedPath: protectedPath || \"\",\n    platform: osPlatform(),\n    taskName: WIN_TASK_NAME,\n    pidFiles: [WATCHER_PID_FILE, BRIDGE_PID_FILE],\n    plistPath: ownsHomePlist ? homePlist : \"\",\n    unitPath: join(homedir(), \".config\", \"systemd\", \"user\", \"dsh-bridge.service\"),\n    log: join(tmpdir(), \"dsh-remote-uninstall.log\"),\n  });\n  return `// dsh-remote 自动生成：彻底卸载的「运行时清理」部分（独立进程执行，避免阻塞 dsh web）\nimport { spawnSync } from \"node:child_process\";\nimport { appendFileSync, existsSync, readFileSync, rmSync } from \"node:fs\";\nimport { homedir } from \"node:os\";\nimport { dirname, join, sep } from \"node:path\";\n\nconst PLAN = ${plan};\n// 与主进程一致的测试隔离开关：置位时**绝不做任何真实系统操作**（不碰 launchctl/systemctl/schtasks/taskkill），\n// 但仍清空配置目录 —— 否则用例会去动开发者本机真实的自启动服务（历史故障，见 setup-output 用例的护栏）。\nconst SKIP_SYSTEM_OPS = process.env.DSH_RELAY_SKIP_SERVICE === \"1\";\nfunction log(m) { try { appendFileSync(PLAN.log, \"\\\\n[\" + new Date().toISOString() + \"] \" + m + \"\\\\n\"); } catch (e) { /* 日志失败不阻断清理 */ } }\nfunction run(cmd, args, timeout) {\n  try { const r = spawnSync(cmd, args, { windowsHide: true, encoding: \"utf8\", timeout }); return r.status === 0; }\n  catch (e) { log(\"命令失败 \" + cmd + \": \" + e.message); return false; }\n}\nfunction alive(pid) { try { process.kill(pid, 0); return true; } catch (e) { return e.code === \"EPERM\"; } }\nfunction readPid(name) {\n  try { const n = Number(String(readFileSync(join(PLAN.relayDir, name), \"utf8\")).trim()); return Number.isInteger(n) && n > 0 ? n : null; }\n  catch (e) { return null; }\n}\nlog(\"运行时清理开始（platform=\" + PLAN.platform + \"，relayDir=\" + PLAN.relayDir + \"）\");\nif (SKIP_SYSTEM_OPS) log(\"测试隔离（DSH_RELAY_SKIP_SERVICE=1）：跳过一切真实系统操作\");\n\n// ① 结束 watcher / bridge 残留进程\nfor (const name of (SKIP_SYSTEM_OPS ? [] : PLAN.pidFiles)) {\n  const pid = readPid(name);\n  if (!pid || pid === process.pid) continue;\n  if (!alive(pid)) { log(name + \" 里的 pid \" + pid + \" 已不在\"); continue; }\n  if (PLAN.platform === \"win32\") run(\"taskkill\", [\"/PID\", String(pid), \"/T\", \"/F\"], 8000);\n  else { try { process.kill(pid, \"SIGTERM\"); } catch (e) { /* 已退出 */ } }\n  log(\"已结束 \" + name + \" 的进程 pid=\" + pid);\n}\n\n// ② 移除自启动（按平台）\nif (SKIP_SYSTEM_OPS) {\n  log(\"跳过自启动清理（测试隔离）\");\n} else if (PLAN.platform === \"win32\") {\n  run(\"schtasks\", [\"/Delete\", \"/TN\", PLAN.taskName, \"/F\"], 15000);\n  log(\"已请求删除登录任务 \" + PLAN.taskName);\n} else if (PLAN.platform === \"darwin\") {\n  if (existsSync(PLAN.plistPath)) {\n    run(\"launchctl\", [\"bootout\", \"gui/\" + (typeof process.getuid === \"function\" ? process.getuid() : 0) + \"/com.dshremote.bridge\"], 8000);\n    try { rmSync(PLAN.plistPath, { force: true }); } catch (e) { /* 非关键 */ }\n    log(\"已移除自启动 plist\");\n  }\n} else if (PLAN.platform === \"linux\") {\n  run(\"systemctl\", [\"--user\", \"stop\", \"dsh-bridge\"], 8000);\n  run(\"systemctl\", [\"--user\", \"disable\", \"dsh-bridge\"], 8000);\n  try { if (existsSync(PLAN.unitPath)) rmSync(PLAN.unitPath, { force: true }); } catch (e) { /* 非关键 */ }\n  log(\"已移除 systemd 用户服务\");\n}\n\n// ③ 清空配置目录（账号/密钥/会话 cookie/固化运行时）——安全护栏与主进程一致\ntry {\n  const isRoot = dirname(PLAN.relayDir) === PLAN.relayDir;\n  const isHome = PLAN.relayDir === homedir();\n  const hitsProfile = Boolean(PLAN.protectedPath) && (\n    PLAN.relayDir === PLAN.protectedPath\n    || PLAN.relayDir.startsWith(PLAN.protectedPath + sep)\n    || PLAN.protectedPath.startsWith(PLAN.relayDir + sep));\n  if (PLAN.relayDir && !isRoot && !isHome && !hitsProfile && existsSync(PLAN.relayDir)) {\n    rmSync(PLAN.relayDir, { recursive: true, force: true });\n    log(\"已清空配置目录\");\n  } else {\n    log(\"跳过配置目录清理（护栏命中或目录不存在）\");\n  }\n} catch (e) { log(\"配置目录清理失败: \" + e.message); }\nlog(\"运行时清理结束\");\n`;\n}\n\n/**\n * 把「运行时清理」交给一个 detached 子进程（不阻塞宿主事件循环）。\n * @returns {{ok:boolean, pid:number|null, log:string, detail:string}}\n */\nfunction spawnRuntimeCleanupDetached(relayDir, protectedPath) {\n  const logPath = join(tmpdir(), \"dsh-remote-uninstall.log\");\n  try {\n    // 助手放**系统临时目录**而不是 relayDir：它自己就要删 relayDir，\n    // 把正在运行的脚本放在待删目录里既别扭又可能在 Windows 上因文件占用而失败。\n    const helperPath = join(tmpdir(), `dsh-remote-uninstall-${process.pid}-${Date.now()}.mjs`);\n    writeFileSync(helperPath, buildRuntimeCleanupHelper(relayDir, protectedPath));\n    const { child, error } = safeSpawn(process.execPath, [helperPath], {\n      detached: true, cwd: homedir(), stdio: \"ignore\", windowsHide: true,\n      // ⚠️ 必须带 spawnEnv：桌面端宿主下 process.execPath 是 Electron 二进制，\n      // 不补 ELECTRON_RUN_AS_NODE=1 的话这里不是\"跑清理脚本\"，而是**又开一个桌面端应用**。\n      env: spawnEnv({}),\n      onError: (e) => console.warn(`[dsh-remote-web] 运行时清理子进程启动失败: ${e.message}`),\n    });\n    if (error || !child) {\n      return { ok: false, pid: null, log: logPath, detail: (error || new Error(\"spawn 未返回子进程\")).message };\n    }\n    child.unref();\n    return { ok: true, pid: child.pid, log: logPath, detail: \"已在后台清理\" };\n  } catch (e) {\n    return { ok: false, pid: null, log: logPath, detail: e.message };\n  }\n}\n\n/** 账号指纹：账号 / 模式 / 设备身份任一变化都意味着\"必须用新凭据重新登记\"。 */\nfunction accountFingerprintOf(cfg) {\n  const c = cfg || {};\n  return [c.local_key ? \"local\" : \"saas\", c.phone || c.email || \"\", String(c.device_id || \"\")].join(\"|\");\n}\n\n/**\n * 账号（或模式/设备身份）变化后，**必须让 bridge 用新凭据重新登记**。\n *\n * 故障（2026-09-19 实测）：从 A 账号切到 B 账号后，配置已经改了、device_id 也清了，\n * 但**正在运行的 bridge 是启动时把账号/密码固化在环境变量里的**，它不会自己换账号；\n * 而那次\"重启 bridge\"又因 launchd 域名不一致（插件只认 gui/<uid>，安装器装在 user/<uid>）静默失败\n * → 设备继续留在 A 账号，B 账号的设备列表里永远看不到这台机器。\n *\n * 这里做三件事：① 停掉旧 bridge（含两个 launchd 域与脱离进程两种形态）；\n * ② 删掉旧账号留下的状态文件（否则面板据 phase=online + 旧 device_id 谎报\"已连接\"，\n * 自愈也就永远不会去纠正）；③ 交给调用方随后重新启动。\n */\nfunction resetBridgeForAccountChange(relayDir, why) {\n  // ★ 2026-10-13：账号/模式变更是**人**做的决定（登录、切换账号、改自建模式），\n  //   它必须无条件生效 —— 所以顺手清掉自愈护栏额度，绝不允许\"自愈循环之前用完了 3 次额度\"\n  //   导致切换账号后新 bridge 起不来（那会让设备继续留在旧账号里，是 2026-09-19 那个老故障的翻版）。\n  resetSelfhealGuard(relayDir);\n  // 换账号 = 设备绑定前提已变：插件半的设备绑定退避也一并复位（新账号的额度/硬上限可能完全不同）\n  const bk = connectBook(relayDir);\n  bk.bindFail = { sig: bindFailSignatureOf(readBindError(relayDir)), step: 0, until: 0 };\n  bk.bindFailLogged = 0;\n  const stopped = stopBridge(relayDir);\n  // 脱离进程形态（launchd 托管不住时的兜底）也要收干净，否则它会用旧凭据继续跑\n  try { stopBridgeDetached(relayDir, { force: true }); } catch { /* 非关键 */ }\n  try {\n    if (bridgeStateFile(relayDir)) {\n      rmSync(join(relayDir, BRIDGE_STATE_FILE), { force: true });\n      appendLogLine(relayDir, AUTO_INSTALL_LOG, `[dsh-remote-web] ${why}：已清除过期的 bridge 状态记录（旧账号的注册证据作废）`);\n    }\n  } catch { /* 非关键 */ }\n  return stopped;\n}\n\n/**\n * 运行中的 bridge 是否属于「当前账号」。\n * 判据：bridge 状态文件记录的 device_id 必须与配置里的一致；配置里没有 device_id\n * （= 刚切过账号、旧身份已作废）而状态里还有 → 说明跑的是**上一个账号**的 bridge。\n * @returns {boolean} true=属于当前账号；false=过期（必须重启）；未记录 device_id 时按旧行为返回 true\n */\nfunction bridgeMatchesCurrentAccount(relayDir, cfg) {\n  const state = bridgeStateFile(relayDir);\n  if (!state || !state.device_id) return true;          // 无记录可判：不改变既有行为\n  const want = String((cfg || loadConfig(relayDir)).device_id || \"\");\n  if (!want) return false;                              // 配置里身份已清空 = 旧 bridge 的注册已作废\n  return want === String(state.device_id);\n}\n\n/** 彻底卸载第 2 步 —— profile 插件清理（兼容市场“拒绝改写用户补丁”）：移除 include、依赖、bundle、本地目录与链接。 */\nfunction uninstallSelf(relayDir, profileDir, patchFile, pkgFile) {\n  const out = { removedPatch: false, removedDep: false, removedDir: false, removedBundle: false };\n  try {\n    const patch = readFileSync(patchFile, \"utf8\");\n    const cleaned = stripOwnEntriesFromPatch(patch); // 兼容当前与历史（dsh-remote-ui）两种名\n    if (cleaned !== patch) { writePatchDocument(patchFile, cleaned); out.removedPatch = true; }\n  } catch { /* 无 patch 忽略 */ }\n  try {\n    const pkg = JSON.parse(readFileSync(pkgFile, \"utf8\"));\n    if (pkg.dependencies) {\n      let removed = false;\n      for (const id of PLUGIN_ALL_IDS) {\n        if (pkg.dependencies[id] !== undefined) { delete pkg.dependencies[id]; removed = true; }\n      }\n      if (removed) out.removedDep = true;\n    }\n    const bundles = pkg.dsh && pkg.dsh.profile && Array.isArray(pkg.dsh.profile.bundles) ? pkg.dsh.profile.bundles : null;\n    if (bundles) {\n      const filtered = bundles.filter((b) => !PLUGIN_ALL_IDS.includes(b));\n      if (filtered.length !== bundles.length) {\n        pkg.dsh.profile.bundles = filtered;\n        out.removedBundle = true;\n      }\n    }\n    if (out.removedDep || out.removedBundle) writeFileSync(pkgFile, JSON.stringify(pkg, null, 2) + \"\\n\");\n  } catch { /* 无 package.json 忽略 */ }\n  try {\n    for (const id of PLUGIN_ALL_IDS) {\n      rmSync(join(profileDir, `${id}-plugin`), { recursive: true, force: true });\n      rmSync(join(profileDir, \"node_modules\", id), { recursive: true, force: true });\n    }\n    // 第二份配对备份住在 profile 的独立数据目录（2026-10-17 双份加固）：里面是账号密码/设备私钥，\n    // 「彻底卸载」必须一起清掉 —— 否则卸载后仍留着凭据副本，且重装后还会提示恢复一个\n    // 用户已经明确不要了的旧账号配对。\n    rmSync(join(profileDir, PROFILE_DATA_DIR), { recursive: true, force: true });\n    out.removedDir = true;\n  } catch { /* ignore */ }\n  return out;\n}\n\n// ---------- 路由 ----------\n\n/** 路由表：{method, path, handler}。 */\n// ---------- 登录后自动闭环：连接阶段（运行环境 → bridge 进程 → 设备已在中继注册=online） ----------\n\n/**\n * 现场观察：新用户注册后手机端 /api/devices 常是空列表，\n * 多人反复点「生成访问链接」（auth.key_create 10~23 次）而 device.bind 始终为 0——他们的电脑端\n * bridge 从未连上过中继。典型路径：注册 → 手机端拿不到设备 → 反复轮询 → 放弃。\n *\n * 缺口不是某个按钮坏了，而是「登录 → 设备已在中继注册成功」这条链路既不可见也不自动：\n * 用户看不出卡在哪一步（运行环境没装？bridge 没起？还是没注册上中继？），也不知道要不要刷新页面。\n *\n * 本段把链路拆成可查询的阶段（GET /dsh-remote/bridge-status），并刻意区分两个极易混淆的状态：\n *   - starting ：「bridge 进程已在跑」——只说明进程起来了；\n *   - online   ：「设备已在中继注册成功」——手机端能看到并进入这台电脑，这才是用户要的「能用了」。\n * 阶段推进所需的动作（补装运行环境 / 拉起 bridge / 可重试错误退避重试）全部由 ensureConnection\n * 在轮询里自动完成，用户零操作、零刷新；只有「彻底失败」才给按钮，且永远留一条可走的路。\n */\nconst BRIDGE_LOG_FILE = \".dsh-bridge.log\";\nconst BRIDGE_STATE_FILE = \".dsh-bridge-state.json\";\nconst BIND_ERROR_FILE = \".bind-error.json\";\n/** 安装标记超时（进程已死或超 10 分钟）→ 视为卡死，清掉标记重新补装（否则 marker 会把补装永久挡住）。 */\nconst INSTALL_STALE_MS = 10 * 60 * 1000;\n/** 设备登记失败提示只在一小时内当作「当前故障」（.bind-error.json 是持久文件，成功时才被清掉）。 */\nconst BIND_ERROR_FRESH_MS = 60 * 60 * 1000;\n/** 自动重试退避（毫秒）：可重试错误按此节奏自动重试，用尽后停在 60s（仍会自动重试，不出现死胡同）。 */\nconst CONNECT_BACKOFF_MS = [2000, 4000, 8000, 16_000, 30_000, 60_000];\n/**\n * 设备登记「永久性失败」的退避（契约 docs/device-overquota-lock-contract.md §6.3/§6.4）。\n *\n * bridge 遇到服务端 `device_bind_cap`（防滥用硬上限）会写 `.bind-error.json` 并以**专用退出码 5**\n * 退出。watcher（dsh-setup.mjs）自己会做 10s→1min→5min→15min（封顶 30min）的指数退避，但它的状态\n * 在**内存**里 —— 插件半的 startBridge（`launchctl kickstart` / `systemctl restart`）会把 watcher\n * 一并换掉，等于每次自愈都把它辛苦攒的退避清零、又 10s 空撞一次。所以插件半必须自己记一份：\n * 退避窗口内不再发起拉起，`.bind-error.json` 的内容签名变化（解绑/换账号/被清掉）时复位。\n */\nconst DEVICE_BIND_CAP_EXIT_CODE = 5;\nconst BIND_CAP_BACKOFF_MS = [10_000, 60_000, 300_000, 900_000];\nconst BIND_CAP_BACKOFF_MAX_MS = 30 * 60 * 1000;\n\n/** 连接阶段文案（面向非技术用户；node 半算好，面板直接显示，避免两端各写一套）。 */\nconst CONNECT_TEXT = {\n  no_account: \"请先登录手机号账号（下方「🔑 账号」卡片），登录后会自动完成剩余步骤\",\n  no_runtime: \"正在准备运行环境（首次约 1~2 分钟）…\",\n  installing: \"正在准备运行环境（首次约 1~2 分钟）…\",\n  starting: \"正在启动 Bridge…\",\n  connecting: \"正在连接中继…\",\n  online: \"已连接 ✅ 现在可以用手机扫码访问\",\n  error: \"连接失败，请按下方提示处理\",\n};\nconst CONNECT_PHASES = [\"no_account\", \"no_runtime\", \"installing\", \"starting\", \"connecting\", \"online\", \"error\"];\n\n/** 每个 relayDir 的连接状态簿（尝试次数 / 退避 / 上报节流）：放内存，进程重启即重置。 */\nconst connectBooks = new Map();\nfunction connectBook(relayDir) {\n  let b = connectBooks.get(relayDir);\n  if (!b) {\n    b = { attempts: 0, lastAttemptAt: 0, reportAt: 0, watcherSeenAt: 0, bindFail: { sig: \"\", step: 0, until: 0 } };\n    connectBooks.set(relayDir, b);\n  }\n  return b;\n}\n/** 已尝试 attempts 次后的退避时长。 */\nfunction connectBackoffMs(attempts) {\n  const i = Math.min(Math.max(attempts, 0), CONNECT_BACKOFF_MS.length - 1);\n  return CONNECT_BACKOFF_MS[i];\n}\n\n/**\n * `.bind-error.json` 的稳定签名：只取 code/device_id/message，**不含 at** ——\n * bridge 每次重试都会刷新 at，拿它当\"变了\"的依据等于永远变化、退避形同虚设。\n */\nfunction bindFailSignatureOf(bindError) {\n  if (!bindError || typeof bindError !== \"object\") return \"\";\n  return [bindError.code || \"\", bindError.device_id || \"\", bindError.message || \"\"].join(\"|\");\n}\n\n/** 是否是「永久性」登记失败（硬上限；用户不解绑就不会自愈，必须指数退避而不是每 10s 重试）。 */\nfunction isPermanentBindFailure(bindError) {\n  return Boolean(bindError && typeof bindError === \"object\" && bindError.code === \"device_bind_cap\");\n}\n\n/** 第 step 次（从 1 开始）拉起后的退避时长：10s→1min→5min→15min，之后封顶 30min。 */\nfunction bindCapBackoffMs(step) {\n  const n = Math.max(1, Number(step) || 1);\n  if (n <= BIND_CAP_BACKOFF_MS.length) return Math.min(BIND_CAP_BACKOFF_MAX_MS, BIND_CAP_BACKOFF_MS[n - 1]);\n  return BIND_CAP_BACKOFF_MAX_MS;\n}\n\n/**\n * 插件半的「设备绑定硬上限」退避闸门：**只读**，由 ensureConnection 在动手前调用。\n * 签名变化（换账号 / 用户解绑后重试得到不同结论 / 成功登记把提示清掉）→ 复位。\n * @returns {{permanent:boolean, blocked:boolean, until:number, step:number, remainingMs:number}}\n */\nfunction bindFailGate(relayDir, bindError) {\n  const book = connectBook(relayDir);\n  if (!book.bindFail) book.bindFail = { sig: \"\", step: 0, until: 0 };\n  const st = book.bindFail;\n  const sig = bindFailSignatureOf(bindError);\n  if (sig !== st.sig) {\n    st.sig = sig;\n    st.step = 0;\n    st.until = 0;\n  }\n  const now = Date.now();\n  return {\n    permanent: isPermanentBindFailure(bindError),\n    blocked: now < st.until,\n    until: st.until,\n    step: st.step,\n    remainingMs: Math.max(0, st.until - now),\n  };\n}\n\n/** 记一次「即将（重新）拉起 bridge」：永久性失败时步进退避，返回退避后的状态。 */\nfunction noteBindFailAttempt(relayDir, bindError) {\n  const book = connectBook(relayDir);\n  if (!book.bindFail) book.bindFail = { sig: bindFailSignatureOf(bindError), step: 0, until: 0 };\n  const st = book.bindFail;\n  st.sig = bindFailSignatureOf(bindError);\n  st.step = Math.min(st.step + 1, BIND_CAP_BACKOFF_MS.length + 1);\n  st.until = Date.now() + bindCapBackoffMs(st.step);\n  return st;\n}\n/** 本机是否已有可用账号凭据（SaaS 账号或自建访问密钥）——没有就谈不上自动连接，先引导登录。 */\nfunction hasAccountCreds(cfg) {\n  return Boolean((cfg.phone || cfg.email) && cfg.password) || Boolean(cfg.local_key);\n}\n\n/** 读文件尾部（日志可能很长，只取末尾用于判定最近一次连接结果）。 */\nfunction readTail(filePath, maxBytes = 64 * 1024) {\n  try {\n    const fd = openSync(filePath, \"r\");\n    try {\n      const size = fstatSync(fd).size;\n      const start = Math.max(0, size - maxBytes);\n      const buf = Buffer.alloc(size - start);\n      readSync(fd, buf, 0, buf.length, start);\n      return buf.toString(\"utf8\");\n    } finally {\n      closeSync(fd);\n    }\n  } catch { return \"\"; }\n}\n\n/** 读取 bridge 写的状态文件（新版 bridge 会写；旧版没有 → 走日志/账号兜底判据）。 */\nfunction bridgeStateFile(relayDir) {\n  try {\n    const j = JSON.parse(readFileSync(join(relayDir, BRIDGE_STATE_FILE), \"utf8\"));\n    return j && typeof j === \"object\" ? j : null;\n  } catch { return null; }\n}\n\n/**\n * 从 bridge 日志尾部判定「最近一次连接是否注册成功」。\n * 依据 dsh-bridge.mjs 的既有输出：`✅ 设备已登记到账号` / `✅ router 注册成功`；\n * 出现新一轮连接（`隧道已连`）或登记失败/拒绝时，之前那次成功不再代表当前状态。\n */\nfunction bridgeLogState(relayDir) {\n  const tail = readTail(join(relayDir, BRIDGE_LOG_FILE));\n  if (!tail) return { tunnelRegistered: false, accountBound: false, lastError: \"\" };\n  let tunnelRegistered = false;\n  let accountBound = false;\n  let lastError = \"\";\n  for (const raw of tail.split(\"\\n\")) {\n    const line = raw.trim();\n    if (!line) continue;\n    if (/✅\\s*router 注册成功/.test(line)) { tunnelRegistered = true; lastError = \"\"; continue; }\n    if (/✅\\s*设备已登记到账号/.test(line)) { accountBound = true; lastError = \"\"; continue; }\n    if (/隧道已连|\\[dsh-remote\\] dsh web 在线，启动 bridge|bridge 退出/.test(line)) {\n      tunnelRegistered = false;\n      accountBound = false;\n      continue;\n    }\n    if (/拒绝注册|注册发送失败|设备登记失败|无法连接账号 API|设备数已达上限/.test(line)) {\n      tunnelRegistered = false;\n      accountBound = false;\n      lastError = line.slice(0, 300);\n    }\n  }\n  return { tunnelRegistered, accountBound, lastError };\n}\n\n/** 读取设备登记失败提示（bridge 在 409/网络失败时写 .bind-error.json）。 */\nfunction readBindError(relayDir) {\n  try {\n    const f = join(relayDir, BIND_ERROR_FILE);\n    if (!existsSync(f)) return null;\n    const j = JSON.parse(readFileSync(f, \"utf8\"));\n    return j && typeof j === \"object\" ? j : null;\n  } catch { return null; }\n}\n\n/** 运行环境安装状态：installing=安装子进程在跑；stale=标记超时/进程已死（可清掉重来）。 */\nfunction installStateOf(relayDir) {\n  const marker = join(relayDir, PROVISION_MARKER);\n  if (!existsSync(marker)) return { installing: false, stale: false, at: 0 };\n  const info = readMarkerInfo(marker) || {};\n  const at = Number(info.at) || 0;\n  const pidDead = info.pid ? pidAlive(Number(info.pid)) === false : false;\n  const stale = pidDead || (at > 0 && Date.now() - at > INSTALL_STALE_MS);\n  return { installing: !stale, stale, at };\n}\n\n/** 清掉卡死的安装标记（下轮 ensureRuntime 才能重新拉起补装）。 */\nfunction clearStaleInstallMarker(relayDir) {\n  try {\n    rmSync(join(relayDir, PROVISION_MARKER), { force: true });\n    appendLogLine(relayDir, AUTO_INSTALL_LOG, \"[dsh-remote-web] 清理卡死的安装标记（安装进程已退出或超时），将重新补装运行环境\");\n    return true;\n  } catch { return false; }\n}\n\n// ---------- 「守护活着、bridge 却迟迟起不来」：判据 + 真重启（0.6.12） ----------\n//\n// 【2026-09-23 用户实测】反馈里那句关键的「**多次修复都没有解决**」，根因就在这里：\n// startBridgeDetached 只要读到 `.dsh-watcher.pid` 指向一个**活着的**进程就返回「已在运行」——\n// 于是一个**活着但拉不起 bridge 的守护**（上游端口不对 / 运行环境半装 / 它自己卡住）会让\n// 所有自救路径全部空转：面板「启动 / 立即重试 / 一键修复」、插件每轮的自愈，一律 no-op。\n// 用户看到的永远是「正在启动 Bridge…」，重试次数一直涨，而状态一点不变。\n// 现在：守护存活超过阈值却仍没有 bridge 进程 → **真的把它结束掉再重新拉起**（有次数上限，不成风暴）。\nconst WEDGER_MS = 90_000;       // 正常一台机器：守护起来后 1~10s 内 bridge 就该出现\nconst WEDGE_FORCE_MS = 20_000;  // 用户显式点了「重试/修复」：给他更短的等待，别让他干等 90 秒\nconst MAX_WATCHER_RESTARTS = 3; // 连续重启上限：再不行就不是「重启能解决」的问题，改为如实报错\nconst watcherRestarts = new Map(); // relayDir → { count, at }\n\n/**\n * 判定窗口（毫秒）。DSH_RELAY_WEDGE_MS 仅供本仓库测试/诊断把节奏压到亚秒级\n * （与 DSH_RELAY_SELFHEAL_MS / DSH_REMOTE_TELEMETRY_MS 同一约定）：生产不设置，值就是上面那串。\n * 设置时「显式重试」也走同一个窗口（否则用例得干等 20 秒）。\n */\nfunction wedgeLimitMs(force) {\n  const v = Number(process.env.DSH_RELAY_WEDGE_MS);\n  if (Number.isFinite(v) && v > 0) return Math.max(80, v);\n  return force ? WEDGE_FORCE_MS : WEDGER_MS;\n}\n\n/**\n * 守护（watcher）已存活多久：优先用 pid 文件的 mtime 当「本次拉起时刻」（插件刚 spawn 完就写它）；\n * 没有 pid 文件时（0.6.7 之前的运行时、或文件被删）回退到 `observedSince` —— 本进程第一次看到\n * 「守护活着但没有 bridge」的时刻。没有这层兜底，那类守护会永远算不出年龄、也就永远不会被重启。\n */\nfunction watcherStartedAt(relayDir, observedSince = 0) {\n  try {\n    const m = statSync(join(relayDir, WATCHER_PID_FILE)).mtimeMs || 0;\n    if (m) return m;\n  } catch { /* 无 pid 文件 → 用观测起点 */ }\n  return Number(observedSince) || 0;\n}\n\n/**\n * 「服务端登录限流」的最早可重试时刻（bridge 收到 429 时落盘，watcher 据此退避）。\n * 读它是为了**如实解释**「正在启动 Bridge…」为什么不动：限流窗口内 watcher 会跳过拉起 bridge，\n * 这是正常等待（15 分钟内自愈），不该被当成故障去重启守护。\n */\nfunction loginRateLimitedUntil(relayDir) {\n  try {\n    const until = Number(String(readFileSync(join(relayDir, \".dsh-login-ratelimited\"), \"utf8\")).trim());\n    return Number.isFinite(until) && until > Date.now() ? until : 0;\n  } catch { return 0; }\n}\n\n/** 本轮是否该把守护当成「卡死」并重启。纯函数式判据，便于用例直接锁死边界。 */\nfunction watcherWedgeOf(relayDir, { watcherRunning, bridgeRunning, force = false, now = Date.now(), observedSince = 0 } = {}) {\n  const rec = watcherRestarts.get(relayDir) || { count: 0, at: 0 };\n  const base = { wedged: false, ageMs: 0, known: false, restarts: rec.count, rateLimitedUntil: 0, exhausted: false };\n  if (!watcherRunning || bridgeRunning) return base;\n  const rateLimitedUntil = loginRateLimitedUntil(relayDir);\n  if (rateLimitedUntil) return { ...base, rateLimitedUntil };\n  const startedAt = watcherStartedAt(relayDir, observedSince);\n  if (!startedAt) return base; // 完全不知道它活了多久 → 不做激进结论\n  const ageMs = Math.max(0, now - startedAt);\n  const limit = wedgeLimitMs(force);\n  return { ...base, ageMs, known: true, wedged: ageMs >= limit, exhausted: rec.count >= MAX_WATCHER_RESTARTS };\n}\n\n/** 记一次「重启卡死守护」；bridge 真的起来后由 resetWatcherRestart 清零。 */\nfunction noteWatcherRestart(relayDir) {\n  const rec = watcherRestarts.get(relayDir) || { count: 0, at: 0 };\n  rec.count += 1;\n  rec.at = Date.now();\n  watcherRestarts.set(relayDir, rec);\n  return rec;\n}\nfunction resetWatcherRestart(relayDir) {\n  watcherRestarts.delete(relayDir);\n}\n\n/** 运行环境版本（运行时自己写的 .dsh-setup-version；缺 = 旧版本，诊断里如实显示「未知」）。 */\nfunction runtimeVersionOf(relayDir) {\n  try { return String(readFileSync(join(relayDir, \".dsh-setup-version\"), \"utf8\")).trim(); } catch { return \"\"; }\n}\n\n/** 上游地址的来源说明（诊断用：一旦端口不对，这一行就能定位）。 */\nfunction upstreamSourceLabel() {\n  if (String(process.env.DSH_BRIDGE_UPSTREAM || \"\").trim()) return \"来自 DSH_BRIDGE_UPSTREAM\";\n  if (boundWebPort()) return \"dsh web 实际监听端口\";\n  if (discoveredUpstream.url && Date.now() - discoveredUpstream.at < UPSTREAM_DISCOVERY_TTL_MS) {\n    return \"**自动发现**（本机回环端口扫描 + 身份校验：问不到宿主自己的监听端口时用这条）\";\n  }\n  if (String(process.env.DSH_WEB_URL || \"\").trim()) return \"来自 DSH_WEB_URL\";\n  return \"默认值 3080（尚未取到/发现 dsh web 实际监听端口）\";\n}\n\n/**\n * 诊断信息里的日志尾部：**必须先脱敏**。\n * 这份文本是给用户复制出去发客服/贴到群里的，而 bridge 日志里有手机号（\"用账号 138… 登录\"）\n * 与可能的 token/密码片段。只取末尾若干行、逐行截断，并抹掉形如凭据的内容。\n */\nfunction redactForDiagnostics(text) {\n  return String(text || \"\")\n    .replace(/(1[3-9]\\d)\\d{4}(\\d{4})/g, \"$1****$2\")                                   // 手机号\n    .replace(/(Bearer\\s+)[A-Za-z0-9._~+/-]{8,}=*/gi, \"$1<已隐去>\")                       // Bearer 令牌\n    .replace(/((?:password|passwd|token|secret|local_key|bridge_secret)\"?\\s*[:=]\\s*\"?)[^\\s\",}]{4,}/gi, \"$1<已隐去>\");\n}\n/** 取日志尾部若干行（含脱敏 + 行截断），供「复制诊断信息」使用。 */\nfunction logTailForDiagnostics(relayDir, name, maxLines = 15) {\n  const tail = readTail(join(relayDir, name), 8 * 1024);\n  if (!tail) return \"\";\n  const lines = tail.split(\"\\n\").map((l) => l.trim()).filter(Boolean).slice(-maxLines);\n  return lines.map((l) => \"  \" + redactForDiagnostics(l).slice(0, 240)).join(\"\\n\");\n}\n\n/** 账号设备表里是否已登记本机 device_id（手机端 /api/devices 能看到的那一份）+ 节流缓存。 */\nasync function accountDeviceBound(relayDir, cfg) {\n  const deviceId = String(cfg.device_id || \"\");\n  if (!deviceId) return { bound: false, reason: \"no_device_id\" };\n  const cached = deviceProbeCache.get(relayDir);\n  if (cached && Date.now() - cached.at < DEVICE_PROBE_TTL_MS) return cached.value;\n  const done = (value) => { deviceProbeCache.set(relayDir, { at: Date.now(), value }); return value; };\n  const token = await relayToken(relayDir).catch(() => \"\");\n  if (!token) return done({ bound: false, reason: \"no_token\" });\n  const api = (cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n  try {\n    const r = await fetch(`${api}/api/devices`, {\n      headers: { authorization: `Bearer ${token}`, \"x-dsh-client\": `dsh-remote-web/${PLUGIN_VERSION}` },\n      signal: AbortSignal.timeout(5000),\n    });\n    if (!r.ok) {\n      if (r.status === 401 || r.status === 403) invalidateRelayToken(relayDir); // JWT 过期/轮换 → 下次重新认证\n      return done({ bound: false, reason: `http_${r.status}` });\n    }\n    const body = await r.json().catch(() => null);\n    const list = Array.isArray(body?.devices) ? body.devices : Array.isArray(body) ? body : [];\n    const bound = list.some((d) => String(d?.id || d?.device_id || \"\") === deviceId);\n    return done({ bound, reason: bound ? \"\" : \"not_in_list\", count: list.length });\n  } catch (e) {\n    return done({ bound: false, reason: `unreachable: ${e.message}` });\n  }\n}\n\n/**\n * 计算当前连接阶段（纯读，不做任何系统操作）。\n * 阶段：no_account | no_runtime | installing | starting | connecting | online | error\n * 判据严格区分「进程在跑」与「已在中继注册」：\n *   online 需要 bridge 进程在跑 **且** 有中继注册证据（状态文件 > 日志 > 账号设备表）。\n */\nasync function composeConnect(relayDir, opts = {}) {\n  const cfg = opts.cfg || loadConfig(relayDir);\n  // 【0.6.15】上游端口问不出来时，先主动发现一次再算阶段：否则诊断里永远是\"3080 不可达\"，\n  // 而用户的 dsh web 其实好好地跑在 2298（飞牛/NAS 实测）—— 面板与用户都会往\"改端口\"这个\n  // 错误方向使劲。发现很快（本机回环，全失败也就几百毫秒），失败不影响任何既有行为。\n  await discoverUpstreamSelf(relayDir).catch(() => FALLBACK_UPSTREAM);\n  const launchd = opts.launchd || launchdStatus();\n  const manual = opts.manual || manualStatus(relayDir);\n  const book = connectBook(relayDir);\n  const now = Date.now();\n  const hasAcct = hasAccountCreds(cfg);\n  const runtime = runtimeReady(relayDir);\n  const runtimeMissing = runtime ? [] : missingRuntimeFiles(relayDir);\n  const inst = installStateOf(relayDir);\n  const bridgePids = Array.isArray(manual.allBridge) ? manual.allBridge : [];\n  const bridgeRunning = Boolean(launchd.running || bridgePids.length > 0 || (manual.bridge || []).length > 0);\n  const watcherPids = Array.isArray(manual.watcher) ? manual.watcher : [];\n  const watcherRunning = Boolean(!bridgeRunning && watcherPids.length > 0);\n  // F5（2026-10-29）：进程发现的「结论」与「工具怎么得出这个结论的」必须一起下发 ——\n  // 那次事故里面板只有一句「bridge 未运行」，看不出是「扫描不可用（工具看不见）」还是\n  // 「四路证据都说没有（真没有）」，于是排查方向被带偏。scanDegraded/bridgeEvidence 就是答案。\n  const scanDegraded = Boolean(manual.scanDegraded);\n  const bridgeEvidence = Array.isArray(manual.bridgeEvidence) ? manual.bridgeEvidence : [];\n  const wedge = watcherWedgeOf(relayDir, { watcherRunning, bridgeRunning, now });\n  const rateLimitedUntil = loginRateLimitedUntil(relayDir);\n  const bindError = readBindError(relayDir);\n  const bindFresh = Boolean(bindError && (!bindError.at || now - Number(bindError.at) < BIND_ERROR_FRESH_MS));\n  const log = bridgeLogState(relayDir);\n  const state = bridgeStateFile(relayDir);\n  const deviceId = String(cfg.device_id || \"\");\n\n  // ── 「设备被超额锁定」证据（契约 §8.1）──\n  // 两个来源都认：① 新 bridge 写的状态文件 phase=locked + locked{plan,limit,upgrade_to}；\n  // ② `.bind-error.json` code=device_locked / 旧版 device_limit_exceeded（老 bridge/半升级场景）。\n  // 锁定 ≠ 故障：设备行还在、手机端能看到它，只是中继按套餐额度拒绝接入；bridge 不退出，\n  // 每 30s 轮询 /api/devices，用户解绑或升级后自动解锁重连。面板的任务是把这两条出路讲清楚。\n  const stateLocked = state && state.phase === \"locked\" && state.locked && typeof state.locked === \"object\" ? state.locked : null;\n  const bindLocked = bindError && (bindError.code === \"device_locked\" || bindError.code === \"device_limit_exceeded\")\n    ? bindError\n    : null;\n  const lockRaw = stateLocked || bindLocked || null;\n  const locked = lockRaw\n    ? {\n        message: String(lockRaw.message || \"\"),\n        plan: String(lockRaw.plan || \"\"),\n        limit: Number.isFinite(Number(lockRaw.limit)) && Number(lockRaw.limit) >= 0 ? Number(lockRaw.limit) : null,\n        upgradeTo: String(lockRaw.upgrade_to || lockRaw.upgradeTo || \"pro_max\")\n      }\n    : null;\n  /** 契约 §8.1 的固定文案（盘点口径：可同时用 N 台 + 两条出路 + 会自动解锁，不让用户以为要重启）。 */\n  const lockedDetail = locked\n    ? `本机已被锁定（当前套餐可同时使用 ${locked.limit === null ? \"N\" : locked.limit} 台）。`\n      + \"升级 Pro Max 可多台设备同时使用；或到手机端「管理电脑」解绑其他设备后本机会自动解锁。\"\n      + \"（后台服务保持运行并每 30 秒检查一次，解锁后自动恢复，无需重启。）\"\n    : \"\";\n\n  // ── 中继注册证据（只有 bridge 进程在跑时才算「现在能用」） ──\n  // ⚠️ 先判「这个 bridge 是不是当前账号的」：账号切换后进程不会自己换凭据，\n  // 旧账号留下的状态文件（phase=online + 旧 device_id）会让面板谎报「已连接」，\n  // 自愈也就永远不会去重启它（2026-09-19 实测故障）。\n  const accountCurrent = bridgeMatchesCurrentAccount(relayDir, cfg);\n  let registered = false;\n  let registerSource = \"\";\n  if (runtime && bridgeRunning && accountCurrent) {\n    if (state && state.phase === \"online\" && Number(state.tunnel_registered_at) > 0) {\n      registered = true; registerSource = \"state\";\n    } else if (log.tunnelRegistered) {\n      registered = true; registerSource = \"tunnel\";\n    } else if (state && Number(state.account_bound_at) > 0) {\n      registered = true; registerSource = \"state_account\";\n    } else if (log.accountBound) {\n      registered = true; registerSource = \"account\";\n    } else if (hasAcct) {\n      const probe = await accountDeviceBound(relayDir, cfg);\n      if (probe.bound) { registered = true; registerSource = \"account_api\"; }\n    }\n  }\n\n  // ── 上游可达性（只在「还没连上」时才探，带 5s 缓存） ──\n  // 这是「bridge 为什么起不来」最常见、也最容易无人知晓的一种：dsh web 不在 bridge 以为的端口上。\n  // 只把结论写进 detail（不动 phase）：探测失败也可能是本机网络栈/代理的偶发抖动，\n  // 直接判死会让「其实马上就好」的用户看到一条红字错误；而 starting 分支同样带「立即重试/复制诊断」。\n  const needUpstream = hasAcct && runtime && !bridgeRunning;\n  const upstream = needUpstream ? await probeUpstream(relayDir) : null;\n  const upstreamBroken = Boolean(upstream && !upstream.ok);\n  const upstreamNote = upstreamBroken\n    ? `\\n⚠️ bridge 要连的本机 dsh web 地址 ${upstreamUrl()}（${upstreamSourceLabel()}）探测不通：${upstream.error || \"连接被拒绝\"}。`\n      + \"本插件会自动发现 dsh web 的真实端口（0.6.15 起支持非默认端口），\"\n      + \"若仍不通：① 确认 dsh web 正在运行；② 点「一键更新」把运行环境升到最新版；\"\n      + \"③ 仍不行可在启动 dsh web 前设环境变量 `DSH_BRIDGE_UPSTREAM=http://127.0.0.1:<你的端口>`。\"\n    : \"\";\n\n  let phase;\n  let error = null;\n  let detail = \"\";\n  let retryable = true;\n  if (UNINSTALLED_DIRS.has(relayDir)) {\n    phase = \"error\"; retryable = false;\n    error = { code: \"uninstalled\", message: \"本插件已彻底卸载，重启 dsh web 后不再自动启动 bridge\" };\n    detail = error.message;\n  } else if (!hasAcct) {\n    phase = \"no_account\"; retryable = false;\n    detail = \"尚未登录账号：登录后会自动补装运行环境 → 启动 bridge → 连接中继，全程无需其他操作。\";\n  } else if (!runtime) {\n    if (inst.stale) {\n      phase = \"error\";\n      error = {\n        code: \"install_stuck\",\n        message: \"运行环境安装没有完成（上次安装进程已退出或超时），已清理残留标记并准备重新安装\",\n      };\n      detail = error.message;\n    } else {\n      phase = inst.installing ? \"installing\" : \"no_runtime\";\n      detail = inst.installing\n        ? \"正在后台安装运行环境（bridge 本体），首次约 1~2 分钟，装完会自动启动。\"\n        : \"检测到缺少运行环境，正在后台自动安装（首次约 1~2 分钟），无需任何操作。\";\n      if (runtimeMissing.length) {\n        // 半装运行时（入口在、依赖不在）：如实说清是「不完整」而不是「没装」，\n        // 否则用户看到「正在准备运行环境」会以为要等它装完，而它其实**已经卡在这状态很久了**。\n        detail = `运行环境不完整（缺 ${runtimeMissing.slice(0, 3).join(\"、\")}${runtimeMissing.length > 3 ? \" 等\" : \"\"}），`\n          + \"正在后台自动补装（约 1~2 分钟），装完会自动启动 bridge。\";\n      }\n    }\n  } else if (locked) {\n    // 契约 §8.1：锁定态给「error」阶段（用户确实用不了），但**不是**普通故障：\n    // 文案要说清「两条出路」+「会自动解锁」，且不能出现\"无限重试\"的暗示。\n    // 必须排在「bridge 没在跑」之前：锁定是服务端额度结论，bridge 为等待解锁会一直跑着；\n    // 即使进程被手动停掉，用户看到的也该是「已被锁定」而不是「正在启动」。\n    phase = \"error\";\n    retryable = true;\n    error = { code: \"device_locked\", message: locked.message || \"本机已被锁定（超出当前套餐设备额度）\" };\n    detail = lockedDetail;\n  } else if (!bridgeRunning) {\n    if (launchd.crashing) {\n      phase = \"error\";\n      error = {\n        code: \"launchd_crash\",\n        message: `后台服务反复启动失败（launchd state=${launchd.state || \"?\"}，lastExit=${launchd.lastExitCode ?? \"?\"}）`,\n      };\n      detail = \"已自动清理失效的自启动项并重新拉起，稍候会自动恢复。\";\n    } else if (bindFresh && bindError) {\n      phase = \"error\";\n      error = { code: bindError.code || \"bind_failed\", message: bindError.message || \"设备登记失败\" };\n      // device_bind_cap = 防滥用硬上限（bridge 退出码 5）：守护按指数退避重试（10s→1min→5min→15min，\n      // 封顶 30min），不是\"每 10 秒撞一次\"。文案要给出用户能做的事，不能暗示无限重试。\n      detail = bindError.code === \"device_bind_cap\"\n        ? \"已绑定设备数达到上限：请在手机端「管理电脑」解绑不再使用的设备；解绑后本机会自动恢复（守护已按指数退避重试，无需手动重启）。\"\n        : \"bridge 因设备登记失败退出，已进入自动重试；请按提示处理后重试。\";\n    } else if (wedge.wedged && wedge.exhausted) {\n      // 守护活着、却反复拉不起 bridge，且已自动重启到上限 → 这是**真的**卡死了，给明确结论 + 出路。\n      // 旧实现在这种状态下永远显示「正在启动 Bridge…」，用户只能反复点修复（实测反馈）。\n      phase = \"error\";\n      error = {\n        code: \"bridge_wedged\",\n        message: `后台守护已运行 ${Math.round(wedge.ageMs / 1000)} 秒仍拉不起 bridge（已自动重启 ${wedge.restarts} 次）`,\n      };\n      detail = `运行环境版本 ${runtimeVersionOf(relayDir) || \"未知\"}。`\n        + \"请点「一键更新」重装运行环境后重试（更新会一并升级 bridge 守护脚本）；仍不行请点「复制诊断信息」发给客服。\"\n        + upstreamNote;\n    } else if (wedge.wedged) {\n      phase = \"starting\";\n      detail = `后台守护已运行 ${Math.round(wedge.ageMs / 1000)} 秒仍未拉起 bridge，正在自动重启它（无需操作）…`;\n    } else if (rateLimitedUntil) {\n      // 服务端登录限流：watcher 会主动等到窗口结束再拉起（这是等待，不是故障）\n      phase = \"starting\";\n      detail = `账号登录被服务端临时限流，约 ${Math.ceil((rateLimitedUntil - now) / 1000)} 秒后自动重试`\n        + \"（凭据没错、无需改密码，也不需要任何操作）。\";\n    } else {\n      phase = \"starting\";\n      detail = (watcherRunning\n        ? `后台守护已启动${wedge.known ? `（${Math.round(wedge.ageMs / 1000)} 秒）` : \"\"}，正在等待 bridge 进程就绪…`\n        : (launchd.running\n          ? \"后台服务已启动，正在等待 bridge 进程就绪…\"\n          : \"正在启动后台服务（bridge），通常几秒内完成，无需任何操作。\")) + upstreamNote;\n    }\n  } else if (registered) {\n    phase = \"online\";\n    detail = registerSource === \"account_api\" || registerSource === \"account\" || registerSource === \"state_account\"\n      ? \"设备已登记到你的账号：手机端「设备列表」能看到这台电脑，扫码/打开链接即可进入。\"\n      : \"bridge 已注册到中继：手机端扫码/打开链接即可进入这台电脑。\";\n  } else if (bindFresh && bindError) {\n    phase = \"error\";\n    error = { code: bindError.code || \"bind_failed\", message: bindError.message || \"设备登记失败\" };\n    // 旧语义（「解绑旧设备才能登录」「无限重试」）已废弃：超额现在一律走 locked 分支（上面），\n    // 只有硬上限/网络类注册失败会落到这里。\n    detail = bindError.code === \"device_bind_cap\"\n      ? \"已绑定设备数达到上限：请在手机端「管理电脑」解绑不再使用的设备；解绑后本机会自动恢复（守护已按指数退避重试，无需手动重启）。\"\n      : \"请确认网络与账号状态后点「重试」；仍不成功可点「复制诊断信息」发给客服。\";\n  } else if (!accountCurrent) {\n    // 进程在跑，但它是**上一个账号**的 bridge：必须重启才能用新账号登记\n    phase = \"starting\";\n    detail = \"检测到后台 bridge 仍是上一个账号的身份（账号切换后需要重启它才能用新账号重新登记），正在自动重启…\";\n  } else {\n    phase = \"connecting\";\n    detail = \"bridge 进程已在运行，正在等待设备注册到中继…通常几秒内完成。\";\n  }\n\n  const wait = connectBackoffMs(book.attempts);\n  const elapsed = book.lastAttemptAt ? now - book.lastAttemptAt : wait;\n  const autoRetrying = phase !== \"online\" && phase !== \"no_account\" && retryable !== false;\n  const nextRetryInMs = autoRetrying ? Math.max(0, wait - elapsed) : 0;\n  // 【2026-10-17 事故】把「安装/配对自检」结论作为独立字段下发：`~/.dsh-remote` 被误删后，\n  // 面板以前只能显示模糊的「未运行/准备中」，用户不知道该重装还是该重新登录。\n  // 只在**需要用户动手**的状态把结论前置到 detail（运行时缺失但插件正在自动补装时仍由既有\n  // no_runtime/installing 文案说明进度，不制造\"需要重装\"的误导）。\n  const setup = setupStateOf(relayDir);\n  const setupNeedsUser = setup.kind === \"all_missing\" || setup.kind === \"pairing_missing\";\n  if (setupNeedsUser) detail = detail ? setup.text + \"\\n\" + detail : setup.text;\n  const conn = {\n    phase,\n    online: phase === \"online\",\n    text: CONNECT_TEXT[phase] || \"正在连接…\",\n    detail,\n    retryable: retryable !== false,\n    deviceId,\n    runtimeReady: runtime,\n    runtimeMissing,\n    runtimeVersion: runtimeVersionOf(relayDir),\n    installing: inst.installing,\n    installStale: inst.stale,\n    bridgeRunning,\n    accountCurrent, // 运行中的 bridge 是否属于当前账号（false = 上一个账号的进程还在跑）\n    bridgePids,\n    // 进程发现的「证据来源」与「扫描是否可用」（F5，2026-10-29）：\n    //   bridgeEvidence ∈ {pid-file, instance-lock, state-file, scan, pgrep}，\n    //   scanDegraded=true 表示这台机器上插件根本没能扫进程（这时「bridge 未运行」没有说服力）。\n    bridgeEvidence,\n    scanDegraded,\n    // 守护（watcher）与上游：这两项以前完全不下发，于是「守护活着但拉不起 bridge」\n    // 与「上游端口不对」在面板上都长得跟「正在启动」一模一样（用户反馈就是这么来的）。\n    watcherPids,\n    watcherRunning,\n    watcherAgeMs: wedge.known ? wedge.ageMs : 0,\n    watcherWedged: Boolean(wedge.wedged),\n    watcherRestarts: wedge.restarts,\n    // 自愈循环自己的重启账本（见 scheduleRuntime 的长注释）：面板诊断据此如实说明\n    // \"插件为这台机器重启过几次 bridge、是不是已经熔断停手\"。默认 0 = 正常，不产生任何文案。\n    selfhealRestarts: selfhealGuardOf(relayDir).count,\n    selfhealExhausted: selfhealGuardOf(relayDir).count >= SELFHEAL_MAX_RESTARTS,\n    upstreamUrl: upstreamUrl(),\n    upstreamSource: upstreamSourceLabel(),\n    // 宿主形态：桌面端（Electron）与 Web 版（node）在若干动作上语义不同 ——\n    // 最典型的是「重启 DeepSeek harness」在桌面端做不到也不该做（Host 由 Electron 托管，\n    // 强行退出会弹原生致命错误）。面板据此改文案/去掉无意义的按钮，而不是等用户点了才失败。\n    desktopHost: IS_ELECTRON_HOST,\n    restartSupported: !IS_ELECTRON_HOST,\n    upstreamReachable: upstream ? upstream.ok : null,\n    upstreamError: upstream && !upstream.ok ? upstream.error : \"\",\n    rateLimitedUntil,\n    launchdState: launchd.state || \"\",\n    launchdCrashLoop: Boolean(launchd.crashing),\n    registered,\n    registerSource,\n    attempts: book.attempts,\n    nextRetryInMs,\n    error,\n    // 设备被超额锁定（契约 §8）：null = 未锁定；非 null 时面板显示锁定文案 + 「🚀 升级 Pro Max」按钮。\n    // limit 为 null 表示服务端没给额度数值（旧版），文案退回占位。\n    locked,\n    bindError: bindFresh && bindError\n      ? {\n          code: bindError.code || \"\",\n          message: bindError.message || \"\",\n          deviceId: bindError.device_id || \"\",\n          plan: bindError.plan || \"\",\n          limit: Number.isFinite(Number(bindError.limit)) && Number(bindError.limit) >= 0 ? Number(bindError.limit) : null,\n          upgradeTo: bindError.upgrade_to || \"\"\n        }\n      : null,\n    // 安装/配对自检（2026-10-17）：kind/text/backup.action 见 setupStateOf 的长注释。\n    // 面板据此显示「运行环境缺失：需要重新安装…」「未配对：需要在面板里登录一次…」\n    // 以及「检测到历史配对备份（时间），可一键恢复」。\n    setup,\n    logPath: join(relayDir, BRIDGE_LOG_FILE),\n    installLogPath: join(relayDir, AUTO_INSTALL_LOG),\n  };\n  conn.diagnostics = buildConnectDiagnostics(relayDir, conn, log);\n  return conn;\n}\n\n/**\n * 跑一次运行环境的 `dsh-remote doctor`，把它的输出交给面板「复制诊断信息」。\n *\n * 为什么用子进程而不是在插件里重写一份：doctor 的每一条结论（上游来源、身份校验、进程、\n * 待补发队列、订阅异常、日志尾部）都必须与用户自己敲 `dsh-remote doctor` 看到的**完全一致** ——\n * 两份实现必然漂移，而这份文本正是我们用来定位用户问题的唯一凭据。\n *\n * 安全与边界：\n *   · **只读**：doctor 自己承诺不改任何东西（连运行时脚本同步都跳过）；\n *   · 10 秒上限 + 输出上限 64KB：子进程卡死不会把面板按钮挂住，也不会把巨型文本塞进剪贴板；\n *   · 测试隔离（DSH_RELAY_SKIP_SERVICE=1）直接跳过，用例不碰真实系统；\n *   · 任何失败都返回 ok:false + 原因，面板退回原有诊断文本（绝不因此变红/报错）。\n *\n * @returns {Promise<{ok:boolean, text:string, error?:string}>}\n */\nfunction runDoctorText(relayDir) {\n  if (skipsSystemOps()) return Promise.resolve({ ok: false, text: \"\", error: \"测试隔离（DSH_RELAY_SKIP_SERVICE=1）\" });\n  const setup = join(relayDir, \"dsh-setup.mjs\");\n  if (!existsSync(setup)) return Promise.resolve({ ok: false, text: \"\", error: `运行环境入口不存在（${setup}）` });\n  return new Promise((resolve) => {\n    let out = \"\";\n    let done = false;\n    const finish = (v) => { if (!done) { done = true; resolve(v); } };\n    const { child, error } = safeSpawn(process.execPath, [setup, \"doctor\"], {\n      cwd: homedir(),\n      env: spawnEnv({}),\n      stdio: [\"ignore\", \"pipe\", \"ignore\"],\n      windowsHide: true,\n      onError: (e) => finish({ ok: false, text: \"\", error: `启动 doctor 失败：${e.message}` }),\n    });\n    if (error || !child) return finish({ ok: false, text: \"\", error: `启动 doctor 失败：${error ? error.message : \"无子进程\"}` });\n    const timer = setTimeout(() => {\n      try { child.kill(\"SIGKILL\"); } catch { /* 已经退出 */ }\n      finish({ ok: false, text: out.trim(), error: \"doctor 超过 10 秒未返回\" });\n    }, 10_000);\n    timer.unref?.();\n    child.stdout?.on(\"data\", (chunk) => {\n      if (out.length < 64 * 1024) out += String(chunk);\n    });\n    child.on(\"exit\", (code) => {\n      clearTimeout(timer);\n      const text = out.trim();\n      if (!text) return finish({ ok: false, text: \"\", error: `doctor 没有输出（退出码 ${code}）` });\n      finish({ ok: true, text });\n    });\n  });\n}\n\n/**\n * 可复制的诊断信息（面板「复制诊断信息」按钮）：版本 / relayDir / 阶段 / 最近错误 / 进程状态 /\n * 日志路径 + **两个日志的尾部**。\n *\n * 【2026-09-23 用户实测】旧版只给日志**路径**：用户反馈里「最近错误: 无」而实际已经卡死——\n * 因为 lastError 只认 bridge 日志里几个特定文案，node 自己的崩溃栈（MODULE_NOT_FOUND 等）\n * 一律不算「错误」，客服/作者手上因此没有任何可用信息，只能来回问。现在把尾部**原文**带上\n * （已脱敏手机号/令牌，见 redactForDiagnostics），一次复制就能定位。\n */\nfunction buildConnectDiagnostics(relayDir, conn, log) {\n  const rows = [\n    \"dsh-remote 连接诊断\",\n    `插件版本: ${PLUGIN_VERSION}`,\n    // 宿主版本：生产反馈里最缺的就是这个数 —— 只报插件版本时，「是不是 DSH 升级导致的兼容故障」答不出来\n    `宿主版本: ${harnessVersion() || \"未知\"}`,\n    `配置目录: ${relayDir}`,\n    `连接阶段: ${conn.phase}（${conn.text}）`,\n    `设备 ID: ${conn.deviceId || \"（未生成）\"}`,\n    `运行环境: ${conn.runtimeReady ? \"已就绪\" : \"缺失\"}${conn.runtimeVersion ? `（运行时 ${conn.runtimeVersion}）` : \"\"}${conn.installing ? \"（后台安装中）\" : \"\"}${conn.installStale ? \"（安装标记已超时）\" : \"\"}`,\n    conn.runtimeReady || !conn.runtimeMissing || !conn.runtimeMissing.length\n      ? \"\"\n      : `运行环境缺文件: ${conn.runtimeMissing.slice(0, 8).join(\", \")}${conn.runtimeMissing.length > 8 ? ` 等 ${conn.runtimeMissing.length} 个` : \"\"}`,\n    `bridge 进程: ${conn.bridgeRunning ? \"在运行\" : \"未运行\"}（pid=${conn.bridgePids && conn.bridgePids.length ? conn.bridgePids.join(\",\") : \"-\"}，launchd state=${conn.launchdState || \"-\"}，崩溃循环=${conn.launchdCrashLoop ? \"是\" : \"否\"}）`,\n    // 进程发现的证据来源（F5，2026-10-29）：没有这一行时，「bridge 未运行」到底是「真没有」还是\n    // 「工具没看见」在诊断里无法区分 —— 上一次事故就是这么被带偏的。\n    `进程发现: ${conn.scanDegraded\n      ? \"⚠️ 进程扫描不可用（PowerShell 调用失败），本次结论只来自 pid 文件/自写证据 —— 「未运行」不一定是真的没跑\"\n      : \"扫描可用\"}｜bridge 证据: ${conn.bridgeEvidence && conn.bridgeEvidence.length ? conn.bridgeEvidence.join(\"/\") : \"无（pid 文件、实例锁、状态文件、扫描都没有活着的 bridge）\"}`,\n    `后台守护: ${conn.watcherRunning ? `在运行（pid=${conn.watcherPids.join(\",\")}${conn.watcherAgeMs ? `，已 ${Math.round(conn.watcherAgeMs / 1000)} 秒` : \"\"}${conn.watcherWedged ? \"，⚠️ 迟迟未拉起 bridge\" : \"\"}${conn.watcherRestarts ? `，已自动重启 ${conn.watcherRestarts} 次` : \"\"}）` : \"未运行\"}`,\n    // 只在真的重启过 bridge 时才出现这一行（正常用户零新增文案，不制造噪音）：\n    // 它回答的是\"插件自己有没有在反复重启 bridge\"—— 2026-10-13 那个故障里，这个问题\n    // 在客户端侧完全没有答案，运维只能从服务端 audit_log 反推。\n    conn.selfhealRestarts\n      ? `自愈重启: 本进程内已重启 bridge ${conn.selfhealRestarts} 次${conn.selfhealExhausted ? \"（⚠️ 已达上限，已停止自动重启，请点「一键更新」）\" : \"\"}`\n      : \"\",\n    `上游 dsh web: ${conn.upstreamUrl}（${conn.upstreamSource}${conn.upstreamReachable === null ? \"\" : conn.upstreamReachable ? \"，可达\" : `，⚠️ 不可达：${conn.upstreamError}`}）`,\n    `目录选择器: ${pickerPinState.kind === \"native\" ? \"⚠️ 系统原生（远程时对话框弹在电脑那台机器上 → 手机上点「添加工作区」会像没反应）\" : (pickerPinState.kind || \"未知\")}${pickerPinState.detail ? `（${pickerPinState.detail}）` : \"\"}`,\n    `中继注册: ${conn.registered ? \"已注册（\" + conn.registerSource + \"）\" : \"未注册\"}`,\n    `bridge 账号: ${conn.accountCurrent === false ? \"⚠️ 仍是上一个账号的身份（需重启 bridge 重新登记）\" : \"当前账号\"}`,\n    conn.rateLimitedUntil ? `登录限流: 约 ${Math.ceil((conn.rateLimitedUntil - Date.now()) / 1000)} 秒后自动重试（凭据无误，无需改密码）` : \"\",\n    `最近错误: ${conn.error ? conn.error.code + \": \" + conn.error.message : (log && log.lastError ? log.lastError : \"无\")}`,\n    `自动重试: 已尝试 ${conn.attempts} 次${conn.nextRetryInMs ? `，约 ${Math.ceil(conn.nextRetryInMs / 1000)} 秒后重试` : \"\"}`,\n    `bridge 日志: ${conn.logPath}`,\n    `安装日志: ${conn.installLogPath}`,\n    `时间: ${new Date().toISOString()}`,\n  ].filter(Boolean);\n  const bridgeTail = logTailForDiagnostics(relayDir, BRIDGE_LOG_FILE);\n  const installTail = logTailForDiagnostics(relayDir, AUTO_INSTALL_LOG);\n  if (bridgeTail) rows.push(\"\", \"--- bridge 日志（末尾）---\", bridgeTail);\n  if (installTail) rows.push(\"\", \"--- 安装日志（末尾）---\", installTail);\n  return rows.join(\"\\n\");\n}\n\n// ---------- 故障上报（用户主动、可预览、可编辑）＋「让 DeepSeek 帮我修」提示词 ----------\n//\n// 2026-09-23 用户反馈的教训：故障现场我们**看不见** —— 面板只给日志\"路径\"，诊断里写「最近错误: 无」，\n// 而我们又绝不做后台自动上传日志（隐私红线，见 docs/telemetry.md）。结果客服与开发者只能来回问，\n// 用户在「装不上 → 不知道怎么报 → 放弃」里流失（近 14 天 Windows 427 台里成功率只有 35.6%）。\n// 现在把「知情同意」做成产品能力，而不是绕过它：\n//   · GET  /dsh-remote/diag/bundle      → 完整预览：将要发送的每一个字（用户可看、可改、可删）；\n//   · POST /dsh-remote/diag/report      → **用户点确认后**才提交；\n//   · GET  /dsh-remote/diag/fix-prompt  → 让用户本机的 DSH 自己修，并产出定格式结论报告，\n//     用户可把报告贴回同一个上报道（不需要我们发版就能自救）。\n// 走**既有反馈通道**（企业端 /api/feedback），因此不需要任何服务端部署：\n// 正文受服务端 2000 字硬限（fb CONTENT_MAX），超出的日志作为**同一条反馈的回复**分片，\n// 于是后台「用户反馈」里就是一条可回复、可追踪的线程。\nconst DIAG_NOTE_MAX = 600;\nconst DIAG_CONTENT_MAX = 1900;   // 服务端 content 上限 2000，留余量\nconst DIAG_PART_MAX = 1900;\nconst DIAG_MAX_PARTS = 4;        // 日志/报告分片上限（超出只留尾部，宁缺毋滥）\n\n/** 上报标题（服务端 title 上限 120 字）。 */\nfunction diagTitleOf(conn, pluginVer) {\n  const bits = [\"[诊断]\", conn.phase || \"unknown\", `v${pluginVer || PLUGIN_VERSION}`, osPlatform(), process.arch];\n  return bits.join(\" \").slice(0, 110);\n}\n\n/**\n * 组装「用户主动上报」的内容：summary（正文）+ parts（分片，作为回复追加）。\n * @param {{note?:string, attachLogs?:boolean, report?:string}} opts\n *        note = 用户自己写的描述（必填引导）；attachLogs = 是否附带两个日志的尾部（默认附）；\n *        report = 用户从 DSH 拿回来的结论报告（可选）。\n */\nasync function buildDiagReport(relayDir, opts = {}) {\n  const note = String(opts.note || \"\").slice(0, DIAG_NOTE_MAX).trim();\n  const attachLogs = opts.attachLogs !== false;\n  const report = String(opts.report || \"\");\n  const manual = manualStatus(relayDir);\n  const conn = await composeConnect(relayDir, { manual });\n  const cfg = loadConfig(relayDir);\n  const head = redactForDiagnostics([\n    `【插件】v${PLUGIN_VERSION}　运行时 ${runtimeVersionOf(relayDir) || \"未知\"}　宿主 ${harnessVersion() || \"未知\"}　${osPlatform()}/${process.arch}　node ${String(process.versions.node).split(\".\")[0]}`,\n    `【阶段】${conn.phase}（${conn.text}）`,\n    `【设备】ID=${conn.deviceId || \"（未生成）\"}　运行环境=${conn.runtimeReady ? \"就绪\" : `缺失${conn.runtimeMissing && conn.runtimeMissing.length ? `（缺 ${conn.runtimeMissing.slice(0, 3).join(\"、\")}）` : \"\"}`}`,\n    `【bridge】${conn.bridgeRunning ? `在运行 pid=${conn.bridgePids.join(\",\")}` : \"未运行\"}　守护=${conn.watcherRunning ? `在运行 pid=${conn.watcherPids.join(\",\")}${conn.watcherAgeMs ? `（${Math.round(conn.watcherAgeMs / 1000)}s）` : \"\"}` : \"未运行\"}${conn.watcherWedged ? \" ⚠️活着但拉不起 bridge\" : \"\"}${conn.watcherRestarts ? ` 已自动重启 ${conn.watcherRestarts} 次` : \"\"}${conn.selfhealRestarts ? `　【自愈重启】本进程内 ${conn.selfhealRestarts} 次${conn.selfhealExhausted ? \"（已达上限，已停止自动重启）\" : \"\"}` : \"\"}`,\n    `【上游】${conn.upstreamUrl}（${conn.upstreamSource}${conn.upstreamReachable === null ? \"\" : conn.upstreamReachable ? \"，可达\" : `，⚠️不可达：${conn.upstreamError}`}）`,\n    `【中继】${conn.registered ? `已注册（${conn.registerSource}）` : \"未注册\"}　账号=${conn.accountCurrent === false ? \"⚠️上一个账号（需重启 bridge）\" : \"当前账号\"}　自动重试=${conn.attempts} 次`,\n    `【错误】${conn.error ? `${conn.error.code}: ${conn.error.message}` : (conn.detail ? \"无（见上方阶段说明）\" : \"无\")}`,\n    `【配置目录】${relayDir}`,\n    `【账号】${cfg.phone || cfg.email ? \"已登录\" : \"未登录\"}（手机号不随本上报外发；服务端据登录态已知是谁）`,\n  ].join(\"\\n\"));\n  const parts = [];\n  const pushPart = (title, text) => {\n    let rest = String(text || \"\").trim();\n    while (rest && parts.length < DIAG_MAX_PARTS) {\n      parts.push(`--- ${title} ---\\n${rest.slice(0, DIAG_PART_MAX)}`);\n      rest = rest.slice(DIAG_PART_MAX);\n    }\n  };\n  if (report.trim()) pushPart(\"用户回传的结论报告\", report);\n  if (attachLogs) {\n    pushPart(\"bridge 日志（末尾）\", logTailForDiagnostics(relayDir, BRIDGE_LOG_FILE, 40));\n    pushPart(\"安装/更新日志（末尾）\", logTailForDiagnostics(relayDir, AUTO_INSTALL_LOG, 40));\n  }\n  const userPart = note ? `【用户描述】\\n${note}\\n\\n` : \"\";\n  const summary = (userPart + head).slice(0, DIAG_CONTENT_MAX);\n  return { conn, title: diagTitleOf(conn, PLUGIN_VERSION), summary, parts };\n}\n\n/** 提交一条反馈（与面板同一条通道：登录态自动附账号 JWT，失败抛错带服务端人话）。 */\nasync function submitFeedback(relayDir, payload) {\n  const cfg = loadConfig(relayDir);\n  const api = feedbackApiOf(cfg);\n  const headers = {\n    \"content-type\": \"application/json\",\n    \"x-dsh-device\": cfg.device_id || \"\",\n    \"x-dsh-client\": `dsh-remote-web/${PLUGIN_VERSION}`,\n    // 与 proxyFeedback 同一约定：结构化平台字段 + 真实 UA（此处没有浏览器请求可转发，\n    // 就如实写本机平台，绝不冒充浏览器 UA）。\n    \"user-agent\": `dsh-remote-web/${PLUGIN_VERSION} (${process.platform}; ${process.arch})`,\n    \"x-dsh-platform\": process.platform,\n  };\n  if (cfg.phone) headers[\"x-dsh-phone\"] = String(cfg.phone);\n  const t = await feedbackAuthToken(relayDir).catch(() => \"\");\n  if (t) headers.authorization = `Bearer ${t}`;\n  const r = await fetch(`${api}/api/feedback`, {\n    method: \"POST\", headers, body: JSON.stringify(payload), signal: AbortSignal.timeout(12000),\n  });\n  const body = await r.json().catch(() => null);\n  if (!r.ok) {\n    const e = new Error(body?.error?.message || `反馈服务返回 ${r.status}`);\n    e.status = r.status;\n    e.code = body?.error?.code || \"\";\n    throw e;\n  }\n  return body || {};\n}\n\n/** 在同一条反馈下追加一条回复（日志分片用；账号态用账号 JWT 即可，无需 thread_token）。 */\nasync function replyFeedback(relayDir, id, content) {\n  const cfg = loadConfig(relayDir);\n  const api = feedbackApiOf(cfg);\n  const headers = {\n    \"content-type\": \"application/json\",\n    \"x-dsh-device\": cfg.device_id || \"\",\n    \"x-dsh-client\": `dsh-remote-web/${PLUGIN_VERSION}`,\n  };\n  if (cfg.phone) headers[\"x-dsh-phone\"] = String(cfg.phone);\n  const t = await feedbackAuthToken(relayDir).catch(() => \"\");\n  if (t) headers.authorization = `Bearer ${t}`;\n  const r = await fetch(`${api}/api/feedback/${encodeURIComponent(id)}/replies`, {\n    method: \"POST\", headers, body: JSON.stringify({ content: content.slice(0, DIAG_PART_MAX) }), signal: AbortSignal.timeout(12000),\n  });\n  if (!r.ok) return { ok: false, status: r.status };\n  return { ok: true };\n}\n\n/**\n * 自动闭环的动作执行（幂等、内部退避）：\n *   ① 缺运行环境 → ensureRuntime（后台 npx 补装；卡死的安装标记先清掉）；\n *   ② 不再缺环境但没账号 → 什么都不做（先把登录引导交给 UI）；\n *   ③ 有账号但 bridge 没在跑 → startBridge（运行环境缺失时它自己会拒绝并转补装）。\n * 由面板的短轮询驱动（GET /dsh-remote/bridge-status），因此用户在登录后不需要点任何按钮、\n * 也不需要刷新页面；退避避免失败时把 launchctl/npx 打成风暴。\n */\nfunction ensureConnection(relayDir, opts = {}) {\n  if (UNINSTALLED_DIRS.has(relayDir)) return null;\n  // 顺手治一次「卡住的更新」（复用面板已有的轮询，不需要新定时器 —— 诊断报告 F5）\n  healStalledJobs(relayDir);\n  const book = connectBook(relayDir);\n  // ★ 2026-10-13：**人工操作永远立即放行**（与 provisionRetryGate 的 resetProvisionRetry 同一原则）。\n  //   面板的「重试 / 一键修复」走的就是 force=true；若不放行，护栏触顶后用户点重试会静默无效 ——\n  //   那就把\"安全阀\"变成了\"用户被自己的插件锁在门外\"。护栏只约束**自动**自愈，不约束人。\n  if (opts.force) resetSelfhealGuard(relayDir);\n  if (opts.force) { book.attempts = 0; book.lastAttemptAt = 0; }\n  const now = Date.now();\n  // ── 设备绑定「永久性失败」→ 插件半指数退避（契约 §6.3/§6.4）────────────────────────────\n  // bridge 撞到防滥用硬上限（device_bind_cap）会写 .bind-error.json 并以**退出码 5** 退出。\n  // watcher 自己会退避，但它的退避状态只存在内存里 —— 插件半的 startBridge（launchctl kickstart /\n  // systemctl restart）会把 watcher 整个换掉，等于每轮自愈都把它的退避清零、又回 10s 空撞一次。\n  // 所以插件半必须自己记一份：退避窗口内**不**发起拉起（也不白耗一次 device-login），\n  // 窗口过了才允许一次新尝试，并按 10s→1min→5min→15min（封顶 30min）继续加倍。\n  // ⚠️ 必须放在「通用 connect 退避」之前判断：否则上一轮动作留下的 2s connect 退避会先 return null，\n  //   面板看到的是\"什么也没发生\"，而不是\"设备绑定已达上限、正在退避等待\"。\n  // 人工操作（opts.force = 面板「重试 / 一键修复」）永远立即放行：安全阀不能把用户锁在门外。\n  const bindErrorNow = readBindError(relayDir);\n  if (opts.force) book.bindFail = { sig: bindFailSignatureOf(bindErrorNow), step: 0, until: 0 };\n  const bindGateEarly = bindFailGate(relayDir, bindErrorNow);\n  if (bindGateEarly.permanent && !opts.force && bindGateEarly.blocked && runtimeReady(relayDir)) {\n    // 同一条结论只写一行日志（面板每 2~3s 轮询一次，逐轮写会把安装日志刷爆）\n    if (book.bindFailLogged !== bindGateEarly.until) {\n      book.bindFailLogged = bindGateEarly.until;\n      appendLogLine(relayDir, AUTO_INSTALL_LOG,\n        `[dsh-remote-web] 设备绑定已达上限（bridge 退出码 ${DEVICE_BIND_CAP_EXIT_CODE}）→ 自愈暂停拉起约 ${Math.ceil(bindGateEarly.remainingMs / 1000)} 秒（指数退避，最长 30 分钟）；请在手机端「管理电脑」解绑不再使用的设备，解绑后自动恢复`);\n    }\n    return { action: \"bind-cap-backoff\", until: bindGateEarly.until, step: bindGateEarly.step };\n  }\n  if (!opts.force && book.lastAttemptAt && now - book.lastAttemptAt < connectBackoffMs(book.attempts)) return null;\n  const cfg = loadConfig(relayDir);\n  if (!hasAccountCreds(cfg)) {\n    // 【2026-10-17 事故】旧规则「未登录 → 不补装也不拉服务」在**运行时**上必须放宽：\n    // 运行时与配对信息都住在 ~/.dsh-remote 里，用户整目录被删后，登录前 ensureRuntime 一次都不会跑，\n    // 于是「登录后自动完成剩余步骤」的第一步就永远缺失。现在：运行时缺失就先复用既有 ensureRuntime\n    // 从插件自带 runtime/ 本地补齐（零网络）；**配对信息仍然只能由用户登录重建**，\n    // 绝不自动填入任何账号/密码（安全边界），也绝不因为有备份就自动恢复旧配对。\n    if (!runtimeReady(relayDir)) {\n      if (installStateOf(relayDir).stale) clearStaleInstallMarker(relayDir);\n      book.lastAttemptAt = now;\n      book.attempts += 1;\n      ensureRuntime(relayDir);\n      return { action: \"provision\" };\n    }\n    return null; // 运行时已就绪但未登录：不拉服务，先让用户登录\n  }\n  if (!runtimeReady(relayDir)) {\n    if (installStateOf(relayDir).stale) clearStaleInstallMarker(relayDir);\n    book.lastAttemptAt = now;\n    book.attempts += 1;\n    ensureRuntime(relayDir);\n    return { action: \"provision\" };\n  }\n  // 运行时已就绪 → 退避窗口外允许一次新尝试：先记账（下一次要等更久），再照常走下面的判断。\n  if (bindGateEarly.permanent && !opts.force) noteBindFailAttempt(relayDir, bindErrorNow);\n  else book.bindFailLogged = 0;\n  const launchd = launchdStatus();\n  const manual = manualStatus(relayDir);\n  const bridgeProcs = [...(manual.allBridge || []), ...(manual.bridge || [])];\n  const watcherProcs = Array.isArray(manual.watcher) ? manual.watcher : [];\n  // ⚠️ 「有进程」必须分成两类看：bridge 本体（能让设备登记）与**守护 watcher**（只是负责拉起它）。\n  // 旧实现把两者混成一个 if，于是「守护活着、bridge 一直没起来」直接走「已在跑」分支 →\n  // 每一次修复/重试都变成 no-op（用户反馈：「多次修复都没有解决」）。0.6.12 拆开处理。\n  const watcherRunning = Boolean(launchd.running || watcherProcs.length);\n  if (bridgeProcs.length || watcherRunning) {\n    // 进程在跑 ≠ 跑对了账号：切换账号后旧 bridge 会一直用旧凭据，\n    // 只看\"有没有进程\"会让自愈永久停摆（实测故障）。这里多判一次账号归属。\n    if (bridgeProcs.length && !bridgeMatchesCurrentAccount(relayDir, cfg)) {\n      book.lastAttemptAt = now;\n      book.attempts += 1;\n      resetBridgeForAccountChange(relayDir, \"bridge 身份与当前账号不符\");\n      const r = startBridge(relayDir);\n      appendLogLine(relayDir, AUTO_INSTALL_LOG,\n        `[dsh-remote-web] 检测到旧账号的 bridge 仍在运行，已重启以用当前账号重新登记（${r.status || \"?\"}）`);\n      return { action: \"restart\", result: r };\n    }\n    if (!bridgeProcs.length) {\n      // 第一次看到「守护活着但没有 bridge」的时刻：pid 文件缺失时用它当存活起点（见 watcherStartedAt）\n      if (!book.watcherSeenAt) book.watcherSeenAt = now;\n      // 守护活着但没有 bridge：只有在「真的卡住了」时才动手（正常启动窗口内不打扰）。\n      const wedge = watcherWedgeOf(relayDir, {\n        watcherRunning: true, bridgeRunning: false, force: Boolean(opts.force), now,\n        observedSince: book.watcherSeenAt,\n      });\n      if (wedge.wedged && !wedge.exhausted) {\n        const rec = noteWatcherRestart(relayDir);\n        // Windows 没有服务管理器；Linux 上没有被 systemd 托管时也是脱离进程：\n        // 这两种都必须**显式结束卡死的守护**，否则 startBridge 幂等会直接返回、重启变成 no-op。\n        // macOS 走 launchctl，startBridge 内部已先 bootout 再 bootstrap，等价于重启。\n        // ★ 0.6.15：以前这里把 Linux 排除在外（那时 Linux 的 startBridge 是死路，重启没意义）。\n        // ★ 2026-10-29：如果那个守护**杀不掉**（pid 已被系统回收给无关进程 / kill 工具不可用 /\n        //   按安全纪律主动跳过），`startBridge` 的幂等判断会因「pid 文件还在且新鲜」再次返回\n        //   「已在运行」→ 重启变成永久 no-op（就是本次要根治的死循环）。此时必须**强制拉起**：\n        //   新 watcher 会用自己的 pid 覆盖 pid 文件；旧实例若真活着，dsh-setup.mjs 自己的 pid 去重会拦。\n        let stopInfo = null;\n        if (isWindows() || (isLinux() && !systemdUserAvailableCached())) stopInfo = stopBridgeDetached(relayDir);\n        const unresolved = (stopInfo && Array.isArray(stopInfo.unresolvedPids)) ? stopInfo.unresolvedPids : [];\n        if (unresolved.length) forceNextDetachedSpawn(`watcher pid 未能结束（pid ${unresolved.join(\", \")}）`);\n        const r = startBridge(relayDir);\n        appendLogLine(relayDir, AUTO_INSTALL_LOG,\n          `[dsh-remote-web] 后台守护已存活 ${Math.round(wedge.ageMs / 1000)} 秒仍无 bridge 进程`\n          + `（上游 ${upstreamUrl()}）→ 已第 ${rec.count} 次重启它（${r && r.status ? r.status : \"?\"}）`);\n        book.attempts = 0;      // 刚重新拉起：给下一轮一个立即复核的机会\n        book.lastAttemptAt = 0;\n        return { action: \"restart-wedged-watcher\", result: r, wedge };\n      }\n      if (wedge.wedged && wedge.exhausted) {\n        // 连续重启都不行 → 不再风暴式重启（面板据 wedged/exhausted 给出「一键更新」结论）\n        book.lastAttemptAt = now;\n        book.attempts += 1;\n        return { action: \"wedge-exhausted\", wedge };\n      }\n    } else {\n      resetWatcherRestart(relayDir); // bridge 真的在跑：连续重启计数清零\n      book.watcherSeenAt = 0;\n    }\n    book.attempts = 0; // 进程已在跑：退避计数归零，后续只等注册\n    book.lastAttemptAt = now;\n    return { action: \"none\" };\n  }\n  if (launchd.crashing) reapBrokenAutostart(relayDir);\n  book.lastAttemptAt = now;\n  book.attempts += 1;\n  const r = startBridge(relayDir);\n  if (r && r.ok === false) {\n    // ★ 2026-09-25：**同一条失败不要每轮都写一遍**。\n    //   两条用户反馈（fb_7b4ee6ec9862 / fb_4cc2c9df749c）的安装日志里，同一行\n    //   `自动启动 bridge 未成功(unsupported): 当前平台（linux）暂不支持自启动服务`\n    //   分别重复了 **19 次 / 13 次** —— 自愈每轮重试是对的，但把同一条结论一遍遍写进日志\n    //   会变成噪音：用户复制过来的诊断里全是重复行，真正的\"第一现场\"反而被淹没\n    //   （那次我们只能靠数行数才能推出时间线）。现在：结论没变就只累加计数。\n    noteAutostartFailure(relayDir, r.status, r.detail);\n  } else if (r && r.ok) {\n    clearAutostartFailure(relayDir); // 起来了 → 下次失败要重新记第一行\n  }\n  return { action: \"start\", result: r };\n}\n\n/**\n * 记一条「自动启动 bridge 失败」，但**同一条结论只写一次**。\n *\n * 【2026-09-25 用户反馈】两条反馈的安装日志里，同一行\n * `自动启动 bridge 未成功(unsupported): 当前平台（linux）暂不支持自启动服务`\n * 分别重复了 **19 次 / 13 次**（自愈每轮重试，每次都写一行）。用户复制过来的诊断里全是重复行，\n * 第一现场被淹没 —— 那次我们只能靠\"数行数 ÷ 每分钟行数\"才推出时间线。\n * 现在：结论没变就只累加计数；只在 5/10/50/100/500 这些节点补一行「还在失败、已 N 次」。\n * （500 次失败总共只留 6 行，而不是 500 行 —— 结论没变的信息量是零。）\n * @returns {number} 累计次数\n */\nfunction noteAutostartFailure(relayDir, status, detail) {\n  const line = `自动启动 bridge 未成功(${status || \"?\"}): ${detail || \"\"}`;\n  const prev = lastAutostartFailure.get(relayDir);\n  if (!prev || prev.line !== line) {\n    lastAutostartFailure.set(relayDir, { line, count: 1 });\n    appendLogLine(relayDir, AUTO_INSTALL_LOG, `[dsh-remote-web] ${line}`);\n    return 1;\n  }\n  prev.count += 1;\n  if ([5, 10, 50, 100, 500].includes(prev.count)) {\n    appendLogLine(relayDir, AUTO_INSTALL_LOG,\n      `[dsh-remote-web] ${line}（已连续 ${prev.count} 次，结论未变，不再重复刷日志）`);\n  }\n  return prev.count;\n}\n\n/** 启动成功后清掉去重状态（下次失败要重新记第一行）。 */\nfunction clearAutostartFailure(relayDir) {\n  lastAutostartFailure.delete(relayDir);\n}\n\n// ---------- 匿名装机/连接遥测（客户端半；契约与隐私边界见 docs/telemetry.md） ----------\n//\n// 背景（2026-09 生产诊断）：11 个新注册用户里只有 3 个把设备连上——6 人电脑端从未安装、2 人装了但\n// bridge 没连上。而「装不上」的人没有任何账号、也就没有任何数据，「本地 OK、新机器失败」因此无法归因。\n// 本通道只补这一段装机/连接事实，且必须守住开源项目的隐私边界：\n//\n//   · 完全匿名：不带 Authorization、不带任何账号标识；install_id 是本机随机 UUID（非硬件派生、\n//     重装即变，不可跨机器关联）；\n//   · 只发白名单事件（TELEMETRY_EVENT_NAMES）与白名单 fail_code（TELEMETRY_FAIL_CODES），\n//     原始错误文本一律不透传（它可能含路径/主机名）；\n//   · 允许的字段**只有**：install_id / 事件名 / fail_code / 插件版本 / **宿主 DSH 版本** /\n//     **更新通道** / os(process.platform) / arch(process.arch) / node(仅主版本号)——唯一构造点是\n//     telemetryEventOf()。宿主版本与通道都是**非识别性的版本串**（形如 0.1.5-rc.2 / beta），\n//     它们回答的是\"这个插件跑在哪个 DSH 上、走的哪条发布通道\"，不指向任何个人或机器；\n//   · 禁止采集（代码与 docs/telemetry.md 双写死）：手机号、邮箱、账号 ID、任何会话内容或文件内容、\n//     真实 hostname / 用户名 / 文件路径、密码与密钥、设备指纹(machine_fp)、原始 IP、精确地理位置；\n//   · 可关闭：DSH_REMOTE_TELEMETRY=0 → 完全关闭（不生成 install_id、不落任何文件、不发任何请求）；\n//   · 全程静默：任何异常都被吞掉，绝不影响面板 / bridge / 连接流程与用户可见行为。\n//\n// 契约（服务端冻结）：POST <api_url>/api/telemetry/events，headers\n//   { content-type: application/json, x-dsh-client: dsh-remote/<PLUGIN_VERSION> }（无 Authorization），\n//   body { install_id, source: \"plugin\", events: [{ name, at, version, harness_version, channel, os, arch, node, fail_code? }] }，\n//   单批 ≤ 20 条、body ≤ 32KB。\n//   `version` = 插件自身版本；`harness_version` = 插件**运行所在的 DSH 宿主**版本（运行时探测，未知为 \"\"），\n//   两者都不是一回事 —— 2026-09 生产问题的根因就是只有前者、答不出\"是不是 DSH 兼容性问题\"。\n//   `harness_version` / `channel` 必须匹配服务端 TELEMETRY_MISC_RE = /^[A-Za-z0-9._-]{0,32}$/，\n//   否则会被服务端**静默清空**：所以这里先自判，不合法就发 \"\"（未知），绝不发一个被改写过的值。\n\n/**\n * 事件名白名单：只用这些，其它一律不发。\n * 2026-09 新增 wechat_bound / wechat_unbound：微信机器人通道的**绑定态跳变**（两态模型，\n * 见 docs/wechat-bot-channel.md §9）—— 这一对该不该有人用、用了之后会不会掉，此前完全看不见。\n * 与服务端 TELEMETRY_EVENTS 必须**逐字对齐**（少一个 = 服务端静默丢弃，事件看起来\"没上报\"）。\n */\nconst TELEMETRY_EVENT_NAMES = new Set([\n  \"install_started\", \"install_failed\", \"runtime_ready\", \"bridge_started\", \"bridge_registered\",\n  \"tunnel_disconnected\", \"first_remote_ok\", \"plugin_loaded\", \"panel_opened\", \"harness_restart\",\n  \"update_started\", \"update_failed\",\n  \"wechat_bound\", \"wechat_unbound\",\n  // 2026-09-26（926 迭代）新增：手机镜像页**就绪耗时**。这一条是\"慢加载\"唯一的量化来源 ——\n  // 在此之前只能靠用户体感反馈。字段 ms（耗时）/ at（客户端事件时刻）/ outcome（ok|slow）\n  // 由路由 /dsh-remote/telemetry/mirror-load 校验后带入（见 telemetryEventOf）。\n  // 与服务端 TELEMETRY_EVENTS 必须逐字对齐（少一个 = 服务端静默丢弃）。\n  \"mirror_load\",\n]);\n/**\n * fail_code 白名单 —— **必须与服务端 TELEMETRY_FAIL_CODES 完全一致**。\n * 两个用途：① 构造事件时校验（白名单外会被清成空串，等于归因白做）；\n * ② 受信边界：只有枚举值能出网络，原始错误文本永不上报。\n * 2026-09-15 教训：新增归因码时忘了同步这里，1659 次 Windows 失败仍然只会显示 unknown。\n */\nconst TELEMETRY_FAIL_CODES = new Set([\n  \"node_missing\", \"node_too_old\", \"npm_unreachable\", \"npm_eacces\", \"platform_unsupported\",\n  \"runtime_install_timeout\", \"launchd_failed\", \"bridge_exit\", \"bind_conflict\", \"bind_device_limit\",\n  \"npx_cmd_unavailable\", \"registry_timeout\", \"install_script_missing\", \"npx_exit_nonzero\", \"npx_output_encoding\", \"update_stalled\",\n  \"unknown\",\n]);\n/** node 半只发 source=plugin。 */\nconst TELEMETRY_SOURCE = \"plugin\";\nconst TELEMETRY_INSTALL_ID_FILE = \".telemetry-install-id\";\nconst TELEMETRY_QUEUE_FILE = \".telemetry-queue.json\";\nconst TELEMETRY_ONCE_FILE = \".telemetry-once.json\";\n/** 本地队列上限（0600）：超出丢最旧，避免长离线机器把磁盘堆满。 */\nconst TELEMETRY_QUEUE_MAX = 200;\n/** 单批事件上限 / body 上限（契约冻结）。 */\nconst TELEMETRY_BATCH_MAX = 20;\nconst TELEMETRY_BODY_MAX = 32 * 1024;\n/** 每 60s 或队列 ≥5 条时批量发送。 */\nconst TELEMETRY_FLUSH_MS = 60_000;\nconst TELEMETRY_FLUSH_THRESHOLD = 5;\n/** 失败退避（30s → 2m → 10m → 1h；落在 60s 心跳网格上），累计 6 次仍失败则丢弃该批。 */\nconst TELEMETRY_BACKOFF_MS = [30_000, 120_000, 600_000, 3_600_000];\nconst TELEMETRY_MAX_ATTEMPTS = 6;\n\n/**\n * 发送心跳间隔（毫秒）。DSH_REMOTE_TELEMETRY_MS 仅供本仓库测试/诊断把节奏压到亚秒级\n * （生产不必设置，与 DSH_RELAY_SELFHEAL_MS 同一约定）；调用时读取，import 之后再改也生效。\n */\nfunction telemetryFlushMs() {\n  const v = Number(process.env.DSH_REMOTE_TELEMETRY_MS);\n  return Number.isFinite(v) && v > 0 ? Math.max(10, v) : TELEMETRY_FLUSH_MS;\n}\n\n/**\n * 遥测开关：DSH_REMOTE_TELEMETRY=0/false/off/no → 完全关闭（不生成 install_id、不落文件、不发请求）；\n * 默认开启（=1/true 显式开启）。\n * 另外：DSH_RELAY_SKIP_SERVICE=1（测试/诊断隔离，见 skipsSystemOps）时同样不发送——\n * 本仓库的测试脚本全局设了该变量，用例绝不能把匿名事件发到真实生产端点。\n */\nfunction telemetryEnabled() {\n  if (skipsSystemOps()) return false;\n  const v = String(process.env.DSH_REMOTE_TELEMETRY ?? \"\").trim().toLowerCase();\n  return !(v === \"0\" || v === \"false\" || v === \"off\" || v === \"no\");\n}\n\n/**\n * 第 attempt 次失败后到下次重试的退避时长（毫秒）：30s → 2m → 10m → 1h（封顶）。\n * 设置了 DSH_REMOTE_TELEMETRY_MS 时按同一比例缩放（仅供本仓库测试把整条重试链压到亚秒级；\n * 生产绝不设置该变量，生产值就是上面这串）。\n */\nfunction telemetryBackoffMs(attempt) {\n  const base = TELEMETRY_BACKOFF_MS[Math.min(Math.max(attempt, 0), TELEMETRY_BACKOFF_MS.length - 1)];\n  const v = Number(process.env.DSH_REMOTE_TELEMETRY_MS);\n  const scale = Number.isFinite(v) && v > 0 ? Math.max(10, v) / TELEMETRY_FLUSH_MS : 1;\n  // 缩放下限 200ms：把整条重试链压到亚秒级时(仅测试/诊断设置该变量),\n  // 若下限低到 10ms,退避窗口会比一次 await 还短,让“窗口内不重试”这类断言变成\n  // 靠调度运气。200ms 既能让 6 次退避在数秒内跑完,又足以稳定观测。\n  // 生产不设该变量(scale=1),base 最小 30s,不受此下限影响。\n  return Math.max(200, Math.round(base * scale));\n}\n\n/** 每个 relayDir 的遥测簿：内存队列 + 心跳句柄 + 退避/去重状态（进程重启即重置）。 */\nconst telemetryBooks = new Map();\nfunction telemetryBook(relayDir) {\n  let b = telemetryBooks.get(relayDir);\n  if (!b) {\n    b = {\n      queue: null,          // null=尚未从磁盘读回\n      timer: null,          // 心跳定时器（unref，不阻塞进程退出）\n      kickPending: false,   // 已排队一次「立即发送」\n      sending: false,\n      attempts: 0,          // 当前批次连续失败次数\n      nextAt: 0,            // 退避解禁时间\n      closed: false,        // 插件已停摆（dispose）→ 不再调度发送\n      fired: new Set(),     // 本进程已发过的事件名（每进程每阶段只发一次）\n      runtimeMissingSeen: false,\n      installStartedAt: 0,\n      tunnelDown: false,    // 同一掉线周期只发一条 tunnel_disconnected\n      wasRegistered: false,\n    };\n    telemetryBooks.set(relayDir, b);\n  }\n  return b;\n}\n\n/**\n * 只在配置目录**已存在**时落盘：遥测绝不为自己的统计去创建配置目录（否则会改变\n * 「本机是否装过运行时」的既有语义——例如彻底卸载用例里 relayDir 本不该存在）。\n * 目录还没出现时事件只留在内存里等下一次心跳，装好了/登录后目录出现即恢复持久化。\n */\nfunction telemetryDirReady(relayDir) {\n  try { return Boolean(relayDir) && existsSync(relayDir); } catch { return false; }\n}\n\n/**\n * 本机 install_id：<relayDir>/.telemetry-install-id（0600），首次 crypto.randomUUID()，之后复用。\n * 它是**随机 UUID**（非硬件派生、不含机器信息、换机/重装即变），因此不可跨机器关联到同一个人。\n * 生成/落盘失败 → 返回 null（本次不发，静默，不阻断任何流程）。\n */\nfunction telemetryInstallId(relayDir) {\n  if (!telemetryEnabled()) return null;   // 关闭：连 ID 都不生成（更不落盘）\n  if (!telemetryDirReady(relayDir)) return null;\n  const file = join(relayDir, TELEMETRY_INSTALL_ID_FILE);\n  try {\n    const cur = readFileSync(file, \"utf8\").trim();\n    if (/^[0-9A-Za-z-]{16,64}$/.test(cur)) return cur;\n  } catch { /* 首次生成 */ }\n  try {\n    const id = randomUUID();\n    try {\n      writeFileSync(file, id, { mode: 0o600, flag: \"wx\" }); // wx：并发时不会互相覆盖\n    } catch {\n      const cur = readFileSync(file, \"utf8\").trim();        // 别的进程刚生成 → 复用它\n      if (cur) return cur;\n      throw new Error(\"install_id 写入失败\");\n    }\n    try { chmodSync(file, 0o600); } catch { /* 权限位不生效不影响使用 */ }\n    return id;\n  } catch {\n    return null; // 生成失败 → 本次不发\n  }\n}\n\n/** 读回本地队列（懒加载；只接受白名单事件名，杜绝外来/损坏内容被转发）。 */\nfunction telemetryLoadQueue(relayDir, book) {\n  if (Array.isArray(book.queue)) return book.queue;\n  book.queue = [];\n  try {\n    const raw = JSON.parse(readFileSync(join(relayDir, TELEMETRY_QUEUE_FILE), \"utf8\"));\n    const list = Array.isArray(raw?.events) ? raw.events : [];\n    book.queue = list.filter((ev) => ev && typeof ev === \"object\" && TELEMETRY_EVENT_NAMES.has(String(ev.name)));\n  } catch { book.queue = []; }\n  return book.queue;\n}\n\n/** 落盘本地队列（0600；写不进去也不影响主流程——退化为只在内存里排队）。 */\nfunction telemetrySaveQueue(relayDir, book) {\n  try {\n    if (!telemetryDirReady(relayDir)) return;\n    const file = join(relayDir, TELEMETRY_QUEUE_FILE);\n    writeFileSync(file, JSON.stringify({ v: 1, events: book.queue || [] }), { mode: 0o600 });\n    try { chmodSync(file, 0o600); } catch { /* 非关键 */ }\n  } catch { /* 非关键 */ }\n}\n\n/** 从队列移除已送达/已放弃的一批（按引用比较，避免并发写入被误删）。 */\nfunction telemetryDrop(relayDir, book, batch) {\n  const queue = telemetryLoadQueue(relayDir, book);\n  for (const ev of batch) {\n    const i = queue.indexOf(ev);\n    if (i >= 0) queue.splice(i, 1);\n  }\n  telemetrySaveQueue(relayDir, book);\n}\n\n/** 一次性事件标记（跨进程、跨重启只发一次，如 first_remote_ok）读/写。 */\nfunction telemetryOnceFlags(relayDir) {\n  try {\n    const j = JSON.parse(readFileSync(join(relayDir, TELEMETRY_ONCE_FILE), \"utf8\"));\n    return j && typeof j === \"object\" ? j : {};\n  } catch { return {}; }\n}\nfunction telemetryMarkOnce(relayDir, name) {\n  try {\n    if (!telemetryDirReady(relayDir)) return;\n    writeFileSync(join(relayDir, TELEMETRY_ONCE_FILE),\n      JSON.stringify({ ...telemetryOnceFlags(relayDir), [name]: Date.now() }), { mode: 0o600 });\n  } catch { /* 非关键 */ }\n}\n\n/**\n * 微信通道「上次观测到的 bound」的跨进程记忆键（与 first_remote_ok 共用同一份\n * .telemetry-once.json，0600）。**刻意不新增第二个落盘机制**：这份文件就是本文件里\n * \"跨进程只记一次/只记一个值\"的既有约定，绑定的基线属于同一类事实。\n * 取值：1 = 上次看到已绑定，0 = 上次看到未绑定，键不存在 = **从未观测过**（null）。\n */\nconst TELEMETRY_WECHAT_BOUND_KEY = \"wechat_bound_state\";\n/**\n * 读回绑定的基线（上次观测值）。键不存在 / 文件缺失 / 损坏 → null（= 从未观测）。\n * 这里**不能**把 null 当成 false：null 是\"没观测过\"（首次观测要播种基线、不发事件），\n * false 是\"观测过且未绑定\"（之后的 true 才算跳变）。两者混淆会系统性虚高绑定数。\n */\nfunction telemetryWeChatBoundBaseline(relayDir) {\n  const v = telemetryOnceFlags(relayDir)[TELEMETRY_WECHAT_BOUND_KEY];\n  if (v === 1 || v === true) return true;\n  if (v === 0 || v === false) return false;\n  return null;\n}\n/** 落盘本次观测到的 bound（0600，写不进去静默）。写失败 → 退化为\"每次都是首次观测\"：宁可少报，绝不重复计数。 */\nfunction telemetryMarkWeChatBound(relayDir, bound) {\n  try {\n    if (!telemetryDirReady(relayDir)) return;\n    writeFileSync(join(relayDir, TELEMETRY_ONCE_FILE),\n      JSON.stringify({ ...telemetryOnceFlags(relayDir), [TELEMETRY_WECHAT_BOUND_KEY]: bound ? 1 : 0 }), { mode: 0o600 });\n  } catch { /* 非关键 */ }\n}\n\n/**\n * 版本类字符串的清洗。服务端只接受 TELEMETRY_MISC_RE = /^[A-Za-z0-9._-]{0,32}$/，\n * 不匹配的字符串字段会被**静默清空**（数据看起来\"没上报\"而不是\"上报错了\"）。\n * 所以这里先判：合法且非空 → 原样发；否则发 \"\"（= 未知）。\n * **绝不改造原始值**——被截断/替换过的版本号比\"未知\"更糟：它会污染归因，且无从分辨。\n */\nconst TELEMETRY_TOKEN_RE = /^[A-Za-z0-9._-]{1,32}$/;\nfunction telemetryToken(v) {\n  const s = String(v ?? \"\");\n  return TELEMETRY_TOKEN_RE.test(s) ? s : \"\";\n}\n\n/**\n * 宿主（DSH / DeepSeek Harness）版本 —— **运行时经验获取，不猜、不硬编码**。\n *\n * 为什么必须有（2026-09 生产问题）：注册 48 人只有 27 人成功，但这个问题当天**答不出来** ——\n * 遥测里的 `version` 是**插件自己**的版本，插件跑在哪个 DSH 上从来没上报过。这类数据**不能回填**，\n * 只能从改版后的新装机开始积累。\n *\n * 取值来源（唯一）：本进程的**主模块** process.argv[1]。dsh CLI 的入口是 `<pkg>/lib/bin.js`\n * （bin 名 `dsh` → 软链 → `<...>/@deepseek-ai/dsh/lib/bin.js`），而 DSH 自己就是用\n * `<pkg>/lib/../package.json` 读版本的（dsh/lib/bin.js 的 readVersion()），所以\"入口的上一级\n * package.json\"是**宿主保证的布局**，不是我们的假设。\n * 本机实测（dsh 0.1.5-rc.2，真实 `dsh web` 进程的 argv）：\n *   argv[1] = /opt/homebrew/bin/dsh（软链）\n *   → realpathSync = /opt/homebrew/lib/node_modules/@deepseek-ai/dsh/lib/bin.js\n *   → ../package.json = { \"name\": \"@deepseek-ai/dsh\", \"version\": \"0.1.5-rc.2\" } → 采到 \"0.1.5-rc.2\"\n * 为什么不用另外三条路（都实测过）：\n *   · 环境变量：DSH 进程**不设置任何 DSH_* 版本变量**（实测 `ps eww`：只有 PATH/HOME/proxy 那几个，\n *     连 DSH_HOME 都没有）→ 无从取值；\n *   · 起 `dsh --version` 子进程：要拉起一个 node（慢），PATH 里没有 dsh 时还要兜底，且**可能挂住** ——\n *     违反\"遥测不得阻塞/挂起\"的前提，直接排除；\n *   · cordis 上下文 / 模块解析：宿主只 provide 了 `dshHomePath`，没有版本服务；profile 的\n *     node_modules 里也**没有** @deepseek-ai/dsh（实测），require.resolve 够不到宿主包。\n * 代价只是读一个本地小 JSON：不起进程、不联网、不可能挂住。任何异常 / 非 dsh 启动\n * （Electron、被嵌入、直接 node 跑别的脚本、测试进程）→ 返回 \"\"（未知），绝不抛、绝不阻塞遥测。\n */\nconst HARNESS_PACKAGE_NAME = \"@deepseek-ai/dsh\";\n\n/** 由主模块路径解析宿主版本；读不到 / 不是 DSH / 版本串不合法（含空）→ \"\"。 */\nfunction harnessVersionFromEntry(entry) {\n  try {\n    const real = realpathSync(String(entry || \"\"));   // 软链（/opt/homebrew/bin/dsh）先落回真实文件，否则\"上一级\"会指错目录\n    const manifest = JSON.parse(readFileSync(join(dirname(real), \"..\", \"package.json\"), \"utf8\"));\n    if (!manifest || manifest.name !== HARNESS_PACKAGE_NAME) return \"\";  // 不是 DSH 启动（如 Electron / 测试进程）\n    return telemetryToken(manifest.version);\n  } catch {\n    return \"\";                                        // 非关键：读不到就是\"未知\"\n  }\n}\n\n/**\n * 由**宿主根目录**解析版本：`<root>/node_modules/@deepseek-ai/dsh/package.json`。\n *\n * 【为什么还要这一条（2026-10-09 真机）】桌面端（DeepSeek Harness 0.2，Electron）的宿主进程 argv 是：\n *   [0] …/MacOS/DeepSeek Harness\n *   [1] --expose-internals                                  ← **是开关，不是路径**\n *   [2] …/app.asar/dsh/node_modules/@deepseek-ai/dsh-desktop-host/lib/index.js\n *   [3] …/app.asar/dsh                                      ← **宿主根目录**\n * 于是「取 argv[1] 的上一级 package.json」在桌面端**必然拿不到**（argv[1] 是 `--expose-internals`），\n * 这就是桌面用户全部上报 harness 版本为空的原因。好在 argv[3] 就是宿主根，其\n * `node_modules/@deepseek-ai/dsh/package.json` 正是宿主版本（实测 0.2.0-rc.2）。\n * 桌面端是 Electron，`readFileSync` 能透明读 asar 内的路径，所以这条在真实宿主里可读。\n */\nfunction harnessVersionFromRoot(root) {\n  try {\n    const manifest = JSON.parse(readFileSync(join(String(root), \"node_modules\", HARNESS_PACKAGE_NAME, \"package.json\"), \"utf8\"));\n    if (!manifest || manifest.name !== HARNESS_PACKAGE_NAME) return \"\";\n    return telemetryToken(manifest.version);\n  } catch {\n    return \"\";   // 不是宿主根 / 读不到 → 交给下一条候选，绝不抛\n  }\n}\n\n/**\n * 从整条 argv 里找出宿主版本（**顺序试探，先命中先返回**）。三条来源都不联网、不起子进程：\n *   ① 目录形态：某参数本身就是宿主根（桌面端 argv[3]）；\n *   ② 文件形态：某参数是 DSH 主模块（Web 版 argv[1]），取它上一级的 package.json；\n * 开关（`-` 开头）与非绝对路径一律跳过 —— 绝不把 `--expose-internals` 当路径去 realpath。\n */\nfunction harnessVersionFromArgv(argv) {\n  const list = Array.isArray(argv) ? argv : [];\n  for (const raw of list) {\n    const p = String(raw ?? \"\");\n    if (p === \"\" || p.startsWith(\"-\") || !isAbsolute(p)) continue;\n    const viaRoot = harnessVersionFromRoot(p);\n    if (viaRoot) return viaRoot;\n    const viaEntry = harnessVersionFromEntry(p);\n    if (viaEntry) return viaEntry;\n  }\n  return \"\";\n}\n\n/** 本进程运行所在的宿主版本（未知 = \"\"）。每次调用现读：事件量很小，且绝不该缓存出过期结论。 */\nfunction harnessVersion() {\n  return harnessVersionFromArgv(process.argv);\n}\n\n/**\n * 【唯一的 payload 构造点】把事件名 + 少量上下文编译成一条遥测事件。\n * 字段仅限契约白名单：name / fail_code / at / version / harness_version / channel / os / arch / node。\n * 这里**绝不**写入手机号、邮箱、账号 ID、会话或文件内容、hostname、用户名、文件路径、\n * 密码/密钥、machine_fp、IP、地理位置等任何可识别信息（见 docs/telemetry.md「不采集什么」）。\n * 返回 null = 事件名不在白名单 → 调用方一律不发。\n */\nfunction telemetryEventOf(name, extra = {}) {\n  if (!TELEMETRY_EVENT_NAMES.has(name)) return null;\n  const ev = {\n    name,\n    at: Date.now(),\n    version: PLUGIN_VERSION,                                    // 插件自身版本（≠ 宿主版本）\n    harness_version: harnessVersion(),                          // 宿主 DSH 版本（运行时探测；未知 = \"\"）\n    channel: telemetryToken(UPDATE_TAG),                        // 更新通道 latest/beta（与\"一键更新\"同源；未知 = \"\"）\n    os: process.platform,                                       // 仅平台名（darwin/linux/win32），非主机名\n    arch: process.arch,                                         // 仅架构（arm64/x64）\n    node: String(process.versions?.node || \"\").split(\".\")[0],   // 仅主版本号，如 \"22\"\n  };\n  if (name === \"install_failed\" || name === \"update_failed\") {\n    const code = String(extra.fail_code || \"\");\n    ev.fail_code = TELEMETRY_FAIL_CODES.has(code) ? code : \"unknown\"; // 白名单外 → unknown\n  }\n  // mirror_load：唯一带**数值**的事件。契约 §2 的两列语义：\n  //   · at  = 客户端事件发生时刻（epoch ms）→ 服务端 at_ms\n  //   · ms  = 耗时毫秒                      → 服务端 value_ms\n  // at 允许缺省（0 = 没给）→ 保留上面那个 Date.now()（= 服务端收包时刻的近似），\n  // 但**绝不把 0 发出去**：0 在分析里会被读成\"1970 年\"，比\"没有值\"更糟。\n  // ms 同样只在有限数时写入（越界/非法由路由先挡掉，这里是第二道防线）。\n  if (name === \"mirror_load\") {\n    if (Number.isFinite(Number(extra.at)) && Number(extra.at) > 0) ev.at = Math.round(Number(extra.at));\n    if (Number.isFinite(Number(extra.ms))) ev.ms = Math.max(0, Math.min(600000, Math.round(Number(extra.ms))));\n    ev.outcome = extra.outcome === \"slow\" ? \"slow\" : \"ok\";\n  }\n  return ev;\n}\n\n/** 从既有日志/错误文本归类 fail_code（白名单内）；原始文本绝不外发（可能含路径/主机名）。 */\nfunction telemetryFailCodeFromText(text) {\n  const t = String(text || \"\");\n  // 顺序有意义：从\"最具体\"到\"最泛\"。\n  // 2026-09-15：Windows 装机失败此前**全部**落到 unknown（1659 次 install_failed 无法定位），\n  // 所以把真实会遇到的形态拆开。仍然只上报枚举，原始文本不出机器（见下方注释与隐私测试）。\n  // ① Windows 上 `npx.cmd` 根本调不起来（不是内部命令 / 找不到 cmd / EINVAL 等）\n  if (/npx(\\.cmd)?\\s+(is not recognized|不是内部或外部命令)|不是内部或外部命令|无法将.*识别为/i.test(t)) return \"npx_cmd_unavailable\";\n  if (/EINVAL|spawn .*\\.cmd/i.test(t)) return \"npx_cmd_unavailable\";\n  // ② 拿到的包不对：404 / 版本被 deprecate / 装完仍没有安装脚本\n  if (/404|Not Found - GET|ETARGET|No matching version/i.test(t)) return \"install_script_missing\";\n  // ③ 纯网络层问题（含 npm ERR! network / 超时 / TLS）\n  if (/ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ETIMEOUT|ECONNREFUSED|ENETUNREACH|ECONNRESET|ERR_SOCKET_TIMEOUT|npm ERR! network|registry\\.npmjs\\.org.*(timeout|timed out)|超时/i.test(t)) {\n    return \"registry_timeout\";\n  }\n  if (/network|registry|EAI|socket hang up/i.test(t)) return \"npm_unreachable\";\n  // ④ 权限（含只读目录 / 沙箱拦截）\n  if (/EACCES|EPERM|permission denied|权限不足|read-only file system/i.test(t)) return \"npm_eacces\";\n  if (/platform|不支持的平台/i.test(t)) return \"platform_unsupported\";\n  if (/too old|版本过低|engine|Unsupported engine/i.test(t)) return \"node_too_old\";\n  if (/ENOENT|not found|No such file|Cannot find module/i.test(t)) return \"node_missing\";\n  // ⑤ 输出是乱码（Windows GBK 代码页下 npm 输出可能整段不可读）→ 谁都没法归因，单独标出来\n  if (/[\\uFFFD]/.test(t)) return \"npx_output_encoding\";\n  // ⑥ 兜底：进程确实退出了非零码，但日志里没有可识别的特征 —— 标成 npx_exit_nonzero，\n  // 与\"启动都没起来\"（npx_cmd_unavailable / node_missing）区分开，便于下轮定位。\n  return \"npx_exit_nonzero\";\n}\n/** 子进程启动失败（spawn error）→ fail_code。 */\nfunction telemetryFailCodeFromError(e) {\n  const code = String(e?.code || \"\");\n  if (code === \"ENOENT\") return \"node_missing\";   // 连 node/npx 可执行文件都找不到 = 本机没有 node\n  if (code === \"EACCES\") return \"npm_eacces\";\n  return telemetryFailCodeFromText(e?.message);\n}\n\n/** 启动发送心跳（懒启动；unref 不阻塞进程退出）。 */\nfunction telemetryTickerStart(relayDir) {\n  const book = telemetryBook(relayDir);\n  if (book.timer || book.closed) return;\n  const t = setInterval(() => { void telemetryFlush(relayDir); }, telemetryFlushMs());\n  t.unref?.();\n  book.timer = t;\n}\n\n/** 排队一次「立即发送」（下一轮事件循环执行；不阻塞调用方）。 */\nfunction telemetryFlushSoon(relayDir) {\n  const book = telemetryBook(relayDir);\n  if (book.kickPending || book.closed || !telemetryEnabled()) return;\n  book.kickPending = true;\n  const t = setTimeout(() => { book.kickPending = false; void telemetryFlush(relayDir); }, 0);\n  t.unref?.();\n}\n\n/**\n * 入队一条事件：白名单 → 队列（上限 200 丢最旧）→ 落盘 → 队列 ≥5 条立即发送，否则等 60s 心跳。\n * 全程 try/catch 静默：遥测绝不能影响面板 / bridge / 连接流程或用户可见行为。\n * @returns {boolean} 是否入队\n */\nfunction telemetryRecord(relayDir, name, extra = {}) {\n  try {\n    if (!telemetryEnabled()) return false;   // 关闭：不落文件、不入队、不发请求\n    const ev = telemetryEventOf(name, extra);\n    if (!ev) return false;                   // 白名单外一律不发\n    const book = telemetryBook(relayDir);\n    if (book.closed) return false;\n    const queue = telemetryLoadQueue(relayDir, book);\n    queue.push(ev);\n    if (queue.length > TELEMETRY_QUEUE_MAX) queue.splice(0, queue.length - TELEMETRY_QUEUE_MAX); // 丢最旧\n    telemetrySaveQueue(relayDir, book);\n    telemetryTickerStart(relayDir);\n    if (queue.length >= TELEMETRY_FLUSH_THRESHOLD) telemetryFlushSoon(relayDir);\n    return true;\n  } catch {\n    return false;\n  }\n}\n\n/** 每进程只发一次的事件（plugin_loaded / panel_opened / bridge_started / bridge_registered）。 */\nfunction telemetryOnce(relayDir, name, extra) {\n  if (!telemetryEnabled()) return false;\n  const book = telemetryBook(relayDir);\n  if (book.fired.has(name)) return false;\n  book.fired.add(name);\n  return telemetryRecord(relayDir, name, extra);\n}\n\n/** 跨进程只发一次的事件（first_remote_ok：持久化标记，先落标记再入队，宁可丢一条也不重复）。 */\nfunction telemetryOnceEver(relayDir, name, extra) {\n  if (!telemetryEnabled()) return false;\n  if (telemetryOnceFlags(relayDir)[name]) return false;\n  telemetryMarkOnce(relayDir, name);\n  return telemetryRecord(relayDir, name, extra);\n}\n\n/** 运行环境就绪（每进程一次）。 */\nfunction telemetryRuntimeReady(relayDir) {\n  if (!telemetryEnabled()) return false;\n  const book = telemetryBook(relayDir);\n  if (book.fired.has(\"runtime_ready\")) return false;\n  book.fired.add(\"runtime_ready\");\n  return telemetryRecord(relayDir, \"runtime_ready\");\n}\n\n/**\n * 运行环境探测（在补装 watcher 与面板轮询里顺手调用，不额外起定时器）：\n *   - 现在缺运行环境 → 记下「本进程见过缺失」，并在超过 INSTALL_STALE_MS 仍缺时归因为\n *     install_failed(runtime_install_timeout)（每进程一次）；\n *   - 之前见过缺失、现在已就绪 → runtime_ready（每进程一次）。\n */\nfunction telemetryRuntimeProbe(relayDir) {\n  if (!telemetryEnabled()) return;\n  try {\n    const book = telemetryBook(relayDir);\n    if (runtimeReady(relayDir)) {\n      if (book.runtimeMissingSeen) telemetryRuntimeReady(relayDir);\n      return;\n    }\n    book.runtimeMissingSeen = true;\n    if (book.installStartedAt && Date.now() - book.installStartedAt > INSTALL_STALE_MS && !book.fired.has(\"install-timeout\")) {\n      book.fired.add(\"install-timeout\");\n      telemetryRecord(relayDir, \"install_failed\", { fail_code: \"runtime_install_timeout\" });\n    }\n  } catch { /* 静默 */ }\n}\n\n/**\n * 「当前隧道是否断连中」判据（仅供遥测）：bridge 日志里最后一次「隧道断开」晚于最后一次\n * 「隧道已连 / ✅ router 注册成功」即为断连中。只看行序，不读任何内容。\n */\nfunction telemetryTunnelDown(relayDir) {\n  const lines = readTail(join(relayDir, BRIDGE_LOG_FILE)).split(\"\\n\");\n  let up = -1;\n  let down = -1;\n  for (let i = 0; i < lines.length; i++) {\n    const line = lines[i].trim();\n    if (!line) continue;\n    if (/✅\\s*router 注册成功|隧道已连/.test(line)) up = i;\n    else if (/隧道断开/.test(line)) down = i;\n  }\n  return down > up && down >= 0;\n}\n\n/** 「本机设备在账号设备表可见」（first_remote_ok 的第二个条件）：状态文件 / 日志 / 账号接口三选一。 */\nfunction telemetryAccountVisible(relayDir, conn) {\n  const src = String(conn?.registerSource || \"\");\n  if (src === \"account_api\" || src === \"account\" || src === \"state_account\") return true;\n  const state = bridgeStateFile(relayDir);\n  if (state && Number(state.account_bound_at) > 0) return true;   // bridge POST /api/devices 成功留下的证据\n  return Boolean(bridgeLogState(relayDir).accountBound);\n}\n\n/**\n * 连接阶段观察（复用既有阶段引擎，不新造状态机）：阶段推进到 starting / online 时各发一次\n * （每进程每阶段只发一次，避免 2~3s 轮询把事件刷爆），掉线时发一条 tunnel_disconnected\n * （同一掉线周期去重）。由持有 conn 的路由调用。\n */\nfunction telemetryObserveConnect(relayDir, conn) {\n  if (!telemetryEnabled() || !conn) return;\n  try {\n    const phase = String(conn.phase || \"\");\n    // bridge_started = bridge 进程被拉起（面板阶段 starting）\n    if (phase === \"starting\") telemetryOnce(relayDir, \"bridge_started\");\n    // bridge_registered = 设备已在中继注册成功（面板阶段 online）——这才是「真正可用」\n    if (phase === \"online\" || conn.registered) telemetryOnce(relayDir, \"bridge_registered\");\n    // tunnel_disconnected = bridge 掉线：日志里最后一次是「隧道断开」，或注册证据由真变假\n    const book = telemetryBook(relayDir);\n    const dropped = telemetryTunnelDown(relayDir) || (book.wasRegistered === true && !conn.registered);\n    if (dropped) {\n      if (!book.tunnelDown) {\n        book.tunnelDown = true;\n        telemetryRecord(relayDir, \"tunnel_disconnected\");\n      }\n    } else {\n      book.tunnelDown = false; // 已恢复/未掉线 → 复位，下一轮掉线可再记一条\n    }\n    if (conn.registered) book.wasRegistered = true;\n    // first_remote_ok = 本机首次观察到 online 且本机设备在账号设备表可见（跨进程只发一次）\n    if (phase === \"online\" && conn.registered && telemetryAccountVisible(relayDir, conn)) {\n      telemetryOnceEver(relayDir, \"first_remote_ok\");\n    }\n  } catch { /* 静默 */ }\n}\n\n/**\n * 批量发送一批（≤20 条、≤32KB；调用方一律不 await）。成功出队；失败按 30s→2m→10m→1h 退避，\n * 累计 6 次仍失败丢弃该批——不永久堆积、不阻塞任何主流程。\n * 匿名：只有 content-type 与 x-dsh-client，**不带 Authorization**（服务端也不接受账号关联）。\n */\nasync function telemetryFlush(relayDir) {\n  const book = telemetryBook(relayDir);\n  try {\n    if (!telemetryEnabled() || book.closed) return;\n    if (book.sending) return;\n    if (Date.now() < book.nextAt) return;        // 退避中：等下一轮心跳到点再看\n    const queue = telemetryLoadQueue(relayDir, book);\n    if (!queue.length) return;\n    const installId = telemetryInstallId(relayDir);\n    if (!installId) return;                      // install_id 生成失败 → 本次不发\n    const build = (list) => JSON.stringify({ install_id: installId, source: TELEMETRY_SOURCE, events: list });\n    let batch = queue.slice(0, TELEMETRY_BATCH_MAX);\n    let body = build(batch);\n    while (batch.length > 1 && Buffer.byteLength(body, \"utf8\") > TELEMETRY_BODY_MAX) {\n      batch = batch.slice(0, batch.length - 1);  // body 超 32KB：收缩批次（正常远小于该上限）\n      body = build(batch);\n    }\n    if (Buffer.byteLength(body, \"utf8\") > TELEMETRY_BODY_MAX) {\n      telemetryDrop(relayDir, book, batch);      // 单条就超限 → 丢弃该批（防御性）\n      return;\n    }\n    const cfg = loadConfig(relayDir);\n    const api = String(cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n    book.sending = true;\n    let ok = false;\n    try {\n      const r = await fetch(`${api}/api/telemetry/events`, {\n        method: \"POST\",\n        headers: {\n          \"content-type\": \"application/json\",\n          \"x-dsh-client\": `dsh-remote/${PLUGIN_VERSION}`,   // 契约冻结：dsh-remote/<version>（非 dsh-remote-web）\n        },\n        body,\n        signal: AbortSignal.timeout(8000),\n      });\n      ok = Boolean(r && r.ok);\n    } catch { ok = false; }                       // 网络失败 → 静默退避（老服务端 404 同理）\n    book.sending = false;\n    if (ok) {\n      telemetryDrop(relayDir, book, batch);\n      book.attempts = 0;\n      book.nextAt = 0;\n      return;\n    }\n    book.attempts += 1;\n    if (book.attempts >= TELEMETRY_MAX_ATTEMPTS) {\n      telemetryDrop(relayDir, book, batch);       // 上限 6 次仍失败 → 丢弃该批\n      book.attempts = 0;\n      book.nextAt = 0;\n      return;\n    }\n    book.nextAt = Date.now() + telemetryBackoffMs(book.attempts - 1);\n  } catch {\n    book.sending = false;                         // 任何异常：静默\n  }\n}\n\n/**\n * 插件装载时的遥测初始化：读回磁盘队列（上次进程遗留的事件不丢，例如重启前那条 harness_restart）\n * 并启动发送心跳。DSH_REMOTE_TELEMETRY=0 时连读都不读 → 零文件零请求。\n */\nfunction telemetryStart(relayDir) {\n  try {\n    if (!telemetryEnabled()) return;\n    const book = telemetryBook(relayDir);\n    book.closed = false;\n    const queue = telemetryLoadQueue(relayDir, book);\n    telemetryTickerStart(relayDir);\n    if (queue.length) telemetryFlushSoon(relayDir);\n  } catch { /* 静默 */ }\n}\n\n/** 插件停摆（dispose）→ 停掉心跳，之后不再调度发送（磁盘队列留给下次装载）。 */\nfunction telemetryStop(relayDir) {\n  try {\n    const b = telemetryBooks.get(relayDir);\n    if (!b) return;\n    b.closed = true;\n    if (b.timer) { clearInterval(b.timer); b.timer = null; }\n  } catch { /* 静默 */ }\n}\n\n/**\n * 微信机器人通道的**绑定态跳变** → 匿名遥测（两态模型：未绑定 / 已绑定，见 docs/wechat-bot-channel.md §9）。\n *\n * 触发点：每一次把面板请求代理到 bridge 控制面之后顺手调用一次（本文件唯一的调用点）——\n *   **不新增定时器、不新增轮询**，只复用面板本来就会发生的读取节奏。\n *\n * 只报**跳变**：\n *   unbound → bound    = wechat_bound\n *   bound   → unbound  = wechat_unbound\n * 稳态（连续多次读到同一个 bound）**一条都不发**：面板在扫码/绑定期间会反复轮询 status，\n * 若按\"每次读到 bound:true 就记一条\"，同一台机器的一次绑定会被刷成几十条，指标直接失去意义。\n *\n * ★ 首次观测**不是**跳变：进程启动后第一次读到这个文件时，若它已经是 bound:true，说明这次绑定\n *   可能发生在几天前（宿主/面板过一段时间才会被打开）—— 此时只**播种基线**、不发事件。\n *   把\"启动时就已经绑好\"当成新绑定，会把历史存量每天都虚报一遍（这是最容易做错、也最难发现的一种虚高）。\n *   基线与\"是否观测过\"记在既有的跨进程文件 .telemetry-once.json（0600，与 first_remote_ok 同一份）：\n *   复用已有持久化约定，既不另造机制，也绝不去写 bridge 拥有的 .wechat-state.json。\n *\n * 隐私边界：只取 `bound` 一个布尔量，事件本体仍是 telemetryEventOf() 那 9 个字段（版本/os/arch/node…）。\n *   **绝不**上报 bot_id、bot_token、被绑定的微信用户标识、手机号或 .wechat-state.json 里的任何其它字段\n *   ——这些字段在本函数里连读都不读。\n * 静默边界：文件缺失 / 内容损坏 / 权限不足 / 半写（JSON 截断）= **本次没有观测**，\n *   既不抛异常进面板路由，也**不当作 unbound**（把它当 unbound 会在下次读到 false→true 之外的假跳变）。\n * 开关：DSH_REMOTE_TELEMETRY=0 → 直接返回，连文件都不读、连基线都不落（与其余遥测同一语义）。\n *\n * @returns {boolean|null} 本次观测到的 bound；未观测（开关关闭 / 读不出）为 null\n */\nfunction telemetryObserveWeChat(relayDir) {\n  try {\n    if (!telemetryEnabled()) return null;          // 关闭：零读取、零落盘、零请求\n    let state = null;\n    try {\n      state = JSON.parse(readFileSync(join(relayDir, WECHAT_STATE_FILE), \"utf8\"));\n    } catch {\n      return null;                                  // 缺失 / 损坏 / 半写：本次没有观测（不是 unbound）\n    }\n    if (!state || typeof state !== \"object\" || typeof state.bound !== \"boolean\") return null;\n    const bound = state.bound;\n    const baseline = telemetryWeChatBoundBaseline(relayDir);\n    if (baseline === bound) return bound;           // 稳态：不重复计数\n    telemetryMarkWeChatBound(relayDir, bound);      // 先落基线再入队：宁可丢一条，也绝不重复计数\n    if (baseline === null) return bound;            // 首次观测：只播种基线（见上方 ★）\n    telemetryRecord(relayDir, bound ? \"wechat_bound\" : \"wechat_unbound\");\n    return bound;\n  } catch {\n    return null;                                    // 遥测异常绝不冒泡到面板 / bridge 流程\n  }\n}\n\n/** 内部接口（仅供本仓库测试与隐私审计；不属于插件对外契约，也不被面板/浏览器半使用）。 */\nexport const __telemetryInternals = {\n  enabled: telemetryEnabled,\n  record: (relayDir, name, extra) => telemetryRecord(relayDir, name, extra),\n  flush: (relayDir) => telemetryFlush(relayDir),\n  installId: (relayDir) => telemetryInstallId(relayDir),\n  queueOf: (relayDir) => telemetryLoadQueue(relayDir, telemetryBook(relayDir)).slice(),\n  eventOf: (name, extra) => telemetryEventOf(name, extra),\n  // 归因函数也暴露出来：Windows 装机失败此前全落到 unknown，需要能被用例逐条锁住\n  failCodeFromText: (text) => telemetryFailCodeFromText(text),\n  failCodeFromError: (e) => telemetryFailCodeFromError(e),\n  // 宿主版本探测与字符串清洗也暴露出来：这两条是\"能不能答出兼容性问题\"的关键，\n  // 必须能被用例逐条锁住（含未知/非法值的降级行为）。\n  harnessVersion: () => harnessVersion(),\n  harnessVersionFromEntry: (entry) => harnessVersionFromEntry(entry),\n  harnessVersionFromRoot: (root) => harnessVersionFromRoot(root),\n  harnessVersionFromArgv: (argv) => harnessVersionFromArgv(argv),\n  harnessToken: (v) => telemetryToken(v),\n  updateTag: UPDATE_TAG,\n  eventNames: [...TELEMETRY_EVENT_NAMES],\n  failCodes: [...TELEMETRY_FAIL_CODES],\n  // 微信通道绑定态观测（跳变判定 + 基线落盘）也暴露出来：这是\"首次观测 != 跳变\"这条\n  // 最容易被写错、且写错就会让绑定数系统性虚高的规则，必须能被用例直接逐条锁住。\n  observeWeChat: (relayDir) => telemetryObserveWeChat(relayDir),\n  wechatBoundBaseline: (relayDir) => telemetryWeChatBoundBaseline(relayDir),\n  queueMax: TELEMETRY_QUEUE_MAX,\n  batchMax: TELEMETRY_BATCH_MAX,\n  bodyMax: TELEMETRY_BODY_MAX,\n  stateOf: (relayDir) => {\n    const b = telemetryBook(relayDir);\n    return { attempts: b.attempts, nextAt: b.nextAt, sending: b.sending, queueLen: telemetryLoadQueue(relayDir, b).length };\n  },\n  reset: (relayDir) => {\n    const b = telemetryBooks.get(relayDir);\n    if (b && b.timer) clearInterval(b.timer);\n    telemetryBooks.delete(relayDir);\n  },\n};\n\n/**\n * 安装信息上报（插件侧通道）：登录后把本机安装信息发给企业端，供「已登录用户升级插件后刷新版本号」\n * 之类的约定统计。无账号凭据不上报；失败静默（绝不阻塞面板、不弹错误）。\n * 契约：POST <api_url>/api/install-report，头 `authorization: Bearer <device-login JWT>`，\n * body { device_id?, install_source, install_version, harness_version, ref_code?, host_os, host_arch }，\n * 成功 200 {ok:true}；404/400 一律忽略（老服务端没有该接口时不能报错）。\n */\nconst INSTALL_REPORT_FILE = \".dsh-install-report.json\";\nconst INSTALL_REPORT_TTL_MS = 24 * 3600 * 1000;\nconst INSTALL_SOURCES = new Set([\"npx\", \"plugin_market\"]);\n/** 本机安装来源判据：环境变量 > 插件自愈记录 > 有运行环境即安装器部署 > 默认插件路径。 */\nfunction installSourceOf(relayDir) {\n  const env = String(process.env.DSH_BRIDGE_INSTALL_SOURCE || \"\").trim();\n  if (INSTALL_SOURCES.has(env)) return env;\n  if (existsSync(join(relayDir, PROVISIONED_MARKER))) return \"plugin_market\";\n  if (runtimeReady(relayDir)) return \"npx\";\n  return \"plugin_market\";\n}\n/**\n * 渠道归因码：安装器 `--ref <code>` 写进 .dsh-config.json 的 `ref_code`（3~12 位字母或数字）。\n * 规则与 clients/dsh-remote/src/channel-ref.mjs 同一份；插件包**不包含** clients/（files 只有 lib+runtime），\n * 所以这里保留这几行等价实现 —— 改契约时两边一起改。\n * 归一化 = NFKC（全角→半角）+ trim + 小写，与后端 channel.js normalizeCode 一致。\n * 缺失/非法 → 空串，调用方据此**整个省略**字段（绝不上报空串/脏值）。\n */\nfunction refCodeOf(cfg) {\n  const raw = cfg && cfg.ref_code;\n  let v = \"\";\n  if (typeof raw === \"number\") v = Number.isInteger(raw) && raw >= 0 ? String(raw) : \"\";\n  else if (typeof raw === \"string\") v = raw;\n  else return \"\";\n  const normalized = v.normalize(\"NFKC\").trim().toLowerCase();\n  return /^[a-z0-9]{3,12}$/.test(normalized) ? normalized : \"\";\n}\nasync function reportInstallOnce(relayDir, cfgOverride, opts = {}) {\n  const cfg = cfgOverride || loadConfig(relayDir);\n  if (!hasAccountCreds(cfg)) return { ok: false, skipped: \"no_credentials\" };\n  const source = installSourceOf(relayDir);\n  const version = PLUGIN_VERSION;\n  // 渠道归因码（可选）：服务端字段可选，缺失/非法就整个省略。\n  const refCode = refCodeOf(cfg);\n  const marker = join(relayDir, INSTALL_REPORT_FILE);\n  if (!opts.force) {\n    try {\n      const prev = JSON.parse(readFileSync(marker, \"utf8\"));\n      // ref 也是去重键的一部分：同一版本下后补 `--ref`（重跑安装器）时必须能补报一次，\n      // 否则归因会在 24h 窗口内被\"已上报过\"吞掉。\n      if (prev && prev.version === version && prev.source === source && (prev.ref || \"\") === refCode && Date.now() - Number(prev.at || 0) < INSTALL_REPORT_TTL_MS) {\n        return { ok: true, skipped: \"already_reported\" };\n      }\n    } catch { /* 首次上报 */ }\n  }\n  const token = await relayToken(relayDir).catch(() => \"\");\n  if (!token) return { ok: false, skipped: \"no_token\" };\n  const api = (cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n  const body = {\n    ...(cfg.device_id ? { device_id: String(cfg.device_id) } : {}),\n    install_source: source,\n    install_version: version,\n    // 宿主（DeepSeek Harness）版本：与 install_version（插件版本）是两个数，\n    // 只报插件版本时「是不是 DSH 升级导致的故障」答不出来（2026-10 生产反馈的普遍缺口）。\n    harness_version: harnessVersion(),\n    ...(refCode ? { ref_code: refCode } : {}),\n    host_os: process.platform,\n    host_arch: process.arch,\n  };\n  try {\n    const r = await fetch(`${api}/api/install-report`, {\n      method: \"POST\",\n      headers: {\n        authorization: `Bearer ${token}`,\n        \"content-type\": \"application/json\",\n        \"x-dsh-client\": `dsh-remote-web/${version}`,\n      },\n      body: JSON.stringify(body),\n      signal: AbortSignal.timeout(6000),\n    });\n    // 老服务端没有该接口（404）或字段不认（400）→ 忽略，绝不影响 UI\n    if (r.status === 400 || r.status === 404) return { ok: false, skipped: `http_${r.status}` };\n    if (!r.ok) return { ok: false, status: r.status };\n    try { writeFileSync(marker, JSON.stringify({ at: Date.now(), version, source, ref: refCode })); } catch { /* 非关键 */ }\n    return { ok: true, status: r.status, install_source: source, install_version: version, ...(refCode ? { ref_code: refCode } : {}) };\n  } catch (e) {\n    return { ok: false, skipped: `unreachable: ${e.message}` };\n  }\n}\n/** 上报节流入口（fire-and-forget）：失败最多 60s 再试一次；成功则按 version/source 去重。 */\nfunction maybeReportInstall(relayDir, opts = {}) {\n  const book = connectBook(relayDir);\n  const now = Date.now();\n  if (!opts.force && book.reportAt && now - book.reportAt < 60_000) return;\n  book.reportAt = now;\n  // 认证走 relayTokenWithReason（60s token 缓存 + 并发合并），因此启动/登录/轮询多次调用\n  // 也只会打一次 device-login，不会放大企业端认证请求。\n  reportInstallOnce(relayDir, null, opts).catch(() => { /* 静默失败：不影响 UI */ });\n}\n\n// ---------- 微信机器人通道（bridge 控制面代理） ----------\n//\n// 微信通道**不在本进程里**：它跑在 bridge（clients/dsh-remote/wechat-runtime.mjs）中，那里只\n// bind 127.0.0.1 的控制面。发现方式与鉴权（docs/wechat-bot-channel.md §3/§8/§10）：\n//   · 端口：<relayDir>/.wechat-control.json = {port,pid,started_at,header} —— **不含任何密钥**；\n//   · 密钥：<relayDir>/.dsh-config.json 的 bridge_secret（与 bridge 同源），放进\n//     `x-dsh-bridge-secret` 头，**只在宿主进程内使用，绝不下发浏览器**。\n//\n// 本半边只做代理：面板 → /dsh-remote/wechat/* → 控制面 /wechat/*。转发回来的一切按键名再脱敏一次\n// （任何名字含 token 的字段一律丢弃）——bridge 侧已有 sanitizeAccount，这里是第二道闸门，\n// 即使上游某天回归了漏脱敏、或新增了字段，浏览器也拿不到 bot_token（§8「面板 API 永不回显 token」）。\nconst WECHAT_CONTROL_FILE = \".wechat-control.json\";\nconst WECHAT_CONTROL_HEADER = \"x-dsh-bridge-secret\";\n/**\n * 微信通道的**面板状态文件** `{ bound, bot_id, bound_at, connected_at, last_push_ok_at, last_error }`\n * （bridge 侧写、0600；绑定模型只有「已绑定 / 未绑定」两态，见 docs/wechat-bot-channel.md §9）。\n * 宿主半边**只读不写** —— 它是 bridge 的财产；本半边只借 `bound` 这一个布尔量做匿名遥测的跳变判定\n * （其余字段一个都不读、更不可能外发，见下方 telemetryObserveWeChat 的隐私边界）。\n */\nconst WECHAT_STATE_FILE = \".wechat-state.json\";\n\n/** 控制面单次调用超时（本地回环，正常在毫秒级；超时 = bridge 卡住或端口被别的东西占了）。 */\nfunction wechatControlTimeoutMs() {\n  const n = Number(process.env.DSH_WECHAT_CONTROL_TIMEOUT_MS || 0);\n  return Number.isFinite(n) && n > 0 ? n : 6000;\n}\n/**\n * `GET /wechat/bind/poll` 是**长轮询**（bridge 侧一次可以挂到 35s 才回，见 wechat-channel.mjs 的\n * QR_LONG_POLL_TIMEOUT_MS）。对这一个路由沿用「短超时」会制造**假超时**——bridge 明明在正常等待\n * 扫码，面板却报「后台服务卡住了」，用户会去重启一个完全正常的后台服务。故只给它放宽，\n * 其余路由一律短超时（那种超时是真的卡住了）。\n */\nconst WECHAT_POLL_TIMEOUT_MS = 40_000;\n\n/** pid 是否还活着（EPERM = 存在但属于别人 → 视为活着）。 */\nfunction wechatProcessAlive(pid) {\n  try {\n    process.kill(pid, 0);\n    return true;\n  } catch (e) {\n    return !!(e && e.code === \"EPERM\");\n  }\n}\n\n/**\n * 读控制面发现文件。**不抛**：任何异常都翻成 {error:{code,error}} —— 因为每种失败对应的用户动作\n * 都不同（启动后台服务 / 重启 / 一键更新），绝不能塌成一句「失败」。\n * @returns {{port:number,pid:number}|{error:{code:string,error:string}}}\n */\nfunction readWeChatControl(relayDir) {\n  let raw;\n  try {\n    raw = readFileSync(join(relayDir, WECHAT_CONTROL_FILE), \"utf8\");\n  } catch {\n    return {\n      error: {\n        code: \"no_control_file\",\n        error: \"本机后台服务还没有运行微信机器人通道（找不到发现文件），通常是两个原因之一：后台服务没启动，或它的版本比面板旧、不支持微信机器人。请先到「📱 远程访问」面板启动后台服务；若已在运行，点那里的「一键更新」升级后再回到本页。\",\n      },\n    };\n  }\n  let info = null;\n  try { info = JSON.parse(raw); } catch { info = null; }\n  const port = info && Number.isInteger(info.port) ? info.port : 0;\n  if (!info || typeof info !== \"object\" || port <= 0 || port > 65535) {\n    return {\n      error: {\n        code: \"bad_control_file\",\n        error: `微信机器人通道的发现文件（${WECHAT_CONTROL_FILE}）内容无法识别，可能是写入中断或文件损坏。到「📱 远程访问」面板重启一次后台服务即可重建它，然后回到本页重试。`,\n      },\n    };\n  }\n  // 发现文件是**上一次**进程写下的：bridge 退出后它会残留。这时如实说「残留」，\n  // 而不是让用户对着「连接被拒绝」去猜——两种情况的处置动作不一样。\n  const pid = Number.isInteger(info.pid) && info.pid > 0 ? info.pid : 0;\n  if (pid && !wechatProcessAlive(pid)) {\n    return {\n      error: {\n        code: \"stale_control_file\",\n        error: `微信机器人通道的发现文件是上一次后台服务留下的（进程 ${pid} 已不在），现在没有进程在监听。到「📱 远程访问」面板启动/重启后台服务后回到本页重试。`,\n      },\n    };\n  }\n  return { port, pid };\n}\n\n/**\n * 递归丢弃任何**名字里含 token** 的字段（§8：面板 API 永不回显 bot_token）。\n * 只按键名过滤，其它字段照原样透传 —— 面板需要的字段一个不少。\n */\nfunction scrubWeChatTokens(value, depth = 0) {\n  if (depth > 6 || value === null || typeof value !== \"object\") return value;\n  if (Array.isArray(value)) return value.map((v) => scrubWeChatTokens(v, depth + 1));\n  const out = {};\n  for (const key of Object.keys(value)) {\n    if (/token/i.test(key)) continue;\n    out[key] = scrubWeChatTokens(value[key], depth + 1);\n  }\n  return out;\n}\n\n/**\n * 把一次面板请求代理到 bridge 控制面。\n *\n * @param {string} relayDir 配置目录\n * @param {string} routePath 控制面路径（如 \"/wechat/status\"）\n * @param {{method?:string, body?:any, timeoutMs?:number}} [init]\n * @returns {Promise<{ok:true, body:any}|{ok:false, status:number, code:string, error:string}>}\n *   失败一律带**各不相同**的人话文案（code 供面板/测试分流）；绝不把密钥或上游原始错误回给浏览器。\n */\nasync function wechatControlCall(relayDir, routePath, init) {\n  const ctl = readWeChatControl(relayDir);\n  if (ctl.error) return { ok: false, status: 503, code: ctl.error.code, error: ctl.error.error };\n\n  const secret = readBridgeSecret(relayDir);\n  if (!secret) {\n    // 没有密钥就不能调用控制面（bridge 侧同样会 403）。如实说是「本机还没拿到设备密钥」，\n    // 而不是伪装成连接故障——此时用户要做的动作是去登录 / 一键更新，不是重启。\n    return {\n      ok: false,\n      status: 503,\n      code: \"no_secret\",\n      error: \"本机配置里还没有设备密钥（bridge_secret），无法安全地调用后台服务的微信通道。请先到「📱 远程访问」面板登录一次（密钥会自动补齐），或点那里的「一键更新」重装运行环境，然后回到本页重试。\",\n    };\n  }\n\n  const opts = init || {};\n  const timeoutMs = Number(opts.timeoutMs) > 0 ? Number(opts.timeoutMs) : wechatControlTimeoutMs();\n  const hasBody = opts.body !== undefined && opts.body !== null;\n  const headers = { accept: \"application/json\", [WECHAT_CONTROL_HEADER]: secret };\n  if (hasBody) headers[\"content-type\"] = \"application/json\";\n\n  let res;\n  try {\n    res = await fetch(`http://127.0.0.1:${ctl.port}${routePath}`, {\n      method: opts.method || \"GET\",\n      headers,\n      body: hasBody ? JSON.stringify(opts.body) : undefined,\n      signal: AbortSignal.timeout(timeoutMs),\n    });\n  } catch (e) {\n    const name = String((e && e.name) || \"\");\n    const cause = String((e && e.cause && e.cause.code) || (e && e.code) || \"\");\n    if (name === \"TimeoutError\" || name === \"AbortError\" || /timeout/i.test(name)) {\n      return {\n        ok: false,\n        status: 504,\n        code: \"timeout\",\n        error: `等待后台服务的微信通道响应超时（超过 ${Math.round(timeoutMs / 1000)} 秒）。它可能正忙、卡住了，或端口被别的东西占住了。稍后重试；一直这样请到「📱 远程访问」面板重启后台服务。`,\n      };\n    }\n    if (cause === \"ECONNREFUSED\") {\n      return {\n        ok: false,\n        status: 502,\n        code: \"refused\",\n        error: \"后台服务的微信通道没有在监听（连接被拒绝）——多半是它刚刚重启完，或者已经退出了。等几秒再试；仍未恢复请到「📱 远程访问」面板重启后台服务。\",\n      };\n    }\n    return {\n      ok: false,\n      status: 502,\n      code: \"unreachable\",\n      error: `连接后台服务的微信通道失败${cause ? `（${cause}）` : \"\"}。请确认「📱 远程访问」面板里的后台服务正在运行，然后重试。`,\n    };\n  }\n\n  let text = \"\";\n  try { text = await res.text(); } catch { text = \"\"; }\n  let body = null;\n  try { body = text ? JSON.parse(text) : null; } catch { body = null; }\n  const upstreamError = body && typeof body === \"object\" && typeof body.error === \"string\" ? body.error : \"\";\n\n  // 鉴权/版本这类「上游说不出缘由」的失败，由本半边给出可据以行动的文案；\n  // 上游自己的业务错误（配对码不合法、二维码取不到…）则原样透传——那是写给用户看的原文。\n  if (res.status === 401) {\n    return {\n      ok: false,\n      status: 502,\n      code: \"unauthorized\",\n      error: \"后台服务拒绝了这次调用（设备密钥不匹配）。密钥可能刚被轮换，或后台服务是用旧密钥启动的。到「📱 远程访问」面板点一次「一键更新」补齐并重启后台服务，然后回到本页重试。\",\n    };\n  }\n  if (res.status === 403) {\n    return {\n      ok: false,\n      status: 502,\n      code: \"forbidden\",\n      error: \"后台服务没有配置设备密钥，因此关闭了微信通道的控制面（这是安全默认：没有密钥就拒绝一切，而不是放行）。到「📱 远程访问」面板点「一键更新」补齐运行环境与密钥后重试。\",\n    };\n  }\n  if (res.status === 404) {\n    return {\n      ok: false,\n      status: 502,\n      code: \"no_such_route\",\n      error: \"后台服务不认识这个微信通道接口，说明它比当前面板旧。到「📱 远程访问」面板点「一键更新」升级后台服务，然后回到本页重试。\",\n    };\n  }\n  if (!res.ok) {\n    return {\n      ok: false,\n      status: 502,\n      code: `upstream_${res.status}`,\n      error: upstreamError || `后台服务的微信通道返回了 HTTP ${res.status}，没有给出原因。稍后重试；一直这样点「📱 远程访问」里的「一键更新」升级后台服务。`,\n    };\n  }\n  if (body === null || typeof body !== \"object\") {\n    return {\n      ok: false,\n      status: 502,\n      code: \"bad_response\",\n      error: \"后台服务的微信通道返回了无法解析的内容（不是 JSON），多半是版本不匹配。到「📱 远程访问」面板点「一键更新」升级后台服务后重试。\",\n    };\n  }\n  return { ok: true, body: scrubWeChatTokens(body) };\n}\n\n/** 代理一次微信通道调用并回写响应（成功体原样透传；失败体统一 {ok:false, code, error}）。 */\nasync function sendWeChatProxy(relayDir, res, routePath, init) {\n  const r = await wechatControlCall(relayDir, routePath, init);\n  // 匿名遥测：顺手观测一次绑定态（只认跳变，稳态不重复计数；DSH_REMOTE_TELEMETRY=0 时是零副作用 no-op）。\n  // 放在这里而不是只放 status 路由：bind/verify 与 unbind 也会让 bridge 改写状态文件，\n  // 那时面板可能还没轮到下一次轮询 —— 把观测点挂在唯一的代理出口上，六条路由一个不漏。\n  telemetryObserveWeChat(relayDir);\n  if (r.ok) return sendJson(res, 200, r.body);\n  return sendJson(res, r.status, { ok: false, code: r.code, error: r.error });\n}\n\n// ============================================================\n// 本地宿主路由的跨站防护（2026-09-27 安全审计）\n//\n// 背景：本插件把 /dsh-remote/* 注册在**本机** dsh web 上，这一层没有任何鉴权\n//   （设计如此：桌面端面板与页面同源，靠\"只有本机能访问\"来保证安全）。\n//   但\"只有本机能访问\"不等于\"同源\" —— 浏览器里任何网页都能向 127.0.0.1:3080 发请求：\n//     · 经典 CSRF：evil.com 表单/fetch(no-cors) POST /dsh-remote/self/uninstall、/config\n//     · DNS rebinding：把 evil.com 解析到 127.0.0.1，浏览器视为同源，于是能**读到**\n//       /dsh-remote/diag/bundle（诊断包，含本机路径与配置）与\n//       /dsh-remote/access-key（能签发设备访问密钥 = 拿到这台电脑的远程控制权）\n//   这些路由里有卸载插件、改配置、重启 harness、签发访问密钥，必须挡住。\n//\n// 判据（两条独立）：\n//   ① Host 白名单：只认 loopback authority。rebinding 时 Host 是攻击者域名 → 拒；\n//   ② Origin / Sec-Fetch-Site：带 Origin 且与 Host 不同源 → 拒；sec-fetch-site: cross-site → 拒。\n//\n// 为什么不会误伤手机端：隧道请求由 dsh-bridge 剥掉 host/origin/sec-fetch-*\n//   （clients/dsh-remote/dsh-bridge.mjs 的 STRIP_REQ_HEADERS），再由 undici 补上\n//   Host: 127.0.0.1:<port>。所以隧道流量天然过 ①、且不带 Origin 而过 ②。\n//\n// 逃生舱：DSH_REMOTE_LOCAL_GUARD=0 关闭整层；\n//   DSH_REMOTE_TRUSTED_HOSTS=a.com,b（放在 dsh web 前面的反向代理需要它）。\n// ============================================================\nconst LOOPBACK_HOST_RE = /^(127\\.0\\.0\\.1|localhost|\\[::1\\]|::1)(:\\d+)?$/i;\n/**\n * 私网 / 链路本地 / mDNS 的 authority。\n *\n * 为什么必须放行：本插件**自己**会把 dsh web 绑到 `0.0.0.0`（见 `cordis.patch.yml` 里那段\n * `remote-web-ui lan-bind block`）——「局域网直连」是产品功能（同一 Wi-Fi 下的平板/手机直连），\n * 只认 loopback 会把它整个挡死。真机验收时就是这么发现的。\n *\n * 放行它们**不等于**放开安全边界：\n *   · DNS rebinding 仍被挡：攻击者页面把 evil.com 指到本机时，请求头里的 Host 是 **evil.com**\n *     （浏览器按 URL 里的主机名发 Host，不看它解析到哪个 IP）→ 仍然命中 bad-host；\n *   · CSRF 仍被挡：跨站请求的 Origin 与 Host 必然不同源 → 命中 origin-mismatch（下面 ②）；\n *   · 唯一多让出来的是「Host 恰好是私网 IP 字面量」的请求，而它只可能来自**同源页面**\n *     （也就是本机自己服务的那个页面），不构成新的攻击面。\n */\nconst PRIVATE_HOST_RE = new RegExp(\n  \"^(?:\" + [\n    \"10\\\\.\\\\d{1,3}\\\\.\\\\d{1,3}\\\\.\\\\d{1,3}\",\n    \"192\\\\.168\\\\.\\\\d{1,3}\\\\.\\\\d{1,3}\",\n    \"172\\\\.(?:1[6-9]|2\\\\d|3[01])\\\\.\\\\d{1,3}\\\\.\\\\d{1,3}\",\n    \"169\\\\.254\\\\.\\\\d{1,3}\\\\.\\\\d{1,3}\",\n    \"[a-z0-9][a-z0-9-]*\\\\.local\",\n    \"\\\\[(?:fe80|fc|fd)[0-9a-f:]*\\\\]\"\n  ].join(\"|\") + \")(:\\\\d+)?$\",\n  \"i\"\n);\nconst LOCAL_GUARD_LOGGED = new Map(); // reason -> 上次告警时间（同一原因 60s 只报一次，避免刷日志）\n\n/** 只读地判断一个请求是否来自\"本机同源页面\"。返回 null=放行，否则返回拒绝原因。\n *  导出仅为可测（见 test/local-route-guard.test.mjs）。 */\nexport function localRequestBlocked(req) {\n  if (String(process.env.DSH_REMOTE_LOCAL_GUARD || \"\") === \"0\") return null;\n  const extra = String(process.env.DSH_REMOTE_TRUSTED_HOSTS || \"\")\n    .split(\",\").map((s) => s.trim().toLowerCase()).filter(Boolean);\n  const headers = (req && req.headers) || {};\n  const host = String(headers.host || \"\").trim().toLowerCase();\n  if (!host) return \"missing-host\";\n  if (!LOOPBACK_HOST_RE.test(host) && !PRIVATE_HOST_RE.test(host) && !extra.includes(host)) return \"bad-host\";\n  const origin = String(headers.origin || \"\").trim().toLowerCase();\n  // Origin: null（file:// 或 sandbox iframe）不在这里判，交给下面的 sec-fetch-site\n  if (origin && origin !== \"null\") {\n    let oh = \"\";\n    try { oh = new URL(origin).host.toLowerCase(); } catch { return \"bad-origin\"; }\n    if (oh !== host && !extra.includes(oh)) return \"origin-mismatch\";\n  }\n  if (String(headers[\"sec-fetch-site\"] || \"\").trim().toLowerCase() === \"cross-site\") return \"cross-site\";\n  return null;\n}\n\nfunction registerRoutes(ctx, relayDir) {\n  // 本插件所在 profile：与配对备份的持久数据目录共用同一份推导（pluginProfileDir），\n  // 避免\"卸载删的目录\"和\"备份写的目录\"各算各的（2026-10-17 双份备份加固时抽出）。\n  const profileDir = pluginProfileDir();\n  const routes = [\n    // 自管理：版本信息 / 检查更新 / 一键更新 / 更新日志 / 彻底卸载\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/self\",\n      handler: async (_req, res) => {\n        const runtimeReady = existsSync(join(relayDir, \"dsh-setup.mjs\"));\n        // channel：当前更新通道（面板要显示出来 —— 否则预发版用户会点出一个方向相反的操作）\n        sendJson(res, 200, { ok: true, version: PLUGIN_VERSION, channel: UPDATE_TAG, runtimeReady, relayDir });\n      },\n    },\n    {\n      /**\n       * `GET /dsh-remote/doctor` —— 面板「复制诊断信息」用的**一条命令自检**输出（只读）。\n       *\n       * 为什么单开一条路由、而不是塞进 bridge-status 的负载：`doctor` 要**起一次子进程**跑\n       * 运行环境里的 `dsh-setup.mjs doctor`（复用唯一实现 —— 插件半不抄第二份）。而 bridge-status\n       * 是 2~3 秒一次的长轮询，往那里塞子进程等于每 3 秒 fork 一个 node。\n       * 这里只在用户**真的点**「复制诊断信息」时跑一次（10 秒上限；任何失败都退回原有文本）。\n       */\n      method: \"GET\",\n      path: \"/dsh-remote/doctor\",\n      handler: async (_req, res) => {\n        sendJson(res, 200, await runDoctorText(relayDir));\n      },\n    },\n    {\n      // 取消「正在进行的更新」：结束挂死的更新子进程 + 清标记。\n      // 面板在「疑似卡住」时提供这个按钮 —— 此前用户面对的是没有时间、没有日志、没有按钮的 spinner。\n      // 注意：取消**不写 update_failed 遥测**（用户主动取消不是失败），只在本地留一条可查询记录。\n      method: \"POST\",\n      path: \"/dsh-remote/self/update/cancel\",\n      handler: async (_req, res) => {\n        updateCancelledDirs.add(relayDir); // 先落闸：kill 会触发 exit，那里的重试逻辑必须看到\"已取消\"\n        const marker = join(relayDir, UPDATE_MARKER);\n        const info = readMarkerInfo(marker);\n        const pid = Number(info && info.pid);\n        let killed = false;\n        if (Number.isInteger(pid) && pid > 0 && pidAlive(pid) === true) killed = killPid(pid, \"SIGKILL\");\n        stopProgressWatch(UPDATE_WATCH_KEY);\n        let cleared = false;\n        try { rmSync(marker, { force: true }); cleared = !existsSync(marker); } catch { /* ignore */ }\n        appendLogLine(relayDir, UPDATE_LOG, `[update] 用户取消：结束进程(${killed ? \"已结束\" : \"无活动进程\"})，清标记(${cleared ? \"成功\" : \"失败\"})`);\n        if (cleared) noteUpdateFailure(relayDir, \"更新已被取消，可以重新点「一键更新」再试一次\", \"user_cancelled\");\n        sendJson(res, 200, { ok: true, killed, cleared, detail: cleared ? \"已取消\" : \"取消失败：标记未能清除\" });\n      },\n    },\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/self/update-check\",\n      handler: async (_req, res) => {\n        const latest = await npmLatestVersion();\n        const current = PLUGIN_VERSION;\n        // 正规比较：注册表版本**严格大于**本地版本才算有更新。\n        // 这样 0.6.4 < 0.6.4（正式版发布后预设版会正确提示升级），\n        // 而 0.6.4-beta.10 < 0.6.4 也能正确判断；解析不了时退回朴素不等（保守提示）。\n        const cmp = compareVersions(latest, current);\n        const outdated = cmp === null ? Boolean(latest && latest !== current) : cmp > 0;\n        sendJson(res, 200, { ok: true, current, latest, outdated });\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/self/update\",\n      handler: async (_req, res) => {\n        sendJson(res, 200, { ok: true, ...(await runOnlineUpdate(relayDir)) });\n      },\n    },\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/self/update-log\",\n      handler: async (_req, res) => {\n        const failure = recentUpdateFailure(relayDir);\n        const markerInfo = readMarkerInfo(join(relayDir, UPDATE_MARKER));\n        const running = existsSync(join(relayDir, UPDATE_MARKER));\n        const live = progressInfoOf(UPDATE_WATCH_KEY);\n        const idleMs = running ? progressIdleMs(relayDir, UPDATE_LOG, markerInfo && markerInfo.at) : 0;\n        const idleThresholdMs = stallIdleMs(\"update\");\n        sendJson(res, 200, {\n          ok: true,\n          running,\n          channel: UPDATE_TAG,\n          log: tailOf(join(relayDir, UPDATE_LOG)),\n          // 供前端在\"没成功\"时如实报错（此前失败只写日志，界面显示\"已完成\"）\n          failure: failure ? { detail: failure.detail, failCode: failure.failCode, at: failure.at } : null,\n          version: PLUGIN_VERSION,\n          // 【0.6.9】让「卡住」在界面上可见：已用时 / 距上次日志变化多久 / 是否超过阈值。\n          // 用日志 mtime 判定 —— 宿主重启后依然有效（实测：重启也清不掉的永久「更新中」）。\n          startedAt: (markerInfo && markerInfo.at) || (live && live.startedAt) || 0,\n          elapsedMs: running && markerInfo ? Date.now() - markerInfo.at : (live ? live.elapsedMs : 0),\n          idleMs,\n          idleThresholdMs,\n          stalled: Boolean(running && idleMs > idleThresholdMs) || Boolean(live && live.stalled)\n        });\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/self/uninstall\",\n      handler: async (_req, res) => {\n        // 彻底卸载 = ① 插件 profile 清理（快、纯 fs、可预期）② 运行时/bridge 清理（慢、要调外部命令）\n        //\n        // ⚠️ 顺序是刻意的，别改回去（2026-09-18 用户实测的僵死故障）：\n        //   旧实现把**慢的** uninstallRuntime 排在最前、uninstallSelf 排在其后，于是\n        //   uninstallRuntime 里任何一次 spawnSync 卡住（Windows 沙箱拦 schtasks，而 spawnSync 的\n        //   timeout 在 Windows 上并不可靠，实测 18s+ 未返回），uninstallSelf 就**永远不执行**\n        //   → 用户看到「点了卸载、插件纹丝不动」，而且整个 dsh web 僵死（端口在听、无响应）。\n        //   现在：先做真正\"卸载掉插件\"的部分 → 立刻关掉自愈 → 立刻回响应 → 慢步骤交独立子进程。\n        let prof = { removedPatch: false, removedDep: false, removedBundle: false, removedDir: false };\n        try {\n          prof = uninstallSelf(relayDir, profileDir, join(profileDir, \"cordis.patch.yml\"), join(profileDir, \"package.json\"));\n        } catch (e) {\n          console.warn(`[dsh-remote-web] 卸载插件引用失败: ${e.message}`);\n        }\n        // 必须在慢步骤之前置位：否则慢步骤期间自愈有机会把 bridge / 配置目录再拉回来\n        markUninstalled(relayDir);\n        // 运行时清理交给独立进程：宿主事件循环绝不做同步子进程调用\n        const cleanup = spawnRuntimeCleanupDetached(relayDir, profileDir);\n        const cleanupMode = cleanup.ok ? \"deferred\" : \"in-process\";\n        const bits = [];\n        if (prof.removedPatch || prof.removedDep || prof.removedBundle || prof.removedDir) bits.push(\"插件引用与本地文件已移除\");\n        bits.push(cleanup.ok\n          ? \"bridge 自启动项与本地配置目录（账号/密钥/固化运行时等）正在后台清理\"\n          : `bridge 自启动项与配置目录的后台清理未能启动（${cleanup.detail}），已改在本进程内清理`);\n        bits.push(\"请重启 dsh web 后完全卸载生效（本插件与「远程访问」面板将消失）；如需再次使用，在插件市场重新安装即可。\");\n        sendJson(res, 200, {\n          ok: true,\n          ...prof, // removedPatch / removedDep / removedBundle / removedDir(profile 插件目录)\n          runtimeCleanup: cleanupMode,\n          cleanupLog: cleanup.log,\n          relayDir,\n          detail: bits.join(\"；\"),\n        });\n        // 兜底：助手起不来（relayDir 不可写 / node 起不来）时才在进程内清理。\n        // **必须放在响应之后**：这条路径会阻塞事件循环，绝不能让用户先等它。\n        if (!cleanup.ok) {\n          setTimeout(() => {\n            try { uninstallRuntime(relayDir, profileDir); }\n            catch { /* 非致命：残留可由用户手动清理 */ }\n          }, 50).unref?.();\n        }\n      },\n    },\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/status\",\n      handler: async (_req, res) => {\n        // 按需补齐浏览器会话 Cookie(不 await:状态接口不能被本地换 Cookie 拖慢)。\n        // 面板轮询会持续触达本接口 → 手机端的 401 会在秒级内自愈。\n        void ensureHarnessCookie(ctx, relayDir).catch(() => {});\n        sendJson(res, 200, await composeStatus(relayDir));\n      },\n    },\n    // 连接阶段短轮询端点（面板 2~3s 一次，非 online 时自动推进；online 后退避到 15s）。\n    // 返回前先执行自动闭环动作（缺环境→补装 / 有账号没进程→拉起 / 卡死标记→清理），\n    // 于是「登录后自动连上」不需要任何按钮或刷新；每步都自带退避，失败不会打成风暴。\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/bridge-status\",\n      handler: async (_req, res) => {\n        ensureConnection(relayDir);\n        maybeReportInstall(relayDir);\n        void ensureHarnessCookie(ctx, relayDir).catch(() => {}); // 同上:手机端授权会话自愈\n        telemetryRuntimeProbe(relayDir); // 匿名遥测：运行环境刚补齐 → runtime_ready（不额外起定时器）\n        const connect = await composeConnect(relayDir);\n        telemetryObserveConnect(relayDir, connect); // 匿名遥测：bridge_started / bridge_registered / 掉线\n        sendJson(res, 200, { ok: true, connect });\n      },\n    },\n    // 面板打开（浏览器半在「远程访问」栏目首次渲染时调一次）：每进程只记一次。\n    // 只发事件名，不含任何账号/内容/设备信息；DSH_REMOTE_TELEMETRY=0 时静默丢弃。\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/telemetry/panel-opened\",\n      handler: async (_req, res) => {\n        telemetryOnce(relayDir, \"panel_opened\");\n        sendJson(res, 200, { ok: true });\n      },\n    },\n    // 镜像页就绪耗时（D1 在 clients/dsh-remote/mobile-adapter.mjs 里量，经此入队）：\n    //   body = { ms: 耗时毫秒, at: 事件时刻 epoch ms, outcome: \"ok\"|\"slow\" }\n    // 契约（926 迭代 §2）：事件名固定 mirror_load，ms 钳制 [0, 600000]，outcome ∈ {ok, slow}。\n    //\n    // 🔒 入参校验失败**静默丢弃**但仍回 200 {ok:true}：这条上报是手机镜像页加载路径上的\n    //    fire-and-forget，任何 4xx 都可能被页面当成\"功能坏了\"而冒泡给用户；统计丢一条无所谓，\n    //    打扰用户不可接受。校验放在**路由里**（而不是 telemetryRecord 里）是因为遥测入队\n    //    必须保持\"只认白名单、绝不抛\"的既有语义，业务校验不属于那一层。\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/telemetry/mirror-load\",\n      handler: async (req, res) => {\n        try {\n          const buf = await readBodyBuffer(req);\n          let body = null;\n          try { body = JSON.parse(buf.toString(\"utf8\") || \"{}\"); } catch { body = null; }\n          const ms = Number(body && body.ms);\n          if (body && Number.isFinite(ms) && ms >= 0 && ms <= 600000) {\n            const atRaw = Number(body.at);\n            const at = Number.isFinite(atRaw) && atRaw > 0 ? Math.round(atRaw) : 0;\n            telemetryRecord(relayDir, \"mirror_load\", {\n              ms: Math.round(ms),\n              at,\n              outcome: body.outcome === \"slow\" ? \"slow\" : \"ok\",\n            });\n          }\n        } catch { /* 体读不到/超限：静默 */ }\n        sendJson(res, 200, { ok: true });\n      },\n    },\n    // 手动重试（error 阶段的「重试」按钮）：清掉退避计数立刻再走一遍闭环。\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/connect/retry\",\n      handler: async (_req, res) => {\n        const action = ensureConnection(relayDir, { force: true });\n        maybeReportInstall(relayDir, { force: true });\n        await sleep(600); // 给 launchctl 一点进入运行态的时间，重试点下去立刻能看到「正在启动 Bridge…」\n        const connect = await composeConnect(relayDir);\n        telemetryObserveConnect(relayDir, connect); // 匿名遥测：同 bridge-status（去重后不会重复计数）\n        sendJson(res, 200, { ok: true, retried: true, action: action && action.action ? action.action : \"none\", connect });\n      },\n    },\n    // ── 🧾 故障上报（用户主动）与「让 DeepSeek 帮我修」提示词（0.6.12） ──────────\n    // 隐私红线：**绝不**后台自动上传日志。这里只提供「预览 → 用户确认 → 提交」，\n    // 以及把提示词交给用户，让他自己那台机器的 DSH 去修 —— 两条都由用户主动触发。\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/diag/bundle\",\n      handler: async (_req, res) => {\n        // 预览 = 用户点确认后**真正会发出去**的全文（正文 + 分片），一字不多一分不少\n        const built = await buildDiagReport(relayDir, { attachLogs: true, note: \"\" });\n        sendJson(res, 200, {\n          ok: true,\n          title: built.title,\n          summary: built.summary,\n          parts: built.parts,\n          noteMax: DIAG_NOTE_MAX,\n          partMax: DIAG_PART_MAX,\n        });\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/diag/report\",\n      handler: async (req, res) => {\n        const body = await readJsonBody(req);\n        if (body.__parseError) return sendJson(res, 400, { ok: false, code: \"bad_request\", error: \"上报数据不是合法 JSON，请刷新页面重试。\" });\n        if (body.__tooLarge) return sendJson(res, 413, { ok: false, code: \"too_large\", error: \"报告内容过大（超过 256KB），请只保留结论部分。\" });\n        let built;\n        try {\n          built = await buildDiagReport(relayDir, {\n            note: body.note, attachLogs: body.attachLogs !== false, report: body.report,\n          });\n        } catch (e) {\n          return sendJson(res, 500, { ok: false, code: \"bundle_failed\", error: `组装诊断信息失败：${e.message}` });\n        }\n        let created;\n        try {\n          created = await submitFeedback(relayDir, {\n            kind: \"feedback\", category: \"bug\", title: built.title, content: built.summary, contact: \"\",\n          });\n        } catch (e) {\n          return sendJson(res, e.status && e.status < 500 ? e.status : 502, {\n            ok: false, code: e.code || \"submit_failed\", error: `上报失败：${e.message}`,\n          });\n        }\n        const id = created?.feedback?.id || created?.id || \"\";\n        const threadToken = created?.thread_token || \"\";\n        // 日志/报告分片：作为**同一条反馈的回复**追加（服务端正文 2000 字硬限；分片失败不影响正文）\n        const warnings = [];\n        let sent = 0;\n        for (const part of built.parts) {\n          if (!id) break;\n          const r = await replyFeedback(relayDir, id, part).catch(() => ({ ok: false }));\n          if (r.ok) sent += 1;\n          else if (!warnings.includes(\"部分日志分片未能上传（正文已到达，不影响定位）\")) warnings.push(\"部分日志分片未能上传（正文已到达，不影响定位）\");\n        }\n        appendLogLine(relayDir, AUTO_INSTALL_LOG,\n          `[dsh-remote-web] 用户主动上报故障诊断（${id || \"?\"}，正文 1 条 + 分片 ${sent}/${built.parts.length}）`);\n        sendJson(res, 200, { ok: true, id, threadToken, parts: sent, totalParts: built.parts.length, warnings });\n      },\n    },\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/diag/fix-prompt\",\n      handler: async (_req, res) => {\n        const conn = await composeConnect(relayDir);\n        const prompt = buildFixPrompt({\n          relayDir,\n          bridgeLogPath: join(relayDir, BRIDGE_LOG_FILE),\n          installLogPath: join(relayDir, AUTO_INSTALL_LOG),\n          pluginVersion: PLUGIN_VERSION,\n          runtimeVersion: runtimeVersionOf(relayDir),\n          upstreamUrl: conn.upstreamUrl,\n          phaseText: `${conn.text}${conn.detail ? \" \" + conn.detail : \"\"}`,\n        });\n        sendJson(res, 200, { ok: true, prompt, reportTitle: REPORT_TITLE, reportFormat: REPORT_FORMAT, reportKeys: REPORT_KEYS });\n      },\n    },\n    // ── 🤖 微信机器人通道（设置页「🤖 微信机器人」栏目） ──────────────────────\n    // 这六条只做代理：真正的协议与扫码状态机在 bridge 里（docs/wechat-bot-channel.md §3/§10）。\n    // 失败一律是 5xx + {ok:false, code, error:<人话>}：面板按 code/文案分流，绝不塌成「失败」两个字。\n    // 路由与契约一一对应，不多也不少（多出来的字段都可能变成 bot_token 的泄漏面）。\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/wechat/status\",\n      handler: async (_req, res) => {\n        await sendWeChatProxy(relayDir, res, \"/wechat/status\");\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/wechat/bind/start\",\n      handler: async (_req, res) => {\n        await sendWeChatProxy(relayDir, res, \"/wechat/bind/start\", { method: \"POST\" });\n      },\n    },\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/wechat/bind/poll\",\n      handler: async (_req, res) => {\n        // 长轮询：只有这一条放宽超时（理由见 WECHAT_POLL_TIMEOUT_MS）\n        await sendWeChatProxy(relayDir, res, \"/wechat/bind/poll\", { timeoutMs: WECHAT_POLL_TIMEOUT_MS });\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/wechat/bind/verify\",\n      handler: async (req, res) => {\n        // 只转发手机微信上那串数字配对码；不认识的字段一律不带过去（控制面只认 {code}）。\n        const body = await readJsonBody(req);\n        if (body.__parseError) {\n          return sendJson(res, 400, { ok: false, code: \"bad_request\", error: \"配对码提交的数据不是合法 JSON，请重新输入。\" });\n        }\n        const code = String(body.code == null ? \"\" : body.code).trim();\n        await sendWeChatProxy(relayDir, res, \"/wechat/bind/verify\", { method: \"POST\", body: { code } });\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/wechat/bind/cancel\",\n      handler: async (_req, res) => {\n        await sendWeChatProxy(relayDir, res, \"/wechat/bind/cancel\", { method: \"POST\" });\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/wechat/unbind\",\n      handler: async (_req, res) => {\n        await sendWeChatProxy(relayDir, res, \"/wechat/unbind\", { method: \"POST\" });\n      },\n    },\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/account\",\n      handler: async (_req, res) => {\n        sendJson(res, 200, { ok: true, account: await relayAccount(relayDir) });\n      },\n    },\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/quota\",\n      handler: async (_req, res) => {\n        sendJson(res, 200, { ok: true, quota: await relayQuota(relayDir) });\n      },\n    },\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/invite-records\",\n      handler: async (_req, res) => {\n        sendJson(res, 200, { ok: true, ...(await relayInviteRecords(relayDir)) });\n      },\n    },\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/remote-url\",\n      handler: async (_req, res) => {\n        const pub = await relayFetch(relayDir, \"/api/public-config\");\n        const body = pub.ok && pub.body && typeof pub.body === \"object\" ? pub.body : {};\n        sendJson(res, 200, {\n          ok: true,\n          remoteUrl: body.app_url || DEFAULT_APP_URL,\n          relayReachable: pub.ok,\n          publicConfig: body\n        });\n      },\n    },\n    // 交流群二维码（设置面板「加入交流群」按钮 + 用户反馈页展示；未配置返回空串，UI 不展示入口）\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/community\",\n      handler: async (_req, res) => {\n        sendJson(res, 200, { ok: true, ...(await communityInfo(relayDir)) });\n      },\n    },\n    // 📄 会员服务购买协议 URL（购买入口的《会员服务购买协议》链接；public-config.agreement_url → 兜底）\n    //    永远 200 ok:true + 一个可点 URL：协议链接不得成为购买流程的故障点。\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/purchase-agreement\",\n      handler: async (_req, res) => {\n        sendJson(res, 200, await purchaseAgreementInfo(relayDir));\n      },\n    },\n    // 一次性访问密钥（📱 远程访问卡）：GET 即创建新 key，企业端 POST /api/auth-key（Bearer）\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/access-key\",\n      handler: async (_req, res) => {\n        await proxyCreateAccessKey(relayDir, res);\n      },\n    },\n    // 已授权设备列表（企业端 POST /api/mobile-sessions，Bearer）\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/mobile-sessions\",\n      handler: async (_req, res) => {\n        await proxyMobileSessions(relayDir, res);\n      },\n    },\n    // 取消已授权设备配对（企业端 POST /api/mobile-sessions/:id/revoke，Bearer）\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/mobile-sessions/revoke\",\n      handler: async (req, res) => {\n        await proxyRevokeMobileSession(relayDir, req, res);\n      },\n    },\n    // 删除已授权设备记录（整行删除并拉黑 jti；企业端 DELETE /api/mobile-sessions/:id，Bearer）\n    {\n      method: \"DELETE\",\n      path: \"/dsh-remote/mobile-sessions/delete\",\n      handler: async (req, res) => {\n        await proxyDeleteMobileSession(relayDir, req, res);\n      },\n    },\n    // 清理本人全部已解绑（revoked）记录（企业端 POST /api/mobile-sessions/purge，Bearer）\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/mobile-sessions/purge\",\n      handler: async (_req, res) => {\n        await proxyPurgeMobileSessions(relayDir, res);\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/config\",\n      handler: async (req, res) => {\n        const body = await readJsonBody(req);\n        if (body.__parseError) return sendJson(res, 400, { ok: false, error: \"JSON 解析失败\" });\n        const cfg = loadConfig(relayDir);\n        const mode = body.mode === \"local\" ? \"local\" : \"saas\";\n        if (mode === \"local\") {\n          // 自建模式:服务器地址 + 访问密钥(免账号体系;随时可切回 SaaS)\n          const selfHostUrl = String(body.selfHostUrl ?? \"\").trim().replace(/^https?:\\/\\//, \"\").replace(/\\/+$/, \"\");\n          const localKey = String(body.localKey ?? \"\").trim();\n          if (!selfHostUrl || !localKey) return sendJson(res, 400, { ok: false, error: \"自建模式需要服务器地址与访问密钥\" });\n          cfg.tunnel_url = `wss://${selfHostUrl}`;\n          cfg.local_key = localKey;\n        } else {\n          const phone = String(body.phone ?? \"\").trim();\n          const password = String(body.password ?? \"\");\n          if (!phone || !password) return sendJson(res, 400, { ok: false, error: \"手机号与密码必填\" });\n          const accountChanged = (cfg.phone || cfg.email || \"\") !== phone || Boolean(cfg.email && cfg.email !== phone);\n          cfg.phone = phone;\n          cfg.password = password;\n          delete cfg.email;\n          if (accountChanged) {\n            delete cfg.device_id;\n            delete cfg.device_private_key;\n            delete cfg.device_public_key;\n          }\n          // SaaS 权威归一化：清除自建残留(local_key/假 tunnel_url)，api/tunnel 一律按云端重算\n          applySaaSMode(cfg);\n          // device-login 共享密钥自愈：只装插件的路径没有安装器那一步，缺密钥会导致\n          // 「首次安装后立即登录」时面板拿不到二维码/设备列表（旧版要等后台自愈或手动刷新）。\n          // 这里在启动 bridge 之前补齐，bridge 首次启动即可带上密钥。\n          if (!cfg.bridge_secret) {\n            // 3s 上限：这次取密钥在登录响应路径上，宁可先放行（后续请求还会自愈）也不拖慢登录\n            const secret = await bridgeSecretOf(relayDir, cfg, { timeoutMs: 3000 });\n            if (secret) cfg.bridge_secret = secret;\n          }\n        }\n        // 账号/模式变化 → 先停掉旧 bridge 并作废它的注册证据，否则新账号永远等不到这台设备\n        const accountFpBefore = accountFingerprintOf(loadConfig(relayDir));\n        saveConfig(relayDir, cfg);\n        // 配对成功即备份（2026-10-17 事故）：.dsh-config.json 里是账号配对+设备密钥，\n        // 一旦被误删/写坏，用户可以一键恢复最近一份（不自动恢复，见 setupStateOf）。\n        backupConfigFile(relayDir);\n        invalidateRelayToken(relayDir); // 账号可能变了：丢弃旧 token 缓存，立即用新账号认证\n        if (accountFingerprintOf(cfg) !== accountFpBefore) resetBridgeForAccountChange(relayDir, \"账号/模式已变更\");\n        const bridgeRestart = startBridge(relayDir);\n        // 登录成功即上报本机安装信息（企业端用于「升级插件后刷新版本号」约定）；失败静默。\n        maybeReportInstall(relayDir, { force: true });\n        sendJson(res, 200, { ok: true, bridgeRestart, ...(await composeStatus(relayDir)) });\n      },\n    },\n    {\n      /**\n       * 一键恢复历史配对备份（2026-10-17 事故）。\n       *\n       * 只在用户**显式点击**时调用：绝不自动恢复 —— 旧备份可能是别人的账号/已失效的凭据，\n       * 自动套用会把这台设备绑到错误账号（比\"未配对\"更糟）。恢复前 restoreConfigBackup 会先把\n       * 当前配置再备份一份（若存在），所以这一步随时可回滚。\n       * body = {} → 恢复最新一份；body = { backup: \"<文件名>\" } → 恢复指定一份。\n       */\n      method: \"POST\",\n      path: \"/dsh-remote/config/restore\",\n      handler: async (req, res) => {\n        const body = await readJsonBody(req);\n        if (body.__parseError) return sendJson(res, 400, { ok: false, error: \"JSON 解析失败\" });\n        const backupName = typeof body.backup === \"string\" ? body.backup : \"\";\n        const restored = restoreConfigBackup(relayDir, backupName);\n        if (!restored.ok) {\n          const msg = restored.reason === \"no-backup\" || restored.reason === \"no-such-backup\"\n            ? \"没有可恢复的配对备份（备份目录为空或文件名不存在）\"\n            : \"恢复配对备份失败（磁盘不可写/文件损坏），请重新登录一次\";\n          return sendJson(res, restored.reason === \"failed\" ? 500 : 404, { ok: false, code: restored.reason, error: msg });\n        }\n        // 恢复的可能是旧账号的配对：与\"登录\"同一套收尾 —— 旧 token 作废、旧 bridge 停掉重拉。\n        invalidateRelayToken(relayDir);\n        resetBridgeForAccountChange(relayDir, \"从历史备份恢复配对信息\");\n        const bridgeRestart = startBridge(relayDir);\n        // 恢复成功本身就是一次配对状态写入 → 让最新备份也指向它（保留时间线）\n        backupConfigFile(relayDir);\n        sendJson(res, 200, {\n          ok: true,\n          restored: restored.restored,\n          restoredAt: restored.at,\n          bridgeRestart,\n          ...(await composeStatus(relayDir)),\n        });\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/logout\",\n      handler: async (_req, res) => {\n        // 退出登录：清除本机保存的账号(邮箱/密码)，并**立刻停掉 bridge**。\n        // 为什么必须停：bridge 的凭据是启动时固化的，不停就会继续用旧账号的隧道对外服务 ——\n        // 用户以为\"已退出登录\"，实际上手机端仍能访问这台电脑（安全语义不成立）。\n        const cfg = loadConfig(relayDir);\n        delete cfg.phone;\n        delete cfg.password;\n        delete cfg.device_id;          // 设备身份一并作废：下次登录会生成新身份并重新登记\n        delete cfg.device_private_key;\n        delete cfg.device_public_key;\n        saveConfig(relayDir, cfg);\n        resetBridgeForAccountChange(relayDir, \"退出登录\");\n        invalidateRelayToken(relayDir); // 退出登录：token 缓存立即失效\n        sendJson(res, 200, { ok: true, ...(await composeStatus(relayDir)) });\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/harness/restart\",\n      handler: async (_req, res) => {\n        // 首次安装/在线更新后重启 DeepSeek harness：插件本体与浏览器半在进程启动时装载，\n        // 不重启则面板入口与 /dsh-remote/* 路由都不会出现。只重启承载本插件的进程。\n        //\n        // 🔴 2026-10-11 用户约定：**桌面端绝不代为重启**。\n        //   \"自动重启会很突兀地把窗口给关掉，关没了……我们应该提示用户自己重启，不要由我们来重启。\"\n        //   桌面端 Host 由 Electron 托管，重启 = 强杀承载窗口的进程（还会弹原生致命错误）。\n        //   这里做成**硬拒绝**（不只是前端藏按钮）：任何调用方都拿不到\"被重启\"的结果，\n        //   只会收到一句明确的\"请手动重启\"，前端据此展示提示。\n        if (IS_ELECTRON_HOST) {\n          sendJson(res, 200, {\n            ...(await composeStatus(relayDir)),\n            ok: false,\n            status: \"manual-restart-required\",\n            detail: \"桌面端不代为重启：请手动退出并重新打开 DeepSeek Harness（自动重启会突兀地关掉窗口）\",\n          });\n          return;\n        }\n        const r = await restartHarness(relayDir);\n        const payload = { ...(await composeStatus(relayDir)), ...r };\n        if (!r.ok) payload.error = r.detail || r.status || \"重启失败\";\n        sendJson(res, r.ok ? 200 : 500, payload);\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/start\",\n      handler: async (_req, res) => {\n        // 用户点了「启动」= 人工指令：清掉自愈护栏额度再动手（同 resetProvisionRetry 的原则），\n        // 否则\"自动自愈刚刚熔断\"会把用户这一次明确的操作也一起挡掉。\n        resetSelfhealGuard(relayDir);\n        const r = startBridge(relayDir);\n        // 【0.6.2】composeStatus 自带 ok:true（那是「状态查询成功」），必须先展开再覆盖，\n        // 否则不管启动成没成功都回 ok:true → 面板一律弹「✅ bridge 已启动」。\n        // 失败时额外带上 error：浏览器半的 api() 优先用它做提示文案，避免只看到「HTTP 500」。\n        const payload = { ...(await composeStatus(relayDir)), ...r };\n        if (!r.ok) payload.error = r.detail || r.status || \"启动失败\";\n        sendJson(res, r.ok ? 200 : 500, payload);\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/stop\",\n      handler: async (_req, res) => {\n        const r = stopBridge(relayDir);\n        const payload = { ...(await composeStatus(relayDir)), ...r };\n        if (!r.ok) payload.error = r.detail || r.status || \"停止失败\";\n        sendJson(res, r.ok ? 200 : 500, payload);\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/sms-code\",\n      handler: async (req, res) => {\n        const body = await readJsonBody(req);\n        if (body.__parseError) return sendJson(res, 400, { ok: false, error: \"JSON 解析失败\" });\n        let phone = String(body.phone ?? \"\").trim();\n        if (!phone) {\n          // 隐私审计(2026-09):账号卡修改密码不再下发明文手机号——服务端以本机账号为准\n          phone = String((loadConfig(relayDir).phone) || \"\").trim();\n        }\n        if (!phone) return sendJson(res, 400, { ok: false, error: \"手机号必填\" });\n        const r = await relayFetch(relayDir, \"/api/sms-code\", {\n          method: \"POST\", headers: { \"content-type\": \"application/json\" },\n          body: JSON.stringify({ phone, ...(body.captcha_id !== undefined ? { captcha_id: String(body.captcha_id), captcha_answer: String(body.captcha_answer ?? \"\") } : {}) }),\n        });\n        sendJson(res, r.status || 502, { ok: r.ok, status: r.status, body: r.body });\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/password/reset\",\n      handler: async (req, res) => {\n        // 公开 POST /api/password/reset（无需 Bearer）：短信验证码重置密码。\n        // 成功 → 企业端使该账号全部授权设备/会话失效（含 E2EE 派生口令）。\n        const body = await readJsonBody(req);\n        if (body.__parseError) return sendJson(res, 400, { ok: false, error: \"JSON 解析失败\" });\n        let phone = String(body.phone ?? \"\").trim();\n        if (!phone) {\n          // 隐私审计(2026-09):同上,账号卡改密不传明文手机号,服务端回填本机账号\n          phone = String((loadConfig(relayDir).phone) || \"\").trim();\n        }\n        const smsCode = String(body.sms_code ?? \"\").trim();\n        const newPassword = String(body.new_password ?? body.password ?? \"\");\n        if (!phone || !smsCode || !newPassword) return sendJson(res, 400, { ok: false, error: \"手机号、短信验证码与新密码必填\" });\n        const r = await relayFetch(relayDir, \"/api/password/reset\", {\n          method: \"POST\",\n          headers: { \"content-type\": \"application/json\" },\n          body: JSON.stringify({ phone, sms_code: smsCode, new_password: newPassword }),\n        });\n        // 透传企业端 ok/error（成功 200 {ok:true}；失败保留 status 与错误体）\n        sendJson(res, r.status || 502, { ok: r.ok, status: r.status, body: r.body });\n      },\n    },\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/captcha\",\n      handler: async (_req, res) => {\n        // 代理 relay /api/captcha。live 契约：200 JSON {captcha_id, svg}；\n        // 兼容旧服务端可能返回的图片（content-type 以 image/ 开头时原样透传）。\n        const cfg = loadConfig(relayDir);\n        const api = (cfg.api_url || DEFAULT_API).replace(/\\/+$/, \"\");\n        try {\n          const r = await fetch(`${api}/api/captcha`, { signal: AbortSignal.timeout(6000) });\n          const type = r.headers.get(\"content-type\") || \"\";\n          const buf = Buffer.from(await r.arrayBuffer());\n          if (!r.ok) {\n            sendJson(res, r.status, { ok: false, error: \"验证码获取失败\", relayStatus: r.status });\n            return;\n          }\n          if (type.startsWith(\"image/\")) {\n            res.writeHead(200, { \"content-type\": type, \"cache-control\": \"no-store\" });\n            res.end(buf);\n            return;\n          }\n          // JSON（{captcha_id, svg}）原样透传\n          res.writeHead(200, { \"content-type\": type || \"application/json; charset=utf-8\", \"cache-control\": \"no-store\" });\n          res.end(buf);\n        } catch (e) {\n          sendJson(res, 502, { ok: false, error: `验证码服务不可达: ${fetchFailReason(e)}` });\n        }\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/register\",\n      handler: async (req, res) => {\n        const body = await readJsonBody(req);\n        if (body.__parseError) return sendJson(res, 400, { ok: false, error: \"JSON 解析失败\" });\n        const phone = String(body.phone ?? \"\").trim();\n        const smsCode = String(body.sms_code ?? \"\").trim();\n        const password = String(body.password ?? \"\");\n        if (!phone || !smsCode || !password) return sendJson(res, 400, { ok: false, error: \"手机号、短信验证码与密码必填\" });\n        // 全量透传 body（不挑字段）：注册来源 reg_source（面板=panel_register／手机端网页=remoteweb_register）\n        // 等扩展字段必须原样进企业端，否则「用户从哪注册的」这类增长约定会全部丢失。\n        const payload = { ...body, phone, sms_code: smsCode, password };\n        delete payload.__parseError;\n        const captchaId = body.captcha_id ?? body.captchaId;\n        const captchaAnswer = body.captcha_answer ?? body.captcha;\n        if (captchaId !== void 0) payload.captcha_id = String(captchaId);\n        if (captchaAnswer !== void 0) payload.captcha_answer = String(captchaAnswer);\n        // 渠道归因（安装器 `--ref` → 配置 ref_code）：面板注册时带上 `channel_code`，\n        // 与 `invite_code`（C 端裂变）是两个字段、互不影响。请求体里自带 channel_code 时\n        // 以请求体为准（手机端 `?ref=` 路径会自己带），这里绝不覆盖。\n        const refCode = refCodeOf(loadConfig(relayDir));\n        if (refCode && !payload.channel_code) payload.channel_code = refCode;\n        const r = await relayFetch(relayDir, \"/api/register\", {\n          method: \"POST\",\n          headers: { \"content-type\": \"application/json\" },\n          body: JSON.stringify(payload),\n        });\n        // 透传 relay 响应体（成功 {token,user} / 失败 {error:{message}}）\n        sendJson(res, r.status || 502, { ok: r.ok, status: r.status, body: r.body });\n      },\n    },\n    {\n      method: \"POST\",\n      path: \"/dsh-remote/login\",\n      handler: async (req, res) => {\n        const body = await readJsonBody(req);\n        if (body.__parseError) return sendJson(res, 400, { ok: false, error: \"JSON 解析失败\" });\n        const phone = String(body.phone ?? \"\").trim();\n        const password = String(body.password ?? \"\");\n        if (!phone || !password) return sendJson(res, 400, { ok: false, error: \"手机号与密码必填\" });\n        // 登录接口已加图形验证码,透传 captcha 字段\n        const payload = { phone, password };\n        if (body.captcha_id !== undefined) payload.captcha_id = String(body.captcha_id);\n        if (body.captcha_answer !== undefined) payload.captcha_answer = String(body.captcha_answer);\n        const r = await relayFetch(relayDir, \"/api/login\", {\n          method: \"POST\",\n          headers: { \"content-type\": \"application/json\" },\n          body: JSON.stringify(payload),\n        });\n        sendJson(res, r.status || 502, { ok: r.ok, status: r.status, body: r.body });\n      },\n    },\n    {\n      method: \"GET\",\n      path: \"/dsh-remote/feedback-config\",\n      handler: async (_req, res) => {\n        const cfg = loadConfig(relayDir);\n        const api = feedbackApiOf(cfg);\n        let reachable = false;\n        try {\n          const r = await fetch(`${api}/api/health`, { signal: AbortSignal.timeout(3000) });\n          reachable = r.ok;\n        } catch {\n          reachable = false;\n        }\n        sendJson(res, 200, {\n          ok: true,\n          feedbackUrl: api,\n          reachable,\n          deviceId: cfg.device_id || \"\",\n          phone: maskPhone(cfg.phone || \"\"), // 隐私:浏览器端只见掩码(代理提交时服务端另附真号)\n          // 登录态（已配置账号或自建密钥）→ 节点半自动附加 JWT，免图形验证码\n          auth: cfg.local_key || (cfg.phone && cfg.password) ? \"account\" : \"anonymous\"\n        });\n      },\n    },\n    {\n      method: \"ALL\",\n      path: \"/dsh-remote/feedback\",\n      prefix: true,\n      handler: async (req, res) => {\n        const url = new URL(req.url ?? \"/\", \"http://x\");\n        await proxyFeedback(relayDir, req, res, url.pathname + url.search);\n      },\n    },\n    // 📣 公告（面板「未读公告」入口 + 电脑端弹窗）：\n    //   声明成 prefix:true + 自行判别子路径，与 feedback 同一形态 ——\n    //   `/dsh-remote/announcements`（列表）与 `/dsh-remote/announcements/click`（点击/已读上报）\n    //   是一对，拆成两条 exact 会在以后加子接口（比如详情）时又要动路由表。\n    {\n      method: \"ALL\",\n      path: \"/dsh-remote/announcements\",\n      prefix: true,\n      handler: async (req, res) => {\n        const url = new URL(req.url ?? \"/\", \"http://x\");\n        await proxyAnnouncements(relayDir, req, res, url.pathname);\n      },\n    },\n    // 🎉 企微交流群引导（桌面端面板使用满 2h 后弹一次；与手机 Web 共用同一套企业端接口）：\n    //   GET  /dsh-remote/community-invite/status → 上游 GET  {api}/api/community-invite/status\n    //   POST /dsh-remote/community-invite/shown  → 上游 POST {api}/api/community-invite/shown（幂等）\n    //   与 feedback/announcements 同一形态（prefix + handler 内判别），以后加子接口不用动路由表。\n    {\n      method: \"ALL\",\n      path: \"/dsh-remote/community-invite\",\n      prefix: true,\n      handler: async (req, res) => {\n        const url = new URL(req.url ?? \"/\", \"http://x\");\n        await proxyCommunityInvite(relayDir, req, res, url.pathname);\n      },\n    },\n  ];\n\n  const disposers = [];\n  for (const route of routes) {\n    const dispose = ctx.webServer.register({\n      kind: route.prefix ? \"prefix\" : \"exact\",\n      path: route.path,\n      handler: (req, res) => {\n        const url = new URL(req.url ?? \"/\", \"http://x\");\n        const match = route.prefix\n          ? url.pathname === route.path || url.pathname.startsWith(route.path + \"/\")\n          : url.pathname === route.path;\n        const methodOk = route.method === \"ALL\" || req.method === route.method;\n        if (!match || !methodOk) {\n          res.writeHead(404);\n          res.end();\n          return;\n        }\n        // 跨站防护：详见 localRequestBlocked 的注释（DNS rebinding / CSRF）\n        const blocked = localRequestBlocked(req);\n        if (blocked) {\n          const now = Date.now();\n          const last = LOCAL_GUARD_LOGGED.get(blocked) || 0;\n          if (now - last > 60_000) {\n            LOCAL_GUARD_LOGGED.set(blocked, now);\n            ctx.logger?.warn?.(\n              `dsh-remote-web: 已拦截跨站请求 ${route.method} ${route.path}（${blocked}）` +\n              ` host=${req.headers?.host || \"-\"} origin=${req.headers?.origin || \"-\"}`\n            );\n          }\n          sendJson(res, 403, { ok: false, error: \"forbidden\", reason: blocked });\n          return;\n        }\n        Promise.resolve(route.handler(req, res)).catch((e) => {\n          ctx.logger?.warn?.(`dsh-remote-web: ${route.method} ${route.path} failed: ${e?.stack || e}`);\n          if (!res.headersSent) sendJson(res, 500, { ok: false, error: String(e?.message || e) });\n          else res.end();\n        });\n        return; // webserver 不需要返回值；返回 void 保持 node:http 语义\n      },\n    });\n    disposers.push(dispose);\n  }\n  return () => {\n    for (const dispose of disposers) dispose();\n  };\n}\n\n/**\n * 插件主体：注册 /dsh-remote/* 路由。\n * @param ctx - host cordis context（注入 webServer）。\n * @param config - entry config（可选 relayDir）。\n */\n\n// ---------- 目录选择器：远程控制下必须用「浏览器内实现」（0.6.14） ----------\n//\n// 用户实测（Windows）：镜像页里点「添加工作区」**没反应**；同一功能在 Mac 上正常。\n//\n// 根因：官方 `directory-picker-auto` 在**绑定仅回环**且平台是 darwin/win32 时会挂\n// **原生**选择器（macOS 走 osascript，Windows 走一个 koffi + worker.cjs 子进程去弹 Win32\n// 文件夹对话框，还要合成 Alt 抢前台）。对远程控制来说这是双输：\n//   · 对话框弹在**电脑**那块屏上 —— 拿手机的人什么也看不到，表现就是\"按钮无效\"；\n//   · Windows 那条原生链路依赖 koffi 原生模块 + 子进程，失败点比 macOS 多得多。\n// 而 auto 只在 `webServer.host !== \"127.0.0.1\"` 时才改选 browse —— DSH Desktop（Electron 壳）\n// 自己持有 webserver 配置（实测监听 43120 / 回环），我们的 LAN 绑定补丁并不生效，于是它一直\n// 用的是原生那条路。**不能把\"手机能不能选工作区\"押在宿主的绑定地址上。**\n//\n// 【0.6.15 故障修正 —— 0.6.14 的\"先建 browse、后摘 auto\"在 DSH Desktop 上必然失败】\n//\n// 现场（用户诊断日志）：\n//   error: service \"directoryPicker\" has been registered at .dLateDirectoryPicker3\n//     at new DirectoryPicker (.../dsh-host-directory-picker/lib/index.js:1782)\n//     at new BrowseDirectoryPicker (.../dsh-host-directory-picker-browse/lib/index.js:245)\n//     at Fiber._execute\n// 用户看到的后果：插件装载失败（`entry did not activate`），而**原生那对还留着**\n// （auto 的析构没跑到 → 没被卸掉）。也就是说 0.6.14 这一版\"修法\"不但没修好，\n// 还额外制造了一条装载报错。\n//\n// 根因：`native` 与 `browse` 两个后端都是 `class DirectoryPicker extends Service`，\n// 注册的是**同一个服务名** `ctx.directoryPicker`。seam 的文档写得很直白：\n//   \"one implementation per context; loading a second throws, cordis' standard\n//    duplicate-service behavior\"（见 @deepseek-ai/dsh-host-directory-picker/lib/index.js）。\n// 所以\"两者并存\"从来就不成立 —— 只要 auto/native 还挂着，建 browse **一定**抛错。\n// 0.6.14 把顺序写反了：唯一能工作的顺序是**先摘 auto（释放服务名）、再建 browse**。\n//\n// 做法：先摘后建 + **失败回滚**（摘了却建不起来时把 auto 原样装回去，用户至少还有原生可用）。\n//\n// 四条护栏：\n//   ① 只在当前 kind === \"native\" 时动手；已经是 browse 就完全不碰（多数自建部署就是这样）；\n//   ② **先摘 auto、后建 browse** —— 两个后端抢同一个服务名，并存是不可能的；\n//   ③ browse 建不起来（或建完仍不是 browse）→ 回滚：卸掉刚建的、把 auto 条目**按原 id** 建回来；\n//   ④ 任何失败只记日志、绝不抛给宿主（插件不能把 dsh web 拖挂）。\n// `DSH_REMOTE_NATIVE_PICKER=1` 可整体退出（想保留系统原生对话框的人）。\nconst PICKER_AUTO_ENTRY_ID = \"directory-picker\";\nconst PICKER_AUTO_PACKAGE = \"@deepseek-ai/dsh-host-directory-picker-auto\";\nconst PICKER_BROWSE_PACKAGES = [\n  \"@deepseek-ai/dsh-host-directory-picker-browse\",\n  \"@deepseek-ai/dsh-client-ui-directory-picker-browse\"\n];\n/** 最近一次固定的结果（诊断面板会显示：这类\"点了没反应\"的问题一眼定位）。 */\nlet pickerPinState = { kind: \"\", action: \"pending\", detail: \"\" };\n\n/** 当前挂的是哪一路选择器（服务未就绪时返回空串）。 */\nfunction directoryPickerKind(ctx) {\n  try {\n    const svc = typeof ctx.get === \"function\" ? ctx.get(\"directoryPicker\") : null;\n    const cap = svc && typeof svc.capability === \"function\" ? svc.capability() : null;\n    return cap && typeof cap.kind === \"string\" ? cap.kind : \"\";\n  } catch {\n    return \"\";\n  }\n}\n\n/**\n * 在 loader 里找条目（`store` 是扁平表；条目结构不同版本略有差异，故 options 也当来源之一）。\n * @returns {{id: string, options: object|null}|null}\n */\nfunction loaderEntryOf(loader, id) {\n  let entry = null;\n  try { entry = loader?.store ? loader.store[id] : null; } catch { entry = null; }\n  if (!entry) return null;\n  const options = entry.options && typeof entry.options === \"object\" ? { ...entry.options } : null;\n  return { id, options: options ? { ...options, id } : { id, name: PICKER_AUTO_PACKAGE } };\n}\n\n/**\n * 把 auto 换成 browse 那一对（**先摘后建 + 失败回滚**）。前提：当前 kind === \"native\"。\n * @returns {Promise<{kind:string, action:string, detail:string}>}\n */\nasync function swapAutoToBrowse(ctx, loader, kind) {\n  const auto = loaderEntryOf(loader, PICKER_AUTO_ENTRY_ID)\n    || { id: PICKER_AUTO_ENTRY_ID, options: { id: PICKER_AUTO_ENTRY_ID, name: PICKER_AUTO_PACKAGE } };\n  // ① 先摘 auto：它的 effect 析构会卸掉 native 那一对，同时**释放 directoryPicker 服务名**。\n  //    不先摘就建 browse，必然撞上 duplicate-service（0.6.14 就是这么坏掉的）。\n  try {\n    await loader.remove(PICKER_AUTO_ENTRY_ID);\n  } catch (e) {\n    pickerPinState = {\n      kind,\n      action: \"kept_native\",\n      detail: `摘不掉 auto 条目，保留原生：${e && e.message ? e.message : e}`\n    };\n    ctx.logger?.warn?.(`dsh-remote-web: 目录选择器切换失败（摘 auto），保留原生：${e && e.message ? e.message : e}`);\n    return pickerPinState;\n  }\n  // ② 再建 browse 那一对（宿主后端 + 界面半边）\n  const created = [];\n  const fail = async (e) => {\n    for (const id of [...created].reverse()) { try { await loader.remove(id); } catch { /* 尽力回滚 */ } }\n    // ③ 回滚 auto：**按原 id 建回来**，让用户至少还有原生选择器可用\n    let restored = false;\n    try { await loader.create(auto.options); restored = true; } catch { restored = false; }\n    const why = e && e.message ? e.message : e;\n    pickerPinState = {\n      kind: directoryPickerKind(ctx),\n      action: \"kept_native\",\n      detail: restored\n        ? `浏览器内选择器装不起来，已还原原生：${why}`\n        : `浏览器内选择器装不起来，且原生条目还原失败（请重启 DeepSeek harness）：${why}`\n    };\n    ctx.logger?.warn?.(`dsh-remote-web: 目录选择器固定为 browse 失败${restored ? \"，已还原原生\" : \"，且还原失败\"}：${why}`);\n    return pickerPinState;\n  };\n  for (const name of PICKER_BROWSE_PACKAGES) {\n    try {\n      created.push(await loader.create({ name }));\n    } catch (e) {\n      return await fail(e);\n    }\n  }\n  // ④ 复核：服务真的换成 browse 了吗（建成功了但服务没挂上也是白搭）\n  const now = directoryPickerKind(ctx);\n  if (now && now !== \"browse\") {\n    return await fail(new Error(`建完 browse 后服务仍是 ${now}`));\n  }\n  pickerPinState = {\n    kind: \"browse\",\n    action: \"pinned\",\n    detail: \"原生对话框在远程时弹在电脑那台屏上（手机上看不到），已改为浏览器内选择器\"\n  };\n  ctx.logger?.info?.(\"dsh-remote-web: 目录选择器已固定为浏览器内实现（原生对话框远程不可见）\");\n  return pickerPinState;\n}\n\n/**\n * 把目录选择器固定成 browse（幂等）。服务要等 auto 挂完才存在，所以内部带重试窗口。\n * @returns {Promise<{kind:string, action:string, detail:string}>}\n */\nasync function pinBrowseDirectoryPicker(ctx, { attempts = 6, gapMs = 700 } = {}) {\n  if (String(process.env.DSH_REMOTE_NATIVE_PICKER || \"\") === \"1\") {\n    pickerPinState = { kind: directoryPickerKind(ctx), action: \"skipped\", detail: \"DSH_REMOTE_NATIVE_PICKER=1，保留系统原生对话框\" };\n    return pickerPinState;\n  }\n  let loader = null;\n  try { loader = typeof ctx.get === \"function\" ? ctx.get(\"loader\") : null; } catch { loader = null; }\n  if (!loader || typeof loader.create !== \"function\" || typeof loader.remove !== \"function\") {\n    pickerPinState = { kind: directoryPickerKind(ctx), action: \"skipped\", detail: \"没有 loader 服务，无法干预选择器\" };\n    return pickerPinState;\n  }\n  for (let i = 0; i < attempts; i += 1) {\n    const kind = directoryPickerKind(ctx);\n    if (kind === \"browse\") {\n      pickerPinState = { kind, action: \"none\", detail: \"已经是浏览器内选择器\" };\n      return pickerPinState;\n    }\n    if (kind === \"native\") return await swapAutoToBrowse(ctx, loader, kind);\n    await sleep(gapMs); // 服务还没挂上（auto 正在建）→ 下一轮再看\n  }\n  pickerPinState = { kind: directoryPickerKind(ctx), action: \"skipped\", detail: \"启动窗口内未确认到选择器服务\" };\n  return pickerPinState;\n}\n\n/** 不持有进程的 sleep（未 ref：宿主随时可以正常退出，不被我们的定时器拖住）。 */\nfunction sleepUnref(ms) {\n  return new Promise((resolve) => {\n    const t = setTimeout(resolve, ms);\n    if (t && typeof t.unref === \"function\") t.unref();\n  });\n}\n\n/* ── 延后接线的闸门参数（全部只为\"别在宿主启动期动 Loader\"，不是功能参数） ───────────── */\nconst PICKER_PIN_READY_WAIT_MS = 120_000; // 等宿主 HTTP 服务 listen 的上限\nconst PICKER_PIN_SETTLE_MS = 8_000;       // listen 之后再静置，避开首轮 client-module compose\nconst PICKER_PIN_PROBE_WAIT_MS = 30_000;  // 等服务挂出来的上限（只等，不换）\nconst PICKER_PIN_PROBE_GAP_MS = 3_000;    // 上面那段轮询间隔\n\n/**\n * 目录选择器的**延后**接线 —— 这是 2026-09-26 启动故障的直接修复。\n *\n * 🔴 故障：旧实现在 `apply()` 里**立刻**调 `pinBrowseDirectoryPicker(ctx)`（最多 6 次 × 700ms 轮询）。\n *    `loader.remove()` / `loader.create()` 会触发 dsh 的 `internal/plugin` 事件，而\n *    `@deepseek-ai/dsh-client-modules` 收到事件就**重新 compose 整张前端插件图**\n *    （`ClientModuleRegistry.flush() → buildCombo() → newlineCount()/identitySectionMap()`）。\n *    启动期本来就在装载几十个插件，此时再改 Loader = 昂贵的重复组合。真机 CPU profile 与实测都\n *    指向这里：把 `DSH_REMOTE_NATIVE_PICKER=1` 写进 launchd plist 后 dsh web 立刻恢复正常启动\n *    （3080 监听、401 约 2ms、单实例）；不设时出现过\"进程活着、3 分钟不监听、CPU 一直转、\n *    日志不更新\"的假死。\n *\n * 所以现在（与旧实现的四点区别）：\n *   ① **等宿主把 HTTP 服务 listen 起来**（`boundWebPort() > 0`）—— 这是\"宿主已启动\"最可靠的信号；\n *      `apply()` 时它还没 listen 完，旧实现正是在\"插件图还在装配\"的窗口里动 Loader，最坏；\n *   ② listen 之后再**静置** `PICKER_PIN_SETTLE_MS`，让首轮 compose 先跑完；\n *   ③ 之后只在\"服务还认不出\"时短轮询；**一旦认出 native 就换，且只换这一次**（换失败也不再来回折腾）；\n *   ④ 认不出/超时/出错 → **静默保留原生选择器**（= 原始行为），绝不影响宿主启动。\n *\n * @returns {() => void} 取消函数（供 `ctx.effect` 做清理）\n */\nfunction schedulePickerPin(ctx) {\n  let cancelled = false;\n  const gone = () => cancelled;\n\n  const waitUntil = async (cond, timeoutMs, stepMs) => {\n    const t0 = Date.now();\n    for (;;) {\n      if (gone()) return false;\n      let ok = false;\n      try { ok = !!cond(); } catch { ok = false; }\n      if (ok) return true;\n      if (Date.now() - t0 >= timeoutMs) return false;\n      await sleepUnref(stepMs);\n    }\n  };\n\n  void (async () => {\n    try {\n      if (String(process.env.DSH_REMOTE_NATIVE_PICKER || \"\") === \"1\") {\n        pickerPinState = { kind: directoryPickerKind(ctx), action: \"skipped\", detail: \"DSH_REMOTE_NATIVE_PICKER=1，保留系统原生对话框\" };\n        return;\n      }\n      // ① 等宿主 listen（apply 时还没 listen 完）\n      const up = await waitUntil(() => boundWebPort() > 0, PICKER_PIN_READY_WAIT_MS, 1000);\n      if (gone()) return;\n      if (!up) {\n        pickerPinState = { kind: \"\", action: \"skipped\", detail: \"宿主监听端口未在等待窗口内就绪，本次不干预目录选择器（保留原生）\" };\n        ctx.logger?.info?.(\"dsh-remote-web: 宿主监听端口未就绪，跳过目录选择器切换（不影响启动）\");\n        return;\n      }\n      // ② 静置，避开首轮 client-module compose\n      await sleepUnref(PICKER_PIN_SETTLE_MS);\n      if (gone()) return;\n      // ③ 等服务挂出来（**只等不换**）\n      await waitUntil(() => directoryPickerKind(ctx) !== \"\", PICKER_PIN_PROBE_WAIT_MS, PICKER_PIN_PROBE_GAP_MS);\n      if (gone()) return;\n      const kind = directoryPickerKind(ctx);\n      if (!kind) {\n        pickerPinState = { kind: \"\", action: \"skipped\", detail: \"窗口内未确认到选择器服务，保留原生（下次重启再试）\" };\n        return;\n      }\n      if (kind === \"browse\") {\n        pickerPinState = { kind, action: \"none\", detail: \"已经是浏览器内选择器\" };\n        return;\n      }\n      if (kind !== \"native\") {\n        pickerPinState = { kind, action: \"skipped\", detail: \"选择器服务当前是 \" + kind + \"，不认识，保留原样\" };\n        return;\n      }\n      // ④ 只换一次（attempts:1 → 内部不会再轮询）\n      await pinBrowseDirectoryPicker(ctx, { attempts: 1, gapMs: 0 });\n    } catch (e) {\n      // 目录选择器是**锦上添花**：任何异常都必须静默，绝不把宿主拖下水\n      try { ctx.logger?.warn?.(\"dsh-remote-web: 目录选择器延后切换异常（已忽略）：\" + (e && e.message ? e.message : e)); } catch { /* ignore */ }\n    }\n  })();\n\n  return () => { cancelled = true; };\n}\n\nexport function apply(ctx, config = {}) {\n  const relayDir = config.relayDir || process.env.DSH_RELAY_DIR || DEFAULT_RELAY_DIR;\n  // 记住宿主 ctx：上游地址要问 dsh web 自己的监听端口（见 upstreamUrl）。\n  // 存 ctx 而不是当场取端口：apply 可能早于 webServer.listen 完成，端口那时还是 0/undefined。\n  webServerCtx = ctx;\n  // 上游地址落盘（0.6.12）：系统自启拉起的守护没有本进程的 env，只认这个文件。\n  publishUpstream(relayDir);\n  // 【0.6.15】问不到自己监听端口时（飞牛/NAS 实测就是这种情况）主动发现一次并固化：\n  // watcher/bridge 是独立进程，只有这里知道 dsh web 真实在哪个端口。fire-and-forget，\n  // 发现完 /dsh-remote/bridge-status 的下一轮轮询与自愈就会用上正确地址。\n  void discoverUpstreamSelf(relayDir).catch(() => FALLBACK_UPSTREAM);\n  // 全新激活（dsh web 重启后插件重新加载，或卸载后再次安装）→ 解除上次的「已卸载」停摆标记\n  UNINSTALLED_DIRS.delete(relayDir);\n  // 匿名遥测：装载即初始化（读回上次进程遗留的磁盘队列，例如重启前那条 harness_restart，\n  // 并启动 60s 发送心跳），随后记一条 plugin_loaded（每进程一次）。\n  // DSH_REMOTE_TELEMETRY=0 → 这里连读都不读：零文件、零请求、零 install_id。\n  telemetryStart(relayDir);\n  telemetryOnce(relayDir, \"plugin_loaded\");\n  // 清理上次进程残留的安装/更新 marker（宿主被重启/强杀时子进程清理回调会丢失）\n  sweepStaleMarkers(relayDir);\n  // 「待重启」状态结清 + 运行时安装检测：\n  //   - bootId 变了 = 这次装载发生在新进程里 → 重启已完成，撤下提示；\n  //   - 插件文件晚于本进程启动才落盘（市场安装/在线更新在运行中改写）→ 当前进程里\n  //     根本没有本插件的路由与面板，必须重启 DeepSeek harness 才能生效。\n  const settled = settleRestartState(relayDir);\n  if (settled.cleared) {\n    ctx.logger?.info?.(\"dsh-remote-web: 检测到 DeepSeek harness 已重启，撤下「需要重启」提示\");\n  }\n  if (!readRestartState(relayDir).pending && pluginInstalledAfterBoot()) {\n    // 唯一还需要用户动一下的情形:插件文件晚于本进程启动才落盘(= 运行中被市场安装/在线更新改写),\n    // 此时本进程里没有本插件的路由与面板。**先让用户刷新页面**(客户端半随之更新);\n    // 只有刷新后仍无面板才需要重启(那时多半是 profile patch 行没被 HMR 读到)。\n    // 不再对\"首次安装/在线更新完成\"提示重启:插件走 patch 热加载、bridge 是独立进程,重启 harness 无必要。\n    markRestartPending(relayDir, \"refresh\", \"插件已更新，刷新页面即可生效\");\n    ctx.logger?.info?.(\"dsh-remote-web: 插件文件晚于本次进程启动 → 提示刷新页面\");\n  }\n  ctx.effect(() => registerRoutes(ctx, relayDir), \"dsh-remote-web: /dsh-remote routes\");\n  // 0.1.2-rc.1+ 浏览器会话代持：换取 Harness 会话 Cookie 供 bridge 上游携带（手机点设备不再 401 白页）\n  ctx.effect(() => scheduleHarnessMint(ctx, relayDir), \"dsh-remote-web: harness browser-session mint\");\n  // 目录选择器:远程控制下必须用浏览器内实现(否则手机点「添加工作区」像没反应) —— 见上方长注释\n  // ⚠️ **必须延后**：绝不能在 apply() 里直接切 Loader —— 会把宿主启动拖成假死（2026-09-26 故障，\n  //    见 schedulePickerPin 上方长注释）。schedulePickerPin 自己等\"宿主已 listen + 静置\"再动手。\n  ctx.effect(() => schedulePickerPin(ctx), \"dsh-remote-web: pin browser directory picker\");\n  // 插件市场一键全功能:缺桌面运行环境则自动安装,登录后自动拉起 bridge(不依赖用户跑 npx)\n  ctx.effect(() => scheduleRuntime(relayDir), \"dsh-remote-web: runtime self-provision\");\n  // 匿名遥测：插件停摆（卸载/重载）时停掉发送心跳；磁盘队列留给下次装载补发。\n  ctx.effect(() => () => telemetryStop(relayDir), \"dsh-remote-web: telemetry flush ticker\");\n  // 【0.6.2】市场安装路径的「装到用户电脑上」第一步：插件加载即后台补装桌面运行环境\n  // （bridge + 自启动），不再等用户先登录、也不再依赖 launchd 状态判断是否「已在运行」。\n  // 已就绪时是零副作用 no-op；正在安装中/已卸载时 ensureRuntime 自身幂等挡下。\n  const provisioned = ensureRuntime(relayDir);\n  if (!provisioned && !runtimeReady(relayDir)) {\n    ctx.logger?.info?.(`dsh-remote-web: 桌面运行环境缺失，已在后台自动安装（relayDir=${relayDir}）`);\n    telemetryRuntimeProbe(relayDir); // 匿名遥测：记下「本进程见过运行环境缺失」（装好后发 runtime_ready）\n  }\n  // 插件启动即上报本机安装信息（install_source/version + 主机 OS/架构；仅有账号凭据时上报，失败静默）。\n  // 面板登录成功（POST /dsh-remote/config）时会再上报一次，覆盖「已登录用户升级插件」的约定。\n  maybeReportInstall(relayDir);\n  ctx.logger?.info?.(`dsh-remote-web: /dsh-remote routes ready (relayDir=${relayDir})`);\n}\n\n// test hooks：cordis 只读 name/inject/apply，这些导出只给用例（见 test/picker-pin.test.mjs）。\n// 为什么不放进 apply 内部直接测：apply 是\"装载即副作用\"的同步函数，选择器固定是异步且带重试窗口的，\n// 单独导出才能把「**先摘 auto、后建 browse**」这个顺序契约钉死。\nexport { pinBrowseDirectoryPicker as __pinBrowseDirectoryPicker, schedulePickerPin as __schedulePickerPin, pickerPinState as __pickerPinState, directoryPickerKind as __directoryPickerKind, PICKER_AUTO_ENTRY_ID as __PICKER_AUTO_ENTRY_ID, PICKER_AUTO_PACKAGE as __PICKER_AUTO_PACKAGE, PICKER_BROWSE_PACKAGES as __PICKER_BROWSE_PACKAGES,\n  // 日志去重（同一条失败不刷屏）也要能被单测钉住 —— 它属于「诊断可读性」，见 test/linux-bridge.test.mjs\n  noteAutostartFailure as __noteAutostartFailure, clearAutostartFailure as __clearAutostartFailure,\n  // ★ 2026-10-13 自愈重启策略（修 12 秒重启风暴）必须能被**行为级**单测钉住，见 test/selfheal-restart-guard.test.mjs。\n  //   为什么必须导出而不是只靠 apply()：这一组用例要断言的是\"定时器跑 N 拍之后，\n  //   `systemctl restart` 到底被调用了几次\"——只有把定时器本体拿到用例里才能确定性地驱动它，\n  //   靠 apply() 间接跑就得靠真实 sleep 猜拍数（脆弱且慢）。\n  //   系统命令仍然走**假 PATH 上的假 systemctl**（与 test/linux-bridge.test.mjs 同一套手法），\n  //   所以不需要为了可测性往生产代码里插入任何依赖注入层。\n  scheduleRuntime as __scheduleRuntime, startBridge as __startBridge, manualStatus as __manualStatus,\n  linuxSystemdUnitState as __linuxSystemdUnitState,\n  selfhealRestartGate as __selfhealRestartGate, noteSelfhealRestart as __noteSelfhealRestart,\n  noteSelfhealBlocked as __noteSelfhealBlocked, resetSelfhealGuard as __resetSelfhealGuard,\n  selfhealGuardOf as __selfhealGuardOf, SELFHEAL_MAX_RESTARTS as __SELFHEAL_MAX_RESTARTS,\n  // 2026-10-17 事故：安装/配对自检 + 配对备份/恢复。见 test/repair-backup.test.mjs\n  // （用例必须把 relayDir 指向 mkdtemp 临时目录、HOME 指向假目录，绝不能在真实\n  //   ~/.dsh-remote 或真实 ~/.dsh 上做写入测试）。\n  setupStateOf as __setupStateOf, ensureConnection as __ensureConnection,\n  // 设备超额锁定（契约 §8）：面板文案 / 插件半设备绑定退避都要能被单测钉住\n  composeConnect as __composeConnect, readBindError as __readBindError, bindFailGate as __bindFailGate,\n  bindFailSignatureOf as __bindFailSignatureOf, isPermanentBindFailure as __isPermanentBindFailure,\n  bindCapBackoffMs as __bindCapBackoffMs, connectBook as __connectBook, noteBindFailAttempt as __noteBindFailAttempt,\n  DEVICE_BIND_CAP_EXIT_CODE as __DEVICE_BIND_CAP_EXIT_CODE, BIND_CAP_BACKOFF_MAX_MS as __BIND_CAP_BACKOFF_MAX_MS,\n  backupConfigFile as __backupConfigFile, listConfigBackups as __listConfigBackups,\n  restoreConfigBackup as __restoreConfigBackup, runtimeDirPresent as __runtimeDirPresent,\n  CONFIG_BACKUP_KEEP as __CONFIG_BACKUP_KEEP, CONFIG_BACKUP_DIR as __CONFIG_BACKUP_DIR,\n  pruneConfigBackups as __pruneConfigBackups,\n  // 双份备份（relayDir + profile 独立数据目录）的落点/推导/卸载清理都要能被行为级单测钉住\n  configBackupDirOf as __configBackupDirOf, pluginProfileDir as __pluginProfileDir,\n  listConfigBackupsIn as __listConfigBackupsIn, uninstallSelf as __uninstallSelf,\n  PROFILE_DATA_DIR as __PROFILE_DATA_DIR, PROFILE_BACKUP_SUBDIR as __PROFILE_BACKUP_SUBDIR };\n"
